INSERT INTO public.learning_catalog_domains (domain_id, version, payload)
VALUES ($catalog$artificial_intelligence$catalog$, $catalog$v1$catalog$, $catalog${"version":"v1","steps":[{"key":"artificial_intelligence.what_is_a_model","domain_id":"artificial_intelligence","objective_ids":["ai_foundations","ai_machine_learning","ai_building"],"stage":1,"order":1,"required":true,"prerequisite_keys":[],"fallback_key":null,"title_fr":"Ce qu'est un modèle : une fonction apprise sur des exemples","title_en":"What a model is: a function learned from examples","summary_fr":"Comprendre qu'un modèle n'est pas une règle écrite à la main mais des paramètres ajustés sur des données.","summary_en":"Understand that a model is not a hand-written rule but parameters fitted on data.","learning_goals_fr":["Distinguer un programme écrit par une personne d'un modèle appris.","Dire ce que contient un modèle une fois entraîné."],"learning_goals_en":["Tell apart a program written by a person and a learned model.","Say what a trained model actually contains."],"tutor_focus_fr":"Fais comparer un filtre anti-spam écrit à la main et un filtre appris, puis demande ce que contient exactement le fichier du modèle.","tutor_focus_en":"Have the student compare a hand-written spam filter with a learned one, then ask what the model file actually contains.","example_contexts_fr":["un filtre anti-spam qui apprend sur des messages signalés","une estimation de prix immobilier à partir de ventes passées","une reconnaissance de chiffres écrits à la main"],"example_contexts_en":["a spam filter learning from reported messages","a house price estimate from past sales","recognition of handwritten digits"],"safety_category":"standard"},{"key":"artificial_intelligence.data_features_labels","domain_id":"artificial_intelligence","objective_ids":["ai_foundations","ai_machine_learning","ai_building"],"stage":1,"order":2,"required":true,"prerequisite_keys":["artificial_intelligence.what_is_a_model"],"fallback_key":null,"title_fr":"Données, caractéristiques et étiquettes","title_en":"Data, features and labels","summary_fr":"Structurer un jeu de données en lignes, colonnes explicatives et colonne à prédire.","summary_en":"Structure a dataset into rows, explanatory columns and the column to predict.","learning_goals_fr":["Séparer les caractéristiques de la cible dans un tableau donné.","Repérer une colonne qui contient déjà la réponse."],"learning_goals_en":["Separate features from the target in a given table.","Spot a column that already contains the answer."],"tutor_focus_fr":"Fais désigner les caractéristiques et la cible dans un tableau de prêts bancaires, puis demande quelle colonne rendrait la prédiction triviale.","tutor_focus_en":"Have the student point out features and target in a table of bank loans, then ask which column would make the prediction trivial.","example_contexts_fr":["un tableau de demandes de prêt avec leur issue","des mesures météo et la pluie du lendemain","des trajets de livraison et leur durée réelle"],"example_contexts_en":["a table of loan applications with their outcome","weather measurements and next-day rain","delivery trips and their actual duration"],"safety_category":"standard"},{"key":"artificial_intelligence.training_vs_inference","domain_id":"artificial_intelligence","objective_ids":["ai_foundations","ai_machine_learning","ai_building"],"stage":1,"order":3,"required":true,"prerequisite_keys":["artificial_intelligence.data_features_labels"],"fallback_key":null,"title_fr":"Entraînement et inférence : deux moments distincts","title_en":"Training and inference: two distinct moments","summary_fr":"Séparer la phase où le modèle ajuste ses paramètres de la phase où il répond à une demande.","summary_en":"Separate the phase where the model fits its parameters from the phase where it answers.","learning_goals_fr":["Dire à quel moment le modèle apprend et à quel moment il ne change plus.","Comparer le coût des deux phases."],"learning_goals_en":["Say when the model learns and when it no longer changes.","Compare the cost of the two phases."],"tutor_focus_fr":"Fais expliquer si un modèle apprend de la question que l'utilisateur vient de poser, puis demande ce qu'il faudrait pour qu'il l'apprenne vraiment.","tutor_focus_en":"Have the student explain whether a model learns from the question just asked, then ask what it would take for it to really learn it.","example_contexts_fr":["un assistant qui répond à une question posée aujourd'hui","une recommandation musicale recalculée chaque nuit","un modèle de traduction embarqué sur un téléphone"],"example_contexts_en":["an assistant answering a question asked today","a music recommendation recomputed every night","a translation model embedded in a phone"],"safety_category":"standard"},{"key":"artificial_intelligence.ai_ml_dl_scope","domain_id":"artificial_intelligence","objective_ids":["ai_foundations","ai_machine_learning","ai_building"],"stage":1,"order":4,"required":true,"prerequisite_keys":["artificial_intelligence.training_vs_inference"],"fallback_key":null,"title_fr":"IA, apprentissage automatique, apprentissage profond : trois cercles emboîtés","title_en":"AI, machine learning, deep learning: three nested circles","summary_fr":"Situer les trois termes les uns par rapport aux autres et rattacher un système donné au bon cercle.","summary_en":"Place the three terms relative to each other and assign a given system to the right circle.","learning_goals_fr":["Ordonner les trois notions du plus large au plus étroit.","Classer trois systèmes réels dans le bon cercle."],"learning_goals_en":["Order the three notions from broadest to narrowest.","Classify three real systems into the right circle."],"tutor_focus_fr":"Fais classer un moteur de règles fiscales, un détecteur de fraude statistique et un modèle de langue, puis demande le critère utilisé pour trancher.","tutor_focus_en":"Have the student classify a tax rule engine, a statistical fraud detector and a language model, then ask which criterion they used.","example_contexts_fr":["un moteur de règles pour le calcul d'impôts","un détecteur de fraude entraîné sur des transactions","un assistant conversationnel généraliste"],"example_contexts_en":["a rule engine computing taxes","a fraud detector trained on transactions","a general-purpose conversational assistant"],"safety_category":"standard"},{"key":"artificial_intelligence.probabilistic_answers","domain_id":"artificial_intelligence","objective_ids":["ai_foundations","ai_machine_learning","ai_building"],"stage":1,"order":5,"required":true,"prerequisite_keys":["artificial_intelligence.ai_ml_dl_scope"],"fallback_key":null,"title_fr":"Pourquoi un modèle donne une réponse probable et non certaine","title_en":"Why a model gives a probable answer, not a certain one","summary_fr":"Comprendre qu'une sortie de modèle est un pari statistique assorti d'un degré de confiance.","summary_en":"Understand that a model output is a statistical bet carrying a confidence level.","learning_goals_fr":["Interpréter un score de confiance de 0,7 sur une classification.","Dire pourquoi une réponse fausse peut être donnée avec assurance."],"learning_goals_en":["Interpret a 0.7 confidence score on a classification.","Say why a wrong answer can be delivered confidently."],"tutor_focus_fr":"Fais interpréter une prédiction à 70 % de confiance, puis demande combien d'erreurs sont attendues sur cent cas de ce type.","tutor_focus_en":"Have the student interpret a prediction at 70% confidence, then ask how many errors to expect over a hundred such cases.","example_contexts_fr":["un diagnostic automatique de panne annoncé à 70 %","une détection de fraude sur un paiement inhabituel","une suggestion de réponse dans une messagerie"],"example_contexts_en":["an automatic fault diagnosis announced at 70%","fraud detection on an unusual payment","a suggested reply in a messaging app"],"safety_category":"standard"},{"key":"artificial_intelligence.tokens_and_text","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":1,"order":6,"required":true,"prerequisite_keys":["artificial_intelligence.probabilistic_answers"],"fallback_key":null,"title_fr":"Comment un modèle de langue découpe le texte en tokens","title_en":"How a language model splits text into tokens","summary_fr":"Voir qu'un modèle lit des morceaux de mots et non des lettres ni des mots entiers.","summary_en":"See that a model reads word pieces rather than letters or whole words.","learning_goals_fr":["Découper une phrase courte en tokens plausibles.","Expliquer pourquoi compter les caractères d'un mot est difficile pour un modèle."],"learning_goals_en":["Split a short sentence into plausible tokens.","Explain why counting the letters of a word is hard for a model."],"tutor_focus_fr":"Fais découper une phrase en tokens plausibles, puis demande pourquoi le modèle se trompe en comptant les lettres d'un mot rare.","tutor_focus_en":"Have the student split a sentence into plausible tokens, then ask why the model miscounts the letters of a rare word.","example_contexts_fr":["un mot rare découpé en plusieurs morceaux","une facture de service au million de tokens","un texte en français plus coûteux qu'en anglais à longueur égale"],"example_contexts_en":["a rare word split into several pieces","a service bill priced per million tokens","a French text costing more than English at equal length"],"safety_category":"standard"},{"key":"artificial_intelligence.supervised_vs_unsupervised","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":1,"order":7,"required":true,"prerequisite_keys":["artificial_intelligence.probabilistic_answers"],"fallback_key":null,"title_fr":"Apprentissage supervisé et non supervisé","title_en":"Supervised and unsupervised learning","summary_fr":"Choisir la famille d'algorithmes selon que les exemples portent ou non une réponse connue.","summary_en":"Pick the algorithm family depending on whether the examples carry a known answer.","learning_goals_fr":["Classer trois problèmes en supervisé ou non supervisé.","Dire ce que coûte l'étiquetage des données."],"learning_goals_en":["Classify three problems as supervised or unsupervised.","Say what labelling data costs."],"tutor_focus_fr":"Fais classer une prévision de churn, une segmentation de clients et une détection d'anomalies, puis demande ce qui manque pour rendre le deuxième supervisé.","tutor_focus_en":"Have the student classify churn prediction, customer segmentation and anomaly detection, then ask what is missing to make the second supervised.","example_contexts_fr":["une prévision de départ de clients à partir d'historiques","une segmentation de clientèle sans catégories prédéfinies","une détection d'anomalies sur des capteurs industriels"],"example_contexts_en":["predicting customer churn from history","segmenting customers with no predefined categories","detecting anomalies on industrial sensors"],"safety_category":"standard"},{"key":"artificial_intelligence.calling_model_api","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":1,"order":8,"required":true,"prerequisite_keys":["artificial_intelligence.probabilistic_answers"],"fallback_key":null,"title_fr":"Ce qui se passe quand une application appelle un modèle","title_en":"What happens when an application calls a model","summary_fr":"Suivre le trajet d'un appel d'API de modèle : requête, jetons consommés, réponse, coût.","summary_en":"Follow a model API call: request, tokens consumed, response, cost.","learning_goals_fr":["Décrire le contenu d'une requête envoyée à un modèle.","Dire d'où vient la facturation d'un appel."],"learning_goals_en":["Describe the content of a request sent to a model.","Say where the billing of a call comes from."],"tutor_focus_fr":"Fais décrire le contenu exact d'une requête à un modèle, puis demande ce qui augmente la facture pour un même service.","tutor_focus_en":"Have the student describe the exact content of a request to a model, then ask what inflates the bill for the same service.","example_contexts_fr":["un chatbot de support intégré à un site","une génération de description produit dans un back-office","une facture mensuelle qui triple sans hausse d'utilisateurs"],"example_contexts_en":["a support chatbot embedded in a website","product description generation in a back office","a monthly bill tripling with no more users"],"safety_category":"standard"},{"key":"artificial_intelligence.train_test_split","domain_id":"artificial_intelligence","objective_ids":["ai_foundations","ai_machine_learning","ai_building"],"stage":2,"order":9,"required":true,"prerequisite_keys":["artificial_intelligence.probabilistic_answers"],"fallback_key":"artificial_intelligence.probabilistic_answers","title_fr":"Pourquoi on garde des données jamais vues","title_en":"Why we keep data the model has never seen","summary_fr":"Séparer entraînement, validation et test pour mesurer autre chose que de la mémorisation.","summary_en":"Split training, validation and test data to measure something other than memorisation.","learning_goals_fr":["Expliquer le rôle de chacun des trois jeux de données.","Repérer une fuite de données entre entraînement et test."],"learning_goals_en":["Explain the role of each of the three datasets.","Spot a data leak between training and test."],"tutor_focus_fr":"Fais expliquer pourquoi un score de 100 % sur les données d'entraînement n'apprend rien, puis demande comment une fuite peut se glisser dans un découpage temporel.","tutor_focus_en":"Have the student explain why 100% on training data teaches nothing, then ask how a leak can slip into a time-based split.","example_contexts_fr":["un modèle de prévision de ventes évalué sur l'année écoulée","des photos du même patient présentes dans les deux jeux","un concours de science des données avec un jeu caché"],"example_contexts_en":["a sales forecast model evaluated on the past year","photos of the same patient present in both sets","a data science contest with a hidden test set"],"safety_category":"standard"},{"key":"artificial_intelligence.overfitting_intuition","domain_id":"artificial_intelligence","objective_ids":["ai_foundations","ai_machine_learning","ai_building"],"stage":2,"order":10,"required":true,"prerequisite_keys":["artificial_intelligence.train_test_split"],"fallback_key":"artificial_intelligence.probabilistic_answers","title_fr":"Sur-apprentissage : mémoriser au lieu de généraliser","title_en":"Overfitting: memorising instead of generalising","summary_fr":"Reconnaître l'écart entre performance d'entraînement et performance réelle comme signal de sur-apprentissage.","summary_en":"Read the gap between training performance and real performance as an overfitting signal.","learning_goals_fr":["Lire un écart entre score d'entraînement et score de test.","Citer deux causes fréquentes de sur-apprentissage."],"learning_goals_en":["Read a gap between training score and test score.","Name two frequent causes of overfitting."],"tutor_focus_fr":"Fais diagnostiquer un modèle à 99 % en entraînement et 62 % en test, puis demande deux corrections possibles et leur effet attendu.","tutor_focus_en":"Have the student diagnose a model at 99% training and 62% test, then ask for two fixes and their expected effect.","example_contexts_fr":["un modèle de scoring entraîné sur trois cents dossiers","un détecteur d'objets qui ne reconnaît que les photos du studio","une prévision qui fonctionnait avant un changement de tarif"],"example_contexts_en":["a scoring model trained on three hundred files","an object detector that only recognises studio photos","a forecast that worked before a pricing change"],"safety_category":"standard"},{"key":"artificial_intelligence.bias_in_data","domain_id":"artificial_intelligence","objective_ids":["ai_foundations","ai_machine_learning","ai_building"],"stage":2,"order":11,"required":true,"prerequisite_keys":["artificial_intelligence.overfitting_intuition"],"fallback_key":"artificial_intelligence.probabilistic_answers","title_fr":"Comment un biais des données devient un biais du modèle","title_en":"How a bias in the data becomes a bias in the model","summary_fr":"Suivre le chemin d'une sous-représentation dans les données jusqu'à une décision systématiquement défavorable.","summary_en":"Follow the path from under-representation in data to a systematically unfavourable decision.","learning_goals_fr":["Identifier une population sous-représentée dans un jeu de données.","Expliquer pourquoi la précision globale peut masquer ce biais."],"learning_goals_en":["Identify an under-represented population in a dataset.","Explain why overall accuracy can hide that bias."],"tutor_focus_fr":"Fais analyser un modèle de recrutement entraîné sur dix ans d'embauches passées, puis demande quelle mesure par sous-groupe révélerait le problème.","tutor_focus_en":"Have the student analyse a hiring model trained on ten years of past hires, then ask which per-subgroup measurement would expose the problem.","example_contexts_fr":["un tri de candidatures appris sur les embauches passées","une reconnaissance vocale entraînée sur peu d'accents","un score de risque calibré sur une seule région"],"example_contexts_en":["application screening learned from past hires","speech recognition trained on few accents","a risk score calibrated on a single region"],"safety_category":"standard"},{"key":"artificial_intelligence.compute_and_data_cost","domain_id":"artificial_intelligence","objective_ids":["ai_foundations","ai_machine_learning","ai_building"],"stage":2,"order":12,"required":true,"prerequisite_keys":["artificial_intelligence.bias_in_data"],"fallback_key":"artificial_intelligence.probabilistic_answers","title_fr":"Ce que coûte un entraînement : données, calcul, énergie","title_en":"What training costs: data, compute, energy","summary_fr":"Relier taille du modèle, volume de données et facture de calcul pour juger un projet réaliste.","summary_en":"Connect model size, data volume and compute bill to judge whether a project is realistic.","learning_goals_fr":["Comparer l'ordre de grandeur d'un entraînement complet et d'un ajustement fin.","Dire ce qui rend une inférence coûteuse à grande échelle."],"learning_goals_en":["Compare the order of magnitude of full training and of fine-tuning.","Say what makes inference expensive at scale."],"tutor_focus_fr":"Fais comparer le coût d'un entraînement complet et celui d'un ajustement fin, puis demande ce qui domine la facture d'un service à un million de requêtes par jour.","tutor_focus_en":"Have the student compare the cost of full training and of fine-tuning, then ask what dominates the bill of a service at a million requests per day.","example_contexts_fr":["une équipe qui veut entraîner son propre modèle de langue","un ajustement fin sur deux mille exemples internes","un service qui traite un million de requêtes par jour"],"example_contexts_en":["a team wanting to train its own language model","a fine-tune on two thousand internal examples","a service handling a million requests per day"],"safety_category":"standard"},{"key":"artificial_intelligence.next_token_prediction","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":2,"order":13,"required":true,"prerequisite_keys":["artificial_intelligence.compute_and_data_cost"],"fallback_key":"artificial_intelligence.tokens_and_text","title_fr":"Prédire le token suivant : le mécanisme de base d'un modèle de langue","title_en":"Next-token prediction: the base mechanism of a language model","summary_fr":"Comprendre qu'un texte long est produit un token à la fois, chacun conditionné par les précédents.","summary_en":"Understand that long text is produced one token at a time, each conditioned on the previous ones.","learning_goals_fr":["Décrire la boucle de génération token par token.","Expliquer pourquoi une erreur au début oriente toute la suite."],"learning_goals_en":["Describe the token-by-token generation loop.","Explain why an early mistake steers the whole continuation."],"tutor_focus_fr":"Fais dérouler la génération des cinq premiers tokens d'une phrase, puis demande l'effet d'un premier token mal choisi.","tutor_focus_en":"Have the student unroll the generation of the first five tokens of a sentence, then ask the effect of a badly chosen first token.","example_contexts_fr":["une réponse d'assistant qui part dans une mauvaise direction","une complétion de code proposée dans un éditeur","un résumé qui reprend le ton du début du texte"],"example_contexts_en":["an assistant answer drifting in the wrong direction","a code completion suggested in an editor","a summary echoing the tone of the opening"],"safety_category":"standard"},{"key":"artificial_intelligence.temperature_sampling","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":2,"order":14,"required":false,"prerequisite_keys":["artificial_intelligence.next_token_prediction"],"fallback_key":"artificial_intelligence.tokens_and_text","title_fr":"Température et échantillonnage : pourquoi deux réponses diffèrent","title_en":"Temperature and sampling: why two answers differ","summary_fr":"Relier le réglage de température à la variabilité des sorties et au risque d'invention.","summary_en":"Connect the temperature setting to output variability and to the risk of invention.","learning_goals_fr":["Prévoir l'effet d'une température basse et d'une température haute.","Choisir un réglage adapté à une tâche factuelle."],"learning_goals_en":["Predict the effect of a low and of a high temperature.","Choose a setting suited to a factual task."],"tutor_focus_fr":"Fais choisir une température pour une extraction de données puis pour une génération d'idées, en demandant de justifier chaque choix.","tutor_focus_en":"Have the student choose a temperature for data extraction then for idea generation, justifying each choice.","example_contexts_fr":["une extraction de champs depuis une facture","une génération de titres publicitaires","deux exécutions du même prompt qui donnent des réponses différentes"],"example_contexts_en":["extracting fields from an invoice","generating advertising headlines","two runs of the same prompt returning different answers"],"safety_category":"standard"},{"key":"artificial_intelligence.linear_regression","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":2,"order":15,"required":true,"prerequisite_keys":["artificial_intelligence.compute_and_data_cost"],"fallback_key":"artificial_intelligence.supervised_vs_unsupervised","title_fr":"La régression linéaire : ajuster une droite et lire ses coefficients","title_en":"Linear regression: fitting a line and reading its coefficients","summary_fr":"Interpréter la pente et l'ordonnée à l'origine comme une relation quantifiée entre deux variables.","summary_en":"Interpret slope and intercept as a quantified relation between two variables.","learning_goals_fr":["Interpréter un coefficient en unités métier.","Repérer une relation manifestement non linéaire."],"learning_goals_en":["Interpret a coefficient in business units.","Spot a clearly non-linear relation."],"tutor_focus_fr":"Fais interpréter un coefficient de surface sur un prix immobilier, puis demande ce qui invalide la droite quand la relation se courbe.","tutor_focus_en":"Have the student interpret a floor-area coefficient on a property price, then ask what invalidates the line when the relation curves.","example_contexts_fr":["un prix au mètre carré estimé sur des ventes récentes","une consommation électrique en fonction de la température","un chiffre d'affaires en fonction du budget publicitaire"],"example_contexts_en":["a price per square metre estimated from recent sales","electricity consumption against temperature","revenue against advertising budget"],"safety_category":"standard"},{"key":"artificial_intelligence.loss_function","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":2,"order":16,"required":false,"prerequisite_keys":["artificial_intelligence.linear_regression"],"fallback_key":"artificial_intelligence.supervised_vs_unsupervised","title_fr":"Ce que mesure une fonction de perte","title_en":"What a loss function measures","summary_fr":"Comprendre que le choix de la perte définit quelle erreur le modèle acceptera de commettre.","summary_en":"Understand that choosing the loss defines which error the model agrees to make.","learning_goals_fr":["Comparer erreur absolue et erreur quadratique sur une valeur aberrante.","Choisir une perte cohérente avec un enjeu métier."],"learning_goals_en":["Compare absolute and squared error on an outlier.","Choose a loss consistent with a business stake."],"tutor_focus_fr":"Fais comparer l'effet d'une valeur aberrante sur deux pertes, puis demande laquelle choisir quand les grosses erreurs coûtent très cher.","tutor_focus_en":"Have the student compare the effect of an outlier on two losses, then ask which to choose when big errors are very costly.","example_contexts_fr":["une prévision de stock où la rupture coûte plus que le surstock","un jeu de mesures contenant une valeur aberrante","une estimation de délai de livraison"],"example_contexts_en":["a stock forecast where a shortage costs more than surplus","a measurement set containing an outlier","a delivery time estimate"],"safety_category":"standard"},{"key":"artificial_intelligence.prompt_structure","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":2,"order":17,"required":true,"prerequisite_keys":["artificial_intelligence.compute_and_data_cost"],"fallback_key":"artificial_intelligence.calling_model_api","title_fr":"Structurer un prompt : rôle, consigne, format attendu","title_en":"Structuring a prompt: role, instruction, expected format","summary_fr":"Écrire une instruction dont la sortie est prévisible parce que le format est imposé.","summary_en":"Write an instruction whose output is predictable because the format is imposed.","learning_goals_fr":["Séparer contexte, tâche et format attendu dans une instruction.","Réécrire une consigne vague en consigne vérifiable."],"learning_goals_en":["Separate context, task and expected format in an instruction.","Rewrite a vague instruction into a verifiable one."],"tutor_focus_fr":"Fais réécrire une consigne vague en trois blocs séparés, puis demande comment vérifier automatiquement que la sortie respecte le format.","tutor_focus_en":"Have the student rewrite a vague instruction into three separate blocks, then ask how to check the output format automatically.","example_contexts_fr":["un résumé d'e-mail client en trois puces","une classification de tickets en quatre catégories fixes","une consigne qui produit un texte différent à chaque exécution"],"example_contexts_en":["a customer email summarised into three bullets","ticket classification into four fixed categories","an instruction producing different text on each run"],"safety_category":"standard"},{"key":"artificial_intelligence.structured_output","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":2,"order":18,"required":false,"prerequisite_keys":["artificial_intelligence.prompt_structure"],"fallback_key":"artificial_intelligence.calling_model_api","title_fr":"Obtenir une sortie JSON exploitable","title_en":"Getting usable JSON output","summary_fr":"Imposer un schéma de sortie et prévoir ce qui se passe quand le modèle s'en écarte.","summary_en":"Impose an output schema and plan for what happens when the model departs from it.","learning_goals_fr":["Décrire un schéma minimal pour une extraction de données.","Choisir le comportement de l'application face à une sortie invalide."],"learning_goals_en":["Describe a minimal schema for a data extraction.","Choose how the application behaves on invalid output."],"tutor_focus_fr":"Fais décrire un schéma pour extraire trois champs d'une facture, puis demande ce que doit faire l'application si un champ manque.","tutor_focus_en":"Have the student describe a schema extracting three invoice fields, then ask what the application must do if a field is missing.","example_contexts_fr":["l'extraction du montant et de la date d'une facture","une réponse tronquée au milieu d'un objet JSON","une intégration qui refuse un champ inconnu"],"example_contexts_en":["extracting the amount and date of an invoice","a response truncated in the middle of a JSON object","an integration rejecting an unknown field"],"safety_category":"standard"},{"key":"artificial_intelligence.embeddings_meaning","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":3,"order":19,"required":true,"prerequisite_keys":["artificial_intelligence.temperature_sampling"],"fallback_key":"artificial_intelligence.temperature_sampling","title_fr":"Les plongements vectoriels : représenter le sens par des nombres","title_en":"Embeddings: representing meaning with numbers","summary_fr":"Comprendre qu'un texte devient un vecteur dont la proximité approche la proximité de sens.","summary_en":"Understand that a text becomes a vector whose closeness approximates closeness in meaning.","learning_goals_fr":["Expliquer ce que mesure la similarité entre deux vecteurs.","Citer un cas où deux textes proches en vecteur ont un sens opposé."],"learning_goals_en":["Explain what similarity between two vectors measures.","Give a case where two close vectors carry opposite meaning."],"tutor_focus_fr":"Fais classer trois phrases par proximité de sens, puis demande pourquoi une négation peut rester très proche de la phrase affirmative.","tutor_focus_en":"Have the student rank three sentences by closeness of meaning, then ask why a negation can stay very close to the affirmative sentence.","example_contexts_fr":["une recherche interne qui trouve des documents sans le mot exact","des articles regroupés par thème automatiquement","une phrase et sa négation jugées très proches"],"example_contexts_en":["an internal search finding documents without the exact word","articles automatically grouped by theme","a sentence and its negation judged very close"],"safety_category":"standard"},{"key":"artificial_intelligence.attention_mechanism","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":3,"order":20,"required":false,"prerequisite_keys":["artificial_intelligence.embeddings_meaning"],"fallback_key":"artificial_intelligence.temperature_sampling","title_fr":"Ce que fait le mécanisme d'attention","title_en":"What the attention mechanism does","summary_fr":"Comprendre comment un modèle pondère les mots du contexte pour interpréter le mot courant.","summary_en":"Understand how a model weighs context words to interpret the current word.","learning_goals_fr":["Expliquer la pondération des mots du contexte sur un exemple d'ambiguïté.","Dire pourquoi l'attention coûte cher quand le texte s'allonge."],"learning_goals_en":["Explain context weighting on an ambiguity example.","Say why attention gets expensive as text grows longer."],"tutor_focus_fr":"Fais désigner les mots qui lèvent l'ambiguïté de « il » dans une phrase, puis demande comment ce coût évolue avec la longueur du texte.","tutor_focus_en":"Have the student point out the words resolving “it” in a sentence, then ask how that cost grows with text length.","example_contexts_fr":["un pronom qui renvoie à l'un de deux personnages","un long contrat où une clause dépend d'une définition initiale","une traduction où le genre du mot dépend du contexte"],"example_contexts_en":["a pronoun referring to one of two characters","a long contract where a clause depends on an early definition","a translation where word gender depends on context"],"safety_category":"standard"},{"key":"artificial_intelligence.hallucination_causes","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":3,"order":21,"required":false,"prerequisite_keys":["artificial_intelligence.attention_mechanism"],"fallback_key":"artificial_intelligence.temperature_sampling","title_fr":"Pourquoi un modèle invente une référence","title_en":"Why a model invents a reference","summary_fr":"Relier l'invention à l'objectif de plausibilité plutôt qu'à une base de faits consultée.","summary_en":"Connect invention to an objective of plausibility rather than a consulted fact base.","learning_goals_fr":["Expliquer pourquoi une citation inventée paraît crédible.","Citer deux dispositifs qui réduisent le risque d'invention."],"learning_goals_en":["Explain why a fabricated citation looks credible.","Name two mechanisms that reduce the risk of invention."],"tutor_focus_fr":"Fais analyser une réponse contenant une référence inexistante, puis demande quel dispositif aurait empêché de la publier.","tutor_focus_en":"Have the student analyse an answer containing a non-existent reference, then ask which mechanism would have blocked publication.","example_contexts_fr":["une note juridique citant un article de loi inexistant","une bibliographie générée pour un mémoire","un numéro de version de bibliothèque inventé"],"example_contexts_en":["a legal note citing a non-existent statute","a bibliography generated for a dissertation","an invented library version number"],"safety_category":"standard"},{"key":"artificial_intelligence.context_window","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":3,"order":22,"required":false,"prerequisite_keys":["artificial_intelligence.hallucination_causes"],"fallback_key":"artificial_intelligence.temperature_sampling","title_fr":"La fenêtre de contexte et ce qui en sort","title_en":"The context window and what falls out of it","summary_fr":"Comprendre la limite de contexte et l'effet de la troncature sur une conversation longue.","summary_en":"Understand the context limit and the effect of truncation on a long conversation.","learning_goals_fr":["Calculer si un document tient dans une fenêtre donnée.","Expliquer ce que le modèle oublie lorsque la fenêtre est dépassée."],"learning_goals_en":["Compute whether a document fits in a given window.","Explain what the model forgets once the window overflows."],"tutor_focus_fr":"Fais estimer si un rapport de cinquante pages tient dans une fenêtre donnée, puis demande quelles informations disparaissent en premier.","tutor_focus_en":"Have the student estimate whether a fifty-page report fits a given window, then ask which information disappears first.","example_contexts_fr":["une conversation longue qui oublie la consigne initiale","un rapport de cinquante pages soumis en une fois","un historique de support client accumulé sur six mois"],"example_contexts_en":["a long conversation forgetting the initial instruction","a fifty-page report submitted at once","six months of accumulated support history"],"safety_category":"standard"},{"key":"artificial_intelligence.gradient_descent","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":3,"order":23,"required":true,"prerequisite_keys":["artificial_intelligence.loss_function"],"fallback_key":"artificial_intelligence.loss_function","title_fr":"La descente de gradient pas à pas","title_en":"Gradient descent step by step","summary_fr":"Suivre l'ajustement itératif des paramètres et l'effet du pas d'apprentissage sur la convergence.","summary_en":"Follow the iterative adjustment of parameters and the effect of the learning rate on convergence.","learning_goals_fr":["Décrire une itération complète de mise à jour des paramètres.","Prévoir le comportement avec un pas trop grand ou trop petit."],"learning_goals_en":["Describe one full parameter update iteration.","Predict the behaviour with a too large or too small step."],"tutor_focus_fr":"Fais dérouler trois itérations sur une fonction à une variable, puis demande ce qui se passe si le pas double à chaque fois.","tutor_focus_en":"Have the student run three iterations on a one-variable function, then ask what happens if the step doubles each time.","example_contexts_fr":["une courbe d'erreur qui descend puis stagne","un entraînement qui diverge dès les premières étapes","un modèle qui n'améliore plus rien après mille itérations"],"example_contexts_en":["an error curve dropping then flattening","a training run diverging from the first steps","a model improving nothing after a thousand iterations"],"safety_category":"standard"},{"key":"artificial_intelligence.classification_threshold","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":3,"order":24,"required":false,"prerequisite_keys":["artificial_intelligence.gradient_descent"],"fallback_key":"artificial_intelligence.loss_function","title_fr":"Le seuil de décision d'un classifieur","title_en":"The decision threshold of a classifier","summary_fr":"Transformer une probabilité en décision et mesurer l'effet du seuil sur les deux types d'erreurs.","summary_en":"Turn a probability into a decision and measure the threshold's effect on both error types.","learning_goals_fr":["Expliquer l'effet d'un seuil abaissé sur les faux positifs.","Fixer un seuil à partir d'un coût métier."],"learning_goals_en":["Explain the effect of lowering the threshold on false positives.","Set a threshold from a business cost."],"tutor_focus_fr":"Fais fixer un seuil pour une détection de fraude, puis demande combien de clients honnêtes seront bloqués à ce seuil.","tutor_focus_en":"Have the student set a threshold for fraud detection, then ask how many honest customers get blocked at that threshold.","example_contexts_fr":["une détection de fraude bancaire","un filtre de modération de commentaires","un test de dépistage à visée éducative"],"example_contexts_en":["bank fraud detection","a comment moderation filter","a screening test used as a teaching example"],"safety_category":"standard"},{"key":"artificial_intelligence.precision_recall","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":3,"order":25,"required":false,"prerequisite_keys":["artificial_intelligence.classification_threshold"],"fallback_key":"artificial_intelligence.loss_function","title_fr":"Précision et rappel : choisir son erreur","title_en":"Precision and recall: choosing your error","summary_fr":"Calculer précision et rappel sur une matrice de confusion et arbitrer selon l'usage.","summary_en":"Compute precision and recall from a confusion matrix and arbitrate by use case.","learning_goals_fr":["Calculer précision et rappel à partir d'une matrice de confusion.","Dire laquelle privilégier pour un usage donné."],"learning_goals_en":["Compute precision and recall from a confusion matrix.","Say which to favour for a given use."],"tutor_focus_fr":"Fais calculer précision et rappel sur une matrice de confusion donnée, puis demande laquelle privilégier pour un filtre anti-spam.","tutor_focus_en":"Have the student compute precision and recall on a given confusion matrix, then ask which to favour for a spam filter.","example_contexts_fr":["un filtre anti-spam qui bloque un message important","une recherche documentaire dans un fonds juridique","une alerte de maintenance préventive"],"example_contexts_en":["a spam filter blocking an important message","document search in a legal archive","a preventive maintenance alert"],"safety_category":"standard"},{"key":"artificial_intelligence.cross_validation","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":3,"order":26,"required":false,"prerequisite_keys":["artificial_intelligence.precision_recall"],"fallback_key":"artificial_intelligence.loss_function","title_fr":"La validation croisée","title_en":"Cross-validation","summary_fr":"Estimer la performance d'un modèle sur peu de données sans dépendre d'un découpage chanceux.","summary_en":"Estimate model performance on little data without depending on a lucky split.","learning_goals_fr":["Décrire une validation croisée en cinq blocs.","Dire pourquoi elle est nécessaire quand les données sont rares."],"learning_goals_en":["Describe a five-fold cross-validation.","Say why it is needed when data is scarce."],"tutor_focus_fr":"Fais décrire une validation croisée en cinq blocs, puis demande ce qu'elle change pour un jeu de deux cents exemples.","tutor_focus_en":"Have the student describe a five-fold cross-validation, then ask what it changes for a set of two hundred examples.","example_contexts_fr":["un jeu de deux cents dossiers médicaux anonymisés","deux découpages qui donnent des scores très différents","une comparaison entre trois modèles candidats"],"example_contexts_en":["a set of two hundred anonymised medical files","two splits giving very different scores","a comparison between three candidate models"],"safety_category":"standard"},{"key":"artificial_intelligence.rag_pipeline","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":3,"order":27,"required":true,"prerequisite_keys":["artificial_intelligence.structured_output"],"fallback_key":"artificial_intelligence.structured_output","title_fr":"Comment fonctionne une architecture RAG","title_en":"How a RAG architecture works","summary_fr":"Enchaîner recherche de passages pertinents et génération pour répondre à partir de documents propres.","summary_en":"Chain retrieval of relevant passages and generation to answer from your own documents.","learning_goals_fr":["Ordonner les étapes indexation, recherche, assemblage, génération.","Dire quelle étape est en cause quand la réponse cite un mauvais document."],"learning_goals_en":["Order the indexing, retrieval, assembly and generation stages.","Say which stage is at fault when the answer cites the wrong document."],"tutor_focus_fr":"Fais ordonner les étapes d'une chaîne RAG, puis demande quelle étape corriger quand la réponse s'appuie sur le mauvais document.","tutor_focus_en":"Have the student order the stages of a RAG chain, then ask which stage to fix when the answer relies on the wrong document.","example_contexts_fr":["un assistant qui répond à partir du manuel interne","une réponse correcte mais fondée sur une version périmée du document","une base documentaire de dix mille pages"],"example_contexts_en":["an assistant answering from the internal handbook","a correct answer based on an outdated document version","a documentation base of ten thousand pages"],"safety_category":"standard"},{"key":"artificial_intelligence.chunking_strategy","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":3,"order":28,"required":false,"prerequisite_keys":["artificial_intelligence.rag_pipeline"],"fallback_key":"artificial_intelligence.structured_output","title_fr":"Découper des documents pour la recherche","title_en":"Chunking documents for retrieval","summary_fr":"Choisir une taille de fragment qui garde le sens complet sans noyer la recherche.","summary_en":"Choose a chunk size that keeps meaning complete without drowning the search.","learning_goals_fr":["Expliquer l'effet d'un fragment trop court et d'un fragment trop long.","Proposer un découpage adapté à un document structuré."],"learning_goals_en":["Explain the effect of a too short and a too long chunk.","Propose a chunking suited to a structured document."],"tutor_focus_fr":"Fais découper un contrat en fragments, puis demande ce qui se perd si une clause est coupée en deux.","tutor_focus_en":"Have the student chunk a contract, then ask what is lost when a clause is split in two.","example_contexts_fr":["un contrat dont une clause est coupée en deux fragments","un manuel technique organisé en sections numérotées","une transcription de réunion sans titres"],"example_contexts_en":["a contract whose clause is split across two chunks","a technical manual organised in numbered sections","a meeting transcript with no headings"],"safety_category":"standard"},{"key":"artificial_intelligence.vector_search","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":3,"order":29,"required":false,"prerequisite_keys":["artificial_intelligence.chunking_strategy"],"fallback_key":"artificial_intelligence.structured_output","title_fr":"La recherche par similarité vectorielle","title_en":"Vector similarity search","summary_fr":"Comparer recherche par mots-clés et recherche vectorielle, et combiner les deux quand c'est utile.","summary_en":"Compare keyword search and vector search, and combine both when useful.","learning_goals_fr":["Citer un cas où la recherche par mots-clés bat la recherche vectorielle.","Expliquer ce qu'apporte une recherche hybride."],"learning_goals_en":["Give a case where keyword search beats vector search.","Explain what hybrid search brings."],"tutor_focus_fr":"Fais comparer les résultats des deux recherches sur une référence produit exacte, puis demande comment les combiner.","tutor_focus_en":"Have the student compare both searches on an exact product reference, then ask how to combine them.","example_contexts_fr":["une référence produit exacte cherchée par un client","une question posée avec d'autres mots que le document","un corpus contenant beaucoup d'acronymes internes"],"example_contexts_en":["an exact product reference searched by a customer","a question asked with different words than the document","a corpus full of internal acronyms"],"safety_category":"standard"},{"key":"artificial_intelligence.latency_cost_budget","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":3,"order":30,"required":false,"prerequisite_keys":["artificial_intelligence.vector_search"],"fallback_key":"artificial_intelligence.structured_output","title_fr":"Budget de latence et de coût par requête","title_en":"Latency and cost budget per request","summary_fr":"Répartir un budget de temps et d'argent entre les étapes d'une chaîne de génération.","summary_en":"Split a time and money budget across the stages of a generation chain.","learning_goals_fr":["Décomposer la latence d'une réponse en étapes mesurables.","Identifier l'étape à optimiser en premier."],"learning_goals_en":["Break down response latency into measurable stages.","Identify the stage to optimise first."],"tutor_focus_fr":"Fais décomposer une réponse de quatre secondes en étapes chiffrées, puis demande laquelle optimiser en premier et pourquoi.","tutor_focus_en":"Have the student break a four-second response into timed stages, then ask which to optimise first and why.","example_contexts_fr":["un assistant qui répond en quatre secondes","une chaîne qui appelle deux modèles successifs","un budget mensuel dépassé en trois semaines"],"example_contexts_en":["an assistant answering in four seconds","a chain calling two models in sequence","a monthly budget exhausted in three weeks"],"safety_category":"standard"},{"key":"artificial_intelligence.pretraining_finetuning","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":4,"order":31,"required":true,"prerequisite_keys":["artificial_intelligence.context_window"],"fallback_key":"artificial_intelligence.context_window","title_fr":"Pré-entraînement, ajustement fin et alignement","title_en":"Pre-training, fine-tuning and alignment","summary_fr":"Distinguer les trois étapes qui transforment un modèle brut en assistant utilisable.","summary_en":"Tell apart the three stages that turn a raw model into a usable assistant.","learning_goals_fr":["Associer chaque étape au type de données qu'elle consomme.","Dire quelle étape corrige un ton inadapté."],"learning_goals_en":["Match each stage to the kind of data it consumes.","Say which stage fixes an inappropriate tone."],"tutor_focus_fr":"Fais associer chaque étape aux données qu'elle utilise, puis demande laquelle corrigerait un modèle au style trop familier.","tutor_focus_en":"Have the student match each stage to its data, then ask which one would fix a model whose style is too casual.","example_contexts_fr":["un modèle brut qui complète du texte sans répondre aux questions","un assistant spécialisé sur le vocabulaire d'une entreprise","un modèle qui refuse une demande dangereuse"],"example_contexts_en":["a raw model completing text instead of answering","an assistant specialised in a company's vocabulary","a model refusing a dangerous request"],"safety_category":"standard"},{"key":"artificial_intelligence.learning_from_preferences","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":4,"order":32,"required":false,"prerequisite_keys":["artificial_intelligence.pretraining_finetuning"],"fallback_key":"artificial_intelligence.context_window","title_fr":"Apprendre à partir de préférences humaines","title_en":"Learning from human preferences","summary_fr":"Comprendre comment des comparaisons entre deux réponses orientent le comportement d'un modèle.","summary_en":"Understand how comparisons between two answers steer a model's behaviour.","learning_goals_fr":["Décrire la boucle comparaison, modèle de récompense, ajustement.","Citer un effet indésirable d'une récompense mal définie."],"learning_goals_en":["Describe the loop of comparison, reward model and tuning.","Name an unwanted effect of a badly defined reward."],"tutor_focus_fr":"Fais décrire la boucle d'apprentissage par préférences, puis demande ce qui arrive si les évaluateurs préfèrent systématiquement les réponses longues.","tutor_focus_en":"Have the student describe the preference learning loop, then ask what happens if raters systematically prefer long answers.","example_contexts_fr":["deux réponses proposées à des évaluateurs humains","un assistant devenu exagérément complaisant","des réponses de plus en plus longues sans gain d'information"],"example_contexts_en":["two answers shown to human raters","an assistant that became excessively agreeable","answers growing longer with no added information"],"safety_category":"standard"},{"key":"artificial_intelligence.eval_benchmarks","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":4,"order":33,"required":false,"prerequisite_keys":["artificial_intelligence.learning_from_preferences"],"fallback_key":"artificial_intelligence.context_window","title_fr":"Ce que mesure vraiment un score de benchmark","title_en":"What a benchmark score really measures","summary_fr":"Lire un classement de modèles en tenant compte de la contamination et de l'écart avec l'usage réel.","summary_en":"Read a model leaderboard accounting for contamination and the gap with real usage.","learning_goals_fr":["Expliquer ce qu'une contamination du jeu de test invalide.","Dire pourquoi un score élevé ne garantit pas un bon usage métier."],"learning_goals_en":["Explain what test-set contamination invalidates.","Say why a high score does not guarantee good business use."],"tutor_focus_fr":"Fais critiquer une annonce de score record, puis demande quelle évaluation serait pertinente pour un cas d'usage précis.","tutor_focus_en":"Have the student critique a record-score announcement, then ask which evaluation would be relevant for one precise use case.","example_contexts_fr":["un classement public de modèles de langue","un jeu de test publié depuis trois ans sur Internet","un modèle excellent en examen mais faible sur des e-mails clients"],"example_contexts_en":["a public leaderboard of language models","a test set published on the internet three years ago","a model excellent at exams but weak on customer emails"],"safety_category":"standard"},{"key":"artificial_intelligence.prompt_sensitivity","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":4,"order":34,"required":false,"prerequisite_keys":["artificial_intelligence.eval_benchmarks"],"fallback_key":"artificial_intelligence.context_window","title_fr":"Pourquoi une reformulation change la réponse","title_en":"Why rewording changes the answer","summary_fr":"Mesurer la sensibilité d'un modèle à la formulation et en tirer une méthode de test.","summary_en":"Measure a model's sensitivity to phrasing and turn it into a testing method.","learning_goals_fr":["Construire deux formulations équivalentes d'une même demande.","Décider quand une variation de réponse est acceptable."],"learning_goals_en":["Build two equivalent phrasings of one request.","Decide when a variation in the answer is acceptable."],"tutor_focus_fr":"Fais écrire deux formulations équivalentes d'une même consigne, puis demande comment vérifier que le modèle répond pareil sur cinquante cas.","tutor_focus_en":"Have the student write two equivalent phrasings of one instruction, then ask how to check the model answers the same over fifty cases.","example_contexts_fr":["une même question posée poliment puis sèchement","une consigne traduite du français vers l'anglais","un ordre de champs modifié dans une demande d'extraction"],"example_contexts_en":["the same question asked politely then bluntly","an instruction translated from French to English","a reordered field list in an extraction request"],"safety_category":"standard"},{"key":"artificial_intelligence.decision_trees_forests","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":4,"order":35,"required":true,"prerequisite_keys":["artificial_intelligence.cross_validation"],"fallback_key":"artificial_intelligence.cross_validation","title_fr":"Arbres de décision et forêts aléatoires","title_en":"Decision trees and random forests","summary_fr":"Comprendre la construction d'un arbre par découpes successives et l'apport du vote d'un ensemble.","summary_en":"Understand tree construction by successive splits and what an ensemble vote adds.","learning_goals_fr":["Lire un arbre de décision et suivre le chemin d'un exemple.","Expliquer ce qu'apporte le vote de plusieurs arbres."],"learning_goals_en":["Read a decision tree and follow one example's path.","Explain what the vote of several trees brings."],"tutor_focus_fr":"Fais suivre un dossier dans un petit arbre de décision, puis demande pourquoi cent arbres différents se trompent moins souvent qu'un seul.","tutor_focus_en":"Have the student follow a file through a small decision tree, then ask why a hundred different trees are wrong less often than one.","example_contexts_fr":["un dossier de prêt suivi de nœud en nœud","un arbre profond qui colle exactement aux données d'entraînement","un score de risque qui doit rester explicable"],"example_contexts_en":["a loan file followed node by node","a deep tree matching the training data exactly","a risk score that must stay explainable"],"safety_category":"standard"},{"key":"artificial_intelligence.feature_engineering","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":4,"order":36,"required":false,"prerequisite_keys":["artificial_intelligence.decision_trees_forests"],"fallback_key":"artificial_intelligence.cross_validation","title_fr":"Construire une caractéristique utile","title_en":"Building a useful feature","summary_fr":"Transformer une donnée brute en variable porteuse d'information pour le modèle.","summary_en":"Turn raw data into a variable that carries information for the model.","learning_goals_fr":["Dériver deux caractéristiques utiles à partir d'une date brute.","Repérer une caractéristique qui ne sera pas disponible au moment de la prédiction."],"learning_goals_en":["Derive two useful features from a raw date.","Spot a feature that will not be available at prediction time."],"tutor_focus_fr":"Fais dériver trois variables à partir d'une date de commande, puis demande laquelle ne serait pas connue au moment de prédire.","tutor_focus_en":"Have the student derive three variables from an order date, then ask which one would not be known at prediction time.","example_contexts_fr":["une date de commande transformée en jour de semaine","une adresse convertie en distance au dépôt","un texte libre résumé en longueur et en présence de mots-clés"],"example_contexts_en":["an order date turned into a weekday","an address converted into distance to the depot","free text reduced to length and keyword presence"],"safety_category":"standard"},{"key":"artificial_intelligence.regularization","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":4,"order":37,"required":false,"prerequisite_keys":["artificial_intelligence.feature_engineering"],"fallback_key":"artificial_intelligence.cross_validation","title_fr":"Régularisation : pénaliser la complexité","title_en":"Regularisation: penalising complexity","summary_fr":"Ajouter une pénalité sur les coefficients pour préférer un modèle plus simple et plus stable.","summary_en":"Add a penalty on coefficients to prefer a simpler and more stable model.","learning_goals_fr":["Expliquer ce qu'une pénalité impose aux coefficients.","Prévoir l'effet d'une pénalité trop forte."],"learning_goals_en":["Explain what a penalty imposes on coefficients.","Predict the effect of a too strong penalty."],"tutor_focus_fr":"Fais comparer les coefficients avec et sans pénalité, puis demande ce qui se passe quand la pénalité devient très grande.","tutor_focus_en":"Have the student compare coefficients with and without penalty, then ask what happens when the penalty becomes very large.","example_contexts_fr":["un modèle à trois cents variables et cinq cents exemples","des coefficients qui changent complètement d'un mois à l'autre","une sélection automatique des variables utiles"],"example_contexts_en":["a model with three hundred variables and five hundred examples","coefficients changing completely from month to month","an automatic selection of useful variables"],"safety_category":"standard"},{"key":"artificial_intelligence.imbalanced_data","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":4,"order":38,"required":false,"prerequisite_keys":["artificial_intelligence.regularization"],"fallback_key":"artificial_intelligence.cross_validation","title_fr":"Données déséquilibrées et métriques trompeuses","title_en":"Imbalanced data and misleading metrics","summary_fr":"Reconnaître qu'une exactitude élevée peut décrire un modèle qui ne détecte jamais la classe rare.","summary_en":"Recognise that high accuracy can describe a model that never detects the rare class.","learning_goals_fr":["Calculer l'exactitude d'un modèle qui prédit toujours la classe majoritaire.","Choisir une métrique adaptée à une classe rare."],"learning_goals_en":["Compute the accuracy of a model always predicting the majority class.","Choose a metric suited to a rare class."],"tutor_focus_fr":"Fais calculer l'exactitude d'un modèle qui répond toujours « non » sur un problème à 1 % de positifs, puis demande quelle métrique utiliser.","tutor_focus_en":"Have the student compute the accuracy of a model always answering “no” on a 1% positive problem, then ask which metric to use.","example_contexts_fr":["une fraude présente dans un paiement sur mille","une panne rare sur une flotte de machines","un modèle à 99 % d'exactitude qui ne détecte rien"],"example_contexts_en":["fraud present in one payment out of a thousand","a rare failure across a fleet of machines","a 99% accurate model detecting nothing"],"safety_category":"standard"},{"key":"artificial_intelligence.tool_calling","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":4,"order":39,"required":true,"prerequisite_keys":["artificial_intelligence.latency_cost_budget"],"fallback_key":"artificial_intelligence.latency_cost_budget","title_fr":"Donner des outils à un modèle","title_en":"Giving tools to a model","summary_fr":"Décrire des fonctions appelables et contrôler ce que le modèle a le droit de déclencher.","summary_en":"Describe callable functions and control what the model is allowed to trigger.","learning_goals_fr":["Décrire un outil par son nom, ses paramètres et son effet.","Dire quels outils ne doivent jamais être exposés sans confirmation."],"learning_goals_en":["Describe a tool by its name, parameters and effect.","Say which tools must never be exposed without confirmation."],"tutor_focus_fr":"Fais décrire deux outils avec leurs paramètres, puis demande lequel exige une confirmation humaine avant exécution.","tutor_focus_en":"Have the student describe two tools with their parameters, then ask which one requires human confirmation before running.","example_contexts_fr":["une consultation de stock en lecture seule","un remboursement client déclenché automatiquement","un envoi d'e-mail au nom de l'entreprise"],"example_contexts_en":["a read-only stock lookup","a customer refund triggered automatically","an email sent on behalf of the company"],"safety_category":"standard"},{"key":"artificial_intelligence.agent_loop","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":4,"order":40,"required":false,"prerequisite_keys":["artificial_intelligence.tool_calling"],"fallback_key":"artificial_intelligence.latency_cost_budget","title_fr":"La boucle d'un agent et sa condition d'arrêt","title_en":"An agent loop and its stopping condition","summary_fr":"Encadrer une boucle observer-décider-agir par un budget d'étapes et un critère de succès.","summary_en":"Bound an observe-decide-act loop with a step budget and a success criterion.","learning_goals_fr":["Décrire une itération complète de la boucle d'un agent.","Définir une condition d'arrêt vérifiable."],"learning_goals_en":["Describe one full iteration of an agent loop.","Define a verifiable stopping condition."],"tutor_focus_fr":"Fais définir la condition d'arrêt d'un agent de recherche documentaire, puis demande ce qui se passe sans limite d'étapes.","tutor_focus_en":"Have the student define the stopping condition of a document research agent, then ask what happens with no step limit.","example_contexts_fr":["un agent qui relance indéfiniment le même appel","une tâche de recherche en plusieurs étapes","un budget de dix appels d'outils par demande"],"example_contexts_en":["an agent retrying the same call forever","a multi-step research task","a budget of ten tool calls per request"],"safety_category":"standard"},{"key":"artificial_intelligence.guardrails_validation","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":4,"order":41,"required":false,"prerequisite_keys":["artificial_intelligence.agent_loop"],"fallback_key":"artificial_intelligence.latency_cost_budget","title_fr":"Valider une sortie de modèle avant de l'utiliser","title_en":"Validating a model output before using it","summary_fr":"Placer des vérifications déterministes entre la génération et l'action effectuée par le produit.","summary_en":"Place deterministic checks between generation and the action the product performs.","learning_goals_fr":["Lister les contrôles à appliquer avant d'enregistrer une sortie.","Choisir le comportement en cas d'échec de validation."],"learning_goals_en":["List the checks to apply before persisting an output.","Choose the behaviour when validation fails."],"tutor_focus_fr":"Fais lister les contrôles avant d'enregistrer un montant extrait automatiquement, puis demande quoi faire quand un contrôle échoue.","tutor_focus_en":"Have the student list the checks before saving an automatically extracted amount, then ask what to do when a check fails.","example_contexts_fr":["un montant extrait puis enregistré en comptabilité","un texte publié directement sur un site public","une réponse contenant une donnée personnelle"],"example_contexts_en":["an amount extracted then written into accounting","text published directly on a public site","an answer containing personal data"],"safety_category":"standard"},{"key":"artificial_intelligence.caching_llm_calls","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":4,"order":42,"required":false,"prerequisite_keys":["artificial_intelligence.guardrails_validation"],"fallback_key":"artificial_intelligence.latency_cost_budget","title_fr":"Mettre en cache des réponses de modèle","title_en":"Caching model responses","summary_fr":"Identifier les appels réellement répétés et construire une clé de cache qui ne mélange pas deux demandes.","summary_en":"Identify genuinely repeated calls and build a cache key that never merges two requests.","learning_goals_fr":["Construire une clé de cache à partir des éléments qui changent la réponse.","Citer un cas où le cache produirait une réponse fausse."],"learning_goals_en":["Build a cache key from the elements that change the answer.","Give a case where the cache would return a wrong answer."],"tutor_focus_fr":"Fais construire la clé de cache d'une génération de description produit, puis demande ce qui arriverait si la langue n'entrait pas dans la clé.","tutor_focus_en":"Have the student build the cache key of a product description generation, then ask what happens if language is not part of the key.","example_contexts_fr":["la même question posée par cent utilisateurs","une génération identique dans deux langues différentes","un prompt modifié sans changement de clé"],"example_contexts_en":["the same question asked by a hundred users","an identical generation in two different languages","a prompt changed without changing the key"],"safety_category":"standard"},{"key":"artificial_intelligence.reasoning_steps","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":5,"order":43,"required":true,"prerequisite_keys":["artificial_intelligence.prompt_sensitivity"],"fallback_key":"artificial_intelligence.prompt_sensitivity","title_fr":"Raisonnement pas à pas et ses limites","title_en":"Step-by-step reasoning and its limits","summary_fr":"Comprendre ce que le raisonnement explicite améliore et pourquoi il ne garantit pas la justesse.","summary_en":"Understand what explicit reasoning improves and why it does not guarantee correctness.","learning_goals_fr":["Citer un type de tâche où le raisonnement explicite aide nettement.","Expliquer pourquoi une justification cohérente peut accompagner un résultat faux."],"learning_goals_en":["Name a task type where explicit reasoning clearly helps.","Explain why a coherent justification can accompany a wrong result."],"tutor_focus_fr":"Fais analyser une résolution détaillée qui aboutit à un résultat faux, puis demande à quelle étape la vérification aurait dû intervenir.","tutor_focus_en":"Have the student analyse a detailed solution reaching a wrong result, then ask at which step verification should have happened.","example_contexts_fr":["un problème arithmétique à plusieurs étapes","une justification élégante mais fausse","un calcul de dates avec années bissextiles"],"example_contexts_en":["a multi-step arithmetic problem","an elegant but wrong justification","a date computation involving leap years"],"safety_category":"standard"},{"key":"artificial_intelligence.model_distillation","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":5,"order":44,"required":false,"prerequisite_keys":["artificial_intelligence.reasoning_steps"],"fallback_key":"artificial_intelligence.prompt_sensitivity","title_fr":"Distiller un grand modèle en petit modèle","title_en":"Distilling a large model into a small one","summary_fr":"Comprendre le transfert de comportement d'un grand modèle vers un modèle plus petit et moins cher.","summary_en":"Understand the transfer of behaviour from a large model to a smaller, cheaper one.","learning_goals_fr":["Décrire ce que le petit modèle apprend du grand.","Dire ce qui se dégrade en premier après distillation."],"learning_goals_en":["Describe what the small model learns from the large one.","Say what degrades first after distillation."],"tutor_focus_fr":"Fais décrire ce que le petit modèle apprend exactement, puis demande sur quel type de tâche l'écart réapparaît en premier.","tutor_focus_en":"Have the student describe exactly what the small model learns, then ask on which task type the gap reappears first.","example_contexts_fr":["un modèle embarqué sur un téléphone sans réseau","un service de classification à très fort volume","un assistant spécialisé sur un seul domaine métier"],"example_contexts_en":["a model embedded on a phone with no network","a very high volume classification service","an assistant specialised in a single business domain"],"safety_category":"standard"},{"key":"artificial_intelligence.multimodal_models","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":5,"order":45,"required":false,"prerequisite_keys":["artificial_intelligence.model_distillation"],"fallback_key":"artificial_intelligence.prompt_sensitivity","title_fr":"Ce qu'un modèle multimodal aligne réellement","title_en":"What a multimodal model actually aligns","summary_fr":"Comprendre la mise en correspondance d'images et de textes dans un même espace de représentation.","summary_en":"Understand how images and texts are mapped into a shared representation space.","learning_goals_fr":["Expliquer ce que signifie aligner une image et une légende.","Citer une erreur typique de lecture d'image."],"learning_goals_en":["Explain what aligning an image and a caption means.","Name a typical image-reading error."],"tutor_focus_fr":"Fais expliquer comment une image et sa légende deviennent comparables, puis demande pourquoi un tableau chiffré photographié reste difficile à lire.","tutor_focus_en":"Have the student explain how an image and its caption become comparable, then ask why a photographed numeric table stays hard to read.","example_contexts_fr":["une photo de facture dont on extrait le montant","une recherche d'images par description textuelle","un graphique photographié dont on demande la tendance"],"example_contexts_en":["a photographed invoice whose amount is extracted","an image search from a text description","a photographed chart whose trend is requested"],"safety_category":"standard"},{"key":"artificial_intelligence.interpretability_probes","domain_id":"artificial_intelligence","objective_ids":["ai_foundations"],"stage":5,"order":46,"required":false,"prerequisite_keys":["artificial_intelligence.multimodal_models"],"fallback_key":"artificial_intelligence.prompt_sensitivity","title_fr":"Ouvrir la boîte : sondes et interprétabilité","title_en":"Opening the box: probes and interpretability","summary_fr":"Découvrir les méthodes qui relient une décision du modèle à des éléments internes ou à des entrées.","summary_en":"Discover the methods linking a model decision to internal elements or to inputs.","learning_goals_fr":["Distinguer une explication locale d'une explication globale.","Dire ce qu'une carte d'importance ne prouve pas."],"learning_goals_en":["Tell apart a local explanation and a global explanation.","Say what an importance map does not prove."],"tutor_focus_fr":"Fais interpréter une carte d'importance sur un refus de crédit, puis demande ce que cette carte ne permet pas de conclure.","tutor_focus_en":"Have the student interpret an importance map on a credit refusal, then ask what that map cannot establish.","example_contexts_fr":["un refus de crédit à justifier auprès d'un client","une image dont on colore les zones décisives","un audit réglementaire d'un modèle de scoring"],"example_contexts_en":["a credit refusal to justify to a customer","an image with decisive regions highlighted","a regulatory audit of a scoring model"],"safety_category":"standard"},{"key":"artificial_intelligence.neural_network_layers","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":5,"order":47,"required":true,"prerequisite_keys":["artificial_intelligence.imbalanced_data"],"fallback_key":"artificial_intelligence.imbalanced_data","title_fr":"Ce qu'ajoute une couche cachée","title_en":"What a hidden layer adds","summary_fr":"Comprendre pourquoi une non-linéarité permet d'apprendre des frontières qu'une droite ne peut pas tracer.","summary_en":"Understand why a non-linearity allows learning boundaries a straight line cannot draw.","learning_goals_fr":["Expliquer le rôle de la fonction d'activation.","Donner un problème qu'un modèle linéaire ne peut pas résoudre."],"learning_goals_en":["Explain the role of the activation function.","Give a problem a linear model cannot solve."],"tutor_focus_fr":"Fais expliquer pourquoi empiler des couches sans activation revient à une seule couche, puis demande un problème que cela rendrait insoluble.","tutor_focus_en":"Have the student explain why stacking layers without activation collapses to one layer, then ask which problem that makes unsolvable.","example_contexts_fr":["une séparation de deux nuages de points imbriqués","une reconnaissance de chiffres manuscrits","un réseau à dix couches sans fonction d'activation"],"example_contexts_en":["separating two interlocked point clouds","recognising handwritten digits","a ten-layer network with no activation function"],"safety_category":"standard"},{"key":"artificial_intelligence.backpropagation","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":5,"order":48,"required":false,"prerequisite_keys":["artificial_intelligence.neural_network_layers"],"fallback_key":"artificial_intelligence.imbalanced_data","title_fr":"La rétropropagation","title_en":"Backpropagation","summary_fr":"Comprendre comment l'erreur finale est répartie sur chaque paramètre pour le corriger.","summary_en":"Understand how the final error is distributed onto each parameter to correct it.","learning_goals_fr":["Décrire le sens de circulation de l'erreur dans le réseau.","Expliquer ce qu'est un gradient qui s'évanouit."],"learning_goals_en":["Describe the direction the error travels through the network.","Explain what a vanishing gradient is."],"tutor_focus_fr":"Fais décrire le trajet de l'erreur de la sortie vers les premières couches, puis demande pourquoi les premières couches apprennent parfois très lentement.","tutor_focus_en":"Have the student describe the error's path from output to first layers, then ask why early layers sometimes learn very slowly.","example_contexts_fr":["un réseau profond dont les premières couches n'évoluent plus","une erreur de sortie répartie sur des milliers de poids","un entraînement suivi couche par couche"],"example_contexts_en":["a deep network whose first layers stop changing","an output error spread over thousands of weights","a training run monitored layer by layer"],"safety_category":"standard"},{"key":"artificial_intelligence.clustering_kmeans","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":5,"order":49,"required":false,"prerequisite_keys":["artificial_intelligence.backpropagation"],"fallback_key":"artificial_intelligence.imbalanced_data","title_fr":"Le regroupement par k-moyennes","title_en":"K-means clustering","summary_fr":"Former des groupes sans étiquettes et mesurer ce que le choix du nombre de groupes impose.","summary_en":"Form groups without labels and see what choosing the number of groups imposes.","learning_goals_fr":["Décrire l'alternance affectation et recalcul des centres.","Expliquer pourquoi deux exécutions peuvent donner des groupes différents."],"learning_goals_en":["Describe the alternation of assignment and centre recomputation.","Explain why two runs can produce different groups."],"tutor_focus_fr":"Fais dérouler deux itérations de k-moyennes sur six points, puis demande comment choisir le nombre de groupes sans étiquettes.","tutor_focus_en":"Have the student run two k-means iterations over six points, then ask how to choose the number of groups without labels.","example_contexts_fr":["une segmentation de clients par montant et fréquence d'achat","des capteurs regroupés par profil de mesure","deux exécutions qui produisent des groupes différents"],"example_contexts_en":["customer segmentation by purchase amount and frequency","sensors grouped by measurement profile","two runs producing different groups"],"safety_category":"standard"},{"key":"artificial_intelligence.dimensionality_reduction","domain_id":"artificial_intelligence","objective_ids":["ai_machine_learning"],"stage":5,"order":50,"required":false,"prerequisite_keys":["artificial_intelligence.clustering_kmeans"],"fallback_key":"artificial_intelligence.imbalanced_data","title_fr":"Réduction de dimension et analyse en composantes principales","title_en":"Dimensionality reduction and principal component analysis","summary_fr":"Projeter des données à nombreuses variables en gardant l'essentiel de leur variance.","summary_en":"Project data with many variables while keeping most of its variance.","learning_goals_fr":["Expliquer ce que conserve une projection en deux dimensions.","Dire ce qui est perdu et pourquoi c'est parfois acceptable."],"learning_goals_en":["Explain what a two-dimensional projection preserves.","Say what is lost and why that is sometimes acceptable."],"tutor_focus_fr":"Fais interpréter une projection expliquant 80 % de la variance, puis demande ce que représentent les 20 % restants.","tutor_focus_en":"Have the student interpret a projection explaining 80% of variance, then ask what the remaining 20% represents.","example_contexts_fr":["cinquante mesures de capteurs projetées sur un plan","une visualisation de clients en deux dimensions","un modèle accéléré en réduisant les variables d'entrée"],"example_contexts_en":["fifty sensor measurements projected onto a plane","a two-dimensional visualisation of customers","a model sped up by reducing input variables"],"safety_category":"standard"},{"key":"artificial_intelligence.product_eval_set","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":5,"order":51,"required":true,"prerequisite_keys":["artificial_intelligence.caching_llm_calls"],"fallback_key":"artificial_intelligence.caching_llm_calls","title_fr":"Construire un jeu d'évaluation pour son produit","title_en":"Building an evaluation set for your product","summary_fr":"Constituer des cas représentatifs et une règle de notation stable pour comparer deux versions.","summary_en":"Assemble representative cases and a stable scoring rule to compare two versions.","learning_goals_fr":["Choisir des cas qui couvrent les usages réels et les cas difficiles.","Définir une notation reproductible par deux personnes différentes."],"learning_goals_en":["Choose cases covering real usage and hard cases.","Define a scoring reproducible by two different people."],"tutor_focus_fr":"Fais constituer dix cas d'évaluation pour un assistant de support, puis demande comment noter sans dépendre de l'humeur de l'évaluateur.","tutor_focus_en":"Have the student assemble ten evaluation cases for a support assistant, then ask how to score without depending on the rater's mood.","example_contexts_fr":["une comparaison entre deux versions d'un prompt","un changement de modèle fournisseur","des cas rares signalés par le service client"],"example_contexts_en":["a comparison between two prompt versions","a change of model provider","rare cases reported by customer service"],"safety_category":"standard"},{"key":"artificial_intelligence.fallback_and_degradation","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":5,"order":52,"required":false,"prerequisite_keys":["artificial_intelligence.product_eval_set"],"fallback_key":"artificial_intelligence.caching_llm_calls","title_fr":"Que faire quand le modèle échoue","title_en":"What to do when the model fails","summary_fr":"Concevoir une dégradation lisible plutôt qu'une erreur brute quand la génération est impossible.","summary_en":"Design a readable degradation rather than a raw error when generation is impossible.","learning_goals_fr":["Distinguer réessai, repli et échec assumé.","Choisir la réponse produit quand aucune génération n'aboutit."],"learning_goals_en":["Tell apart retry, fallback and accepted failure.","Choose the product answer when no generation succeeds."],"tutor_focus_fr":"Fais choisir le comportement produit quand le modèle est indisponible dix minutes, puis demande ce que l'utilisateur doit voir exactement.","tutor_focus_en":"Have the student choose the product behaviour when the model is down for ten minutes, then ask what the user must see exactly.","example_contexts_fr":["une panne du fournisseur pendant dix minutes","une sortie invalide malgré deux tentatives","un dépassement de quota en pleine journée"],"example_contexts_en":["a provider outage lasting ten minutes","an invalid output despite two attempts","a quota exceeded in the middle of the day"],"safety_category":"standard"},{"key":"artificial_intelligence.finetuning_vs_prompting","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":5,"order":53,"required":false,"prerequisite_keys":["artificial_intelligence.fallback_and_degradation"],"fallback_key":"artificial_intelligence.caching_llm_calls","title_fr":"Ajuster un modèle ou améliorer le prompt","title_en":"Fine-tuning a model or improving the prompt","summary_fr":"Arbitrer entre ajustement fin, exemples dans le prompt et recherche documentaire selon le problème observé.","summary_en":"Arbitrate between fine-tuning, in-prompt examples and retrieval based on the observed problem.","learning_goals_fr":["Associer un symptôme observé au bon levier de correction.","Citer ce que l'ajustement fin ne corrige pas."],"learning_goals_en":["Match an observed symptom to the right corrective lever.","State what fine-tuning does not fix."],"tutor_focus_fr":"Fais choisir le levier adapté à trois symptômes : mauvais format, faits manquants, ton inadapté, en demandant de justifier.","tutor_focus_en":"Have the student pick the right lever for three symptoms: wrong format, missing facts, wrong tone, justifying each.","example_contexts_fr":["un format de sortie régulièrement incorrect","des faits internes absents des réponses","un ton inadapté à la marque"],"example_contexts_en":["an output format regularly incorrect","internal facts missing from answers","a tone that does not match the brand"],"safety_category":"standard"},{"key":"artificial_intelligence.prompt_injection_defense","domain_id":"artificial_intelligence","objective_ids":["ai_building"],"stage":5,"order":54,"required":false,"prerequisite_keys":["artificial_intelligence.finetuning_vs_prompting"],"fallback_key":"artificial_intelligence.caching_llm_calls","title_fr":"Se protéger de l'injection de prompt","title_en":"Defending against prompt injection","summary_fr":"Traiter tout contenu externe comme non fiable et séparer les instructions des données lues.","summary_en":"Treat all external content as untrusted and keep instructions separate from read data.","learning_goals_fr":["Expliquer pourquoi un document lu peut contenir une instruction hostile.","Citer deux protections qui limitent l'impact d'une injection."],"learning_goals_en":["Explain why a read document can contain a hostile instruction.","Name two protections limiting the impact of an injection."],"tutor_focus_fr":"Fais analyser une page web contenant une instruction cachée destinée à l'assistant, puis demande quelles limites d'outils réduisent le risque.","tutor_focus_en":"Have the student analyse a web page containing a hidden instruction aimed at the assistant, then ask which tool limits reduce the risk.","example_contexts_fr":["une page web lue par un assistant de navigation","un e-mail entrant contenant une consigne cachée","un document partagé par un tiers externe"],"example_contexts_en":["a web page read by a browsing assistant","an incoming email carrying a hidden instruction","a document shared by an external third party"],"safety_category":"standard"}]}$catalog$::jsonb)
ON CONFLICT (domain_id) DO UPDATE
SET version = EXCLUDED.version, payload = EXCLUDED.payload, updated_at = now();

INSERT INTO public.learning_catalog_domains (domain_id, version, payload)
VALUES ($catalog$blockchain$catalog$, $catalog$v1$catalog$, $catalog${"version":"v1","steps":[{"key":"blockchain.double_spend_problem","domain_id":"blockchain","objective_ids":["blockchain_foundations","blockchain_ecosystem","blockchain_building"],"stage":1,"order":1,"required":true,"prerequisite_keys":[],"fallback_key":null,"title_fr":"Le problème de la double dépense","title_en":"The double-spending problem","summary_fr":"Comprendre pourquoi un fichier monétaire copiable exige un ordre commun accepté par tous.","summary_en":"Understand why copyable digital money requires one shared order everyone accepts.","learning_goals_fr":["Expliquer pourquoi une monnaie numérique se copie trivialement.","Dire ce qu'un registre partagé résout que la copie ne résout pas."],"learning_goals_en":["Explain why digital money is trivially copied.","Say what a shared ledger solves that copying does not."],"tutor_focus_fr":"Fais raconter ce qui se passe si le même euro numérique est envoyé à deux marchands en même temps, puis demande ce qui doit être partagé pour l'empêcher.","tutor_focus_en":"Have the student narrate the same digital euro sent to two merchants at once, then ask what must be shared to prevent it.","example_contexts_fr":["le même paiement envoyé à deux marchands","un fichier de monnaie dupliqué par copier-coller","un chèque encaissé deux fois dans deux agences"],"example_contexts_en":["the same payment sent to two merchants","a money file duplicated by copy and paste","a cheque cashed twice in two branches"],"safety_category":"standard"},{"key":"blockchain.hash_function_basics","domain_id":"blockchain","objective_ids":["blockchain_foundations","blockchain_ecosystem","blockchain_building"],"stage":1,"order":2,"required":true,"prerequisite_keys":["blockchain.double_spend_problem"],"fallback_key":null,"title_fr":"Ce que fait une fonction de hachage","title_en":"What a hash function does","summary_fr":"Comprendre l'empreinte de taille fixe, sa sensibilité au moindre changement et son irréversibilité.","summary_en":"Understand the fixed-size fingerprint, its sensitivity to any change and its irreversibility.","learning_goals_fr":["Citer trois propriétés attendues d'une fonction de hachage.","Expliquer pourquoi on ne retrouve pas le document à partir de son empreinte."],"learning_goals_en":["State three expected properties of a hash function.","Explain why the document cannot be recovered from its fingerprint."],"tutor_focus_fr":"Fais prédire l'effet d'une virgule ajoutée dans un contrat sur son empreinte, puis demande pourquoi l'inverse est impossible.","tutor_focus_en":"Have the student predict the effect of one added comma in a contract on its fingerprint, then ask why the inverse is impossible.","example_contexts_fr":["un contrat dont on veut prouver qu'il n'a pas bougé","un mot de passe stocké sous forme d'empreinte","une somme de contrôle affichée à côté d'un téléchargement"],"example_contexts_en":["a contract you want to prove unchanged","a password stored as a fingerprint","a checksum shown next to a download"],"safety_category":"standard"},{"key":"blockchain.blocks_and_chain","domain_id":"blockchain","objective_ids":["blockchain_foundations","blockchain_ecosystem","blockchain_building"],"stage":1,"order":3,"required":true,"prerequisite_keys":["blockchain.hash_function_basics"],"fallback_key":null,"title_fr":"Comment des blocs forment une chaîne","title_en":"How blocks form a chain","summary_fr":"Voir que chaque bloc contient l'empreinte du précédent et que modifier le passé casse toute la suite.","summary_en":"See that each block carries the previous block's hash, so changing the past breaks everything after.","learning_goals_fr":["Décrire ce qu'un bloc contient en plus des transactions.","Expliquer pourquoi modifier un bloc ancien invalide les suivants."],"learning_goals_en":["Describe what a block holds besides transactions.","Explain why editing an old block invalidates the later ones."],"tutor_focus_fr":"Fais modifier une transaction dans un bloc ancien de la chaîne dessinée, puis demande quels blocs deviennent invalides et pourquoi.","tutor_focus_en":"Have the student edit a transaction ten blocks back in the drawn chain, then ask which blocks become invalid and why.","example_contexts_fr":["une transaction modifiée dix blocs en arrière","un registre comptable dont chaque page référence la précédente","un historique consulté par un nouvel arrivant sur le réseau"],"example_contexts_en":["a transaction edited ten blocks back","an accounting ledger where each page references the previous one","a history checked by a newcomer joining the network"],"safety_category":"standard"},{"key":"blockchain.keys_and_signatures","domain_id":"blockchain","objective_ids":["blockchain_foundations","blockchain_ecosystem","blockchain_building"],"stage":1,"order":4,"required":true,"prerequisite_keys":["blockchain.blocks_and_chain"],"fallback_key":null,"title_fr":"Clé publique, clé privée et signature","title_en":"Public key, private key and signature","summary_fr":"Comprendre qu'une signature prouve la possession d'une clé sans jamais la révéler.","summary_en":"Understand that a signature proves possession of a key without ever revealing it.","learning_goals_fr":["Dire ce qui se partage et ce qui ne se partage jamais.","Expliquer ce qu'une signature valide prouve exactement."],"learning_goals_en":["Say what is shared and what is never shared.","Explain exactly what a valid signature proves."],"tutor_focus_fr":"Fais expliquer ce qu'une signature prouve et ce qu'elle ne prouve pas, puis demande ce qui se passe si la clé privée est copiée.","tutor_focus_en":"Have the student explain what a signature proves and does not prove, then ask what happens if the private key is copied.","example_contexts_fr":["une transaction signée depuis un téléphone","une adresse publiée pour recevoir un paiement","une clé privée photographiée par erreur"],"example_contexts_en":["a transaction signed from a phone","an address published to receive a payment","a private key photographed by mistake"],"safety_category":"standard"},{"key":"blockchain.wallet_contents","domain_id":"blockchain","objective_ids":["blockchain_foundations","blockchain_ecosystem","blockchain_building"],"stage":1,"order":5,"required":true,"prerequisite_keys":["blockchain.keys_and_signatures"],"fallback_key":null,"title_fr":"Ce qu'un portefeuille contient vraiment","title_en":"What a wallet actually holds","summary_fr":"Comprendre qu'un portefeuille stocke des clés et non des jetons, qui restent inscrits sur la chaîne.","summary_en":"Understand that a wallet stores keys, not coins, which stay recorded on the chain.","learning_goals_fr":["Dire où sont réellement les avoirs quand un portefeuille est réinstallé.","Expliquer le rôle d'une phrase de récupération."],"learning_goals_en":["Say where the holdings really are when a wallet is reinstalled.","Explain the role of a recovery phrase."],"tutor_focus_fr":"Fais expliquer ce qu'un utilisateur récupère en réinstallant son portefeuille avec sa phrase, puis demande ce qu'il perd définitivement sans elle.","tutor_focus_en":"Have the student explain what a user recovers by reinstalling a wallet with the phrase, then ask what is lost forever without it.","example_contexts_fr":["un téléphone perdu avec le portefeuille installé","une phrase de récupération notée sur papier","un portefeuille réinstallé sur un nouvel appareil"],"example_contexts_en":["a lost phone with the wallet installed","a recovery phrase written on paper","a wallet reinstalled on a new device"],"safety_category":"financial_educational"},{"key":"blockchain.peer_to_peer_propagation","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":1,"order":6,"required":true,"prerequisite_keys":["blockchain.wallet_contents"],"fallback_key":null,"title_fr":"Comment les nœuds propagent l'information","title_en":"How nodes propagate information","summary_fr":"Comprendre la diffusion de proche en proche et l'absence de serveur central de référence.","summary_en":"Understand neighbour-to-neighbour broadcast and the absence of a central reference server.","learning_goals_fr":["Décrire le trajet d'une transaction diffusée sur le réseau.","Expliquer comment un nouveau nœud rattrape l'historique."],"learning_goals_en":["Describe the path of a transaction broadcast on the network.","Explain how a new node catches up with history."],"tutor_focus_fr":"Fais décrire la diffusion d'une transaction depuis un seul nœud, puis demande comment un nœud éteint depuis un mois se remet à jour.","tutor_focus_en":"Have the student describe broadcast from a single node, then ask how a node offline for a month gets back up to date.","example_contexts_fr":["un nœud rallumé après un mois d'arrêt","une transaction émise depuis un pays isolé","deux régions du réseau temporairement coupées"],"example_contexts_en":["a node restarted after a month offline","a transaction sent from an isolated country","two network regions temporarily cut off"],"safety_category":"standard"},{"key":"blockchain.ethereum_vs_bitcoin","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":1,"order":7,"required":true,"prerequisite_keys":["blockchain.wallet_contents"],"fallback_key":null,"title_fr":"Ce qu'Ethereum ajoute à Bitcoin","title_en":"What Ethereum adds to Bitcoin","summary_fr":"Passer d'un registre de paiements à une machine qui exécute du code partagé par tous les nœuds.","summary_en":"Move from a payment ledger to a machine that executes code shared by every node.","learning_goals_fr":["Comparer les deux réseaux sur ce qu'un utilisateur peut y publier.","Citer une application impossible sur un registre de paiements seul."],"learning_goals_en":["Compare the two networks on what a user can publish.","Name an application impossible on a payment-only ledger."],"tutor_focus_fr":"Fais comparer ce que chaque réseau permet de publier, puis demande une application qui exige un programme sur la chaîne.","tutor_focus_en":"Have the student compare what each network lets you publish, then ask for an application requiring an on-chain program.","example_contexts_fr":["un paiement simple entre deux adresses","une vente aux enchères automatisée sans intermédiaire","un jeton créé par une équipe en quelques lignes de code"],"example_contexts_en":["a simple payment between two addresses","an automated auction with no intermediary","a token created by a team in a few lines of code"],"safety_category":"standard"},{"key":"blockchain.smart_contract_basics","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":1,"order":8,"required":true,"prerequisite_keys":["blockchain.wallet_contents"],"fallback_key":null,"title_fr":"Ce qu'un smart contract peut et ne peut pas faire","title_en":"What a smart contract can and cannot do","summary_fr":"Comprendre un programme déterministe déclenché par une transaction et incapable d'agir seul.","summary_en":"Understand a deterministic program triggered by a transaction and unable to act on its own.","learning_goals_fr":["Dire ce qui déclenche l'exécution d'un contrat.","Citer trois choses qu'un contrat ne peut pas faire seul."],"learning_goals_en":["Say what triggers a contract's execution.","Name three things a contract cannot do by itself."],"tutor_focus_fr":"Fais expliquer pourquoi un contrat ne peut pas s'exécuter tout seul chaque lundi, puis demande comment un projet contourne cette limite.","tutor_focus_en":"Have the student explain why a contract cannot run itself every Monday, then ask how a project works around that limit.","example_contexts_fr":["un versement mensuel que personne ne déclenche","un contrat qui doit connaître un cours de bourse","une vente déclenchée par un acheteur"],"example_contexts_en":["a monthly payout nobody triggers","a contract needing a stock price","a sale triggered by a buyer"],"safety_category":"standard"},{"key":"blockchain.transaction_lifecycle","domain_id":"blockchain","objective_ids":["blockchain_foundations","blockchain_ecosystem","blockchain_building"],"stage":2,"order":9,"required":true,"prerequisite_keys":["blockchain.wallet_contents"],"fallback_key":"blockchain.wallet_contents","title_fr":"Le cycle de vie d'une transaction","title_en":"The life cycle of a transaction","summary_fr":"Suivre une transaction de la signature à la confirmation en passant par la file d'attente du réseau.","summary_en":"Follow a transaction from signature to confirmation through the network's waiting pool.","learning_goals_fr":["Ordonner signature, diffusion, sélection, inclusion, confirmation.","Expliquer pourquoi une transaction peut rester en attente."],"learning_goals_en":["Order signing, broadcast, selection, inclusion and confirmation.","Explain why a transaction can stay pending."],"tutor_focus_fr":"Fais suivre une transaction jusqu'à sa confirmation, puis demande pourquoi une transaction sous-payée peut rester bloquée des heures.","tutor_focus_en":"Have the student follow a transaction to confirmation, then ask why an underpriced transaction can stay stuck for hours.","example_contexts_fr":["un paiement en attente depuis vingt minutes","un pic d'activité qui allonge la file","un transfert confirmé après quelques blocs"],"example_contexts_en":["a payment pending for twenty minutes","an activity spike lengthening the queue","a transfer confirmed after a few blocks"],"safety_category":"standard"},{"key":"blockchain.decentralization_tradeoffs","domain_id":"blockchain","objective_ids":["blockchain_foundations","blockchain_ecosystem","blockchain_building"],"stage":2,"order":10,"required":true,"prerequisite_keys":["blockchain.transaction_lifecycle"],"fallback_key":"blockchain.wallet_contents","title_fr":"Ce que la décentralisation coûte","title_en":"What decentralisation costs","summary_fr":"Comparer une base de données classique et une chaîne publique sur le débit, le coût et la confiance requise.","summary_en":"Compare a classic database and a public chain on throughput, cost and required trust.","learning_goals_fr":["Comparer débit et coût entre les deux architectures.","Nommer le problème qui justifie de payer ce surcoût."],"learning_goals_en":["Compare throughput and cost across the two architectures.","Name the problem that justifies paying that overhead."],"tutor_focus_fr":"Fais comparer le nombre de transactions par seconde d'une carte bancaire et d'une chaîne publique, puis demande quel problème justifie l'écart.","tutor_focus_en":"Have the student compare transactions per second of a card network and of a public chain, then ask which problem justifies the gap.","example_contexts_fr":["un réseau de cartes bancaires à des milliers d'opérations par seconde","un registre foncier tenu par une administration","un transfert international entre deux inconnus"],"example_contexts_en":["a card network at thousands of operations per second","a land registry kept by a public administration","an international transfer between two strangers"],"safety_category":"standard"},{"key":"blockchain.immutability_finality","domain_id":"blockchain","objective_ids":["blockchain_foundations","blockchain_ecosystem","blockchain_building"],"stage":2,"order":11,"required":true,"prerequisite_keys":["blockchain.decentralization_tradeoffs"],"fallback_key":"blockchain.wallet_contents","title_fr":"Immutabilité et finalité : quand une transaction est-elle définitive","title_en":"Immutability and finality: when is a transaction definitive","summary_fr":"Distinguer une transaction incluse dans un bloc d'une transaction que le réseau ne peut plus annuler.","summary_en":"Tell apart a transaction included in a block and a transaction the network can no longer undo.","learning_goals_fr":["Expliquer pourquoi on attend plusieurs confirmations.","Dire ce que change une finalité garantie par le protocole."],"learning_goals_en":["Explain why several confirmations are awaited.","Say what protocol-guaranteed finality changes."],"tutor_focus_fr":"Fais choisir le nombre de confirmations à attendre pour livrer une marchandise, puis demande ce qui justifie ce choix.","tutor_focus_en":"Have the student choose how many confirmations to wait before shipping goods, then ask what justifies that choice.","example_contexts_fr":["un marchand qui livre après une seule confirmation","un échange qui exige trente confirmations pour un retrait","un bloc abandonné après une réorganisation"],"example_contexts_en":["a merchant shipping after a single confirmation","an exchange requiring thirty confirmations for a withdrawal","a block dropped after a reorganisation"],"safety_category":"standard"},{"key":"blockchain.public_private_chains","domain_id":"blockchain","objective_ids":["blockchain_foundations","blockchain_ecosystem","blockchain_building"],"stage":2,"order":12,"required":true,"prerequisite_keys":["blockchain.immutability_finality"],"fallback_key":"blockchain.wallet_contents","title_fr":"Chaîne publique, chaîne privée, chaîne de consortium","title_en":"Public, private and consortium chains","summary_fr":"Choisir le modèle d'accès selon qui doit pouvoir lire, écrire et valider.","summary_en":"Choose the access model based on who must be able to read, write and validate.","learning_goals_fr":["Comparer les trois modèles sur les droits de lecture et de validation.","Dire quand une base classique reste préférable."],"learning_goals_en":["Compare the three models on read and validation rights.","Say when a classic database is still preferable."],"tutor_focus_fr":"Fais choisir le modèle adapté à une traçabilité alimentaire entre cinq entreprises, puis demande pourquoi une base partagée ne suffisait pas.","tutor_focus_en":"Have the student choose the model for food traceability across five companies, then ask why a shared database was not enough.","example_contexts_fr":["une traçabilité alimentaire entre cinq industriels","un registre interne à une seule banque","un réseau ouvert à n'importe quel participant"],"example_contexts_en":["food traceability across five manufacturers","a ledger internal to a single bank","a network open to any participant"],"safety_category":"standard"},{"key":"blockchain.proof_of_work","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":2,"order":13,"required":true,"prerequisite_keys":["blockchain.public_private_chains"],"fallback_key":"blockchain.peer_to_peer_propagation","title_fr":"La preuve de travail","title_en":"Proof of work","summary_fr":"Comprendre pourquoi un calcul coûteux et facilement vérifiable protège l'ordre des blocs.","summary_en":"Understand why an expensive but easily verified computation protects the order of blocks.","learning_goals_fr":["Expliquer l'asymétrie entre produire et vérifier une preuve.","Dire ce qu'un attaquant devrait dépenser pour réécrire l'histoire."],"learning_goals_en":["Explain the asymmetry between producing and verifying a proof.","Say what an attacker would have to spend to rewrite history."],"tutor_focus_fr":"Fais expliquer pourquoi trouver un nonce est long et le vérifier est immédiat, puis demande le coût d'une réécriture de dix blocs.","tutor_focus_en":"Have the student explain why finding a nonce is slow while checking it is instant, then ask the cost of rewriting ten blocks.","example_contexts_fr":["un mineur qui teste des milliards de nonces","un nœud qui vérifie un bloc reçu en une milliseconde","une tentative de réécrire les dix derniers blocs"],"example_contexts_en":["a miner testing billions of nonces","a node verifying a received block in a millisecond","an attempt to rewrite the last ten blocks"],"safety_category":"standard"},{"key":"blockchain.mining_difficulty","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":2,"order":14,"required":false,"prerequisite_keys":["blockchain.proof_of_work"],"fallback_key":"blockchain.peer_to_peer_propagation","title_fr":"L'ajustement de difficulté","title_en":"Difficulty adjustment","summary_fr":"Comprendre la boucle de rétroaction qui maintient un intervalle de blocs stable malgré la puissance ajoutée.","summary_en":"Understand the feedback loop keeping block intervals stable despite added computing power.","learning_goals_fr":["Expliquer ce qui déclenche une hausse de difficulté.","Prévoir l'effet du départ soudain de la moitié des mineurs."],"learning_goals_en":["Explain what triggers a difficulty increase.","Predict the effect of half the miners suddenly leaving."],"tutor_focus_fr":"Fais prévoir l'intervalle entre blocs si la puissance double sans ajustement, puis demande ce que corrige le prochain recalcul.","tutor_focus_en":"Have the student predict the block interval if power doubles with no adjustment, then ask what the next recalculation fixes.","example_contexts_fr":["une vague de nouvelles machines mises en service","la moitié des mineurs déconnectés en une semaine","un intervalle moyen visé de dix minutes"],"example_contexts_en":["a wave of new machines brought online","half the miners disconnected within a week","a target average interval of ten minutes"],"safety_category":"standard"},{"key":"blockchain.gas_and_fees","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":2,"order":15,"required":true,"prerequisite_keys":["blockchain.public_private_chains"],"fallback_key":"blockchain.ethereum_vs_bitcoin","title_fr":"Le gas : payer le calcul","title_en":"Gas: paying for computation","summary_fr":"Comprendre qu'une exécution est facturée à l'opération et qu'une limite protège le réseau.","summary_en":"Understand that execution is billed per operation and that a limit protects the network.","learning_goals_fr":["Distinguer quantité de gas et prix du gas.","Expliquer ce qui se passe quand la limite est atteinte en cours d'exécution."],"learning_goals_en":["Tell apart gas amount and gas price.","Explain what happens when the limit is hit mid-execution."],"tutor_focus_fr":"Fais comparer le coût d'un transfert simple et d'une opération complexe, puis demande ce que paie l'utilisateur si l'exécution échoue.","tutor_focus_en":"Have the student compare the cost of a simple transfer and a complex operation, then ask what the user pays when execution fails.","example_contexts_fr":["un transfert simple comparé à un échange automatisé","une transaction qui échoue après avoir consommé du gas","une limite fixée trop basse par un portefeuille"],"example_contexts_en":["a simple transfer compared with an automated swap","a transaction failing after consuming gas","a limit set too low by a wallet"],"safety_category":"financial_educational"},{"key":"blockchain.token_standards","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":2,"order":16,"required":false,"prerequisite_keys":["blockchain.gas_and_fees"],"fallback_key":"blockchain.ethereum_vs_bitcoin","title_fr":"Ce qu'est un standard de jeton","title_en":"What a token standard is","summary_fr":"Comprendre qu'un standard est une interface commune qui rend un jeton compatible avec tout l'écosystème.","summary_en":"Understand that a standard is a shared interface making a token compatible with the ecosystem.","learning_goals_fr":["Citer les fonctions attendues d'un jeton fongible.","Distinguer un jeton fongible d'un jeton non fongible."],"learning_goals_en":["List the functions expected from a fungible token.","Tell apart a fungible and a non-fungible token."],"tutor_focus_fr":"Fais lister les fonctions qu'un portefeuille attend d'un jeton, puis demande ce qui casse si l'une d'elles est renommée.","tutor_focus_en":"Have the student list the functions a wallet expects from a token, then ask what breaks if one of them is renamed.","example_contexts_fr":["un jeton affiché automatiquement par un portefeuille","un billet de concert unique et nominatif","un jeton dont une fonction ne respecte pas le standard"],"example_contexts_en":["a token displayed automatically by a wallet","a unique named concert ticket","a token whose function departs from the standard"],"safety_category":"standard"},{"key":"blockchain.evm_execution","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":2,"order":17,"required":true,"prerequisite_keys":["blockchain.public_private_chains"],"fallback_key":"blockchain.smart_contract_basics","title_fr":"Comment la machine virtuelle exécute un contrat","title_en":"How the virtual machine executes a contract","summary_fr":"Comprendre l'exécution identique sur tous les nœuds et l'obligation de déterminisme.","summary_en":"Understand identical execution on every node and the resulting determinism requirement.","learning_goals_fr":["Expliquer pourquoi tous les nœuds doivent obtenir le même résultat.","Citer une source d'aléa interdite dans un contrat."],"learning_goals_en":["Explain why every node must reach the same result.","Name a source of randomness forbidden inside a contract."],"tutor_focus_fr":"Fais expliquer ce qui se passerait si un contrat utilisait un nombre aléatoire local, puis demande comment obtenir un aléa acceptable.","tutor_focus_en":"Have the student explain what would happen if a contract used a local random number, then ask how to obtain acceptable randomness.","example_contexts_fr":["un tirage au sort dans un contrat de loterie","un contrat qui voudrait lire l'heure locale d'un nœud","une exécution rejouée par mille nœuds"],"example_contexts_en":["a draw inside a lottery contract","a contract wanting to read a node's local clock","an execution replayed by a thousand nodes"],"safety_category":"standard"},{"key":"blockchain.contract_storage_cost","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":2,"order":18,"required":false,"prerequisite_keys":["blockchain.evm_execution"],"fallback_key":"blockchain.smart_contract_basics","title_fr":"Le coût du stockage sur la chaîne","title_en":"The cost of on-chain storage","summary_fr":"Comparer le coût d'écrire une donnée sur la chaîne et celui de la garder hors chaîne.","summary_en":"Compare the cost of writing data on chain with keeping it off chain.","learning_goals_fr":["Comparer le coût d'un stockage sur chaîne et d'une empreinte seule.","Choisir ce qui doit vraiment être écrit sur la chaîne."],"learning_goals_en":["Compare the cost of on-chain storage and of a hash alone.","Choose what genuinely needs to be written on chain."],"tutor_focus_fr":"Fais choisir ce qui va sur la chaîne pour un certificat de diplôme, puis demande ce que prouve encore une empreinte seule.","tutor_focus_en":"Have the student choose what goes on chain for a diploma certificate, then ask what a hash alone still proves.","example_contexts_fr":["un certificat de diplôme à rendre vérifiable","une image de plusieurs mégaoctets","un journal d'événements écrit à chaque appel"],"example_contexts_en":["a diploma certificate to be made verifiable","an image of several megabytes","an event log written on every call"],"safety_category":"standard"},{"key":"blockchain.merkle_tree","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":3,"order":19,"required":true,"prerequisite_keys":["blockchain.mining_difficulty"],"fallback_key":"blockchain.mining_difficulty","title_fr":"L'arbre de Merkle et la preuve d'inclusion","title_en":"The Merkle tree and inclusion proofs","summary_fr":"Prouver qu'une transaction est dans un bloc sans télécharger toutes les transactions du bloc.","summary_en":"Prove a transaction is in a block without downloading every transaction of that block.","learning_goals_fr":["Décrire la construction de la racine à partir des transactions.","Compter les empreintes nécessaires à une preuve d'inclusion."],"learning_goals_en":["Describe how the root is built from the transactions.","Count the hashes needed for an inclusion proof."],"tutor_focus_fr":"Fais construire la racine d'un arbre à quatre transactions, puis demande combien d'empreintes suffisent pour prouver l'une d'elles.","tutor_focus_en":"Have the student build the root of a four-transaction tree, then ask how many hashes suffice to prove one of them.","example_contexts_fr":["un portefeuille mobile qui vérifie un paiement reçu","un bloc contenant trois mille transactions","une preuve envoyée à un client léger"],"example_contexts_en":["a mobile wallet verifying a received payment","a block containing three thousand transactions","a proof sent to a light client"],"safety_category":"standard"},{"key":"blockchain.utxo_model","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":3,"order":20,"required":false,"prerequisite_keys":["blockchain.merkle_tree"],"fallback_key":"blockchain.mining_difficulty","title_fr":"Le modèle UTXO de Bitcoin","title_en":"Bitcoin's UTXO model","summary_fr":"Comprendre qu'un paiement consomme des sorties entières et produit une sortie de monnaie rendue.","summary_en":"Understand that a payment consumes whole outputs and produces a change output.","learning_goals_fr":["Décomposer un paiement en entrées, sortie de paiement et sortie de rendu.","Expliquer pourquoi un solde est une somme de sorties disponibles."],"learning_goals_en":["Break a payment into inputs, payment output and change output.","Explain why a balance is a sum of available outputs."],"tutor_focus_fr":"Fais construire un paiement de 0,3 à partir de deux sorties de 0,2, puis demande où va la différence.","tutor_focus_en":"Have the student build a 0.3 payment from two 0.2 outputs, then ask where the difference goes.","example_contexts_fr":["un paiement de 0,3 financé par deux sorties de 0,2","un solde composé de quarante petites sorties","des frais qui augmentent avec le nombre d'entrées"],"example_contexts_en":["a 0.3 payment funded by two 0.2 outputs","a balance made of forty small outputs","fees growing with the number of inputs"],"safety_category":"standard"},{"key":"blockchain.forks_and_reorgs","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":3,"order":21,"required":false,"prerequisite_keys":["blockchain.utxo_model"],"fallback_key":"blockchain.mining_difficulty","title_fr":"Fourches et réorganisations de chaîne","title_en":"Forks and chain reorganisations","summary_fr":"Distinguer une fourche temporaire due à la latence d'une fourche durable due à une règle changée.","summary_en":"Tell apart a temporary fork caused by latency and a lasting fork caused by a rule change.","learning_goals_fr":["Expliquer ce qui arrive aux transactions d'un bloc abandonné.","Distinguer fourche logicielle et fourche matérielle."],"learning_goals_en":["Explain what happens to the transactions of an abandoned block.","Tell apart a soft fork and a hard fork."],"tutor_focus_fr":"Fais raconter ce qui arrive à une transaction incluse dans un bloc finalement abandonné, puis demande quand la fourche devient permanente.","tutor_focus_en":"Have the student narrate what happens to a transaction in a block eventually abandoned, then ask when the fork becomes permanent.","example_contexts_fr":["deux blocs trouvés à quelques secondes d'écart","un changement de règles refusé par une partie des nœuds","un paiement accepté sur la branche perdante"],"example_contexts_en":["two blocks found seconds apart","a rule change rejected by part of the nodes","a payment accepted on the losing branch"],"safety_category":"standard"},{"key":"blockchain.chain_selection_rule","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":3,"order":22,"required":false,"prerequisite_keys":["blockchain.forks_and_reorgs"],"fallback_key":"blockchain.mining_difficulty","title_fr":"Pourquoi la chaîne la plus lourde l'emporte","title_en":"Why the heaviest chain wins","summary_fr":"Comprendre la règle de sélection qui permet à des nœuds sans coordination de converger.","summary_en":"Understand the selection rule that lets uncoordinated nodes converge.","learning_goals_fr":["Énoncer la règle appliquée par un nœud face à deux branches.","Expliquer pourquoi cette règle rend la triche coûteuse."],"learning_goals_en":["State the rule a node applies when facing two branches.","Explain why that rule makes cheating expensive."],"tutor_focus_fr":"Fais appliquer la règle de sélection à deux branches de longueurs différentes, puis demande ce que devrait produire un attaquant pour l'emporter.","tutor_focus_en":"Have the student apply the selection rule to two branches of different length, then ask what an attacker would need to produce to win.","example_contexts_fr":["un nœud qui reçoit deux branches concurrentes","un attaquant qui mine une branche parallèle en secret","une convergence observée quelques minutes après une fourche"],"example_contexts_en":["a node receiving two competing branches","an attacker mining a parallel branch in secret","convergence observed minutes after a fork"],"safety_category":"standard"},{"key":"blockchain.stablecoins","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":3,"order":23,"required":true,"prerequisite_keys":["blockchain.token_standards"],"fallback_key":"blockchain.token_standards","title_fr":"Comment un stablecoin tient sa parité","title_en":"How a stablecoin holds its peg","summary_fr":"Comparer réserve centralisée, surcollatéralisation et mécanisme algorithmique sur la solidité de la parité.","summary_en":"Compare centralised reserves, over-collateralisation and algorithmic designs on peg robustness.","learning_goals_fr":["Comparer trois mécanismes de stabilisation sur leur point de rupture.","Dire ce qu'un utilisateur doit vérifier avant d'y placer de la valeur."],"learning_goals_en":["Compare three stabilisation mechanisms on their breaking point.","Say what a user should check before storing value there."],"tutor_focus_fr":"Fais comparer trois mécanismes de parité, puis demande lequel casse en premier lors d'une chute brutale des marchés.","tutor_focus_en":"Have the student compare three peg mechanisms, then ask which breaks first during a sharp market drop.","example_contexts_fr":["une réserve bancaire auditée trimestriellement","une position surcollatéralisée liquidée pendant une chute","une parité perdue pendant plusieurs jours"],"example_contexts_en":["a bank reserve audited quarterly","an over-collateralised position liquidated during a crash","a peg lost for several days"],"safety_category":"financial_educational"},{"key":"blockchain.automated_market_makers","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":3,"order":24,"required":false,"prerequisite_keys":["blockchain.stablecoins"],"fallback_key":"blockchain.token_standards","title_fr":"Les teneurs de marché automatisés","title_en":"Automated market makers","summary_fr":"Comprendre comment une réserve de deux actifs fixe un prix sans carnet d'ordres.","summary_en":"Understand how a two-asset pool sets a price without an order book.","learning_goals_fr":["Expliquer comment le prix évolue quand un échange vide une réserve.","Dire pourquoi un gros ordre subit un prix dégradé."],"learning_goals_en":["Explain how the price moves when a swap drains one side of the pool.","Say why a large order gets a degraded price."],"tutor_focus_fr":"Fais calculer l'effet d'un échange important sur une réserve de deux actifs, puis demande pourquoi le prix obtenu s'écarte du prix affiché.","tutor_focus_en":"Have the student compute the effect of a large swap on a two-asset pool, then ask why the obtained price departs from the quoted one.","example_contexts_fr":["un échange de deux jetons dans une réserve commune","un ordre important passé sur une petite réserve","un prix affiché différent du prix finalement obtenu"],"example_contexts_en":["a swap of two tokens in a shared pool","a large order placed against a small pool","a quoted price differing from the executed price"],"safety_category":"financial_educational"},{"key":"blockchain.lending_and_liquidation","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":3,"order":25,"required":false,"prerequisite_keys":["blockchain.automated_market_makers"],"fallback_key":"blockchain.token_standards","title_fr":"Prêt collatéralisé et liquidation","title_en":"Collateralised lending and liquidation","summary_fr":"Comprendre le seuil de liquidation et pourquoi un emprunt automatisé se dénoue sans négociation.","summary_en":"Understand the liquidation threshold and why an automated loan unwinds without negotiation.","learning_goals_fr":["Calculer un ratio de collatéral et le comparer au seuil.","Expliquer ce que déclenche mécaniquement le franchissement du seuil."],"learning_goals_en":["Compute a collateral ratio and compare it to the threshold.","Explain what crossing the threshold mechanically triggers."],"tutor_focus_fr":"Fais calculer le ratio d'une position puis simuler une baisse de 30 % du collatéral, en demandant ce qui se déclenche.","tutor_focus_en":"Have the student compute a position's ratio then simulate a 30% collateral drop, asking what gets triggered.","example_contexts_fr":["un emprunt garanti par un actif volatil","une chute de 30 % du prix du collatéral","une position liquidée pendant la nuit"],"example_contexts_en":["a loan backed by a volatile asset","a 30% drop in collateral price","a position liquidated overnight"],"safety_category":"financial_educational"},{"key":"blockchain.oracles","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":3,"order":26,"required":false,"prerequisite_keys":["blockchain.lending_and_liquidation"],"fallback_key":"blockchain.token_standards","title_fr":"Les oracles : faire entrer une donnée externe","title_en":"Oracles: bringing external data in","summary_fr":"Comprendre que la chaîne ne voit pas le monde extérieur et que l'oracle devient un point de confiance.","summary_en":"Understand that the chain cannot see the outside world, making the oracle a trust point.","learning_goals_fr":["Expliquer pourquoi un contrat ne peut pas lire une donnée externe seul.","Citer deux protections contre une donnée d'oracle manipulée."],"learning_goals_en":["Explain why a contract cannot read external data on its own.","Name two protections against manipulated oracle data."],"tutor_focus_fr":"Fais expliquer pourquoi un contrat ne peut pas connaître un prix seul, puis demande ce qui se passe si l'oracle publie une valeur fausse.","tutor_focus_en":"Have the student explain why a contract cannot know a price by itself, then ask what happens if the oracle publishes a wrong value.","example_contexts_fr":["un contrat d'assurance déclenché par une donnée météo","un prix de marché publié toutes les minutes","un oracle unique qui publie une valeur aberrante"],"example_contexts_en":["an insurance contract triggered by weather data","a market price published every minute","a single oracle publishing an aberrant value"],"safety_category":"standard"},{"key":"blockchain.contract_functions_visibility","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":3,"order":27,"required":true,"prerequisite_keys":["blockchain.contract_storage_cost"],"fallback_key":"blockchain.contract_storage_cost","title_fr":"Fonctions, visibilité et modificateurs","title_en":"Functions, visibility and modifiers","summary_fr":"Contrôler qui peut appeler quoi et factoriser les vérifications d'accès dans un contrat.","summary_en":"Control who can call what and factor access checks inside a contract.","learning_goals_fr":["Choisir la visibilité adaptée à trois fonctions d'un contrat.","Écrire une condition d'accès réutilisable."],"learning_goals_en":["Choose the right visibility for three contract functions.","Write a reusable access condition."],"tutor_focus_fr":"Fais choisir la visibilité de trois fonctions d'un contrat de vente, puis demande ce qui arrive si une fonction interne devient publique.","tutor_focus_en":"Have the student choose visibility for three functions of a sale contract, then ask what happens if an internal function becomes public.","example_contexts_fr":["une fonction de retrait réservée au propriétaire","une consultation de solde ouverte à tous","une fonction interne exposée par erreur"],"example_contexts_en":["a withdrawal function reserved to the owner","a balance lookup open to everyone","an internal function exposed by mistake"],"safety_category":"standard"},{"key":"blockchain.events_and_logs","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":3,"order":28,"required":false,"prerequisite_keys":["blockchain.contract_functions_visibility"],"fallback_key":"blockchain.contract_storage_cost","title_fr":"Événements et journaux","title_en":"Events and logs","summary_fr":"Émettre des événements lisibles hors chaîne pour reconstituer l'état sans tout relire.","summary_en":"Emit events readable off chain to rebuild state without re-reading everything.","learning_goals_fr":["Dire pourquoi une interface écoute des événements plutôt que le stockage.","Choisir les champs à indexer dans un événement."],"learning_goals_en":["Say why an interface listens to events rather than storage.","Choose which fields to index in an event."],"tutor_focus_fr":"Fais concevoir l'événement émis à chaque vente, puis demande quels champs doivent être indexés pour filtrer par acheteur.","tutor_focus_en":"Have the student design the event emitted on each sale, then ask which fields must be indexed to filter by buyer.","example_contexts_fr":["une interface qui affiche l'historique des ventes","un tableau de bord alimenté par les journaux","une recherche filtrée par adresse d'acheteur"],"example_contexts_en":["an interface showing the sales history","a dashboard fed by the logs","a search filtered by buyer address"],"safety_category":"standard"},{"key":"blockchain.testing_contracts","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":3,"order":29,"required":false,"prerequisite_keys":["blockchain.events_and_logs"],"fallback_key":"blockchain.contract_storage_cost","title_fr":"Tester un contrat avant déploiement","title_en":"Testing a contract before deployment","summary_fr":"Écrire des tests qui couvrent les chemins d'échec, sachant qu'un contrat déployé ne se corrige pas.","summary_en":"Write tests covering failure paths, knowing a deployed contract cannot simply be patched.","learning_goals_fr":["Lister les cas d'échec à tester avant tout déploiement.","Expliquer pourquoi la couverture compte plus qu'ailleurs."],"learning_goals_en":["List the failure cases to test before any deployment.","Explain why coverage matters more here than elsewhere."],"tutor_focus_fr":"Fais lister les cas d'échec d'un contrat de vente aux enchères, puis demande lequel serait catastrophique en production.","tutor_focus_en":"Have the student list the failure cases of an auction contract, then ask which one would be catastrophic in production.","example_contexts_fr":["une enchère clôturée sans gagnant","un appel émis par une adresse non autorisée","un contrat déployé avec un paramètre erroné"],"example_contexts_en":["an auction closing with no winner","a call issued by an unauthorised address","a contract deployed with a wrong parameter"],"safety_category":"standard"},{"key":"blockchain.local_devnet","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":3,"order":30,"required":false,"prerequisite_keys":["blockchain.testing_contracts"],"fallback_key":"blockchain.contract_storage_cost","title_fr":"Développer sur un réseau local","title_en":"Developing on a local network","summary_fr":"Utiliser un réseau local puis un réseau de test avant d'engager des frais réels.","summary_en":"Use a local network then a test network before spending real fees.","learning_goals_fr":["Comparer réseau local, réseau de test et réseau principal.","Citer un comportement qui diffère entre réseau local et réseau réel."],"learning_goals_en":["Compare local network, test network and main network.","Name a behaviour that differs between a local and a real network."],"tutor_focus_fr":"Fais comparer les trois environnements, puis demande quel problème n'apparaît jamais sur un réseau local instantané.","tutor_focus_en":"Have the student compare the three environments, then ask which problem never shows on an instant local chain.","example_contexts_fr":["un déploiement instantané sur une chaîne locale","un test avec des jetons sans valeur","un problème de congestion invisible en local"],"example_contexts_en":["an instant deployment on a local chain","a test using valueless tokens","a congestion problem invisible locally"],"safety_category":"standard"},{"key":"blockchain.proof_of_stake","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":4,"order":31,"required":true,"prerequisite_keys":["blockchain.chain_selection_rule"],"fallback_key":"blockchain.chain_selection_rule","title_fr":"La preuve d'enjeu et la sanction des validateurs","title_en":"Proof of stake and validator penalties","summary_fr":"Remplacer le coût énergétique par un capital immobilisé qui peut être détruit en cas de faute.","summary_en":"Replace energy cost with locked capital that can be destroyed when a validator misbehaves.","learning_goals_fr":["Expliquer ce qu'un validateur risque en signant deux blocs concurrents.","Comparer les coûts d'attaque des deux mécanismes."],"learning_goals_en":["Explain what a validator risks by signing two competing blocks.","Compare the attack cost of the two mechanisms."],"tutor_focus_fr":"Fais expliquer ce que perd un validateur qui signe deux blocs contradictoires, puis demande comment le protocole le détecte.","tutor_focus_en":"Have the student explain what a validator loses by signing two contradictory blocks, then ask how the protocol detects it.","example_contexts_fr":["un validateur qui signe deux blocs contradictoires","un opérateur hors ligne pendant une journée","un capital immobilisé pendant plusieurs semaines"],"example_contexts_en":["a validator signing two contradictory blocks","an operator offline for a full day","capital locked for several weeks"],"safety_category":"standard"},{"key":"blockchain.byzantine_faults","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":4,"order":32,"required":false,"prerequisite_keys":["blockchain.proof_of_stake"],"fallback_key":"blockchain.chain_selection_rule","title_fr":"Le problème des généraux byzantins","title_en":"The Byzantine generals problem","summary_fr":"Formuler l'accord entre participants dont une partie peut mentir, et la limite du tiers de fautifs.","summary_en":"State agreement among participants where some may lie, and the one-third faulty bound.","learning_goals_fr":["Distinguer une panne franche d'un comportement malveillant.","Citer la proportion maximale de participants fautifs tolérée."],"learning_goals_en":["Tell apart a crash failure and malicious behaviour.","State the maximum share of faulty participants tolerated."],"tutor_focus_fr":"Fais distinguer un nœud éteint d'un nœud qui envoie deux messages contradictoires, puis demande pourquoi le second est plus difficile à gérer.","tutor_focus_en":"Have the student distinguish a node that is off from a node sending two contradictory messages, then ask why the second is harder.","example_contexts_fr":["un nœud qui envoie deux messages contradictoires","un serveur simplement éteint","un consortium de dix participants dont trois trichent"],"example_contexts_en":["a node sending two contradictory messages","a server that is simply switched off","a ten-member consortium where three cheat"],"safety_category":"standard"},{"key":"blockchain.block_size_propagation","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":4,"order":33,"required":false,"prerequisite_keys":["blockchain.byzantine_faults"],"fallback_key":"blockchain.chain_selection_rule","title_fr":"Taille des blocs et propagation","title_en":"Block size and propagation","summary_fr":"Relier la taille d'un bloc au temps de diffusion et au risque de blocs orphelins.","summary_en":"Connect block size to broadcast time and to the risk of orphaned blocks.","learning_goals_fr":["Expliquer pourquoi un bloc plus gros augmente le risque d'orphelin.","Dire ce que la taille de bloc impose aux nœuds domestiques."],"learning_goals_en":["Explain why a larger block raises the orphan risk.","Say what block size imposes on home nodes."],"tutor_focus_fr":"Fais expliquer pourquoi doubler la taille des blocs n'améliore pas proportionnellement le débit utile, puis demande qui ne peut plus suivre.","tutor_focus_en":"Have the student explain why doubling block size does not proportionally improve useful throughput, then ask who can no longer keep up.","example_contexts_fr":["un bloc trop gros diffusé lentement sur le réseau","un nœud domestique avec une connexion limitée","un débat communautaire sur l'augmentation de la limite"],"example_contexts_en":["an oversized block spreading slowly across the network","a home node on a limited connection","a community debate on raising the limit"],"safety_category":"standard"},{"key":"blockchain.fee_market","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":4,"order":34,"required":false,"prerequisite_keys":["blockchain.block_size_propagation"],"fallback_key":"blockchain.chain_selection_rule","title_fr":"Le marché des frais de transaction","title_en":"The transaction fee market","summary_fr":"Comprendre l'enchère implicite pour un espace de bloc limité et l'effet d'un pic de demande.","summary_en":"Understand the implicit auction for limited block space and the effect of a demand spike.","learning_goals_fr":["Expliquer comment les frais sont fixés en période de congestion.","Dire ce qui remplacera la récompense de bloc à long terme."],"learning_goals_en":["Explain how fees are set during congestion.","Say what will replace the block reward in the long run."],"tutor_focus_fr":"Fais expliquer pourquoi les frais montent lors d'un pic d'activité, puis demande ce qui rémunérera les validateurs quand l'émission s'arrêtera.","tutor_focus_en":"Have the student explain why fees rise during an activity spike, then ask what will pay validators once issuance stops.","example_contexts_fr":["une journée de forte congestion du réseau","une transaction non urgente envoyée avec des frais bas","une émission de nouvelles unités qui diminue avec le temps"],"example_contexts_en":["a day of heavy network congestion","a non-urgent transaction sent with low fees","an issuance of new units decreasing over time"],"safety_category":"financial_educational"},{"key":"blockchain.cross_chain_bridges","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":4,"order":35,"required":true,"prerequisite_keys":["blockchain.oracles"],"fallback_key":"blockchain.oracles","title_fr":"Les ponts entre chaînes et leur risque","title_en":"Cross-chain bridges and their risk","summary_fr":"Comprendre le mécanisme de blocage et d'émission d'un actif représenté sur une autre chaîne.","summary_en":"Understand the lock-and-mint mechanism of an asset represented on another chain.","learning_goals_fr":["Décrire ce que représente un jeton reçu à l'arrivée d'un pont.","Expliquer pourquoi les ponts concentrent le risque."],"learning_goals_en":["Describe what a token received at a bridge's destination represents.","Explain why bridges concentrate risk."],"tutor_focus_fr":"Fais décrire ce que devient l'actif d'origine pendant un transfert par pont, puis demande ce que vaut le jeton reçu si le pont est compromis.","tutor_focus_en":"Have the student describe what happens to the original asset during a bridge transfer, then ask what the received token is worth if the bridge is compromised.","example_contexts_fr":["un actif bloqué d'un côté et représenté de l'autre","un pont détenant les avoirs de milliers d'utilisateurs","un jeton représenté dont la garantie disparaît"],"example_contexts_en":["an asset locked on one side and represented on the other","a bridge holding the funds of thousands of users","a wrapped token whose backing disappears"],"safety_category":"standard"},{"key":"blockchain.layer_two_rollups","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":4,"order":36,"required":false,"prerequisite_keys":["blockchain.cross_chain_bridges"],"fallback_key":"blockchain.oracles","title_fr":"Les rollups de couche 2","title_en":"Layer 2 rollups","summary_fr":"Comprendre l'exécution hors chaîne dont le résultat est publié et vérifiable sur la chaîne principale.","summary_en":"Understand off-chain execution whose result is published and verifiable on the main chain.","learning_goals_fr":["Expliquer d'où vient la baisse de coût d'un rollup.","Comparer preuve de fraude et preuve de validité sur le délai de retrait."],"learning_goals_en":["Explain where a rollup's cost reduction comes from.","Compare fraud proofs and validity proofs on withdrawal delay."],"tutor_focus_fr":"Fais expliquer ce qui est réellement publié sur la chaîne principale par un rollup, puis demande pourquoi un retrait peut prendre une semaine.","tutor_focus_en":"Have the student explain what a rollup actually publishes on the main chain, then ask why a withdrawal can take a week.","example_contexts_fr":["un paiement à quelques centimes de frais","un retrait vers la chaîne principale différé d'une semaine","un opérateur de rollup temporairement indisponible"],"example_contexts_en":["a payment costing a few cents in fees","a withdrawal to the main chain delayed by a week","a rollup operator temporarily unavailable"],"safety_category":"standard"},{"key":"blockchain.token_governance","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":4,"order":37,"required":false,"prerequisite_keys":["blockchain.layer_two_rollups"],"fallback_key":"blockchain.oracles","title_fr":"La gouvernance par jeton","title_en":"Token-based governance","summary_fr":"Analyser un vote pondéré par les avoirs et les effets de concentration qu'il produit.","summary_en":"Analyse holdings-weighted voting and the concentration effects it produces.","learning_goals_fr":["Expliquer ce qu'un vote pondéré par les avoirs favorise.","Citer un mécanisme qui limite la capture d'une décision."],"learning_goals_en":["Explain what holdings-weighted voting favours.","Name a mechanism limiting capture of a decision."],"tutor_focus_fr":"Fais analyser un vote où trois détenteurs pèsent 60 %, puis demande quel mécanisme réduirait ce déséquilibre.","tutor_focus_en":"Have the student analyse a vote where three holders carry 60%, then ask which mechanism would reduce that imbalance.","example_contexts_fr":["une proposition adoptée par trois grands détenteurs","un quorum jamais atteint sur les petits votes","un délai obligatoire avant application d'une décision"],"example_contexts_en":["a proposal passed by three large holders","a quorum never reached on small votes","a mandatory delay before a decision takes effect"],"safety_category":"standard"},{"key":"blockchain.custody_models","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":4,"order":38,"required":false,"prerequisite_keys":["blockchain.token_governance"],"fallback_key":"blockchain.oracles","title_fr":"Garde des clés : autogarde ou dépositaire","title_en":"Key custody: self-custody or custodian","summary_fr":"Comparer les modèles de garde sur le risque de perte, le risque de faillite et le recours possible.","summary_en":"Compare custody models on loss risk, insolvency risk and available recourse.","learning_goals_fr":["Comparer les deux modèles sur ce qui se passe en cas d'erreur.","Dire ce qu'une signature multiple change au risque."],"learning_goals_en":["Compare both models on what happens when something goes wrong.","Say what multi-signature changes about the risk."],"tutor_focus_fr":"Fais comparer ce qui se passe en cas de perte de clé et en cas de faillite du dépositaire, puis demande ce qu'apporte une signature multiple.","tutor_focus_en":"Have the student compare a lost key and an insolvent custodian, then ask what multi-signature adds.","example_contexts_fr":["une clé perdue sans phrase de récupération","une plateforme dépositaire en défaut","un portefeuille exigeant deux signatures sur trois"],"example_contexts_en":["a key lost with no recovery phrase","a custodial platform in default","a wallet requiring two signatures out of three"],"safety_category":"financial_educational"},{"key":"blockchain.reentrancy","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":4,"order":39,"required":true,"prerequisite_keys":["blockchain.local_devnet"],"fallback_key":"blockchain.local_devnet","title_fr":"La faille de réentrance","title_en":"The reentrancy flaw","summary_fr":"Comprendre comment un appel externe rappelle le contrat avant la mise à jour de son état.","summary_en":"Understand how an external call re-enters the contract before its state is updated.","learning_goals_fr":["Décrire l'ordre fautif entre envoi de fonds et mise à jour du solde.","Appliquer le schéma vérifications, effets, interactions."],"learning_goals_en":["Describe the faulty order between sending funds and updating the balance.","Apply the checks-effects-interactions pattern."],"tutor_focus_fr":"Fais décrire l'ordre des opérations d'un retrait vulnérable, puis demande la réécriture qui supprime la faille.","tutor_focus_en":"Have the student describe the operation order of a vulnerable withdrawal, then ask for the rewrite that removes the flaw.","example_contexts_fr":["un retrait qui envoie les fonds avant de mettre à jour le solde","un contrat appelant un contrat inconnu","un solde décrémenté trop tard"],"example_contexts_en":["a withdrawal sending funds before updating the balance","a contract calling an unknown contract","a balance decremented too late"],"safety_category":"standard"},{"key":"blockchain.contract_access_control","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":4,"order":40,"required":false,"prerequisite_keys":["blockchain.reentrancy"],"fallback_key":"blockchain.local_devnet","title_fr":"Contrôle d'accès et rôles","title_en":"Access control and roles","summary_fr":"Concevoir des rôles limités plutôt qu'un propriétaire unique tout-puissant.","summary_en":"Design limited roles rather than one all-powerful owner.","learning_goals_fr":["Découper des permissions en rôles distincts.","Expliquer le risque d'une clé unique de propriétaire."],"learning_goals_en":["Split permissions into distinct roles.","Explain the risk of a single owner key."],"tutor_focus_fr":"Fais découper les permissions d'un contrat en trois rôles, puis demande ce qui se passe si la clé du propriétaire est perdue.","tutor_focus_en":"Have the student split a contract's permissions into three roles, then ask what happens if the owner key is lost.","example_contexts_fr":["une clé de propriétaire compromise","une mise en pause d'urgence réservée à deux adresses","un rôle de trésorier distinct du rôle d'administrateur"],"example_contexts_en":["a compromised owner key","an emergency pause reserved to two addresses","a treasurer role separate from the admin role"],"safety_category":"standard"},{"key":"blockchain.upgradeable_contracts","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":4,"order":41,"required":false,"prerequisite_keys":["blockchain.contract_access_control"],"fallback_key":"blockchain.local_devnet","title_fr":"Contrats évolutifs et proxy","title_en":"Upgradeable contracts and proxies","summary_fr":"Comprendre le motif proxy et le compromis entre correction possible et confiance demandée.","summary_en":"Understand the proxy pattern and the trade-off between fixability and required trust.","learning_goals_fr":["Expliquer la séparation entre stockage et logique dans un proxy.","Dire ce que l'évolutivité retire comme garantie aux utilisateurs."],"learning_goals_en":["Explain the split between storage and logic in a proxy.","Say what upgradeability removes as a guarantee for users."],"tutor_focus_fr":"Fais expliquer où vit l'état dans un montage proxy, puis demande ce qu'un utilisateur accepte en utilisant un contrat évolutif.","tutor_focus_en":"Have the student explain where state lives in a proxy setup, then ask what a user accepts by using an upgradeable contract.","example_contexts_fr":["une correction de bug après déploiement","un stockage conservé pendant un changement de logique","une mise à jour décidée par une seule équipe"],"example_contexts_en":["a bug fixed after deployment","storage preserved through a logic change","an upgrade decided by a single team"],"safety_category":"standard"},{"key":"blockchain.gas_optimization","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":4,"order":42,"required":false,"prerequisite_keys":["blockchain.upgradeable_contracts"],"fallback_key":"blockchain.local_devnet","title_fr":"Optimiser le gas sans casser la lisibilité","title_en":"Optimising gas without destroying readability","summary_fr":"Identifier les opérations réellement coûteuses avant d'écrire du code difficile à relire.","summary_en":"Identify the genuinely expensive operations before writing hard-to-read code.","learning_goals_fr":["Classer trois opérations par coût réel.","Décider quand une optimisation ne vaut pas sa complexité."],"learning_goals_en":["Rank three operations by real cost.","Decide when an optimisation is not worth its complexity."],"tutor_focus_fr":"Fais classer une écriture en stockage, une lecture et un calcul par coût, puis demande quelle optimisation apporte le plus pour un contrat donné.","tutor_focus_en":"Have the student rank a storage write, a read and a computation by cost, then ask which optimisation pays most for a given contract.","example_contexts_fr":["une boucle qui écrit en stockage à chaque tour","un tableau parcouru pour trouver un élément","un contrat illisible après optimisation"],"example_contexts_en":["a loop writing to storage on every turn","an array scanned to find one element","a contract made unreadable by optimisation"],"safety_category":"standard"},{"key":"blockchain.light_clients","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":5,"order":43,"required":true,"prerequisite_keys":["blockchain.fee_market"],"fallback_key":"blockchain.fee_market","title_fr":"Clients légers et preuves de vérification","title_en":"Light clients and verification proofs","summary_fr":"Comprendre ce qu'un client léger vérifie réellement et la confiance résiduelle qu'il accorde.","summary_en":"Understand what a light client really verifies and the residual trust it grants.","learning_goals_fr":["Comparer ce que vérifie un nœud complet et un client léger.","Citer une hypothèse de confiance propre au client léger."],"learning_goals_en":["Compare what a full node and a light client verify.","Name a trust assumption specific to light clients."],"tutor_focus_fr":"Fais comparer les vérifications d'un nœud complet et d'un portefeuille mobile, puis demande ce que le second croit sans le vérifier.","tutor_focus_en":"Have the student compare the checks of a full node and a mobile wallet, then ask what the latter believes without verifying.","example_contexts_fr":["un portefeuille mobile de 30 mégaoctets","un nœud complet stockant l'historique entier","une preuve d'inclusion reçue d'un serveur tiers"],"example_contexts_en":["a 30-megabyte mobile wallet","a full node storing the entire history","an inclusion proof received from a third-party server"],"safety_category":"standard"},{"key":"blockchain.transaction_ordering_value","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":5,"order":44,"required":false,"prerequisite_keys":["blockchain.light_clients"],"fallback_key":"blockchain.fee_market","title_fr":"L'ordonnancement des transactions et la valeur extractible","title_en":"Transaction ordering and extractable value","summary_fr":"Comprendre pourquoi le pouvoir d'ordonner les transactions d'un bloc a une valeur économique.","summary_en":"Understand why the power to order transactions inside a block carries economic value.","learning_goals_fr":["Expliquer pourquoi l'ordre dans un bloc n'est pas neutre.","Citer une protection utilisateur contre un mauvais prix d'exécution."],"learning_goals_en":["Explain why order inside a block is not neutral.","Name a user protection against a poor execution price."],"tutor_focus_fr":"Fais expliquer ce que rapporte le choix de l'ordre des transactions dans un bloc, puis demande quel réglage protège un utilisateur ordinaire.","tutor_focus_en":"Have the student explain what choosing the order of transactions in a block earns, then ask which setting protects an ordinary user.","example_contexts_fr":["un ordre d'échange visible dans la file d'attente","un prix d'exécution moins bon que prévu","une tolérance de glissement réglée par l'utilisateur"],"example_contexts_en":["a trade order visible in the waiting pool","an execution price worse than expected","a slippage tolerance set by the user"],"safety_category":"financial_educational"},{"key":"blockchain.post_quantum_signatures","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":5,"order":45,"required":false,"prerequisite_keys":["blockchain.transaction_ordering_value"],"fallback_key":"blockchain.fee_market","title_fr":"Ce qu'un ordinateur quantique menacerait","title_en":"What a quantum computer would threaten","summary_fr":"Distinguer la menace sur les signatures de la menace bien plus faible sur les fonctions de hachage.","summary_en":"Separate the threat to signatures from the much weaker threat to hash functions.","learning_goals_fr":["Dire quelle brique cryptographique serait la plus exposée.","Expliquer pourquoi une adresse jamais dépensée est moins exposée."],"learning_goals_en":["Say which cryptographic building block would be most exposed.","Explain why a never-spent address is less exposed."],"tutor_focus_fr":"Fais comparer l'exposition des signatures et du hachage, puis demande pourquoi une adresse dont la clé publique n'a jamais été révélée est plus sûre.","tutor_focus_en":"Have the student compare the exposure of signatures and hashing, then ask why an address whose public key was never revealed is safer.","example_contexts_fr":["une adresse dont la clé publique est apparue lors d'une dépense","un projet qui prépare une migration cryptographique","un fonds inactif depuis dix ans"],"example_contexts_en":["an address whose public key appeared when spending","a project preparing a cryptographic migration","a fund untouched for ten years"],"safety_category":"standard"},{"key":"blockchain.pseudonymity_analysis","domain_id":"blockchain","objective_ids":["blockchain_foundations"],"stage":5,"order":46,"required":false,"prerequisite_keys":["blockchain.post_quantum_signatures"],"fallback_key":"blockchain.fee_market","title_fr":"Pseudonymat et analyse de chaîne","title_en":"Pseudonymity and chain analysis","summary_fr":"Comprendre pourquoi un registre public permet de relier des adresses à une même personne.","summary_en":"Understand why a public ledger allows linking addresses to the same person.","learning_goals_fr":["Expliquer la différence entre anonymat et pseudonymat.","Citer deux comportements qui relient des adresses entre elles."],"learning_goals_en":["Explain the difference between anonymity and pseudonymity.","Name two behaviours that link addresses together."],"tutor_focus_fr":"Fais expliquer comment deux adresses se retrouvent liées par une même transaction, puis demande ce qu'un point d'entrée réglementé ajoute à l'analyse.","tutor_focus_en":"Have the student explain how two addresses become linked by one transaction, then ask what a regulated entry point adds to the analysis.","example_contexts_fr":["deux adresses dépensées ensemble dans une transaction","un retrait vers une plateforme qui vérifie l'identité","une adresse publiée sur un profil public"],"example_contexts_en":["two addresses spent together in one transaction","a withdrawal to a platform verifying identity","an address published on a public profile"],"safety_category":"standard"},{"key":"blockchain.impermanent_loss","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":5,"order":47,"required":true,"prerequisite_keys":["blockchain.custody_models"],"fallback_key":"blockchain.custody_models","title_fr":"La perte impermanente d'un fournisseur de liquidité","title_en":"Impermanent loss for a liquidity provider","summary_fr":"Comparer la valeur d'une position en réserve et celle des mêmes actifs simplement conservés.","summary_en":"Compare the value of a pooled position with the same assets simply held.","learning_goals_fr":["Expliquer d'où vient l'écart entre les deux stratégies.","Dire dans quel scénario de prix l'écart se réduit."],"learning_goals_en":["Explain where the gap between the two strategies comes from.","Say in which price scenario the gap narrows."],"tutor_focus_fr":"Fais comparer la valeur finale d'une position fournie en liquidité et des mêmes actifs conservés après un doublement de prix.","tutor_focus_en":"Have the student compare the final value of a pooled position and of the same assets held after a price doubling.","example_contexts_fr":["un actif dont le prix double pendant la période","une paire de deux actifs stables entre eux","des frais perçus qui compensent partiellement l'écart"],"example_contexts_en":["an asset whose price doubles over the period","a pair of two assets stable against each other","collected fees partially offsetting the gap"],"safety_category":"financial_educational"},{"key":"blockchain.token_supply_schedule","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":5,"order":48,"required":false,"prerequisite_keys":["blockchain.impermanent_loss"],"fallback_key":"blockchain.custody_models","title_fr":"Émission, dilution et calendrier de distribution","title_en":"Issuance, dilution and distribution schedule","summary_fr":"Lire un calendrier d'émission pour anticiper la dilution des détenteurs existants.","summary_en":"Read an issuance schedule to anticipate dilution for existing holders.","learning_goals_fr":["Lire un calendrier de déblocage et repérer les échéances sensibles.","Distinguer offre en circulation et offre totale."],"learning_goals_en":["Read an unlock schedule and spot the sensitive dates.","Tell apart circulating supply and total supply."],"tutor_focus_fr":"Fais lire un calendrier où 20 % de l'offre se débloque en un mois, puis demande ce que cela implique pour les détenteurs existants.","tutor_focus_en":"Have the student read a schedule unlocking 20% of supply in one month, then ask what it implies for existing holders.","example_contexts_fr":["un déblocage de 20 % de l'offre en un mois","une offre en circulation très inférieure à l'offre totale","une émission continue destinée à rémunérer des validateurs"],"example_contexts_en":["an unlock of 20% of supply within a month","a circulating supply far below total supply","continuous issuance paying validators"],"safety_category":"financial_educational"},{"key":"blockchain.regulatory_frameworks","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":5,"order":49,"required":false,"prerequisite_keys":["blockchain.token_supply_schedule"],"fallback_key":"blockchain.custody_models","title_fr":"Ce que la régulation encadre","title_en":"What regulation actually covers","summary_fr":"Repérer les points de contact entre un protocole ouvert et les obligations qui pèsent sur les intermédiaires.","summary_en":"Identify the contact points between an open protocol and the duties placed on intermediaries.","learning_goals_fr":["Distinguer ce qui vise le protocole et ce qui vise les intermédiaires.","Citer une obligation typique d'une plateforme d'échange."],"learning_goals_en":["Tell apart what targets the protocol and what targets intermediaries.","Name a typical obligation of an exchange platform."],"tutor_focus_fr":"Fais distinguer les obligations d'un protocole ouvert et celles d'une plateforme d'échange, puis demande où se situe le point de contrôle réel.","tutor_focus_en":"Have the student separate the duties of an open protocol from those of an exchange, then ask where the real control point sits.","example_contexts_fr":["une plateforme qui vérifie l'identité de ses clients","un protocole publié en logiciel libre","un émetteur de jeton adossé à une monnaie"],"example_contexts_en":["a platform verifying its customers' identity","a protocol published as free software","an issuer of a currency-backed token"],"safety_category":"standard"},{"key":"blockchain.onchain_analytics","domain_id":"blockchain","objective_ids":["blockchain_ecosystem"],"stage":5,"order":50,"required":false,"prerequisite_keys":["blockchain.regulatory_frameworks"],"fallback_key":"blockchain.custody_models","title_fr":"Lire l'activité d'un protocole dans les données de chaîne","title_en":"Reading a protocol's activity in chain data","summary_fr":"Distinguer des indicateurs d'usage réel des chiffres facilement gonflés par un même acteur.","summary_en":"Tell real usage indicators apart from figures one actor can easily inflate.","learning_goals_fr":["Choisir deux indicateurs difficiles à manipuler.","Expliquer pourquoi le nombre d'adresses actives trompe souvent."],"learning_goals_en":["Choose two indicators that are hard to manipulate.","Explain why the count of active addresses often misleads."],"tutor_focus_fr":"Fais critiquer une communication fondée sur le nombre d'adresses actives, puis demande quels indicateurs seraient plus solides.","tutor_focus_en":"Have the student critique a claim based on active address count, then ask which indicators would be sturdier.","example_contexts_fr":["un protocole affichant cent mille adresses actives","un volume gonflé par des échanges entre deux comptes","des frais payés par des utilisateurs réels"],"example_contexts_en":["a protocol advertising a hundred thousand active addresses","volume inflated by trades between two accounts","fees paid by real users"],"safety_category":"standard"},{"key":"blockchain.contract_audit","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":5,"order":51,"required":true,"prerequisite_keys":["blockchain.gas_optimization"],"fallback_key":"blockchain.gas_optimization","title_fr":"Ce qu'un audit de contrat cherche","title_en":"What a contract audit looks for","summary_fr":"Comprendre la démarche d'un audit et ce que son rapport ne garantit pas.","summary_en":"Understand the audit process and what its report does not guarantee.","learning_goals_fr":["Citer trois familles de vulnérabilités recherchées.","Dire ce qu'un rapport d'audit ne prouve pas."],"learning_goals_en":["Name three families of vulnerabilities searched for.","Say what an audit report does not prove."],"tutor_focus_fr":"Fais lister ce qu'un auditeur examine en priorité, puis demande ce qu'un rapport favorable ne garantit toujours pas.","tutor_focus_en":"Have the student list what an auditor examines first, then ask what a favourable report still does not guarantee.","example_contexts_fr":["un contrat audité qui subit tout de même un incident","une hypothèse d'oracle non vérifiée par l'audit","un périmètre d'audit limité à deux fichiers"],"example_contexts_en":["an audited contract that still suffers an incident","an oracle assumption not covered by the audit","an audit scope limited to two files"],"safety_category":"standard"},{"key":"blockchain.formal_verification","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":5,"order":52,"required":false,"prerequisite_keys":["blockchain.contract_audit"],"fallback_key":"blockchain.gas_optimization","title_fr":"Vérifier formellement une invariante","title_en":"Formally verifying an invariant","summary_fr":"Exprimer une propriété qui doit rester vraie et la prouver sur toutes les exécutions possibles.","summary_en":"State a property that must always hold and prove it over every possible execution.","learning_goals_fr":["Formuler une invariante vérifiable pour un contrat donné.","Comparer la portée d'une preuve et celle d'un test."],"learning_goals_en":["State a verifiable invariant for a given contract.","Compare the reach of a proof and of a test."],"tutor_focus_fr":"Fais formuler l'invariante d'un contrat de dépôt, puis demande ce qu'une preuve apporte de plus que mille tests.","tutor_focus_en":"Have the student state the invariant of a deposit contract, then ask what a proof adds over a thousand tests.","example_contexts_fr":["la somme des dépôts égale au solde du contrat","un contrat testé par mille cas aléatoires","une propriété fausse sur un cas jamais testé"],"example_contexts_en":["the sum of deposits equal to the contract balance","a contract tested with a thousand random cases","a property false on a case never tested"],"safety_category":"standard"},{"key":"blockchain.frontend_integration","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":5,"order":53,"required":false,"prerequisite_keys":["blockchain.formal_verification"],"fallback_key":"blockchain.gas_optimization","title_fr":"Relier une interface web à un contrat","title_en":"Connecting a web interface to a contract","summary_fr":"Gérer côté interface la signature, l'attente de confirmation et l'échec d'une transaction.","summary_en":"Handle signing, confirmation waiting and transaction failure on the interface side.","learning_goals_fr":["Décrire les états à afficher entre l'envoi et la confirmation.","Choisir ce que voit l'utilisateur en cas d'échec."],"learning_goals_en":["Describe the states to display between sending and confirmation.","Choose what the user sees on failure."],"tutor_focus_fr":"Fais lister les états d'interface entre le clic et la confirmation, puis demande ce qu'il faut afficher si la transaction échoue.","tutor_focus_en":"Have the student list the interface states between the click and the confirmation, then ask what to show if the transaction fails.","example_contexts_fr":["un bouton d'achat cliqué deux fois par impatience","une transaction rejetée par l'utilisateur dans son portefeuille","une confirmation qui arrive après trente secondes"],"example_contexts_en":["a buy button clicked twice out of impatience","a transaction rejected by the user in their wallet","a confirmation arriving after thirty seconds"],"safety_category":"standard"},{"key":"blockchain.onchain_incident_response","domain_id":"blockchain","objective_ids":["blockchain_building"],"stage":5,"order":54,"required":false,"prerequisite_keys":["blockchain.frontend_integration"],"fallback_key":"blockchain.gas_optimization","title_fr":"Réagir à un incident sur un contrat déployé","title_en":"Responding to an incident on a deployed contract","summary_fr":"Préparer à l'avance les leviers disponibles quand un contrat déployé se comporte mal.","summary_en":"Prepare in advance the levers available when a deployed contract misbehaves.","learning_goals_fr":["Lister les leviers d'urgence prévus à la conception.","Ordonner les actions des premières minutes d'un incident."],"learning_goals_en":["List the emergency levers designed in from the start.","Order the actions of the first minutes of an incident."],"tutor_focus_fr":"Fais ordonner les actions des dix premières minutes d'un incident, puis demande quel levier doit exister dès la conception.","tutor_focus_en":"Have the student order the actions of the first ten minutes of an incident, then ask which lever must exist from the design stage.","example_contexts_fr":["des fonds qui sortent anormalement d'un contrat","une fonction de pause prévue dès la conception","une communication publique pendant un incident"],"example_contexts_en":["funds flowing abnormally out of a contract","a pause function designed in from the start","public communication during an incident"],"safety_category":"standard"}]}$catalog$::jsonb)
ON CONFLICT (domain_id) DO UPDATE
SET version = EXCLUDED.version, payload = EXCLUDED.payload, updated_at = now();

INSERT INTO public.learning_catalog_domains (domain_id, version, payload)
VALUES ($catalog$computer_science$catalog$, $catalog$v1$catalog$, $catalog${"version":"v1","steps":[{"key":"computer_science.machine_layers","domain_id":"computer_science","objective_ids":["cs_systems","cs_programming","cs_software_data"],"stage":1,"order":1,"required":true,"prerequisite_keys":[],"fallback_key":null,"title_fr":"Les couches d'un ordinateur, du transistor à l'application","title_en":"The layers of a computer, from transistor to application","summary_fr":"Situer les cinq couches qui séparent un transistor de l'application ouverte à l'écran.","summary_en":"Place the five layers that separate a transistor from the application on screen.","learning_goals_fr":["Nommer dans l'ordre transistor, circuit, processeur, système d'exploitation, application.","Dire à quelle couche appartient un problème donné."],"learning_goals_en":["Name transistor, circuit, processor, operating system and application in order.","Say which layer a given problem belongs to."],"tutor_focus_fr":"Fais nommer les couches de bas en haut, puis demande à quelle couche appartiennent trois problèmes concrets : un écran gelé, un calcul faux, une batterie qui chauffe.","tutor_focus_en":"Have the student name the layers bottom-up, then ask which layer owns three concrete problems: a frozen screen, a wrong calculation, a hot battery.","example_contexts_fr":["un téléphone qui ouvre une application de messagerie","une calculatrice à quatre opérations","un serveur qui héberge un site web"],"example_contexts_en":["a phone opening a messaging app","a four-function pocket calculator","a server hosting a website"],"safety_category":"standard"},{"key":"computer_science.binary_numbers","domain_id":"computer_science","objective_ids":["cs_systems","cs_programming","cs_software_data"],"stage":1,"order":2,"required":true,"prerequisite_keys":["computer_science.machine_layers"],"fallback_key":null,"title_fr":"Comment les nombres sont écrits en binaire","title_en":"How numbers are written in binary","summary_fr":"Convertir un petit nombre décimal en binaire et comprendre pourquoi la machine n'utilise que deux états.","summary_en":"Convert a small decimal number to binary and see why a machine only uses two states.","learning_goals_fr":["Convertir un nombre inférieur à 32 en binaire et l'inverse.","Expliquer pourquoi deux états suffisent à une machine électronique."],"learning_goals_en":["Convert a number below 32 to binary and back.","Explain why two states are enough for an electronic machine."],"tutor_focus_fr":"Fais convertir 13 puis 40 en binaire en écrivant les puissances de deux, et demande combien de valeurs tiennent sur 8 bits.","tutor_focus_en":"Have the student convert 13 then 40 to binary by writing the powers of two, and ask how many values fit in 8 bits.","example_contexts_fr":["un compteur de likes qui passe de 255 à 256","une adresse IPv4 écrite en quatre octets","un interrupteur allumé ou éteint"],"example_contexts_en":["a like counter going from 255 to 256","an IPv4 address written as four bytes","a switch that is on or off"],"safety_category":"standard"},{"key":"computer_science.text_encoding","domain_id":"computer_science","objective_ids":["cs_systems","cs_programming","cs_software_data"],"stage":1,"order":3,"required":true,"prerequisite_keys":["computer_science.binary_numbers"],"fallback_key":null,"title_fr":"Pourquoi le texte a besoin d'Unicode et d'UTF-8","title_en":"Why text needs Unicode and UTF-8","summary_fr":"Comprendre qu'un caractère est un numéro et que l'encodage décide du nombre d'octets utilisés.","summary_en":"See that a character is a number and that the encoding decides how many bytes it takes.","learning_goals_fr":["Distinguer le caractère, son point de code Unicode et ses octets UTF-8.","Expliquer l'origine des caractères illisibles dans un fichier."],"learning_goals_en":["Tell apart the character, its Unicode code point and its UTF-8 bytes.","Explain where unreadable characters in a file come from."],"tutor_focus_fr":"Fais expliquer pourquoi « é » occupe deux octets en UTF-8 alors que « e » en occupe un, puis demande ce qui se passe si un fichier UTF-8 est lu en latin-1.","tutor_focus_en":"Have the student explain why “é” takes two bytes in UTF-8 while “e” takes one, then ask what happens when a UTF-8 file is read as latin-1.","example_contexts_fr":["un prénom accentué mal affiché dans un export CSV","un emoji qui compte pour plusieurs octets dans un SMS","un nom de fichier japonais copié sur une clé USB"],"example_contexts_en":["an accented first name broken in a CSV export","an emoji counting as several bytes in a text message","a Japanese file name copied onto a USB stick"],"safety_category":"standard"},{"key":"computer_science.what_is_algorithm","domain_id":"computer_science","objective_ids":["cs_systems","cs_programming","cs_software_data"],"stage":1,"order":4,"required":true,"prerequisite_keys":["computer_science.text_encoding"],"fallback_key":null,"title_fr":"Ce qu'est vraiment un algorithme","title_en":"What an algorithm really is","summary_fr":"Distinguer un algorithme d'un programme : une suite finie d'étapes non ambiguës qui termine.","summary_en":"Separate an algorithm from a program: a finite sequence of unambiguous steps that terminates.","learning_goals_fr":["Citer les trois propriétés d'un algorithme : entrées définies, étapes non ambiguës, terminaison.","Écrire en français les étapes d'une recherche du plus grand élément."],"learning_goals_en":["State the three properties of an algorithm: defined inputs, unambiguous steps, termination.","Write in plain words the steps of a search for the largest element."],"tutor_focus_fr":"Fais rédiger en français les étapes pour trouver le maximum d'une liste, puis fais tester ces étapes sur une liste vide pour montrer le cas oublié.","tutor_focus_en":"Have the student write in plain words the steps to find the maximum of a list, then run those steps on an empty list to expose the forgotten case.","example_contexts_fr":["trouver le trajet le plus court dans une application de transport","classer des candidatures par date de dépôt","vérifier qu'un mot est un palindrome"],"example_contexts_en":["finding the shortest route in a transit app","sorting applications by submission date","checking whether a word is a palindrome"],"safety_category":"standard"},{"key":"computer_science.client_server","domain_id":"computer_science","objective_ids":["cs_systems","cs_programming","cs_software_data"],"stage":1,"order":5,"required":true,"prerequisite_keys":["computer_science.what_is_algorithm"],"fallback_key":null,"title_fr":"Client et serveur : qui demande, qui répond","title_en":"Client and server: who asks, who answers","summary_fr":"Poser le modèle requête-réponse et identifier ce qui tourne sur l'appareil et ce qui tourne à distance.","summary_en":"Set up the request-response model and identify what runs on the device and what runs remotely.","learning_goals_fr":["Décrire le trajet d'une requête et de sa réponse.","Dire quelle partie d'une application donnée est cliente et laquelle est serveur."],"learning_goals_en":["Describe the path of a request and its response.","Say which part of a given application is the client and which is the server."],"tutor_focus_fr":"Fais tracer la requête et la réponse d'un rafraîchissement de fil d'actualité, puis demande ce qui reste possible hors connexion.","tutor_focus_en":"Have the student trace the request and response of a feed refresh, then ask what still works offline.","example_contexts_fr":["une application météo qui rafraîchit ses prévisions","un site de réservation qui affiche les places restantes","une boîte mail qui télécharge les nouveaux messages"],"example_contexts_en":["a weather app refreshing its forecast","a booking site showing remaining seats","a mailbox downloading new messages"],"safety_category":"standard"},{"key":"computer_science.cpu_instruction_cycle","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":1,"order":6,"required":true,"prerequisite_keys":["computer_science.client_server"],"fallback_key":null,"title_fr":"Comment un processeur exécute une instruction","title_en":"How a processor executes an instruction","summary_fr":"Dérouler le cycle chercher-décoder-exécuter sur une instruction d'addition.","summary_en":"Walk the fetch-decode-execute cycle through a single addition instruction.","learning_goals_fr":["Nommer les trois phases du cycle et le rôle du compteur ordinal.","Dire où sont lues les données et où est écrit le résultat."],"learning_goals_en":["Name the three phases of the cycle and the role of the program counter.","Say where the data is read and where the result is written."],"tutor_focus_fr":"Fais dérouler pas à pas l'addition de deux registres, phase par phase, puis demande ce que devient le compteur ordinal après un saut.","tutor_focus_en":"Have the student walk an addition of two registers phase by phase, then ask what happens to the program counter after a jump.","example_contexts_fr":["l'addition de deux nombres dans une boucle de comptage","un branchement conditionnel qui change la suite du programme","une instruction de copie entre deux registres"],"example_contexts_en":["adding two numbers inside a counting loop","a conditional branch changing what runs next","a copy instruction between two registers"],"safety_category":"standard"},{"key":"computer_science.variables_and_types","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":1,"order":7,"required":true,"prerequisite_keys":["computer_science.client_server"],"fallback_key":null,"title_fr":"Variables et types : ce que la machine range vraiment","title_en":"Variables and types: what the machine actually stores","summary_fr":"Séparer le nom, la valeur et le type, et voir ce que le type autorise comme opérations.","summary_en":"Separate the name, the value and the type, and see what the type allows as operations.","learning_goals_fr":["Distinguer le nom d'une variable, sa valeur et son type.","Prévoir le résultat d'une addition entre un nombre et une chaîne."],"learning_goals_en":["Tell apart a variable name, its value and its type.","Predict the result of adding a number to a string."],"tutor_focus_fr":"Fais prédire le résultat de \"2\" + 3 dans deux langages différents, puis demande ce que le type change pour la machine.","tutor_focus_en":"Have the student predict the result of \"2\" + 3 in two different languages, then ask what the type changes for the machine.","example_contexts_fr":["un âge saisi dans un formulaire et lu comme du texte","un prix décimal arrondi à l'affichage","un compteur remis à zéro à chaque tour de boucle"],"example_contexts_en":["an age typed in a form and read as text","a decimal price rounded for display","a counter reset to zero on each loop turn"],"safety_category":"standard"},{"key":"computer_science.what_is_database","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":1,"order":8,"required":true,"prerequisite_keys":["computer_science.client_server"],"fallback_key":null,"title_fr":"Ce qu'une base de données garantit qu'un fichier ne garantit pas","title_en":"What a database guarantees that a file does not","summary_fr":"Comparer un fichier partagé et une base sur les écritures simultanées et l'intégrité des données.","summary_en":"Compare a shared file and a database on concurrent writes and data integrity.","learning_goals_fr":["Citer trois garanties qu'une base apporte à un fichier partagé.","Décrire ce qui casse quand deux personnes écrivent le même fichier."],"learning_goals_en":["State three guarantees a database adds over a shared file.","Describe what breaks when two people write the same file."],"tutor_focus_fr":"Fais raconter ce qui arrive à un tableur partagé modifié par deux personnes hors ligne, puis demande ce qu'une base aurait empêché.","tutor_focus_en":"Have the student narrate what happens to a shared spreadsheet edited offline by two people, then ask what a database would have prevented.","example_contexts_fr":["un tableur de stock partagé par deux magasins","un fichier de contacts recopié sur plusieurs postes","un registre de réservations tenu à la main"],"example_contexts_en":["a stock spreadsheet shared by two shops","a contact file copied onto several machines","a booking register kept by hand"],"safety_category":"standard"},{"key":"computer_science.source_to_execution","domain_id":"computer_science","objective_ids":["cs_systems","cs_programming","cs_software_data"],"stage":2,"order":9,"required":true,"prerequisite_keys":["computer_science.client_server"],"fallback_key":"computer_science.client_server","title_fr":"Du code source au programme qui s'exécute","title_en":"From source code to a running program","summary_fr":"Suivre le passage du texte source aux instructions machine, par compilation ou par interprétation.","summary_en":"Follow how source text becomes machine instructions, through compilation or interpretation.","learning_goals_fr":["Comparer compilation et interprétation sur le moment où l'erreur apparaît.","Nommer ce que produit un compilateur et ce que lit un interpréteur."],"learning_goals_en":["Compare compilation and interpretation by when the error shows up.","Name what a compiler produces and what an interpreter reads."],"tutor_focus_fr":"Fais comparer une faute de frappe détectée à la compilation en Java et la même faute détectée à l'exécution en Python, puis demande laquelle coûte le plus cher en production.","tutor_focus_en":"Have the student compare a typo caught at compile time in Java with the same typo caught at run time in Python, then ask which one costs more in production.","example_contexts_fr":["une application mobile publiée sur un magasin d'applications","un script Python lancé dans un terminal","une page web dont le JavaScript s'exécute dans le navigateur"],"example_contexts_en":["a mobile app shipped to an app store","a Python script launched from a terminal","a web page whose JavaScript runs in the browser"],"safety_category":"standard"},{"key":"computer_science.abstraction_layers","domain_id":"computer_science","objective_ids":["cs_systems","cs_programming","cs_software_data"],"stage":2,"order":10,"required":true,"prerequisite_keys":["computer_science.source_to_execution"],"fallback_key":"computer_science.client_server","title_fr":"Pourquoi l'informatique empile des couches d'abstraction","title_en":"Why computing stacks layers of abstraction","summary_fr":"Voir qu'une abstraction cache des détails en échange d'un coût et d'une perte de contrôle.","summary_en":"See that an abstraction hides details in exchange for a cost and a loss of control.","learning_goals_fr":["Donner un exemple d'abstraction qui fait gagner du temps et un exemple qui coûte cher.","Expliquer ce qu'une abstraction qui fuit rend visible."],"learning_goals_en":["Give one abstraction that saves time and one that costs dearly.","Explain what a leaky abstraction makes visible."],"tutor_focus_fr":"Fais lister ce que cache l'appel « enregistrer un fichier », puis demande ce que l'utilisateur découvre quand le disque est plein.","tutor_focus_en":"Have the student list what the call “save a file” hides, then ask what the user discovers when the disk is full.","example_contexts_fr":["un langage qui gère la mémoire à la place du développeur","un service de stockage en ligne présenté comme un dossier","une bibliothèque graphique qui masque le pilote de la carte"],"example_contexts_en":["a language that manages memory for the developer","an online storage service presented as a folder","a graphics library hiding the card driver"],"safety_category":"standard"},{"key":"computer_science.files_and_filesystem","domain_id":"computer_science","objective_ids":["cs_systems","cs_programming","cs_software_data"],"stage":2,"order":11,"required":true,"prerequisite_keys":["computer_science.abstraction_layers"],"fallback_key":"computer_science.client_server","title_fr":"Ce qu'est un fichier pour un système d'exploitation","title_en":"What a file is for an operating system","summary_fr":"Comprendre qu'un fichier est un nom, des métadonnées et une suite d'octets répartie sur le disque.","summary_en":"Understand that a file is a name, metadata and a byte sequence spread over the disk.","learning_goals_fr":["Distinguer le nom, le chemin, les métadonnées et le contenu.","Expliquer pourquoi supprimer un fichier n'efface pas immédiatement ses octets."],"learning_goals_en":["Tell apart the name, the path, the metadata and the content.","Explain why deleting a file does not immediately erase its bytes."],"tutor_focus_fr":"Fais décrire ce que contient l'entrée de répertoire d'un fichier photo, puis demande pourquoi un logiciel de récupération peut encore le retrouver après suppression.","tutor_focus_en":"Have the student describe what the directory entry of a photo file holds, then ask why recovery software can still find it after deletion.","example_contexts_fr":["une photo déplacée entre deux dossiers","un document verrouillé parce qu'il est déjà ouvert","une clé USB retirée pendant une copie"],"example_contexts_en":["a photo moved between two folders","a document locked because it is already open","a USB stick pulled out during a copy"],"safety_category":"standard"},{"key":"computer_science.orders_of_magnitude","domain_id":"computer_science","objective_ids":["cs_systems","cs_programming","cs_software_data"],"stage":2,"order":12,"required":true,"prerequisite_keys":["computer_science.files_and_filesystem"],"fallback_key":"computer_science.client_server","title_fr":"Ordres de grandeur : octet, milliseconde, million d'opérations","title_en":"Orders of magnitude: byte, millisecond, million operations","summary_fr":"Acquérir les repères chiffrés qui permettent de juger si une performance est normale ou absurde.","summary_en":"Build the numeric landmarks that tell whether a measured performance is normal or absurd.","learning_goals_fr":["Citer l'ordre de grandeur d'un accès mémoire, d'un accès disque et d'un aller-retour réseau.","Estimer si une opération annoncée est plausible."],"learning_goals_en":["State the order of magnitude of a memory access, a disk access and a network round trip.","Estimate whether an announced operation is plausible."],"tutor_focus_fr":"Fais classer un accès RAM, une lecture SSD et un appel réseau transatlantique par durée, puis demande combien d'appels réseau tiennent dans une seconde.","tutor_focus_en":"Have the student rank a RAM access, an SSD read and a transatlantic network call by duration, then ask how many network calls fit in one second.","example_contexts_fr":["une page web qui met trois secondes à s'afficher","un export de 50 000 lignes annoncé instantané","une sauvegarde de 2 Go sur une connexion domestique"],"example_contexts_en":["a web page taking three seconds to appear","a 50,000-row export announced as instant","a 2 GB backup over a home connection"],"safety_category":"standard"},{"key":"computer_science.ram_vs_storage","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":2,"order":13,"required":true,"prerequisite_keys":["computer_science.orders_of_magnitude"],"fallback_key":"computer_science.cpu_instruction_cycle","title_fr":"Différence entre RAM et stockage","title_en":"The difference between RAM and storage","summary_fr":"Opposer mémoire vive et stockage persistant sur la volatilité, la vitesse et le prix par gigaoctet.","summary_en":"Contrast volatile memory and persistent storage on volatility, speed and price per gigabyte.","learning_goals_fr":["Expliquer pourquoi un travail non enregistré disparaît à l'extinction.","Comparer les temps d'accès RAM et SSD par ordre de grandeur."],"learning_goals_en":["Explain why unsaved work disappears when the machine powers off.","Compare RAM and SSD access times by order of magnitude."],"tutor_focus_fr":"Fais expliquer ce qui est perdu lors d'une coupure de courant, puis demande pourquoi on n'installe pas 2 To de RAM à la place du disque.","tutor_focus_en":"Have the student explain what is lost in a power cut, then ask why we do not install 2 TB of RAM instead of a disk.","example_contexts_fr":["un document en cours d'écriture pendant une coupure de courant","un jeu qui affiche un écran de chargement","un téléphone qui ferme une application restée en arrière-plan"],"example_contexts_en":["a document being written during a power cut","a game showing a loading screen","a phone closing an app left in the background"],"safety_category":"standard"},{"key":"computer_science.os_processes","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":2,"order":14,"required":false,"prerequisite_keys":["computer_science.ram_vs_storage"],"fallback_key":"computer_science.cpu_instruction_cycle","title_fr":"Pourquoi les systèmes d'exploitation utilisent des processus","title_en":"Why operating systems use processes","summary_fr":"Comprendre le processus comme unité d'isolation : mémoire séparée, droits propres, arrêt indépendant.","summary_en":"See the process as the unit of isolation: separate memory, own permissions, independent shutdown.","learning_goals_fr":["Expliquer ce qu'un processus isole d'un autre.","Dire ce qui survit et ce qui disparaît quand un processus est tué."],"learning_goals_en":["Explain what one process isolates from another.","Say what survives and what disappears when a process is killed."],"tutor_focus_fr":"Fais expliquer pourquoi un onglet de navigateur qui plante ne tue pas les autres, puis demande ce que le système récupère à la fin d'un processus.","tutor_focus_en":"Have the student explain why a crashing browser tab does not kill the others, then ask what the system reclaims when a process ends.","example_contexts_fr":["un onglet de navigateur qui plante seul","un antivirus qui tourne sans bloquer le traitement de texte","un serveur qui redémarre un service défaillant"],"example_contexts_en":["a browser tab crashing on its own","an antivirus running without freezing the word processor","a server restarting a failed service"],"safety_category":"standard"},{"key":"computer_science.conditions_and_loops","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":2,"order":15,"required":true,"prerequisite_keys":["computer_science.orders_of_magnitude"],"fallback_key":"computer_science.variables_and_types","title_fr":"Conditions et boucles : contrôler le flux d'exécution","title_en":"Conditions and loops: controlling execution flow","summary_fr":"Écrire une condition sans cas oublié et une boucle dont on sait pourquoi elle s'arrête.","summary_en":"Write a condition with no forgotten case and a loop whose stopping reason is known.","learning_goals_fr":["Écrire une condition qui couvre tous les cas d'entrée.","Identifier la variable qui garantit l'arrêt d'une boucle."],"learning_goals_en":["Write a condition that covers every input case.","Identify the variable that guarantees a loop terminates."],"tutor_focus_fr":"Fais écrire les conditions d'un tarif à trois tranches, puis demande quelle entrée n'est traitée par aucune branche.","tutor_focus_en":"Have the student write the conditions of a three-band fare, then ask which input no branch handles.","example_contexts_fr":["un tarif réduit selon l'âge du voyageur","une boucle qui parcourt les lignes d'un fichier","un mot de passe redemandé jusqu'à trois essais"],"example_contexts_en":["a reduced fare based on traveller age","a loop reading the lines of a file","a password prompt allowed up to three attempts"],"safety_category":"standard"},{"key":"computer_science.functions_and_scope","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":2,"order":16,"required":false,"prerequisite_keys":["computer_science.conditions_and_loops"],"fallback_key":"computer_science.variables_and_types","title_fr":"Fonctions, paramètres et portée des variables","title_en":"Functions, parameters and variable scope","summary_fr":"Comprendre ce qu'une fonction reçoit, ce qu'elle renvoie et ce qu'elle ne devrait pas connaître.","summary_en":"Understand what a function receives, what it returns and what it should not know about.","learning_goals_fr":["Distinguer paramètre, argument et valeur de retour.","Expliquer pourquoi une variable locale n'existe plus après l'appel."],"learning_goals_en":["Tell apart parameter, argument and return value.","Explain why a local variable no longer exists after the call."],"tutor_focus_fr":"Fais transformer un bloc de code répété en fonction avec deux paramètres, puis demande quelles variables globales elle ne doit plus lire.","tutor_focus_en":"Have the student turn a repeated block into a function with two parameters, then ask which global variables it must stop reading.","example_contexts_fr":["un calcul de TVA répété à trois endroits","une fonction de validation d'adresse e-mail","un utilitaire de formatage de date partagé par deux écrans"],"example_contexts_en":["a VAT computation repeated in three places","an email address validation function","a date formatting helper shared by two screens"],"safety_category":"standard"},{"key":"computer_science.tables_and_keys","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":2,"order":17,"required":true,"prerequisite_keys":["computer_science.orders_of_magnitude"],"fallback_key":"computer_science.what_is_database","title_fr":"Tables, clés primaires et clés étrangères","title_en":"Tables, primary keys and foreign keys","summary_fr":"Modéliser deux entités liées et comprendre ce qu'une clé étrangère interdit.","summary_en":"Model two related entities and understand what a foreign key forbids.","learning_goals_fr":["Choisir une clé primaire stable pour une entité.","Expliquer ce qu'une clé étrangère empêche d'insérer ou de supprimer."],"learning_goals_en":["Choose a stable primary key for an entity.","Explain what a foreign key prevents on insert and on delete."],"tutor_focus_fr":"Fais modéliser clients et commandes en deux tables, puis demande ce qui se passe à la suppression d'un client qui a des commandes.","tutor_focus_en":"Have the student model customers and orders as two tables, then ask what happens when deleting a customer who has orders.","example_contexts_fr":["un client et ses commandes dans une boutique en ligne","un auteur et ses articles dans un blog","un élève et ses inscriptions à des cours"],"example_contexts_en":["a customer and their orders in an online shop","an author and their posts in a blog","a student and their course enrolments"],"safety_category":"standard"},{"key":"computer_science.git_commit_history","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":2,"order":18,"required":false,"prerequisite_keys":["computer_science.tables_and_keys"],"fallback_key":"computer_science.what_is_database","title_fr":"Ce qu'un commit Git enregistre vraiment","title_en":"What a Git commit actually records","summary_fr":"Voir un commit comme un instantané complet relié à son parent, et non comme une différence isolée.","summary_en":"See a commit as a full snapshot linked to its parent, not as an isolated diff.","learning_goals_fr":["Décrire ce que contient un commit et ce qui le relie au précédent.","Expliquer pourquoi l'historique permet de revenir en arrière."],"learning_goals_en":["Describe what a commit contains and what links it to the previous one.","Explain why the history makes it possible to go back."],"tutor_focus_fr":"Fais décrire le contenu d'un commit et son lien au parent, puis demande ce que retrouve exactement un retour à un commit ancien.","tutor_focus_en":"Have the student describe a commit's content and its parent link, then ask exactly what checking out an old commit restores.","example_contexts_fr":["une correction envoyée juste avant une démonstration","un fichier supprimé par erreur la semaine précédente","deux développeurs qui travaillent sur le même dossier"],"example_contexts_en":["a fix pushed right before a demo","a file deleted by mistake the week before","two developers working in the same folder"],"safety_category":"standard"},{"key":"computer_science.http_request_path","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":3,"order":19,"required":true,"prerequisite_keys":["computer_science.os_processes"],"fallback_key":"computer_science.os_processes","title_fr":"Comment une requête HTTP atteint un serveur","title_en":"How an HTTP request reaches a server","summary_fr":"Suivre une requête depuis la barre d'adresse jusqu'au processus serveur qui la traite.","summary_en":"Follow a request from the address bar to the server process that handles it.","learning_goals_fr":["Ordonner résolution de nom, connexion, requête, réponse.","Lire une ligne de requête et un code de statut."],"learning_goals_en":["Order name resolution, connection, request and response.","Read a request line and a status code."],"tutor_focus_fr":"Fais décrire chaque étape entre la touche Entrée et l'affichage, puis demande ce que signifient un 404 et un 502 pour le trajet décrit.","tutor_focus_en":"Have the student describe each step between pressing Enter and seeing the page, then ask what a 404 and a 502 mean along that path.","example_contexts_fr":["l'ouverture d'un article de presse en ligne","un formulaire de connexion envoyé en POST","une image qui reste en chargement sur une page"],"example_contexts_en":["opening an online news article","a login form submitted with POST","an image stuck loading on a page"],"safety_category":"standard"},{"key":"computer_science.dns_resolution","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":3,"order":20,"required":false,"prerequisite_keys":["computer_science.http_request_path"],"fallback_key":"computer_science.os_processes","title_fr":"Comment un nom de domaine devient une adresse IP","title_en":"How a domain name becomes an IP address","summary_fr":"Décrire la résolution DNS en cascade et le rôle du cache dans la vitesse et dans les pannes.","summary_en":"Describe cascading DNS resolution and the role of caching in both speed and outages.","learning_goals_fr":["Nommer les résolveurs successifs interrogés lors d'une résolution.","Expliquer l'effet d'un TTL sur un changement d'adresse."],"learning_goals_en":["Name the successive resolvers queried during a lookup.","Explain the effect of a TTL when an address changes."],"tutor_focus_fr":"Fais décrire la cascade de résolveurs pour un nom jamais visité, puis demande pourquoi un changement d'hébergeur met des heures à être visible partout.","tutor_focus_en":"Have the student describe the resolver cascade for a never-visited name, then ask why a hosting move takes hours to be visible everywhere.","example_contexts_fr":["un site déménagé chez un nouvel hébergeur","un réseau d'entreprise qui bloque un domaine","un nom de domaine qui vient d'être acheté"],"example_contexts_en":["a site moved to a new hosting provider","a corporate network blocking a domain","a domain name bought minutes ago"],"safety_category":"standard"},{"key":"computer_science.cpu_cache_locality","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":3,"order":21,"required":false,"prerequisite_keys":["computer_science.dns_resolution"],"fallback_key":"computer_science.os_processes","title_fr":"Pourquoi les caches du processeur rendent un code rapide ou lent","title_en":"Why CPU caches make code fast or slow","summary_fr":"Relier la hiérarchie mémoire à la localité des accès et au coût réel d'un défaut de cache.","summary_en":"Connect the memory hierarchy to access locality and to the real cost of a cache miss.","learning_goals_fr":["Expliquer localité temporelle et localité spatiale.","Prévoir quel parcours de tableau à deux dimensions sera le plus rapide."],"learning_goals_en":["Explain temporal locality and spatial locality.","Predict which traversal of a two-dimensional array will be faster."],"tutor_focus_fr":"Fais comparer le parcours d'une matrice ligne par ligne et colonne par colonne, puis demande d'estimer le rapport de durée entre les deux.","tutor_focus_en":"Have the student compare row-by-row and column-by-column traversal of a matrix, then ask for an estimate of the ratio between the two.","example_contexts_fr":["le parcours d'une image pixel par pixel","une somme sur un très grand tableau de mesures","une liste chaînée dispersée en mémoire"],"example_contexts_en":["walking an image pixel by pixel","summing a very large array of measurements","a linked list scattered across memory"],"safety_category":"standard"},{"key":"computer_science.threads_and_context_switch","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":3,"order":22,"required":false,"prerequisite_keys":["computer_science.cpu_cache_locality"],"fallback_key":"computer_science.os_processes","title_fr":"Threads et changement de contexte","title_en":"Threads and context switching","summary_fr":"Comprendre ce que le système sauvegarde pour donner l'illusion que tout tourne en même temps.","summary_en":"Understand what the system saves to keep the illusion that everything runs at once.","learning_goals_fr":["Distinguer parallélisme réel et concurrence par alternance.","Citer ce qui est sauvegardé lors d'un changement de contexte."],"learning_goals_en":["Tell apart true parallelism and concurrency by interleaving.","List what is saved during a context switch."],"tutor_focus_fr":"Fais expliquer comment quatre cœurs font tourner cent tâches, puis demande pourquoi multiplier les threads finit par ralentir la machine.","tutor_focus_en":"Have the student explain how four cores run a hundred tasks, then ask why adding threads eventually slows the machine down.","example_contexts_fr":["un serveur web qui traite mille connexions simultanées","une interface qui reste réactive pendant un téléchargement","un traitement d'images réparti sur plusieurs cœurs"],"example_contexts_en":["a web server handling a thousand simultaneous connections","an interface staying responsive during a download","image processing spread across several cores"],"safety_category":"standard"},{"key":"computer_science.arrays_vs_linked_lists","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":3,"order":23,"required":true,"prerequisite_keys":["computer_science.functions_and_scope"],"fallback_key":"computer_science.functions_and_scope","title_fr":"Tableau ou liste chaînée : quel coût pour quelle opération","title_en":"Array or linked list: which cost for which operation","summary_fr":"Comparer accès indexé et insertion au milieu pour choisir la structure adaptée à un usage.","summary_en":"Compare indexed access and middle insertion to pick the structure that fits a usage.","learning_goals_fr":["Comparer le coût de l'accès par indice et de l'insertion pour les deux structures.","Choisir la structure adaptée à une liste modifiée en permanence."],"learning_goals_en":["Compare the cost of index access and insertion for both structures.","Choose the right structure for a constantly modified list."],"tutor_focus_fr":"Fais comparer l'insertion de mille éléments au milieu d'un tableau et d'une liste chaînée, puis demande laquelle convient à une file d'attente.","tutor_focus_en":"Have the student compare inserting a thousand elements in the middle of an array and of a linked list, then ask which fits a waiting queue.","example_contexts_fr":["une file d'attente de tickets de support","un historique de navigation parcouru en arrière","un tableau de scores trié affiché à l'écran"],"example_contexts_en":["a support ticket waiting queue","a browsing history walked backwards","a sorted scoreboard displayed on screen"],"safety_category":"standard"},{"key":"computer_science.hash_maps","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":3,"order":24,"required":false,"prerequisite_keys":["computer_science.arrays_vs_linked_lists"],"fallback_key":"computer_science.functions_and_scope","title_fr":"Comment une table de hachage retrouve une clé","title_en":"How a hash map finds a key","summary_fr":"Relier la fonction de hachage, le seau d'arrivée et la gestion des collisions au coût moyen constant.","summary_en":"Connect the hash function, the target bucket and collision handling to constant average cost.","learning_goals_fr":["Expliquer le chemin d'une clé jusqu'à sa valeur.","Dire ce qui dégrade une table de hachage en recherche linéaire."],"learning_goals_en":["Explain the path from a key to its value.","Say what degrades a hash map into a linear search."],"tutor_focus_fr":"Fais suivre une clé jusqu'à son seau, puis demande ce qui se passe si toutes les clés tombent dans le même seau.","tutor_focus_en":"Have the student follow a key to its bucket, then ask what happens when every key lands in the same bucket.","example_contexts_fr":["un annuaire téléphonique interrogé par nom","un cache de sessions utilisateur","un comptage d'occurrences de mots dans un texte"],"example_contexts_en":["a phone directory queried by name","a cache of user sessions","counting word occurrences in a text"],"safety_category":"standard"},{"key":"computer_science.linear_vs_log_complexity","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":3,"order":25,"required":false,"prerequisite_keys":["computer_science.hash_maps"],"fallback_key":"computer_science.functions_and_scope","title_fr":"Complexité linéaire et logarithmique","title_en":"Linear and logarithmic complexity","summary_fr":"Comparer le nombre d'opérations d'une recherche séquentielle et d'une recherche dichotomique.","summary_en":"Compare the operation count of a sequential search and a binary search.","learning_goals_fr":["Compter les comparaisons des deux recherches sur un million d'éléments.","Nommer la condition qui rend la dichotomie possible."],"learning_goals_en":["Count the comparisons of both searches over a million elements.","Name the condition that makes binary search possible."],"tutor_focus_fr":"Fais compter les comparaisons pour un million d'éléments dans les deux cas, puis demande ce qu'exige la dichotomie sur les données.","tutor_focus_en":"Have the student count comparisons for a million elements in both cases, then ask what binary search requires from the data.","example_contexts_fr":["la recherche d'un mot dans un dictionnaire papier","un identifiant cherché dans un journal d'événements","un produit cherché dans un catalogue trié par référence"],"example_contexts_en":["looking up a word in a paper dictionary","an identifier searched in an event log","a product searched in a catalogue sorted by reference"],"safety_category":"standard"},{"key":"computer_science.recursion_base_case","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":3,"order":26,"required":false,"prerequisite_keys":["computer_science.linear_vs_log_complexity"],"fallback_key":"computer_science.functions_and_scope","title_fr":"Récursivité et cas de base","title_en":"Recursion and the base case","summary_fr":"Écrire une fonction récursive dont le cas de base est atteint et suivre l'empilement des appels.","summary_en":"Write a recursive function whose base case is reached and follow the stack of calls.","learning_goals_fr":["Identifier le cas de base et la réduction du problème.","Expliquer l'origine d'un débordement de pile."],"learning_goals_en":["Identify the base case and how the problem shrinks.","Explain where a stack overflow comes from."],"tutor_focus_fr":"Fais dérouler la pile d'appels d'une factorielle de 4, puis demande ce qui manque dans une version qui ne s'arrête jamais.","tutor_focus_en":"Have the student unroll the call stack of factorial 4, then ask what is missing in a version that never stops.","example_contexts_fr":["le parcours des dossiers imbriqués d'un disque","le calcul d'une factorielle","l'affichage d'un fil de commentaires imbriqués"],"example_contexts_en":["walking the nested folders of a disk","computing a factorial","rendering a thread of nested comments"],"safety_category":"standard"},{"key":"computer_science.sql_select_join","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":3,"order":27,"required":true,"prerequisite_keys":["computer_science.git_commit_history"],"fallback_key":"computer_science.git_commit_history","title_fr":"Ce que fait vraiment une jointure SQL","title_en":"What a SQL join actually does","summary_fr":"Comprendre l'appariement ligne à ligne d'une jointure et l'effet d'une jointure externe.","summary_en":"Understand the row-by-row matching of a join and the effect of an outer join.","learning_goals_fr":["Prévoir le nombre de lignes produites par une jointure.","Distinguer jointure interne et jointure externe sur un exemple."],"learning_goals_en":["Predict the number of rows a join produces.","Tell apart inner and outer join on a concrete example."],"tutor_focus_fr":"Fais prévoir le nombre de lignes d'une jointure entre trois clients et cinq commandes, puis demande ce que change une jointure externe à gauche.","tutor_focus_en":"Have the student predict the row count of a join between three customers and five orders, then ask what a left outer join changes.","example_contexts_fr":["un rapport des commandes par client","une liste d'élèves sans note enregistrée","un export comptable qui duplique des lignes"],"example_contexts_en":["a report of orders per customer","a list of students with no recorded grade","an accounting export that duplicates rows"],"safety_category":"standard"},{"key":"computer_science.rest_api_contract","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":3,"order":28,"required":false,"prerequisite_keys":["computer_science.sql_select_join"],"fallback_key":"computer_science.git_commit_history","title_fr":"Le contrat d'une API REST","title_en":"The contract of a REST API","summary_fr":"Lire une API comme un contrat : ressources, verbes, codes de statut et forme des erreurs.","summary_en":"Read an API as a contract: resources, verbs, status codes and error shape.","learning_goals_fr":["Associer chaque verbe HTTP à l'effet attendu sur une ressource.","Choisir le code de statut adapté à trois situations d'erreur."],"learning_goals_en":["Map each HTTP verb to its expected effect on a resource.","Pick the right status code for three error situations."],"tutor_focus_fr":"Fais choisir le verbe et le code de statut pour créer, modifier et supprimer une réservation, puis demande ce que doit contenir le corps d'une erreur.","tutor_focus_en":"Have the student pick verb and status code to create, update and delete a booking, then ask what an error body must contain.","example_contexts_fr":["une API de réservation de salles","une intégration de paiement appelée par une application mobile","un client qui envoie un champ obligatoire vide"],"example_contexts_en":["a room booking API","a payment integration called by a mobile app","a client sending a required field empty"],"safety_category":"standard"},{"key":"computer_science.database_indexes","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":3,"order":29,"required":false,"prerequisite_keys":["computer_science.rest_api_contract"],"fallback_key":"computer_science.git_commit_history","title_fr":"Pourquoi une base de données utilise des index","title_en":"Why a database uses indexes","summary_fr":"Comprendre l'index comme structure triée qui accélère la lecture et ralentit l'écriture.","summary_en":"See an index as a sorted structure that speeds reads up and slows writes down.","learning_goals_fr":["Expliquer ce qu'un index évite de parcourir.","Citer deux coûts d'un index inutile."],"learning_goals_en":["Explain what an index avoids scanning.","State two costs of a useless index."],"tutor_focus_fr":"Fais comparer une recherche par e-mail sur un million de lignes avec et sans index, puis demande ce que coûte cet index à chaque insertion.","tutor_focus_en":"Have the student compare an email lookup over a million rows with and without an index, then ask what that index costs on every insert.","example_contexts_fr":["une connexion utilisateur recherchée par adresse e-mail","un rapport mensuel filtré par date de commande","une table d'historique alimentée en continu"],"example_contexts_en":["a user login looked up by email address","a monthly report filtered by order date","a history table written to continuously"],"safety_category":"standard"},{"key":"computer_science.git_branch_merge","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":3,"order":30,"required":false,"prerequisite_keys":["computer_science.database_indexes"],"fallback_key":"computer_science.git_commit_history","title_fr":"Branches et fusions","title_en":"Branches and merges","summary_fr":"Comprendre l'origine d'un conflit de fusion et ce que Git demande de trancher.","summary_en":"Understand where a merge conflict comes from and what Git asks you to decide.","learning_goals_fr":["Expliquer ce qu'une branche isole du tronc commun.","Décrire la situation exacte qui produit un conflit."],"learning_goals_en":["Explain what a branch isolates from the main line.","Describe the exact situation that produces a conflict."],"tutor_focus_fr":"Fais décrire deux branches qui modifient la même ligne, puis demande ce que Git ne peut pas décider seul et pourquoi.","tutor_focus_en":"Have the student describe two branches editing the same line, then ask what Git cannot decide alone and why.","example_contexts_fr":["une correction urgente pendant qu'une refonte est en cours","deux équipes qui modifient le même fichier de configuration","une branche restée ouverte pendant trois semaines"],"example_contexts_en":["an urgent fix while a rewrite is in progress","two teams editing the same configuration file","a branch left open for three weeks"],"safety_category":"standard"},{"key":"computer_science.virtual_memory","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":4,"order":31,"required":true,"prerequisite_keys":["computer_science.threads_and_context_switch"],"fallback_key":"computer_science.threads_and_context_switch","title_fr":"Mémoire virtuelle et pagination","title_en":"Virtual memory and paging","summary_fr":"Comprendre la traduction d'adresses virtuelles en adresses physiques et le coût du recours au disque.","summary_en":"Understand the translation from virtual to physical addresses and the cost of falling back to disk.","learning_goals_fr":["Expliquer pourquoi chaque processus croit disposer de toute la mémoire.","Décrire ce qui se passe lors d'un défaut de page."],"learning_goals_en":["Explain why every process believes it owns the whole memory.","Describe what happens on a page fault."],"tutor_focus_fr":"Fais expliquer la traduction d'une adresse par la table des pages, puis demande pourquoi une machine qui swappe devient brutalement inutilisable.","tutor_focus_en":"Have the student explain address translation through the page table, then ask why a swapping machine becomes suddenly unusable.","example_contexts_fr":["un ordinateur qui rame quand la mémoire est saturée","deux processus qui utilisent la même adresse virtuelle","un très gros fichier ouvert par projection en mémoire"],"example_contexts_en":["a computer crawling once memory is saturated","two processes using the same virtual address","a very large file opened through memory mapping"],"safety_category":"standard"},{"key":"computer_science.tcp_vs_udp","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":4,"order":32,"required":false,"prerequisite_keys":["computer_science.virtual_memory"],"fallback_key":"computer_science.threads_and_context_switch","title_fr":"TCP ou UDP : fiabilité contre latence","title_en":"TCP or UDP: reliability against latency","summary_fr":"Choisir entre livraison garantie et livraison rapide selon ce que coûte une donnée perdue.","summary_en":"Choose between guaranteed delivery and fast delivery based on what a lost packet costs.","learning_goals_fr":["Citer ce que TCP ajoute et ce qu'UDP refuse d'ajouter.","Justifier le choix du protocole pour un usage donné."],"learning_goals_en":["State what TCP adds and what UDP refuses to add.","Justify the protocol choice for a given use."],"tutor_focus_fr":"Fais justifier le protocole retenu pour un transfert de fichier puis pour un appel vidéo, en demandant à chaque fois le coût d'un paquet perdu.","tutor_focus_en":"Have the student justify the protocol for a file transfer then for a video call, each time asking what a lost packet costs.","example_contexts_fr":["un appel vidéo qui pixellise une demi-seconde","le téléchargement d'une mise à jour système","un jeu en ligne où la position du joueur change dix fois par seconde"],"example_contexts_en":["a video call pixelating for half a second","downloading a system update","an online game where the player position changes ten times per second"],"safety_category":"standard"},{"key":"computer_science.tls_handshake","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":4,"order":33,"required":false,"prerequisite_keys":["computer_science.tcp_vs_udp"],"fallback_key":"computer_science.threads_and_context_switch","title_fr":"Ce que négocie une poignée de main TLS","title_en":"What a TLS handshake negotiates","summary_fr":"Comprendre l'enchaînement authentification du serveur, échange de clés, chiffrement symétrique.","summary_en":"Understand the chain of server authentication, key exchange and symmetric encryption.","learning_goals_fr":["Expliquer le rôle du certificat et de l'autorité qui le signe.","Dire pourquoi la suite de la session n'utilise plus l'asymétrique."],"learning_goals_en":["Explain the role of the certificate and of the authority signing it.","Say why the rest of the session stops using asymmetric cryptography."],"tutor_focus_fr":"Fais décrire les échanges jusqu'à la clé de session, puis demande ce qu'un avertissement de certificat expiré prouve et ne prouve pas.","tutor_focus_en":"Have the student describe the exchanges up to the session key, then ask what an expired-certificate warning proves and does not prove.","example_contexts_fr":["un cadenas affiché dans la barre d'adresse","un avertissement de certificat sur un réseau d'hôtel","une application mobile qui refuse un serveur de test"],"example_contexts_en":["a padlock shown in the address bar","a certificate warning on a hotel network","a mobile app refusing a test server"],"safety_category":"standard"},{"key":"computer_science.race_conditions_locks","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":4,"order":34,"required":false,"prerequisite_keys":["computer_science.tls_handshake"],"fallback_key":"computer_science.threads_and_context_switch","title_fr":"Conditions de course et verrous","title_en":"Race conditions and locks","summary_fr":"Identifier l'entrelacement fautif de deux opérations concurrentes et le coût d'un verrou.","summary_en":"Spot the faulty interleaving of two concurrent operations and the cost of a lock.","learning_goals_fr":["Construire un entrelacement qui produit un solde faux.","Expliquer ce qu'un verrou garantit et ce qu'il coûte."],"learning_goals_en":["Build an interleaving that produces a wrong balance.","Explain what a lock guarantees and what it costs."],"tutor_focus_fr":"Fais écrire l'entrelacement de deux retraits simultanés sur le même compte, puis demande où poser le verrou sans bloquer tout le service.","tutor_focus_en":"Have the student write the interleaving of two simultaneous withdrawals on one account, then ask where to place the lock without blocking the whole service.","example_contexts_fr":["deux retraits simultanés sur le même compte bancaire","deux acheteurs pour le dernier billet d'un concert","un compteur de vues incrémenté par plusieurs serveurs"],"example_contexts_en":["two simultaneous withdrawals from one bank account","two buyers for the last concert ticket","a view counter incremented by several servers"],"safety_category":"standard"},{"key":"computer_science.sorting_algorithms","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":4,"order":35,"required":true,"prerequisite_keys":["computer_science.recursion_base_case"],"fallback_key":"computer_science.recursion_base_case","title_fr":"Pourquoi le tri fusion bat le tri par insertion","title_en":"Why merge sort beats insertion sort","summary_fr":"Comparer deux stratégies de tri sur le nombre de comparaisons et sur la mémoire consommée.","summary_en":"Compare two sorting strategies on comparison count and on memory used.","learning_goals_fr":["Expliquer le découpage récursif du tri fusion.","Dire dans quel cas un tri quadratique reste préférable."],"learning_goals_en":["Explain the recursive splitting of merge sort.","Say when a quadratic sort is still preferable."],"tutor_focus_fr":"Fais trier six nombres par insertion puis par fusion en comptant les comparaisons, et demande à partir de quelle taille l'écart devient décisif.","tutor_focus_en":"Have the student sort six numbers by insertion then by merging while counting comparisons, and ask at which size the gap becomes decisive.","example_contexts_fr":["le tri de dix mille commandes par date","le classement d'une main de cartes","un fichier de logs presque déjà trié"],"example_contexts_en":["sorting ten thousand orders by date","arranging a hand of playing cards","a log file that is almost already sorted"],"safety_category":"standard"},{"key":"computer_science.trees_and_traversal","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":4,"order":36,"required":false,"prerequisite_keys":["computer_science.sorting_algorithms"],"fallback_key":"computer_science.recursion_base_case","title_fr":"Arbres et parcours","title_en":"Trees and traversals","summary_fr":"Choisir entre parcours en profondeur et en largeur selon la question posée à la structure.","summary_en":"Choose between depth-first and breadth-first traversal depending on the question asked.","learning_goals_fr":["Distinguer racine, nœud, feuille et hauteur.","Choisir le parcours qui répond à une question donnée."],"learning_goals_en":["Tell apart root, node, leaf and height.","Choose the traversal that answers a given question."],"tutor_focus_fr":"Fais parcourir un arbre de six nœuds en profondeur puis en largeur, et demande lequel trouve d'abord le nœud le plus proche de la racine.","tutor_focus_en":"Have the student traverse a six-node tree depth-first then breadth-first, and ask which one finds the node closest to the root first.","example_contexts_fr":["l'arborescence des dossiers d'un projet","un organigramme d'entreprise","le rendu d'une page HTML et de ses balises imbriquées"],"example_contexts_en":["the folder tree of a project","a company org chart","rendering an HTML page and its nested tags"],"safety_category":"standard"},{"key":"computer_science.unit_tests","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":4,"order":37,"required":false,"prerequisite_keys":["computer_science.trees_and_traversal"],"fallback_key":"computer_science.recursion_base_case","title_fr":"Ce qu'un bon test unitaire vérifie","title_en":"What a good unit test checks","summary_fr":"Écrire un test qui échoue pour une seule raison et qui documente le comportement attendu.","summary_en":"Write a test that fails for exactly one reason and documents the expected behaviour.","learning_goals_fr":["Séparer préparation, action et vérification dans un test.","Choisir les cas limites à couvrir en priorité."],"learning_goals_en":["Separate arrange, act and assert inside a test.","Choose which edge cases to cover first."],"tutor_focus_fr":"Fais écrire trois cas de test pour une fonction de remise commerciale, dont un cas limite, puis demande lequel casserait si la règle changeait.","tutor_focus_en":"Have the student write three test cases for a discount function, one of them an edge case, then ask which would break if the rule changed.","example_contexts_fr":["une fonction de remise à partir de 100 euros d'achat","un validateur de numéro de téléphone","un calcul de dates de livraison en fin de mois"],"example_contexts_en":["a discount function from 100 euros of purchase","a phone number validator","a delivery date computation at the end of a month"],"safety_category":"standard"},{"key":"computer_science.immutability_side_effects","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":4,"order":38,"required":false,"prerequisite_keys":["computer_science.unit_tests"],"fallback_key":"computer_science.recursion_base_case","title_fr":"Effets de bord et immutabilité","title_en":"Side effects and immutability","summary_fr":"Repérer une fonction qui modifie son entrée et mesurer ce que cela coûte au débogage.","summary_en":"Spot a function that mutates its input and measure what that costs during debugging.","learning_goals_fr":["Distinguer une fonction pure d'une fonction à effet de bord.","Expliquer pourquoi une entrée modifiée rend un bug difficile à reproduire."],"learning_goals_en":["Tell apart a pure function and a function with side effects.","Explain why a mutated input makes a bug hard to reproduce."],"tutor_focus_fr":"Fais repérer la mutation cachée dans une fonction qui trie la liste reçue, puis demande comment la réécrire sans changer l'appelant.","tutor_focus_en":"Have the student spot the hidden mutation in a function that sorts the list it receives, then ask how to rewrite it without changing callers.","example_contexts_fr":["une fonction de tri qui modifie la liste d'origine","un objet de configuration partagé par deux modules","un panier d'achat mis à jour depuis deux écrans"],"example_contexts_en":["a sort function that modifies the original list","a configuration object shared by two modules","a shopping cart updated from two screens"],"safety_category":"standard"},{"key":"computer_science.transactions_acid","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":4,"order":39,"required":true,"prerequisite_keys":["computer_science.git_branch_merge"],"fallback_key":"computer_science.git_branch_merge","title_fr":"Transactions et propriétés ACID","title_en":"Transactions and ACID properties","summary_fr":"Utiliser une transaction pour qu'une suite d'écritures réussisse entièrement ou pas du tout.","summary_en":"Use a transaction so that a sequence of writes fully succeeds or does not happen at all.","learning_goals_fr":["Expliquer atomicité et isolation sur un transfert entre deux comptes.","Dire ce que voit une autre session pendant la transaction."],"learning_goals_en":["Explain atomicity and isolation on a transfer between two accounts.","Say what another session sees while the transaction runs."],"tutor_focus_fr":"Fais dérouler un virement interrompu au milieu, puis demande ce qu'une autre session lit avant la validation.","tutor_focus_en":"Have the student walk through a transfer interrupted midway, then ask what another session reads before the commit.","example_contexts_fr":["un virement entre deux comptes","une commande qui décrémente un stock","une inscription qui crée un compte et un profil"],"example_contexts_en":["a transfer between two accounts","an order decrementing stock","a signup creating an account and a profile"],"safety_category":"standard"},{"key":"computer_science.n_plus_one_queries","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":4,"order":40,"required":false,"prerequisite_keys":["computer_science.transactions_acid"],"fallback_key":"computer_science.git_branch_merge","title_fr":"Le problème des requêtes N+1","title_en":"The N+1 query problem","summary_fr":"Repérer une boucle qui interroge la base à chaque itération et la remplacer par une requête groupée.","summary_en":"Spot a loop that queries the database on each iteration and replace it with one batched query.","learning_goals_fr":["Compter les requêtes générées par une boucle d'affichage.","Proposer une requête unique qui remplace la boucle."],"learning_goals_en":["Count the queries generated by a rendering loop.","Propose a single query that replaces the loop."],"tutor_focus_fr":"Fais compter les requêtes d'une page qui affiche cent commandes avec leur client, puis demande la requête unique équivalente.","tutor_focus_en":"Have the student count the queries of a page showing a hundred orders with their customer, then ask for the equivalent single query.","example_contexts_fr":["une page listant cent commandes avec le nom du client","un export qui charge les auteurs article par article","une API mobile lente uniquement sur la liste principale"],"example_contexts_en":["a page listing a hundred orders with the customer name","an export loading authors article by article","a mobile API slow only on the main list"],"safety_category":"standard"},{"key":"computer_science.cache_invalidation","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":4,"order":41,"required":false,"prerequisite_keys":["computer_science.n_plus_one_queries"],"fallback_key":"computer_science.git_branch_merge","title_fr":"Mettre en cache sans servir des données périmées","title_en":"Caching without serving stale data","summary_fr":"Choisir une stratégie d'invalidation adaptée à la tolérance métier à la donnée obsolète.","summary_en":"Pick an invalidation strategy matching how much staleness the business tolerates.","learning_goals_fr":["Comparer expiration par durée et invalidation à l'écriture.","Fixer une durée de cache justifiée pour une donnée donnée."],"learning_goals_en":["Compare time-based expiry and write-through invalidation.","Set a justified cache duration for a given piece of data."],"tutor_focus_fr":"Fais fixer une durée de cache pour un prix puis pour un article de blog, en demandant à chaque fois le coût d'une valeur périmée.","tutor_focus_en":"Have the student set a cache duration for a price then for a blog post, each time asking what a stale value costs.","example_contexts_fr":["un prix modifié pendant une promotion","une page d'accueil éditoriale mise à jour deux fois par jour","un solde de points de fidélité affiché après un achat"],"example_contexts_en":["a price changed during a promotion","an editorial homepage refreshed twice a day","a loyalty point balance shown right after a purchase"],"safety_category":"standard"},{"key":"computer_science.api_versioning","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":4,"order":42,"required":false,"prerequisite_keys":["computer_science.cache_invalidation"],"fallback_key":"computer_science.git_branch_merge","title_fr":"Faire évoluer une API sans casser ses clients","title_en":"Evolving an API without breaking its clients","summary_fr":"Distinguer changement compatible et rupture, et organiser une migration de clients existants.","summary_en":"Tell apart compatible changes and breaking changes, and plan a migration for existing clients.","learning_goals_fr":["Classer trois modifications en compatibles ou en ruptures.","Décrire une transition qui laisse les anciens clients fonctionner."],"learning_goals_en":["Classify three modifications as compatible or breaking.","Describe a transition that keeps old clients working."],"tutor_focus_fr":"Fais classer l'ajout d'un champ, le renommage d'un champ et le durcissement d'une validation, puis demande le plan de migration correspondant.","tutor_focus_en":"Have the student classify adding a field, renaming a field and tightening a validation, then ask for the matching migration plan.","example_contexts_fr":["une application mobile installée que l'on ne peut pas forcer à se mettre à jour","un partenaire qui intègre l'API depuis deux ans","un champ obligatoire ajouté à un formulaire d'inscription"],"example_contexts_en":["an installed mobile app that cannot be forced to update","a partner integrating the API for two years","a required field added to a signup form"],"safety_category":"standard"},{"key":"computer_science.distributed_replication","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":5,"order":43,"required":true,"prerequisite_keys":["computer_science.race_conditions_locks"],"fallback_key":"computer_science.race_conditions_locks","title_fr":"Réplication et cohérence dans un système distribué","title_en":"Replication and consistency in a distributed system","summary_fr":"Comparer réplication synchrone et asynchrone sur la fraîcheur des lectures et le risque de perte.","summary_en":"Compare synchronous and asynchronous replication on read freshness and risk of data loss.","learning_goals_fr":["Expliquer ce qu'une réplique en retard fait lire à un utilisateur.","Dire ce qui est perdu lors d'une bascule en réplication asynchrone."],"learning_goals_en":["Explain what a lagging replica shows to a user.","Say what is lost during a failover under asynchronous replication."],"tutor_focus_fr":"Fais raconter ce que voit un utilisateur qui écrit puis relit sur une réplique en retard, et demande quel réglage supprime ce symptôme et à quel prix.","tutor_focus_en":"Have the student narrate what a user sees when writing then reading from a lagging replica, and ask which setting removes that symptom and at what price.","example_contexts_fr":["un commentaire publié qui n'apparaît pas au rafraîchissement","une base répliquée entre l'Europe et l'Amérique","une bascule d'urgence vers un centre de données de secours"],"example_contexts_en":["a posted comment missing after a refresh","a database replicated between Europe and America","an emergency failover to a backup data centre"],"safety_category":"standard"},{"key":"computer_science.cap_tradeoffs","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":5,"order":44,"required":false,"prerequisite_keys":["computer_science.distributed_replication"],"fallback_key":"computer_science.race_conditions_locks","title_fr":"Le compromis CAP en pratique","title_en":"The CAP trade-off in practice","summary_fr":"Décider, pendant une partition réseau, entre refuser le service et accepter des données divergentes.","summary_en":"Decide, during a network partition, between refusing service and accepting divergent data.","learning_goals_fr":["Reformuler CAP comme un choix qui n'existe que pendant une partition.","Choisir cohérence ou disponibilité pour un service donné."],"learning_goals_en":["Restate CAP as a choice that only exists during a partition.","Pick consistency or availability for a given service."],"tutor_focus_fr":"Fais choisir entre refuser une écriture et accepter une divergence pour un panier d'achat puis pour un solde bancaire, en demandant de justifier chaque choix.","tutor_focus_en":"Have the student choose between refusing a write and accepting divergence for a shopping cart then for a bank balance, justifying each choice.","example_contexts_fr":["un panier d'achat modifié pendant une coupure réseau","un solde bancaire pendant une partition entre deux régions","un compteur de likes pendant un incident réseau"],"example_contexts_en":["a shopping cart edited during a network outage","a bank balance during a partition between two regions","a like counter during a network incident"],"safety_category":"standard"},{"key":"computer_science.load_balancing","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":5,"order":45,"required":false,"prerequisite_keys":["computer_science.cap_tradeoffs"],"fallback_key":"computer_science.race_conditions_locks","title_fr":"Comment un répartiteur de charge choisit un serveur","title_en":"How a load balancer picks a server","summary_fr":"Comparer tourniquet, moindre charge et hachage de session, et gérer les serveurs en mauvaise santé.","summary_en":"Compare round robin, least connections and session hashing, and handle unhealthy servers.","learning_goals_fr":["Comparer trois stratégies de répartition sur un même trafic.","Expliquer le rôle du contrôle de santé dans le retrait d'un serveur."],"learning_goals_en":["Compare three balancing strategies on the same traffic.","Explain the role of health checks in removing a server."],"tutor_focus_fr":"Fais comparer tourniquet et moindre charge quand une requête sur dix dure dix fois plus longtemps, puis demande l'effet d'un contrôle de santé trop lent.","tutor_focus_en":"Have the student compare round robin and least connections when one request in ten takes ten times longer, then ask what a slow health check causes.","example_contexts_fr":["un pic de trafic après une campagne d'emailing","un serveur qui répond mais renvoie des erreurs","une session utilisateur qui doit rester sur la même machine"],"example_contexts_en":["a traffic spike after an email campaign","a server that answers but returns errors","a user session that must stay on the same machine"],"safety_category":"standard"},{"key":"computer_science.observability_latency","domain_id":"computer_science","objective_ids":["cs_systems"],"stage":5,"order":46,"required":false,"prerequisite_keys":["computer_science.load_balancing"],"fallback_key":"computer_science.race_conditions_locks","title_fr":"Lire une latence p99 pour diagnostiquer un système","title_en":"Reading p99 latency to diagnose a system","summary_fr":"Utiliser les percentiles plutôt que la moyenne pour retrouver l'expérience réelle des utilisateurs.","summary_en":"Use percentiles rather than the average to recover what users actually experience.","learning_goals_fr":["Expliquer pourquoi la moyenne masque les incidents visibles par les clients.","Interpréter un écart important entre p50 et p99."],"learning_goals_en":["Explain why the average hides incidents that customers see.","Interpret a wide gap between p50 and p99."],"tutor_focus_fr":"Fais interpréter un p50 à 80 ms et un p99 à 4 s, puis demande quelles causes techniques produisent cet écart.","tutor_focus_en":"Have the student interpret an 80 ms p50 with a 4 s p99, then ask which technical causes produce that gap.","example_contexts_fr":["un tableau de bord de supervision après une mise en production","une plainte client sur un service annoncé rapide","un travail de fond qui sature la base une fois par heure"],"example_contexts_en":["a monitoring dashboard after a release","a customer complaint about a service advertised as fast","a background job saturating the database once an hour"],"safety_category":"standard"},{"key":"computer_science.dynamic_programming","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":5,"order":47,"required":true,"prerequisite_keys":["computer_science.immutability_side_effects"],"fallback_key":"computer_science.immutability_side_effects","title_fr":"Mémoïsation et programmation dynamique","title_en":"Memoisation and dynamic programming","summary_fr":"Transformer une récursion exponentielle en calcul linéaire en stockant les sous-résultats.","summary_en":"Turn an exponential recursion into a linear computation by storing sub-results.","learning_goals_fr":["Repérer les sous-problèmes recalculés dans une récursion.","Comparer le nombre d'appels avant et après mémoïsation."],"learning_goals_en":["Spot the sub-problems recomputed inside a recursion.","Compare the call count before and after memoisation."],"tutor_focus_fr":"Fais compter les appels de Fibonacci 10 sans mémoïsation puis avec, et demande quelle propriété du problème rend la technique applicable.","tutor_focus_en":"Have the student count the calls of Fibonacci 10 without memoisation then with it, and ask which property of the problem makes the technique valid.","example_contexts_fr":["le calcul du nombre de chemins dans une grille","le rendu de monnaie avec un nombre minimal de pièces","la distance d'édition entre deux mots"],"example_contexts_en":["counting the paths across a grid","making change with the fewest coins","the edit distance between two words"],"safety_category":"standard"},{"key":"computer_science.graph_search","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":5,"order":48,"required":false,"prerequisite_keys":["computer_science.dynamic_programming"],"fallback_key":"computer_science.immutability_side_effects","title_fr":"Parcours de graphe : BFS et DFS","title_en":"Graph traversal: BFS and DFS","summary_fr":"Choisir le parcours qui garantit le chemin le plus court dans un graphe non pondéré.","summary_en":"Choose the traversal that guarantees the shortest path in an unweighted graph.","learning_goals_fr":["Expliquer pourquoi BFS trouve le chemin minimal en nombre d'arêtes.","Gérer les nœuds déjà visités pour éviter une boucle infinie."],"learning_goals_en":["Explain why BFS finds the minimal path in number of edges.","Handle already visited nodes to avoid an infinite loop."],"tutor_focus_fr":"Fais dérouler BFS sur un petit réseau de stations, puis demande ce qui se passe sans marquage des nœuds visités.","tutor_focus_en":"Have the student run BFS over a small station network, then ask what happens without marking visited nodes.","example_contexts_fr":["un itinéraire en métro avec correspondances","des amis en commun dans un réseau social","les dépendances entre paquets logiciels"],"example_contexts_en":["a metro route with interchanges","mutual friends in a social network","dependencies between software packages"],"safety_category":"standard"},{"key":"computer_science.big_o_amortized","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":5,"order":49,"required":false,"prerequisite_keys":["computer_science.graph_search"],"fallback_key":"computer_science.immutability_side_effects","title_fr":"Coût amorti : pourquoi un tableau dynamique reste rapide","title_en":"Amortised cost: why a dynamic array stays fast","summary_fr":"Expliquer qu'un doublement occasionnel du tableau garde un coût moyen constant par ajout.","summary_en":"Explain how occasional doubling keeps the average cost per append constant.","learning_goals_fr":["Compter les copies effectuées sur une suite d'ajouts.","Distinguer le pire cas ponctuel du coût amorti."],"learning_goals_en":["Count the copies performed over a sequence of appends.","Tell apart a one-off worst case and the amortised cost."],"tutor_focus_fr":"Fais compter les copies après seize ajouts dans un tableau qui double, puis demande pourquoi le pire cas ne décrit pas correctement ce coût.","tutor_focus_en":"Have the student count copies after sixteen appends into a doubling array, then ask why the worst case does not describe that cost properly.","example_contexts_fr":["un tableau qui grandit à chaque nouvel enregistrement","un tampon de journalisation qui se réalloue","une file de tâches qui absorbe un pic de messages"],"example_contexts_en":["an array growing with each new record","a logging buffer that reallocates","a task queue absorbing a spike of messages"],"safety_category":"standard"},{"key":"computer_science.property_based_testing","domain_id":"computer_science","objective_ids":["cs_programming"],"stage":5,"order":50,"required":false,"prerequisite_keys":["computer_science.big_o_amortized"],"fallback_key":"computer_science.immutability_side_effects","title_fr":"Tests par propriétés","title_en":"Property-based testing","summary_fr":"Remplacer une liste d'exemples par une invariante vérifiée sur des entrées générées.","summary_en":"Replace a list of examples with an invariant checked over generated inputs.","learning_goals_fr":["Formuler une propriété toujours vraie pour une fonction donnée.","Expliquer ce qu'un contre-exemple réduit apporte au débogage."],"learning_goals_en":["State a property that always holds for a given function.","Explain what a shrunk counterexample brings to debugging."],"tutor_focus_fr":"Fais formuler deux propriétés d'une fonction de tri, puis demande quel contre-exemple minimal révélerait un tri instable.","tutor_focus_en":"Have the student state two properties of a sort function, then ask which minimal counterexample would reveal an unstable sort.","example_contexts_fr":["une fonction de tri testée sur des listes aléatoires","un encodeur et son décodeur appliqués l'un après l'autre","un calcul de prix qui ne doit jamais devenir négatif"],"example_contexts_en":["a sort function tested on random lists","an encoder and its decoder applied one after the other","a price computation that must never go negative"],"safety_category":"standard"},{"key":"computer_science.normalization_denormalization","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":5,"order":51,"required":true,"prerequisite_keys":["computer_science.api_versioning"],"fallback_key":"computer_science.api_versioning","title_fr":"Normaliser ou dénormaliser un schéma","title_en":"Normalising or denormalising a schema","summary_fr":"Arbitrer entre absence de duplication et rapidité de lecture selon les requêtes réellement servies.","summary_en":"Arbitrate between no duplication and fast reads based on the queries actually served.","learning_goals_fr":["Citer le risque principal de la duplication de données.","Justifier une dénormalisation par une requête précise."],"learning_goals_en":["State the main risk of duplicating data.","Justify a denormalisation with a precise query."],"tutor_focus_fr":"Fais justifier la duplication du nom du client dans la table des commandes, puis demande ce qui doit être mis à jour quand ce nom change.","tutor_focus_en":"Have the student justify duplicating the customer name into the orders table, then ask what must be updated when that name changes.","example_contexts_fr":["un tableau de bord de ventes recalculé à chaque ouverture","une adresse de livraison figée au moment de la commande","un catalogue lu mille fois plus souvent qu'il n'est modifié"],"example_contexts_en":["a sales dashboard recomputed on every open","a delivery address frozen at order time","a catalogue read a thousand times more often than written"],"safety_category":"standard"},{"key":"computer_science.idempotency_retries","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":5,"order":52,"required":false,"prerequisite_keys":["computer_science.normalization_denormalization"],"fallback_key":"computer_science.api_versioning","title_fr":"Idempotence et reprise sur erreur","title_en":"Idempotency and retries","summary_fr":"Concevoir une opération que l'on peut rejouer sans créer de doublon ni double paiement.","summary_en":"Design an operation that can be replayed without creating a duplicate or a double charge.","learning_goals_fr":["Expliquer ce qu'une clé d'idempotence garantit lors d'un réessai.","Repérer une opération dangereuse à rejouer."],"learning_goals_en":["Explain what an idempotency key guarantees during a retry.","Spot an operation that is dangerous to replay."],"tutor_focus_fr":"Fais analyser un paiement dont la réponse s'est perdue, puis demande quelle clé permet de rejouer l'appel sans débiter deux fois.","tutor_focus_en":"Have the student analyse a payment whose response was lost, then ask which key allows replaying the call without charging twice.","example_contexts_fr":["un paiement dont la réponse réseau s'est perdue","un webhook renvoyé trois fois par un partenaire","un travail de fond relancé après un redémarrage"],"example_contexts_en":["a payment whose network response was lost","a webhook re-sent three times by a partner","a background job restarted after a reboot"],"safety_category":"standard"},{"key":"computer_science.cloud_scaling","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":5,"order":53,"required":false,"prerequisite_keys":["computer_science.idempotency_retries"],"fallback_key":"computer_science.api_versioning","title_fr":"Mise à l'échelle horizontale et état partagé","title_en":"Horizontal scaling and shared state","summary_fr":"Identifier l'état local qui empêche d'ajouter des serveurs et le déplacer vers un service partagé.","summary_en":"Identify the local state that blocks adding servers and move it to a shared service.","learning_goals_fr":["Repérer un état conservé en mémoire d'une seule instance.","Proposer où déplacer cet état pour permettre l'ajout de serveurs."],"learning_goals_en":["Spot state kept in the memory of a single instance.","Propose where to move that state to allow adding servers."],"tutor_focus_fr":"Fais expliquer pourquoi des sessions en mémoire déconnectent les utilisateurs après un ajout de serveur, puis demande où déplacer ces sessions.","tutor_focus_en":"Have the student explain why in-memory sessions log users out after a server is added, then ask where those sessions should move.","example_contexts_fr":["des utilisateurs déconnectés après l'ajout d'un serveur","des fichiers téléversés stockés sur le disque d'une machine","un travail planifié qui s'exécute en double sur deux instances"],"example_contexts_en":["users logged out after a server was added","uploaded files stored on one machine's disk","a scheduled job running twice on two instances"],"safety_category":"standard"},{"key":"computer_science.slo_error_budget","domain_id":"computer_science","objective_ids":["cs_software_data"],"stage":5,"order":54,"required":false,"prerequisite_keys":["computer_science.cloud_scaling"],"fallback_key":"computer_science.api_versioning","title_fr":"SLO et budget d'erreur","title_en":"SLOs and error budgets","summary_fr":"Traduire un objectif de fiabilité en minutes d'indisponibilité tolérées et en décision de mise en production.","summary_en":"Translate a reliability target into tolerated downtime minutes and into a release decision.","learning_goals_fr":["Convertir un objectif de 99,9 % en durée d'indisponibilité mensuelle.","Décider d'une mise en production selon le budget consommé."],"learning_goals_en":["Convert a 99.9% target into monthly downtime.","Decide on a release based on the consumed budget."],"tutor_focus_fr":"Fais convertir 99,9 % en minutes par mois, puis demande quelle décision prendre si le budget est déjà consommé au dix du mois.","tutor_focus_en":"Have the student convert 99.9% into minutes per month, then ask which decision to take if the budget is already spent by the tenth.","example_contexts_fr":["un service dont le budget d'erreur est épuisé en début de mois","une mise en production prévue un vendredi soir","un incident de quarante minutes sur un service critique"],"example_contexts_en":["a service whose error budget is exhausted early in the month","a release planned for a Friday evening","a forty-minute incident on a critical service"],"safety_category":"standard"}]}$catalog$::jsonb)
ON CONFLICT (domain_id) DO UPDATE
SET version = EXCLUDED.version, payload = EXCLUDED.payload, updated_at = now();

INSERT INTO public.learning_catalog_domains (domain_id, version, payload)
VALUES ($catalog$cybersecurity$catalog$, $catalog$v1$catalog$, $catalog${"version":"v1","steps":[{"key":"cybersecurity.cia_triad","domain_id":"cybersecurity","objective_ids":["cyber_foundations","cyber_network_defense","cyber_app_cloud"],"stage":1,"order":1,"required":true,"prerequisite_keys":[],"fallback_key":null,"title_fr":"Confidentialité, intégrité, disponibilité","title_en":"Confidentiality, integrity, availability","summary_fr":"Classer un incident selon la propriété de sécurité qu'il met en défaut.","summary_en":"Classify an incident by the security property it breaks.","learning_goals_fr":["Définir les trois propriétés avec un exemple chacune.","Classer trois incidents réels dans la bonne catégorie."],"learning_goals_en":["Define the three properties with one example each.","Classify three real incidents into the right category."],"tutor_focus_fr":"Fais classer trois incidents dans les trois propriétés, puis demande lequel serait le plus grave pour un hôpital et pourquoi.","tutor_focus_en":"Have the student classify three incidents across the three properties, then ask which would hurt a hospital most and why.","example_contexts_fr":["un fichier client copié par un tiers","un montant de facture modifié dans une base","un site inaccessible pendant une journée"],"example_contexts_en":["a customer file copied by a third party","an invoice amount altered in a database","a site unreachable for a day"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.threat_model","domain_id":"cybersecurity","objective_ids":["cyber_foundations","cyber_network_defense","cyber_app_cloud"],"stage":1,"order":2,"required":true,"prerequisite_keys":["cybersecurity.cia_triad"],"fallback_key":null,"title_fr":"Ce qu'est un modèle de menace","title_en":"What a threat model is","summary_fr":"Nommer ce que l'on protège, contre qui et jusqu'où avant de choisir des protections.","summary_en":"Name what you protect, against whom and how far, before choosing protections.","learning_goals_fr":["Formuler un modèle de menace en trois questions.","Expliquer pourquoi une protection sans menace identifiée est inutile."],"learning_goals_en":["Frame a threat model in three questions.","Explain why a protection without an identified threat is useless."],"tutor_focus_fr":"Fais formuler le modèle de menace d'un journaliste puis celui d'une boutique en ligne, et demande ce qui change entre les deux.","tutor_focus_en":"Have the student frame the threat model of a journalist then of an online shop, and ask what changes between them.","example_contexts_fr":["un journaliste protégeant ses sources","une boutique en ligne et ses données de paiement","un particulier qui craint surtout le vol de son téléphone"],"example_contexts_en":["a journalist protecting sources","an online shop and its payment data","an individual mainly worried about phone theft"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.authentication_authorization","domain_id":"cybersecurity","objective_ids":["cyber_foundations","cyber_network_defense","cyber_app_cloud"],"stage":1,"order":3,"required":true,"prerequisite_keys":["cybersecurity.threat_model"],"fallback_key":null,"title_fr":"Authentification et autorisation","title_en":"Authentication and authorisation","summary_fr":"Séparer la preuve d'identité de la décision d'accorder un accès.","summary_en":"Separate proving identity from deciding to grant access.","learning_goals_fr":["Distinguer les deux notions sur un cas concret.","Repérer un système qui authentifie sans autoriser correctement."],"learning_goals_en":["Tell the two notions apart on a concrete case.","Spot a system that authenticates but authorises badly."],"tutor_focus_fr":"Fais analyser un cas où un utilisateur authentifié accède à des données qui ne le concernent pas, puis demande quelle étape a échoué.","tutor_focus_en":"Have the student analyse a case where a logged-in user reaches data that is not theirs, then ask which step failed.","example_contexts_fr":["un badge d'immeuble qui ouvre tous les étages","un employé connecté qui voit les dossiers d'un collègue","un compte administrateur utilisé pour un usage courant"],"example_contexts_en":["a building badge that opens every floor","a signed-in employee seeing a colleague's files","an administrator account used for daily work"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.password_reuse_risk","domain_id":"cybersecurity","objective_ids":["cyber_foundations","cyber_network_defense","cyber_app_cloud"],"stage":1,"order":4,"required":true,"prerequisite_keys":["cybersecurity.authentication_authorization"],"fallback_key":null,"title_fr":"Pourquoi un mot de passe unique par service","title_en":"Why every service needs its own password","summary_fr":"Comprendre comment une fuite sur un site compromet tous les comptes partageant le même mot de passe.","summary_en":"Understand how one site's breach compromises every account sharing that password.","learning_goals_fr":["Décrire l'enchaînement d'une fuite vers d'autres comptes.","Expliquer ce qu'un gestionnaire de mots de passe résout."],"learning_goals_en":["Describe the chain from a breach to other accounts.","Explain what a password manager solves."],"tutor_focus_fr":"Fais décrire ce qu'un attaquant fait d'une liste de couples adresse et mot de passe issue d'une fuite ancienne.","tutor_focus_en":"Have the student describe what an attacker does with a list of address and password pairs from an old breach.","example_contexts_fr":["une fuite d'un forum abandonné depuis cinq ans","une même adresse e-mail utilisée partout","un gestionnaire de mots de passe installé sur deux appareils"],"example_contexts_en":["a breach of a forum abandoned five years ago","the same email address used everywhere","a password manager installed on two devices"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.phishing_recognition","domain_id":"cybersecurity","objective_ids":["cyber_foundations","cyber_network_defense","cyber_app_cloud"],"stage":1,"order":5,"required":true,"prerequisite_keys":["cybersecurity.password_reuse_risk"],"fallback_key":null,"title_fr":"Reconnaître une tentative d'hameçonnage","title_en":"Recognising a phishing attempt","summary_fr":"Repérer les signaux d'un message frauduleux et adopter un réflexe de vérification hors canal.","summary_en":"Spot the signals of a fraudulent message and build an out-of-band verification reflex.","learning_goals_fr":["Citer quatre signaux d'alerte dans un message.","Décrire la vérification à effectuer avant toute action."],"learning_goals_en":["Name four warning signals in a message.","Describe the verification to run before acting."],"tutor_focus_fr":"Fais analyser un message urgent demandant une action immédiate, puis demande quelle vérification indépendante effectuer.","tutor_focus_en":"Have the student analyse an urgent message demanding immediate action, then ask which independent check to run.","example_contexts_fr":["un message annonçant la suspension d'un compte","une demande de virement urgente attribuée à un dirigeant","un lien affichant un nom de domaine presque correct"],"example_contexts_en":["a message announcing an account suspension","an urgent transfer request attributed to an executive","a link showing an almost-correct domain name"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.authentication_factors","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":1,"order":6,"required":true,"prerequisite_keys":["cybersecurity.phishing_recognition"],"fallback_key":null,"title_fr":"Les facteurs d'authentification","title_en":"Authentication factors","summary_fr":"Distinguer ce que l'on sait, ce que l'on possède et ce que l'on est, et combiner deux catégories.","summary_en":"Tell apart something you know, own and are, and combine two different categories.","learning_goals_fr":["Classer trois moyens d'authentification par catégorie.","Expliquer pourquoi deux facteurs de la même catégorie n'ajoutent rien."],"learning_goals_en":["Sort three authentication means by category.","Explain why two factors of the same category add nothing."],"tutor_focus_fr":"Fais classer trois moyens d'authentification, puis demande pourquoi deux mots de passe ne valent pas une double authentification.","tutor_focus_en":"Have the student sort three authentication means, then ask why two passwords do not amount to two-factor authentication.","example_contexts_fr":["un code reçu sur une application dédiée","une empreinte digitale sur un téléphone","une question secrète dont la réponse est publique"],"example_contexts_en":["a code received in a dedicated app","a fingerprint on a phone","a secret question whose answer is public"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.ports_and_services","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":1,"order":7,"required":true,"prerequisite_keys":["cybersecurity.phishing_recognition"],"fallback_key":null,"title_fr":"Ports et services exposés","title_en":"Ports and exposed services","summary_fr":"Comprendre qu'un service à l'écoute sur un port est une porte visible depuis le réseau.","summary_en":"Understand that a service listening on a port is a door visible from the network.","learning_goals_fr":["Expliquer ce qu'un port ouvert signifie concrètement.","Identifier un service qui ne devrait pas être exposé."],"learning_goals_en":["Explain what an open port concretely means.","Identify a service that should not be exposed."],"tutor_focus_fr":"Fais lister les services qu'un serveur web doit exposer, puis demande lesquels doivent rester accessibles uniquement en interne.","tutor_focus_en":"Have the student list the services a web server must expose, then ask which should stay internal only.","example_contexts_fr":["un serveur web exposant aussi sa base de données","un service d'administration accessible depuis Internet","un port ouvert par une application installée par défaut"],"example_contexts_en":["a web server also exposing its database","an administration service reachable from the internet","a port opened by a default-installed application"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.https_protection","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":1,"order":8,"required":true,"prerequisite_keys":["cybersecurity.phishing_recognition"],"fallback_key":null,"title_fr":"Ce que HTTPS protège","title_en":"What HTTPS protects","summary_fr":"Délimiter la protection du transport et ce qui reste visible ou vulnérable ailleurs.","summary_en":"Delimit transport protection and what stays visible or vulnerable elsewhere.","learning_goals_fr":["Dire ce qu'un tiers sur le réseau peut encore observer.","Expliquer pourquoi HTTPS ne rend pas un site fiable."],"learning_goals_en":["Say what a third party on the network can still observe.","Explain why HTTPS does not make a site trustworthy."],"tutor_focus_fr":"Fais lister ce qu'un observateur du réseau voit encore malgré HTTPS, puis demande ce que le cadenas ne garantit pas.","tutor_focus_en":"Have the student list what a network observer still sees despite HTTPS, then ask what the padlock does not guarantee.","example_contexts_fr":["une connexion à un site depuis un café","un site frauduleux affichant un cadenas","des données stockées en clair sur le serveur"],"example_contexts_en":["a connection to a site from a café","a fraudulent site displaying a padlock","data stored in clear text on the server"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.attack_surface","domain_id":"cybersecurity","objective_ids":["cyber_foundations","cyber_network_defense","cyber_app_cloud"],"stage":2,"order":9,"required":true,"prerequisite_keys":["cybersecurity.phishing_recognition"],"fallback_key":"cybersecurity.phishing_recognition","title_fr":"La surface d'attaque","title_en":"The attack surface","summary_fr":"Inventorier les points d'entrée exposés et réduire ceux qui ne servent à personne.","summary_en":"Inventory the exposed entry points and remove the ones nobody uses.","learning_goals_fr":["Lister les points d'entrée d'un système donné.","Identifier un service exposé sans usage réel."],"learning_goals_en":["List the entry points of a given system.","Identify an exposed service with no real use."],"tutor_focus_fr":"Fais lister les points d'entrée d'une petite entreprise, puis demande lequel peut être fermé sans gêner personne.","tutor_focus_en":"Have the student list the entry points of a small company, then ask which can be closed without inconveniencing anyone.","example_contexts_fr":["une imprimante accessible depuis Internet","un ancien site de campagne resté en ligne","un accès distant ouvert pour un prestataire parti"],"example_contexts_en":["a printer reachable from the internet","an old campaign website still online","a remote access left open for a departed contractor"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.defense_in_depth","domain_id":"cybersecurity","objective_ids":["cyber_foundations","cyber_network_defense","cyber_app_cloud"],"stage":2,"order":10,"required":true,"prerequisite_keys":["cybersecurity.attack_surface"],"fallback_key":"cybersecurity.phishing_recognition","title_fr":"La défense en profondeur","title_en":"Defence in depth","summary_fr":"Empiler des protections indépendantes pour qu'une seule faille ne suffise pas.","summary_en":"Stack independent protections so that one failure is never enough.","learning_goals_fr":["Décrire trois couches de protection indépendantes.","Expliquer pourquoi une seule barrière est insuffisante."],"learning_goals_en":["Describe three independent protection layers.","Explain why a single barrier is insufficient."],"tutor_focus_fr":"Fais décrire les couches qui séparent un attaquant d'une base de données, puis demande laquelle manque le plus souvent.","tutor_focus_en":"Have the student describe the layers separating an attacker from a database, then ask which one is most often missing.","example_contexts_fr":["un attaquant qui a déjà obtenu un mot de passe valide","un poste de travail infecté dans un réseau interne","une sauvegarde stockée hors du réseau principal"],"example_contexts_en":["an attacker who already holds a valid password","an infected workstation inside an internal network","a backup stored outside the main network"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.patch_management","domain_id":"cybersecurity","objective_ids":["cyber_foundations","cyber_network_defense","cyber_app_cloud"],"stage":2,"order":11,"required":true,"prerequisite_keys":["cybersecurity.defense_in_depth"],"fallback_key":"cybersecurity.phishing_recognition","title_fr":"Pourquoi les mises à jour comptent","title_en":"Why updates matter","summary_fr":"Comprendre la course entre la publication d'un correctif et son exploitation par des attaquants.","summary_en":"Understand the race between a patch being published and attackers exploiting it.","learning_goals_fr":["Expliquer ce que la publication d'un correctif révèle.","Proposer un délai de correction selon la criticité."],"learning_goals_en":["Explain what publishing a patch reveals.","Propose a remediation delay based on criticality."],"tutor_focus_fr":"Fais expliquer pourquoi une faille devient plus dangereuse après publication du correctif, puis demande un délai raisonnable d'application.","tutor_focus_en":"Have the student explain why a flaw gets more dangerous after its patch is published, then propose a reasonable rollout delay.","example_contexts_fr":["un correctif publié pour un serveur exposé","un logiciel maintenu mais jamais redémarré","un équipement dont le fabricant a cessé le support"],"example_contexts_en":["a patch published for an exposed server","software that is maintained but never restarted","a device whose vendor ended support"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.risk_prioritization","domain_id":"cybersecurity","objective_ids":["cyber_foundations","cyber_network_defense","cyber_app_cloud"],"stage":2,"order":12,"required":true,"prerequisite_keys":["cybersecurity.patch_management"],"fallback_key":"cybersecurity.phishing_recognition","title_fr":"Prioriser un risque : probabilité et impact","title_en":"Prioritising a risk: likelihood and impact","summary_fr":"Classer des risques par produit probabilité-impact plutôt que par crainte subjective.","summary_en":"Rank risks by likelihood times impact rather than by subjective fear.","learning_goals_fr":["Positionner trois risques sur une matrice probabilité-impact.","Justifier de ne pas traiter un risque immédiatement."],"learning_goals_en":["Place three risks on a likelihood-impact matrix.","Justify not addressing a risk immediately."],"tutor_focus_fr":"Fais positionner trois risques sur une matrice, puis demande lequel traiter en premier avec un budget limité.","tutor_focus_en":"Have the student place three risks on a matrix, then ask which to treat first with a limited budget.","example_contexts_fr":["un risque rare mais catastrophique","un incident fréquent au coût faible","un budget de sécurité limité à un seul chantier"],"example_contexts_en":["a rare but catastrophic risk","a frequent incident with low cost","a security budget limited to one project"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.symmetric_asymmetric","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":2,"order":13,"required":true,"prerequisite_keys":["cybersecurity.risk_prioritization"],"fallback_key":"cybersecurity.authentication_factors","title_fr":"Chiffrement symétrique et asymétrique","title_en":"Symmetric and asymmetric encryption","summary_fr":"Comparer les deux familles sur la distribution des clés et sur la vitesse.","summary_en":"Compare both families on key distribution and on speed.","learning_goals_fr":["Dire quel problème l'asymétrique résout que le symétrique ne résout pas.","Expliquer pourquoi les deux sont utilisés ensemble."],"learning_goals_en":["Say which problem asymmetric solves that symmetric does not.","Explain why both are used together."],"tutor_focus_fr":"Fais expliquer comment deux inconnus établissent un secret commun, puis demande pourquoi la suite des échanges revient au symétrique.","tutor_focus_en":"Have the student explain how two strangers establish a shared secret, then ask why the rest of the exchange returns to symmetric.","example_contexts_fr":["deux personnes qui ne se sont jamais rencontrées","un fichier chiffré sur un disque dur personnel","un échange de clés au début d'une connexion sécurisée"],"example_contexts_en":["two people who have never met","a file encrypted on a personal hard drive","a key exchange at the start of a secure connection"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.password_hashing","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":2,"order":14,"required":false,"prerequisite_keys":["cybersecurity.symmetric_asymmetric"],"fallback_key":"cybersecurity.authentication_factors","title_fr":"Pourquoi les mots de passe sont hachés et salés","title_en":"Why passwords are hashed and salted","summary_fr":"Comprendre le stockage d'une empreinte lente et salée plutôt que du mot de passe lui-même.","summary_en":"Understand storing a slow, salted fingerprint rather than the password itself.","learning_goals_fr":["Expliquer le rôle du sel contre les tables précalculées.","Dire pourquoi une fonction lente est préférable ici."],"learning_goals_en":["Explain the role of the salt against precomputed tables.","Say why a slow function is preferable here."],"tutor_focus_fr":"Fais expliquer ce qu'un attaquant obtient en volant une table de mots de passe correctement hachés et salés.","tutor_focus_en":"Have the student explain what an attacker gets from stealing a correctly hashed and salted password table.","example_contexts_fr":["une base de comptes utilisateurs exfiltrée","deux utilisateurs ayant choisi le même mot de passe","un service qui envoie le mot de passe en clair par e-mail"],"example_contexts_en":["an exfiltrated user account database","two users who picked the same password","a service emailing the password in clear text"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.firewall_rules","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":2,"order":15,"required":true,"prerequisite_keys":["cybersecurity.risk_prioritization"],"fallback_key":"cybersecurity.ports_and_services","title_fr":"Ce que fait un pare-feu","title_en":"What a firewall does","summary_fr":"Écrire des règles de filtrage qui refusent par défaut et n'autorisent que le nécessaire.","summary_en":"Write filtering rules that deny by default and allow only what is needed.","learning_goals_fr":["Rédiger un jeu de règles à refus par défaut.","Expliquer pourquoi l'ordre des règles compte."],"learning_goals_en":["Write a deny-by-default rule set.","Explain why rule order matters."],"tutor_focus_fr":"Fais rédiger trois règles pour un serveur web, puis demande ce qu'une règle d'autorisation large placée en premier annule.","tutor_focus_en":"Have the student write three rules for a web server, then ask what a broad allow rule placed first cancels.","example_contexts_fr":["un serveur web accessible uniquement en HTTPS","une règle temporaire jamais retirée","un accès d'administration limité à quelques adresses"],"example_contexts_en":["a web server reachable over HTTPS only","a temporary rule never removed","administration access limited to a few addresses"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.vpn_scope","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":2,"order":16,"required":false,"prerequisite_keys":["cybersecurity.firewall_rules"],"fallback_key":"cybersecurity.ports_and_services","title_fr":"Ce qu'un VPN protège et ne protège pas","title_en":"What a VPN protects and does not protect","summary_fr":"Délimiter la protection d'un tunnel chiffré et ce qui reste exposé au-delà.","summary_en":"Delimit what an encrypted tunnel protects and what stays exposed beyond it.","learning_goals_fr":["Dire ce qu'un VPN cache et à qui.","Citer une menace qu'un VPN ne réduit pas."],"learning_goals_en":["Say what a VPN hides and from whom.","Name a threat a VPN does not reduce."],"tutor_focus_fr":"Fais lister ce qu'un VPN protège sur un réseau public, puis demande ce qu'il ne change absolument pas.","tutor_focus_en":"Have the student list what a VPN protects on a public network, then ask what it changes nothing about.","example_contexts_fr":["une connexion depuis le réseau Wi-Fi d'un aéroport","un site consulté qui suit l'utilisateur avec un compte","un poste déjà infecté qui se connecte au VPN"],"example_contexts_en":["a connection from an airport Wi-Fi network","a visited site tracking the user through an account","an already infected machine connecting to the VPN"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.input_validation","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":2,"order":17,"required":true,"prerequisite_keys":["cybersecurity.risk_prioritization"],"fallback_key":"cybersecurity.https_protection","title_fr":"Valider les entrées côté serveur","title_en":"Validating input on the server","summary_fr":"Comprendre pourquoi toute validation faite dans le navigateur peut être contournée.","summary_en":"Understand why any validation done in the browser can be bypassed.","learning_goals_fr":["Expliquer pourquoi une validation côté client ne protège pas.","Définir une validation stricte pour un champ donné."],"learning_goals_en":["Explain why client-side validation does not protect.","Define a strict validation for a given field."],"tutor_focus_fr":"Fais expliquer comment une contrainte de formulaire peut être contournée, puis demande la validation serveur correspondante.","tutor_focus_en":"Have the student explain how a form constraint can be bypassed, then ask for the matching server-side validation.","example_contexts_fr":["un champ de quantité limité à cent dans le formulaire","un prix envoyé par le navigateur lors d'un achat","un identifiant de commande modifié dans l'URL"],"example_contexts_en":["a quantity field capped at a hundred in the form","a price sent by the browser during a purchase","an order identifier edited in the URL"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.secrets_management","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":2,"order":18,"required":false,"prerequisite_keys":["cybersecurity.input_validation"],"fallback_key":"cybersecurity.https_protection","title_fr":"Ne pas mettre de secret dans le code","title_en":"Keeping secrets out of the code","summary_fr":"Sortir les secrets du dépôt et prévoir leur rotation après une exposition.","summary_en":"Move secrets out of the repository and plan their rotation after exposure.","learning_goals_fr":["Citer trois endroits où un secret ne doit jamais figurer.","Décrire la réaction à une clé publiée par erreur."],"learning_goals_en":["Name three places a secret must never appear.","Describe the reaction to a key published by mistake."],"tutor_focus_fr":"Fais décrire les actions à mener quand une clé d'API a été publiée dans un dépôt public il y a un mois.","tutor_focus_en":"Have the student describe the actions to take when an API key was published in a public repository a month ago.","example_contexts_fr":["une clé d'API laissée dans un fichier de configuration","un mot de passe visible dans l'historique du dépôt","un secret affiché dans les journaux d'une application"],"example_contexts_en":["an API key left in a configuration file","a password visible in the repository history","a secret printed in an application's logs"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.certificates_and_trust","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":3,"order":19,"required":true,"prerequisite_keys":["cybersecurity.password_hashing"],"fallback_key":"cybersecurity.password_hashing","title_fr":"Certificats et autorités de certification","title_en":"Certificates and certificate authorities","summary_fr":"Comprendre la chaîne de confiance qui relie un certificat de site à une racine installée.","summary_en":"Understand the trust chain linking a site certificate to an installed root.","learning_goals_fr":["Décrire la chaîne de confiance d'un certificat de site.","Dire ce qu'un certificat prouve et ce qu'il ne prouve pas."],"learning_goals_en":["Describe the trust chain of a site certificate.","Say what a certificate proves and what it does not."],"tutor_focus_fr":"Fais dérouler la chaîne de confiance d'un certificat, puis demande ce qu'un certificat valide ne garantit pas sur le site visité.","tutor_focus_en":"Have the student walk a certificate's trust chain, then ask what a valid certificate does not guarantee about the site.","example_contexts_fr":["un site de phishing muni d'un certificat valide","une autorité racine installée par défaut dans un navigateur","un certificat expiré depuis deux jours"],"example_contexts_en":["a phishing site holding a valid certificate","a root authority preinstalled in a browser","a certificate expired two days ago"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.social_engineering","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":3,"order":20,"required":false,"prerequisite_keys":["cybersecurity.certificates_and_trust"],"fallback_key":"cybersecurity.password_hashing","title_fr":"L'ingénierie sociale","title_en":"Social engineering","summary_fr":"Comprendre les leviers psychologiques exploités et les procédures qui y résistent.","summary_en":"Understand the psychological levers exploited and the procedures that resist them.","learning_goals_fr":["Nommer trois leviers psychologiques utilisés contre un employé.","Concevoir une procédure qui résiste à la pression."],"learning_goals_en":["Name three psychological levers used against an employee.","Design a procedure that resists pressure."],"tutor_focus_fr":"Fais concevoir une procédure de validation des virements qui résiste à un appel urgent d'un supposé dirigeant.","tutor_focus_en":"Have the student design a payment validation procedure that resists an urgent call from a supposed executive.","example_contexts_fr":["un appel urgent attribué à la direction","un prestataire inconnu qui réclame un accès immédiat","une demande formulée juste avant un week-end"],"example_contexts_en":["an urgent call attributed to management","an unknown contractor demanding immediate access","a request made right before a weekend"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.malware_families","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":3,"order":21,"required":false,"prerequisite_keys":["cybersecurity.social_engineering"],"fallback_key":"cybersecurity.password_hashing","title_fr":"Les familles de logiciels malveillants","title_en":"Malware families","summary_fr":"Classer les menaces par objectif afin de choisir la protection et la réaction adaptées.","summary_en":"Classify threats by objective in order to pick the right protection and reaction.","learning_goals_fr":["Associer trois familles à leur objectif principal.","Choisir la protection prioritaire selon la famille."],"learning_goals_en":["Match three families to their main objective.","Choose the priority protection for each family."],"tutor_focus_fr":"Fais associer trois familles à leur objectif, puis demande quelle protection prioritaire découle de chacune.","tutor_focus_en":"Have the student match three families to their objective, then ask which priority protection follows from each.","example_contexts_fr":["des fichiers d'entreprise soudain illisibles","un poste qui envoie des données vers l'extérieur la nuit","un ordinateur exceptionnellement lent depuis une semaine"],"example_contexts_en":["company files suddenly unreadable","a machine sending data outward at night","a computer unusually slow for a week"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.backup_strategy","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":3,"order":22,"required":false,"prerequisite_keys":["cybersecurity.malware_families"],"fallback_key":"cybersecurity.password_hashing","title_fr":"La règle de sauvegarde 3-2-1","title_en":"The 3-2-1 backup rule","summary_fr":"Concevoir des sauvegardes qui survivent à un incident touchant tout le réseau.","summary_en":"Design backups that survive an incident affecting the whole network.","learning_goals_fr":["Énoncer la règle et l'appliquer à un cas concret.","Expliquer pourquoi une sauvegarde doit être testée et isolée."],"learning_goals_en":["State the rule and apply it to a concrete case.","Explain why a backup must be tested and isolated."],"tutor_focus_fr":"Fais concevoir un plan de sauvegarde pour une PME, puis demande ce qui se passe si les sauvegardes sont accessibles depuis le réseau.","tutor_focus_en":"Have the student design a backup plan for a small company, then ask what happens if backups are reachable from the network.","example_contexts_fr":["une PME dont les serveurs sont chiffrés par une attaque","une sauvegarde jamais restaurée depuis deux ans","un disque de sauvegarde branché en permanence"],"example_contexts_en":["a company whose servers are encrypted by an attack","a backup never restored in two years","a backup drive permanently plugged in"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.network_segmentation","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":3,"order":23,"required":true,"prerequisite_keys":["cybersecurity.vpn_scope"],"fallback_key":"cybersecurity.vpn_scope","title_fr":"La segmentation réseau","title_en":"Network segmentation","summary_fr":"Découper un réseau pour qu'un poste compromis n'atteigne pas les systèmes critiques.","summary_en":"Split a network so a compromised machine cannot reach critical systems.","learning_goals_fr":["Proposer un découpage en trois zones justifiées.","Expliquer ce que la segmentation ralentit chez un attaquant."],"learning_goals_en":["Propose a justified split into three zones.","Explain what segmentation slows down for an attacker."],"tutor_focus_fr":"Fais découper le réseau d'une PME en trois zones, puis demande ce qu'un poste compromis peut encore atteindre.","tutor_focus_en":"Have the student split a small company network into three zones, then ask what a compromised machine can still reach.","example_contexts_fr":["un poste d'accueil sur le même réseau que la comptabilité","des caméras connectées au réseau bureautique","un environnement de test relié à la production"],"example_contexts_en":["a reception desk machine on the accounting network","connected cameras on the office network","a test environment linked to production"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.detection_vs_prevention","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":3,"order":24,"required":false,"prerequisite_keys":["cybersecurity.network_segmentation"],"fallback_key":"cybersecurity.vpn_scope","title_fr":"Détection et prévention d'intrusion","title_en":"Intrusion detection and prevention","summary_fr":"Arbitrer entre alerter et bloquer selon le coût d'un blocage injustifié.","summary_en":"Arbitrate between alerting and blocking based on the cost of a wrong block.","learning_goals_fr":["Comparer détection et blocage sur le risque de faux positif.","Choisir le mode adapté à un service donné."],"learning_goals_en":["Compare detection and blocking on false positive risk.","Choose the right mode for a given service."],"tutor_focus_fr":"Fais choisir entre alerter et bloquer pour un service de paiement, puis demande le coût d'un blocage injustifié.","tutor_focus_en":"Have the student choose between alerting and blocking for a payment service, then ask the cost of a wrong block.","example_contexts_fr":["un service de paiement bloqué à tort en pleine journée","un trafic inhabituel détecté la nuit","une signature d'attaque déclenchée par un usage légitime"],"example_contexts_en":["a payment service wrongly blocked mid-day","unusual traffic detected at night","an attack signature triggered by legitimate usage"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.log_collection","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":3,"order":25,"required":false,"prerequisite_keys":["cybersecurity.detection_vs_prevention"],"fallback_key":"cybersecurity.vpn_scope","title_fr":"Collecte et centralisation des journaux","title_en":"Log collection and centralisation","summary_fr":"Choisir quoi journaliser, où le conserver et comment garder les traces exploitables.","summary_en":"Choose what to log, where to keep it and how to keep the traces usable.","learning_goals_fr":["Lister les journaux indispensables à une enquête.","Expliquer pourquoi les journaux doivent quitter la machine."],"learning_goals_en":["List the logs essential to an investigation.","Explain why logs must leave the machine."],"tutor_focus_fr":"Fais lister les journaux nécessaires pour reconstituer une intrusion, puis demande ce qu'un attaquant efface en premier.","tutor_focus_en":"Have the student list the logs needed to reconstruct an intrusion, then ask what an attacker erases first.","example_contexts_fr":["une machine dont les journaux ont été effacés","des horloges désynchronisées entre deux serveurs","une rétention de journaux limitée à sept jours"],"example_contexts_en":["a machine whose logs were wiped","clocks out of sync between two servers","a log retention limited to seven days"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.vulnerability_scanning","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":3,"order":26,"required":false,"prerequisite_keys":["cybersecurity.log_collection"],"fallback_key":"cybersecurity.vpn_scope","title_fr":"Le scan de vulnérabilités","title_en":"Vulnerability scanning","summary_fr":"Interpréter un rapport de scan et prioriser sans se noyer dans les scores bruts.","summary_en":"Interpret a scan report and prioritise without drowning in raw scores.","learning_goals_fr":["Interpréter un score de gravité en tenant compte de l'exposition.","Justifier de traiter une faille moyenne avant une faille critique."],"learning_goals_en":["Interpret a severity score accounting for exposure.","Justify fixing a medium flaw before a critical one."],"tutor_focus_fr":"Fais prioriser trois vulnérabilités dont la plus grave concerne un serveur interne isolé, et demande de justifier l'ordre.","tutor_focus_en":"Have the student prioritise three vulnerabilities where the worst affects an isolated internal server, and justify the order.","example_contexts_fr":["une faille critique sur une machine sans accès réseau","une faille moyenne sur le serveur public principal","un rapport contenant huit cents lignes"],"example_contexts_en":["a critical flaw on a machine with no network access","a medium flaw on the main public server","a report containing eight hundred lines"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.sql_injection_defense","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":3,"order":27,"required":true,"prerequisite_keys":["cybersecurity.secrets_management"],"fallback_key":"cybersecurity.secrets_management","title_fr":"Se protéger de l'injection SQL","title_en":"Defending against SQL injection","summary_fr":"Séparer le code de la donnée grâce aux requêtes paramétrées plutôt qu'au filtrage de caractères.","summary_en":"Separate code from data using parameterised queries rather than character filtering.","learning_goals_fr":["Expliquer pourquoi la concaténation de chaînes est dangereuse.","Réécrire une requête vulnérable en requête paramétrée."],"learning_goals_en":["Explain why string concatenation is dangerous.","Rewrite a vulnerable query as a parameterised one."],"tutor_focus_fr":"Fais réécrire une requête construite par concaténation en requête paramétrée, puis demande pourquoi filtrer les apostrophes ne suffit pas.","tutor_focus_en":"Have the student rewrite a concatenated query as a parameterised one, then ask why filtering quotes is not enough.","example_contexts_fr":["un formulaire de recherche interrogeant une base","une page de connexion construisant sa requête à la main","un filtre de caractères contourné par un encodage"],"example_contexts_en":["a search form querying a database","a login page building its query by hand","a character filter bypassed through encoding"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.xss_defense","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":3,"order":28,"required":false,"prerequisite_keys":["cybersecurity.sql_injection_defense"],"fallback_key":"cybersecurity.secrets_management","title_fr":"Se protéger du script intersite","title_en":"Defending against cross-site scripting","summary_fr":"Échapper les contenus fournis par les utilisateurs au moment de l'affichage.","summary_en":"Escape user-supplied content at the moment it is rendered.","learning_goals_fr":["Expliquer ce qu'un contenu non échappé permet dans un navigateur.","Choisir l'échappement adapté au contexte d'affichage."],"learning_goals_en":["Explain what unescaped content enables in a browser.","Choose the escaping suited to the rendering context."],"tutor_focus_fr":"Fais expliquer ce qui se passe quand un commentaire contenant du code est affiché tel quel, puis demande où appliquer l'échappement.","tutor_focus_en":"Have the student explain what happens when a comment containing code is displayed as-is, then ask where to apply escaping.","example_contexts_fr":["un commentaire affiché sur une page publique","un nom d'utilisateur repris dans une page de profil","un paramètre d'URL réaffiché dans un message d'erreur"],"example_contexts_en":["a comment displayed on a public page","a username echoed on a profile page","a URL parameter echoed in an error message"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.session_management","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":3,"order":29,"required":false,"prerequisite_keys":["cybersecurity.xss_defense"],"fallback_key":"cybersecurity.secrets_management","title_fr":"Gérer les sessions et les cookies","title_en":"Managing sessions and cookies","summary_fr":"Protéger un jeton de session par ses attributs, sa durée et son renouvellement.","summary_en":"Protect a session token through its attributes, its lifetime and its renewal.","learning_goals_fr":["Citer les attributs qui protègent un cookie de session.","Expliquer pourquoi renouveler l'identifiant après connexion."],"learning_goals_en":["Name the attributes that protect a session cookie.","Explain why the identifier is renewed after login."],"tutor_focus_fr":"Fais lister les attributs d'un cookie de session sûr, puis demande ce qu'un vol de jeton permet malgré un bon mot de passe.","tutor_focus_en":"Have the student list the attributes of a safe session cookie, then ask what a stolen token allows despite a strong password.","example_contexts_fr":["un jeton de session volé sur un poste partagé","une session qui ne expire jamais","un identifiant de session inchangé après connexion"],"example_contexts_en":["a session token stolen on a shared machine","a session that never expires","a session identifier unchanged after login"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.broken_access_control","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":3,"order":30,"required":false,"prerequisite_keys":["cybersecurity.session_management"],"fallback_key":"cybersecurity.secrets_management","title_fr":"Les défauts de contrôle d'accès","title_en":"Broken access control","summary_fr":"Vérifier les droits côté serveur pour chaque objet demandé, pas seulement à l'affichage.","summary_en":"Check permissions on the server for every requested object, not only at display time.","learning_goals_fr":["Repérer un accès direct à un objet non contrôlé.","Décrire le contrôle à effectuer à chaque requête."],"learning_goals_en":["Spot a direct object access with no check.","Describe the check to run on every request."],"tutor_focus_fr":"Fais analyser une URL où changer un identifiant affiche la facture d'un autre client, puis demande le contrôle manquant.","tutor_focus_en":"Have the student analyse a URL where changing an identifier shows another customer's invoice, then ask for the missing check.","example_contexts_fr":["un identifiant de facture incrémenté dans l'URL","un bouton masqué mais dont l'appel reste possible","un rôle vérifié uniquement à l'affichage du menu"],"example_contexts_en":["an invoice identifier incremented in the URL","a hidden button whose call still works","a role checked only when rendering the menu"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.key_management","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":4,"order":31,"required":true,"prerequisite_keys":["cybersecurity.backup_strategy"],"fallback_key":"cybersecurity.backup_strategy","title_fr":"La gestion des clés","title_en":"Key management","summary_fr":"Organiser génération, stockage, rotation et révocation des clés sur toute leur durée de vie.","summary_en":"Organise generation, storage, rotation and revocation of keys across their lifetime.","learning_goals_fr":["Décrire le cycle de vie complet d'une clé.","Expliquer ce qu'une rotation limite comme dégât."],"learning_goals_en":["Describe the full life cycle of a key.","Explain what damage rotation limits."],"tutor_focus_fr":"Fais décrire le cycle de vie d'une clé, puis demande ce qu'il faut faire immédiatement quand une clé est suspectée compromise.","tutor_focus_en":"Have the student describe a key's life cycle, then ask what to do immediately when a key is suspected compromised.","example_contexts_fr":["une clé de chiffrement en service depuis six ans","un développeur qui quitte l'entreprise","une clé retrouvée dans un dépôt de code public"],"example_contexts_en":["an encryption key in service for six years","a developer leaving the company","a key found in a public code repository"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.digital_signatures","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":4,"order":32,"required":false,"prerequisite_keys":["cybersecurity.key_management"],"fallback_key":"cybersecurity.backup_strategy","title_fr":"Signature numérique et non-répudiation","title_en":"Digital signatures and non-repudiation","summary_fr":"Distinguer ce qu'une signature garantit sur l'origine et sur l'intégrité d'un document.","summary_en":"Separate what a signature guarantees about origin and about document integrity.","learning_goals_fr":["Dire ce qu'une signature valide établit exactement.","Expliquer ce qu'une clé volée retire à cette garantie."],"learning_goals_en":["Say what a valid signature exactly establishes.","Explain what a stolen key removes from that guarantee."],"tutor_focus_fr":"Fais expliquer ce qu'une signature valide prouve, puis demande ce qui change si la clé privée a été copiée trois mois plus tôt.","tutor_focus_en":"Have the student explain what a valid signature proves, then ask what changes if the private key was copied three months earlier.","example_contexts_fr":["un contrat signé électroniquement","une mise à jour logicielle signée par son éditeur","une clé privée copiée à l'insu de son détenteur"],"example_contexts_en":["a contract signed electronically","a software update signed by its publisher","a private key copied without its owner knowing"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.data_minimization","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":4,"order":33,"required":false,"prerequisite_keys":["cybersecurity.digital_signatures"],"fallback_key":"cybersecurity.backup_strategy","title_fr":"Minimisation des données","title_en":"Data minimisation","summary_fr":"Réduire l'impact d'une fuite en ne collectant et ne conservant que le nécessaire.","summary_en":"Reduce the impact of a breach by collecting and keeping only what is needed.","learning_goals_fr":["Identifier les données collectées sans usage réel.","Fixer une durée de conservation justifiée."],"learning_goals_en":["Identify data collected with no real use.","Set a justified retention period."],"tutor_focus_fr":"Fais examiner un formulaire d'inscription et supprimer les champs inutiles, puis demande une durée de conservation justifiée.","tutor_focus_en":"Have the student review a signup form and drop useless fields, then set a justified retention period.","example_contexts_fr":["un formulaire demandant la date de naissance sans raison","des journaux conservés depuis cinq ans","une copie de pièce d'identité gardée après vérification"],"example_contexts_en":["a form asking for a birth date with no reason","logs kept for five years","an identity document copy kept after verification"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.security_awareness","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":4,"order":34,"required":false,"prerequisite_keys":["cybersecurity.data_minimization"],"fallback_key":"cybersecurity.backup_strategy","title_fr":"Construire une sensibilisation efficace","title_en":"Building effective security awareness","summary_fr":"Concevoir une sensibilisation mesurable qui change les comportements plutôt que la culpabilité.","summary_en":"Design measurable awareness that changes behaviour rather than assigning blame.","learning_goals_fr":["Définir un indicateur de progrès mesurable.","Expliquer pourquoi punir le signalement dégrade la sécurité."],"learning_goals_en":["Define a measurable progress indicator.","Explain why punishing reports degrades security."],"tutor_focus_fr":"Fais définir deux indicateurs de sensibilisation, puis demande ce qui arrive si les employés craignent de signaler une erreur.","tutor_focus_en":"Have the student define two awareness indicators, then ask what happens when employees fear reporting a mistake.","example_contexts_fr":["un employé qui n'ose pas signaler un clic malheureux","une campagne de test d'hameçonnage interne","une formation annuelle suivie sans effet mesurable"],"example_contexts_en":["an employee afraid to report an unlucky click","an internal phishing simulation campaign","an annual training with no measurable effect"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.alert_correlation","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":4,"order":35,"required":true,"prerequisite_keys":["cybersecurity.vulnerability_scanning"],"fallback_key":"cybersecurity.vulnerability_scanning","title_fr":"La corrélation d'alertes","title_en":"Alert correlation","summary_fr":"Relier des événements isolés pour distinguer un incident réel d'un bruit permanent.","summary_en":"Link isolated events to tell a real incident apart from permanent noise.","learning_goals_fr":["Construire une règle de corrélation à partir de deux événements.","Expliquer le coût opérationnel d'un excès d'alertes."],"learning_goals_en":["Build a correlation rule from two events.","Explain the operational cost of alert overload."],"tutor_focus_fr":"Fais construire une règle reliant un échec de connexion répété à une connexion réussie inhabituelle, et demande son taux de faux positifs attendu.","tutor_focus_en":"Have the student build a rule linking repeated login failures to an unusual success, and ask its expected false positive rate.","example_contexts_fr":["cent échecs de connexion suivis d'une réussite","une équipe qui reçoit trois mille alertes par jour","une connexion réussie depuis deux pays en dix minutes"],"example_contexts_en":["a hundred login failures followed by a success","a team receiving three thousand alerts a day","a successful login from two countries in ten minutes"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.incident_response_phases","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":4,"order":36,"required":false,"prerequisite_keys":["cybersecurity.alert_correlation"],"fallback_key":"cybersecurity.vulnerability_scanning","title_fr":"Les phases d'une réponse à incident","title_en":"The phases of incident response","summary_fr":"Ordonner détection, confinement, éradication, rétablissement et retour d'expérience.","summary_en":"Order detection, containment, eradication, recovery and lessons learned.","learning_goals_fr":["Ordonner les phases et dire ce que chacune vise.","Expliquer pourquoi éteindre un serveur trop vite peut nuire."],"learning_goals_en":["Order the phases and state what each aims at.","Explain why powering a server off too early can hurt."],"tutor_focus_fr":"Fais ordonner les phases sur un cas concret, puis demande pourquoi le confinement précède l'éradication.","tutor_focus_en":"Have the student order the phases on a concrete case, then ask why containment comes before eradication.","example_contexts_fr":["un serveur compromis découvert un vendredi soir","une décision d'isoler une machine sans l'éteindre","un retour d'expérience rédigé deux semaines après"],"example_contexts_en":["a compromised server discovered on a Friday evening","a decision to isolate a machine without powering it off","a lessons-learned report written two weeks later"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.availability_attacks","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":4,"order":37,"required":false,"prerequisite_keys":["cybersecurity.incident_response_phases"],"fallback_key":"cybersecurity.vulnerability_scanning","title_fr":"Absorber une saturation de service","title_en":"Absorbing a service saturation","summary_fr":"Préparer les protections qui maintiennent un service disponible pendant une saturation.","summary_en":"Prepare the protections that keep a service available during a saturation event.","learning_goals_fr":["Citer trois protections qui absorbent une charge anormale.","Expliquer pourquoi la préparation compte plus que la réaction."],"learning_goals_en":["Name three protections that absorb abnormal load.","Explain why preparation matters more than reaction."],"tutor_focus_fr":"Fais lister les protections à mettre en place avant un pic anormal, puis demande lesquelles ne peuvent plus être activées en urgence.","tutor_focus_en":"Have the student list the protections to set up before an abnormal spike, then ask which cannot be enabled in a hurry.","example_contexts_fr":["un site public saturé pendant une opération commerciale","un service dépendant d'un seul fournisseur d'accès","un contrat de mitigation signé après l'incident"],"example_contexts_en":["a public site saturated during a sales event","a service depending on a single access provider","a mitigation contract signed after the incident"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.endpoint_detection","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":4,"order":38,"required":false,"prerequisite_keys":["cybersecurity.availability_attacks"],"fallback_key":"cybersecurity.vulnerability_scanning","title_fr":"La détection sur les postes","title_en":"Endpoint detection","summary_fr":"Comprendre ce qu'un agent observe sur un poste et ce qu'il ne peut pas voir.","summary_en":"Understand what an agent observes on a machine and what it cannot see.","learning_goals_fr":["Citer trois comportements suspects observables sur un poste.","Expliquer les limites d'une détection par signature."],"learning_goals_en":["Name three suspicious behaviours observable on a machine.","Explain the limits of signature-based detection."],"tutor_focus_fr":"Fais citer trois comportements suspects sur un poste, puis demande pourquoi la détection par signature seule ne suffit plus.","tutor_focus_en":"Have the student name three suspicious behaviours on a machine, then ask why signature detection alone no longer suffices.","example_contexts_fr":["un outil d'administration légitime utilisé anormalement","un document bureautique qui lance un script","un logiciel jamais vu ailleurs dans le parc"],"example_contexts_en":["a legitimate admin tool used abnormally","an office document launching a script","software never seen elsewhere in the fleet"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.delegated_access","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":4,"order":39,"required":true,"prerequisite_keys":["cybersecurity.broken_access_control"],"fallback_key":"cybersecurity.broken_access_control","title_fr":"Déléguer un accès sans partager son mot de passe","title_en":"Delegating access without sharing a password","summary_fr":"Comprendre l'échange de jetons à portée limitée et révocable entre trois parties.","summary_en":"Understand the exchange of limited-scope, revocable tokens between three parties.","learning_goals_fr":["Décrire les trois rôles impliqués dans une délégation d'accès.","Expliquer ce qu'une portée limitée empêche."],"learning_goals_en":["Describe the three roles involved in access delegation.","Explain what a limited scope prevents."],"tutor_focus_fr":"Fais décrire les trois rôles d'une délégation d'accès, puis demande ce qu'une portée trop large permettrait à l'application tierce.","tutor_focus_en":"Have the student describe the three roles of access delegation, then ask what an overly broad scope would let the third-party app do.","example_contexts_fr":["une application tierce qui lit un agenda","un accès révoqué depuis les paramètres du compte","une portée demandant plus de droits que nécessaire"],"example_contexts_en":["a third-party app reading a calendar","an access revoked from the account settings","a scope requesting more rights than needed"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.least_privilege_cloud","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":4,"order":40,"required":false,"prerequisite_keys":["cybersecurity.delegated_access"],"fallback_key":"cybersecurity.broken_access_control","title_fr":"Le moindre privilège dans le cloud","title_en":"Least privilege in the cloud","summary_fr":"Attribuer à chaque composant les seules permissions dont il a besoin pour fonctionner.","summary_en":"Grant each component only the permissions it needs to work.","learning_goals_fr":["Réduire une permission trop large à un besoin réel.","Expliquer ce qu'un rôle trop permissif aggrave lors d'un incident."],"learning_goals_en":["Narrow an overly broad permission to a real need.","Explain what an over-permissive role worsens during an incident."],"tutor_focus_fr":"Fais réduire une permission d'écriture globale au strict nécessaire, puis demande ce que cela change en cas de compromission.","tutor_focus_en":"Have the student narrow a global write permission to the strict minimum, then ask what it changes if compromised.","example_contexts_fr":["un service disposant d'un accès complet au stockage","un rôle d'administration attribué par facilité","une clé de service partagée entre trois applications"],"example_contexts_en":["a service holding full access to storage","an admin role granted for convenience","a service key shared across three applications"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.container_isolation","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":4,"order":41,"required":false,"prerequisite_keys":["cybersecurity.least_privilege_cloud"],"fallback_key":"cybersecurity.broken_access_control","title_fr":"L'isolation des conteneurs","title_en":"Container isolation","summary_fr":"Comprendre ce qu'un conteneur isole réellement et ce qu'il partage avec l'hôte.","summary_en":"Understand what a container actually isolates and what it shares with the host.","learning_goals_fr":["Dire ce qu'un conteneur partage avec le système hôte.","Citer deux réglages qui renforcent son isolation."],"learning_goals_en":["Say what a container shares with the host system.","Name two settings that strengthen its isolation."],"tutor_focus_fr":"Fais comparer l'isolation d'un conteneur et celle d'une machine virtuelle, puis demande deux réglages qui réduisent le risque.","tutor_focus_en":"Have the student compare container and virtual machine isolation, then ask for two settings that reduce risk.","example_contexts_fr":["un conteneur exécuté avec les droits administrateur","un dossier de l'hôte monté dans un conteneur","une image construite à partir d'une base non maintenue"],"example_contexts_en":["a container running with administrator rights","a host folder mounted inside a container","an image built from an unmaintained base"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.dependency_vulnerabilities","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":4,"order":42,"required":false,"prerequisite_keys":["cybersecurity.container_isolation"],"fallback_key":"cybersecurity.broken_access_control","title_fr":"Les vulnérabilités des dépendances","title_en":"Dependency vulnerabilities","summary_fr":"Suivre les bibliothèques tierces et décider quand une alerte concerne réellement l'application.","summary_en":"Track third-party libraries and decide when an alert really concerns the application.","learning_goals_fr":["Vérifier si une faille annoncée est réellement atteignable.","Choisir entre mise à jour immédiate et contournement."],"learning_goals_en":["Check whether an announced flaw is actually reachable.","Choose between immediate update and a workaround."],"tutor_focus_fr":"Fais vérifier si une faille signalée dans une dépendance est atteignable dans l'application, puis demande la décision à prendre.","tutor_focus_en":"Have the student check whether a reported dependency flaw is reachable in the application, then ask for the decision.","example_contexts_fr":["une alerte sur une bibliothèque utilisée pour une seule fonction","une dépendance indirecte présente huit niveaux plus bas","une mise à jour majeure qui casse l'application"],"example_contexts_en":["an alert on a library used for a single function","an indirect dependency eight levels down","a major update that breaks the application"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.zero_trust","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":5,"order":43,"required":true,"prerequisite_keys":["cybersecurity.security_awareness"],"fallback_key":"cybersecurity.security_awareness","title_fr":"Le modèle zero trust","title_en":"The zero trust model","summary_fr":"Remplacer la confiance accordée au réseau interne par une vérification à chaque accès.","summary_en":"Replace trust granted to the internal network with verification at every access.","learning_goals_fr":["Expliquer ce que le modèle abandonne comme hypothèse.","Décrire ce qui est vérifié à chaque requête."],"learning_goals_en":["Explain which assumption the model abandons.","Describe what is verified on each request."],"tutor_focus_fr":"Fais expliquer pourquoi la position réseau ne suffit plus à accorder un accès, puis demande ce qu'il faut vérifier à la place.","tutor_focus_en":"Have the student explain why network position no longer justifies access, then ask what must be verified instead.","example_contexts_fr":["un poste connecté au réseau interne mais compromis","un salarié en télétravail depuis un lieu public","un prestataire disposant d'un accès temporaire"],"example_contexts_en":["a machine on the internal network but compromised","an employee working remotely from a public place","a contractor holding temporary access"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.threat_intelligence","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":5,"order":44,"required":false,"prerequisite_keys":["cybersecurity.zero_trust"],"fallback_key":"cybersecurity.security_awareness","title_fr":"Le renseignement sur les menaces","title_en":"Threat intelligence","summary_fr":"Transformer une information sur des attaquants en décision de défense concrète.","summary_en":"Turn information about attackers into a concrete defensive decision.","learning_goals_fr":["Distinguer une information exploitable d'un simple indicateur.","Traduire un rapport de menace en action de défense."],"learning_goals_en":["Tell actionable intelligence apart from a bare indicator.","Translate a threat report into a defensive action."],"tutor_focus_fr":"Fais traduire un rapport décrivant une campagne d'attaque en trois actions défensives concrètes et priorisées.","tutor_focus_en":"Have the student turn a report describing an attack campaign into three concrete, prioritised defensive actions.","example_contexts_fr":["un rapport public décrivant une campagne visant un secteur","une liste d'indicateurs techniques déjà obsolètes","un signalement partagé entre entreprises d'un même secteur"],"example_contexts_en":["a public report describing a campaign against one sector","a list of technical indicators already outdated","a warning shared between companies of one industry"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.supply_chain_risk","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":5,"order":45,"required":false,"prerequisite_keys":["cybersecurity.threat_intelligence"],"fallback_key":"cybersecurity.security_awareness","title_fr":"Le risque fournisseur","title_en":"Supplier risk","summary_fr":"Évaluer ce qu'un prestataire compromis permettrait d'atteindre dans le système d'information.","summary_en":"Assess what a compromised supplier would let an attacker reach in your systems.","learning_goals_fr":["Cartographier les accès accordés à des tiers.","Définir une exigence de sécurité contractuelle utile."],"learning_goals_en":["Map the accesses granted to third parties.","Define a useful contractual security requirement."],"tutor_focus_fr":"Fais cartographier les accès d'un prestataire de maintenance, puis demande ce qu'un attaquant obtiendrait en le compromettant.","tutor_focus_en":"Have the student map a maintenance supplier's access, then ask what an attacker would obtain by compromising it.","example_contexts_fr":["un prestataire de maintenance disposant d'un accès permanent","un outil externe intégré dans toutes les pages du site","une bibliothèque logicielle maintenue par une seule personne"],"example_contexts_en":["a maintenance supplier holding permanent access","an external tool embedded in every page of the site","a software library maintained by a single person"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.security_governance","domain_id":"cybersecurity","objective_ids":["cyber_foundations"],"stage":5,"order":46,"required":false,"prerequisite_keys":["cybersecurity.supply_chain_risk"],"fallback_key":"cybersecurity.security_awareness","title_fr":"Politique de sécurité et responsabilité","title_en":"Security policy and accountability","summary_fr":"Écrire des règles applicables et désigner qui décide et qui assume un risque accepté.","summary_en":"Write applicable rules and name who decides and who owns an accepted risk.","learning_goals_fr":["Distinguer une règle applicable d'une intention vague.","Identifier qui doit formellement accepter un risque résiduel."],"learning_goals_en":["Tell an applicable rule apart from a vague intention.","Identify who must formally accept a residual risk."],"tutor_focus_fr":"Fais réécrire une règle vague en règle vérifiable, puis demande qui doit signer l'acceptation d'un risque résiduel.","tutor_focus_en":"Have the student rewrite a vague rule into a checkable one, then ask who must sign off a residual risk.","example_contexts_fr":["une politique qui interdit tout sans exception praticable","un risque accepté sans trace écrite","une exception accordée oralement à une équipe"],"example_contexts_en":["a policy forbidding everything with no workable exception","an accepted risk with no written trace","an exception granted verbally to one team"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.threat_hunting","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":5,"order":47,"required":true,"prerequisite_keys":["cybersecurity.endpoint_detection"],"fallback_key":"cybersecurity.endpoint_detection","title_fr":"La chasse aux menaces","title_en":"Threat hunting","summary_fr":"Partir d'une hypothèse plutôt que d'une alerte pour chercher une compromission silencieuse.","summary_en":"Start from a hypothesis rather than an alert to look for a silent compromise.","learning_goals_fr":["Formuler une hypothèse de chasse vérifiable dans les journaux.","Dire ce qu'une chasse infructueuse apporte quand même."],"learning_goals_en":["Frame a hunting hypothesis verifiable in the logs.","Say what an unsuccessful hunt still brings."],"tutor_focus_fr":"Fais formuler une hypothèse de chasse vérifiable dans les journaux existants, puis demande ce que prouve un résultat négatif.","tutor_focus_en":"Have the student frame a hunting hypothesis checkable in existing logs, then ask what a negative result proves.","example_contexts_fr":["une compromission présente depuis six mois sans alerte","une hypothèse fondée sur une technique d'attaque connue","une recherche qui ne trouve finalement rien"],"example_contexts_en":["a compromise present for six months with no alert","a hypothesis based on a known attack technique","a search that finds nothing in the end"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.forensic_timeline","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":5,"order":48,"required":false,"prerequisite_keys":["cybersecurity.threat_hunting"],"fallback_key":"cybersecurity.endpoint_detection","title_fr":"Reconstituer une chronologie d'incident","title_en":"Reconstructing an incident timeline","summary_fr":"Assembler des traces de sources différentes en une chronologie fiable et datée.","summary_en":"Assemble traces from different sources into one reliable, timestamped timeline.","learning_goals_fr":["Ordonner des traces provenant de trois sources distinctes.","Expliquer l'importance d'une référence de temps commune."],"learning_goals_en":["Order traces coming from three distinct sources.","Explain the importance of a shared time reference."],"tutor_focus_fr":"Fais reconstituer une chronologie à partir de trois sources aux horloges décalées, puis demande comment lever l'ambiguïté.","tutor_focus_en":"Have the student rebuild a timeline from three sources with skewed clocks, then ask how to resolve the ambiguity.","example_contexts_fr":["un pare-feu, un serveur et un poste aux horloges différentes","une trace effacée sur une seule des trois sources","un incident dont l'origine remonte à plusieurs semaines"],"example_contexts_en":["a firewall, a server and a workstation with different clocks","a trace erased on only one of the three sources","an incident whose origin goes back several weeks"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.joint_exercises","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":5,"order":49,"required":false,"prerequisite_keys":["cybersecurity.forensic_timeline"],"fallback_key":"cybersecurity.endpoint_detection","title_fr":"L'exercice conjoint attaque-défense","title_en":"Joint attack-defence exercises","summary_fr":"Organiser un exercice autorisé où les défenseurs mesurent leur détection en temps réel.","summary_en":"Organise an authorised exercise where defenders measure their detection in real time.","learning_goals_fr":["Définir le périmètre et les règles d'un exercice autorisé.","Choisir les indicateurs de détection à mesurer."],"learning_goals_en":["Define the scope and rules of an authorised exercise.","Choose the detection indicators to measure."],"tutor_focus_fr":"Fais définir le périmètre, l'autorisation écrite et deux indicateurs de détection pour un exercice interne.","tutor_focus_en":"Have the student define the scope, the written authorisation and two detection indicators for an internal exercise.","example_contexts_fr":["un exercice planifié avec autorisation écrite de la direction","un délai moyen de détection mesuré pendant l'exercice","une action d'exercice confondue avec une vraie attaque"],"example_contexts_en":["an exercise planned with written management approval","a mean detection time measured during the exercise","an exercise action mistaken for a real attack"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.business_continuity","domain_id":"cybersecurity","objective_ids":["cyber_network_defense"],"stage":5,"order":50,"required":false,"prerequisite_keys":["cybersecurity.joint_exercises"],"fallback_key":"cybersecurity.endpoint_detection","title_fr":"Plan de continuité et reprise","title_en":"Continuity and recovery planning","summary_fr":"Fixer une durée d'interruption et une perte de données acceptables, puis dimensionner en conséquence.","summary_en":"Set an acceptable outage duration and data loss, then size the plan accordingly.","learning_goals_fr":["Définir une durée d'interruption et une perte de données acceptables.","Vérifier qu'un plan a été réellement testé."],"learning_goals_en":["Define an acceptable outage duration and data loss.","Check that a plan has actually been tested."],"tutor_focus_fr":"Fais fixer une durée d'interruption acceptable pour un service critique, puis demande ce que cela impose aux sauvegardes.","tutor_focus_en":"Have the student set an acceptable outage duration for a critical service, then ask what that imposes on backups.","example_contexts_fr":["un service de facturation arrêté quatre heures","une reprise testée uniquement sur le papier","des données perdues depuis la dernière sauvegarde nocturne"],"example_contexts_en":["a billing service down for four hours","a recovery tested only on paper","data lost since the last nightly backup"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.secure_development_lifecycle","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":5,"order":51,"required":true,"prerequisite_keys":["cybersecurity.dependency_vulnerabilities"],"fallback_key":"cybersecurity.dependency_vulnerabilities","title_fr":"Intégrer la sécurité au cycle de développement","title_en":"Building security into the development cycle","summary_fr":"Placer les contrôles de sécurité au moment où une correction coûte le moins cher.","summary_en":"Place security checks where a fix costs the least.","learning_goals_fr":["Associer trois contrôles aux étapes du cycle.","Expliquer pourquoi un audit final seul coûte plus cher."],"learning_goals_en":["Match three checks to the stages of the cycle.","Explain why a final audit alone costs more."],"tutor_focus_fr":"Fais placer trois contrôles de sécurité aux bonnes étapes du cycle, puis demande le coût d'une correction découverte en production.","tutor_focus_en":"Have the student place three security checks at the right stages, then ask the cost of a fix found in production.","example_contexts_fr":["une faille de conception découverte la veille du lancement","un contrôle automatique exécuté à chaque proposition de code","un audit annuel réalisé après la mise en production"],"example_contexts_en":["a design flaw found the day before launch","an automated check run on every code proposal","an annual audit performed after release"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.architecture_threat_modeling","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":5,"order":52,"required":false,"prerequisite_keys":["cybersecurity.secure_development_lifecycle"],"fallback_key":"cybersecurity.dependency_vulnerabilities","title_fr":"Modéliser les menaces d'une architecture","title_en":"Threat modelling an architecture","summary_fr":"Analyser un schéma d'architecture pour repérer les frontières de confiance et leurs risques.","summary_en":"Analyse an architecture diagram to find trust boundaries and their risks.","learning_goals_fr":["Tracer les frontières de confiance sur un schéma.","Associer une contre-mesure à chaque frontière franchie."],"learning_goals_en":["Draw the trust boundaries on a diagram.","Attach a countermeasure to each boundary crossed."],"tutor_focus_fr":"Fais tracer les frontières de confiance d'une architecture à trois composants, puis demande une contre-mesure par frontière.","tutor_focus_en":"Have the student draw the trust boundaries of a three-component architecture, then give one countermeasure per boundary.","example_contexts_fr":["une application mobile appelant une API publique","un service interne qui fait confiance à son appelant","un flux de données traversant un partenaire externe"],"example_contexts_en":["a mobile app calling a public API","an internal service trusting its caller","a data flow crossing an external partner"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.cloud_misconfiguration","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":5,"order":53,"required":false,"prerequisite_keys":["cybersecurity.architecture_threat_modeling"],"fallback_key":"cybersecurity.dependency_vulnerabilities","title_fr":"Les erreurs de configuration cloud","title_en":"Cloud misconfiguration","summary_fr":"Repérer les réglages par défaut qui exposent des données sans qu'aucune faille soit exploitée.","summary_en":"Spot the default settings that expose data without any flaw being exploited.","learning_goals_fr":["Citer trois configurations fréquemment exposées.","Décrire un contrôle automatique qui les détecte."],"learning_goals_en":["Name three frequently exposed configurations.","Describe an automated check that detects them."],"tutor_focus_fr":"Fais citer trois configurations exposant des données sans faille logicielle, puis demande comment les détecter automatiquement.","tutor_focus_en":"Have the student name three configurations exposing data with no software flaw, then ask how to detect them automatically.","example_contexts_fr":["un espace de stockage accessible publiquement","une base de données ouverte sans mot de passe","un journal de débogage exposé sur Internet"],"example_contexts_en":["a storage bucket left publicly readable","a database open with no password","a debug log exposed on the internet"],"safety_category":"cyber_defensive"},{"key":"cybersecurity.api_abuse_protection","domain_id":"cybersecurity","objective_ids":["cyber_app_cloud"],"stage":5,"order":54,"required":false,"prerequisite_keys":["cybersecurity.cloud_misconfiguration"],"fallback_key":"cybersecurity.dependency_vulnerabilities","title_fr":"Protéger une API des abus","title_en":"Protecting an API from abuse","summary_fr":"Limiter le débit, détecter l'énumération et protéger les points d'entrée coûteux.","summary_en":"Limit rate, detect enumeration and protect expensive endpoints.","learning_goals_fr":["Choisir une limite de débit adaptée à un point d'entrée.","Repérer un usage automatisé dans des journaux d'API."],"learning_goals_en":["Choose a rate limit suited to an endpoint.","Spot automated usage in API logs."],"tutor_focus_fr":"Fais fixer une limite de débit pour un point d'entrée de connexion, puis demande comment repérer une énumération de comptes.","tutor_focus_en":"Have the student set a rate limit for a login endpoint, then ask how to spot account enumeration.","example_contexts_fr":["un point d'entrée de connexion appelé mille fois par minute","une recherche coûteuse appelée en boucle","des identifiants testés séquentiellement"],"example_contexts_en":["a login endpoint called a thousand times per minute","an expensive search called in a loop","identifiers tested sequentially"],"safety_category":"cyber_defensive"}]}$catalog$::jsonb)
ON CONFLICT (domain_id) DO UPDATE
SET version = EXCLUDED.version, payload = EXCLUDED.payload, updated_at = now();

INSERT INTO public.learning_catalog_domains (domain_id, version, payload)
VALUES ($catalog$human_biology_medicine$catalog$, $catalog$v1$catalog$, $catalog${"version":"v1","steps":[{"key":"human_biology_medicine.cell_basics","domain_id":"human_biology_medicine","objective_ids":["medicine_body","medicine_disease","medicine_evidence"],"stage":1,"order":1,"required":true,"prerequisite_keys":[],"fallback_key":null,"title_fr":"La cellule, unité de base du vivant","title_en":"The cell, basic unit of life","summary_fr":"Situer les principaux compartiments d'une cellule et le rôle de chacun.","summary_en":"Locate the main compartments of a cell and the role of each one.","learning_goals_fr":["Nommer trois compartiments cellulaires et leur fonction.","Expliquer le rôle de la membrane comme frontière sélective."],"learning_goals_en":["Name three cell compartments and their function.","Explain the membrane's role as a selective boundary."],"tutor_focus_fr":"Fais nommer trois compartiments d'une cellule et leur rôle, puis demande ce qui se passe si la membrane laisse tout passer.","tutor_focus_en":"Have the student name three cell compartments and their role, then ask what happens if the membrane lets everything through.","example_contexts_fr":["une cellule musculaire riche en mitochondries","un globule rouge dépourvu de noyau","une cellule de la peau qui se renouvelle"],"example_contexts_en":["a muscle cell rich in mitochondria","a red blood cell without a nucleus","a skin cell being renewed"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.body_systems_map","domain_id":"human_biology_medicine","objective_ids":["medicine_body","medicine_disease","medicine_evidence"],"stage":1,"order":2,"required":true,"prerequisite_keys":["human_biology_medicine.cell_basics"],"fallback_key":null,"title_fr":"Les grands systèmes du corps et leur coordination","title_en":"The major body systems and their coordination","summary_fr":"Relier les systèmes entre eux plutôt que de les mémoriser séparément.","summary_en":"Connect the systems to each other rather than memorising them separately.","learning_goals_fr":["Associer chaque grand système à sa fonction principale.","Décrire une coordination entre deux systèmes lors d'un effort."],"learning_goals_en":["Match each major system to its main function.","Describe a coordination between two systems during exercise."],"tutor_focus_fr":"Fais décrire ce qui se coordonne entre trois systèmes quand on monte un escalier rapidement.","tutor_focus_en":"Have the student describe what three systems coordinate when climbing stairs quickly.","example_contexts_fr":["une montée d'escalier rapide","un repas copieux suivi d'une somnolence","une déshydratation par forte chaleur"],"example_contexts_en":["a quick climb up a staircase","a heavy meal followed by drowsiness","dehydration during a heatwave"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.homeostasis","domain_id":"human_biology_medicine","objective_ids":["medicine_body","medicine_disease","medicine_evidence"],"stage":1,"order":3,"required":true,"prerequisite_keys":["human_biology_medicine.body_systems_map"],"fallback_key":null,"title_fr":"L'homéostasie : maintenir un équilibre","title_en":"Homeostasis: keeping a balance","summary_fr":"Comprendre la régulation par rétroaction négative sur des exemples de température et de glycémie.","summary_en":"Understand negative feedback regulation through temperature and blood sugar examples.","learning_goals_fr":["Décrire une boucle de rétroaction négative complète.","Identifier capteur, centre de contrôle et effecteur."],"learning_goals_en":["Describe a full negative feedback loop.","Identify sensor, control centre and effector."],"tutor_focus_fr":"Fais décrire la boucle qui ramène la température corporelle après un effort, en nommant capteur, centre et effecteur.","tutor_focus_en":"Have the student describe the loop returning body temperature to normal after exercise, naming sensor, centre and effector.","example_contexts_fr":["une transpiration déclenchée par la chaleur","un frisson par temps froid","une glycémie qui remonte après un repas"],"example_contexts_en":["sweating triggered by heat","shivering in cold weather","blood sugar rising after a meal"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.dna_to_protein","domain_id":"human_biology_medicine","objective_ids":["medicine_body","medicine_disease","medicine_evidence"],"stage":1,"order":4,"required":true,"prerequisite_keys":["human_biology_medicine.homeostasis"],"fallback_key":null,"title_fr":"De l'ADN à la protéine","title_en":"From DNA to protein","summary_fr":"Suivre le passage d'une séquence d'ADN à une protéine fonctionnelle en deux étapes.","summary_en":"Follow the path from a DNA sequence to a functional protein in two steps.","learning_goals_fr":["Ordonner transcription et traduction.","Expliquer pourquoi toutes les cellules n'expriment pas les mêmes gènes."],"learning_goals_en":["Order transcription and translation.","Explain why not all cells express the same genes."],"tutor_focus_fr":"Fais ordonner les deux étapes du gène à la protéine, puis demande pourquoi deux cellules du même corps sont différentes.","tutor_focus_en":"Have the student order the two steps from gene to protein, then ask why two cells of the same body differ.","example_contexts_fr":["l'insuline produite par le pancréas","une cellule de peau et un neurone au même génome","une enzyme digestive fabriquée après un repas"],"example_contexts_en":["insulin produced by the pancreas","a skin cell and a neuron sharing one genome","a digestive enzyme made after a meal"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.medical_vocabulary","domain_id":"human_biology_medicine","objective_ids":["medicine_body","medicine_disease","medicine_evidence"],"stage":1,"order":5,"required":true,"prerequisite_keys":["human_biology_medicine.dna_to_protein"],"fallback_key":null,"title_fr":"Lire un terme médical","title_en":"Reading a medical term","summary_fr":"Décomposer un mot médical en préfixe, racine et suffixe pour en deviner le sens.","summary_en":"Break a medical word into prefix, root and suffix to infer its meaning.","learning_goals_fr":["Décomposer trois termes médicaux courants.","Deviner le sens d'un terme inconnu à partir de ses éléments."],"learning_goals_en":["Break down three common medical terms.","Infer the meaning of an unknown term from its parts."],"tutor_focus_fr":"Fais décomposer trois termes médicaux, puis demande de deviner le sens d'un quatrième jamais rencontré.","tutor_focus_en":"Have the student break down three medical terms, then infer the meaning of a fourth they have never seen.","example_contexts_fr":["un compte rendu d'examen rempli d'abréviations","un terme finissant par -ite dans une notice","un mot composé désignant une opération"],"example_contexts_en":["a test report full of abbreviations","a term ending in -itis in a leaflet","a compound word naming a surgical procedure"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.skeleton_and_muscles","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":1,"order":6,"required":true,"prerequisite_keys":["human_biology_medicine.medical_vocabulary"],"fallback_key":null,"title_fr":"Os, articulations et muscles","title_en":"Bones, joints and muscles","summary_fr":"Comprendre le levier formé par un os, une articulation et un muscle qui se contracte.","summary_en":"Understand the lever formed by a bone, a joint and a contracting muscle.","learning_goals_fr":["Décrire le mouvement produit par une paire de muscles antagonistes.","Nommer les trois éléments d'un levier articulaire."],"learning_goals_en":["Describe the movement produced by a pair of antagonist muscles.","Name the three parts of a joint lever."],"tutor_focus_fr":"Fais décrire les muscles qui plient puis tendent le coude, et demande pourquoi un muscle ne peut que tirer.","tutor_focus_en":"Have the student describe the muscles bending then extending the elbow, and ask why a muscle can only pull.","example_contexts_fr":["la flexion du coude en portant un sac","une articulation du genou en descente","une posture assise maintenue longtemps"],"example_contexts_en":["bending the elbow while carrying a bag","a knee joint going downhill","a seated posture held for a long time"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.pathogen_types","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":1,"order":7,"required":true,"prerequisite_keys":["human_biology_medicine.medical_vocabulary"],"fallback_key":null,"title_fr":"Bactéries, virus, champignons et parasites","title_en":"Bacteria, viruses, fungi and parasites","summary_fr":"Distinguer les grandes familles d'agents infectieux et ce que cela implique pour les traitements.","summary_en":"Tell apart the major families of infectious agents and what that implies for treatment.","learning_goals_fr":["Comparer bactérie et virus sur la structure et la reproduction.","Expliquer pourquoi un antibiotique n'agit pas sur un virus."],"learning_goals_en":["Compare bacteria and viruses on structure and reproduction.","Explain why an antibiotic does not act on a virus."],"tutor_focus_fr":"Fais comparer une bactérie et un virus, puis demande pourquoi un antibiotique est inutile contre une infection virale.","tutor_focus_en":"Have the student compare a bacterium and a virus, then ask why an antibiotic is useless against a viral infection.","example_contexts_fr":["une angine d'origine virale ou bactérienne","une infection cutanée due à un champignon","une contamination alimentaire par une bactérie"],"example_contexts_en":["a sore throat of viral or bacterial origin","a skin infection caused by a fungus","food contamination by a bacterium"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.what_is_a_drug","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":1,"order":8,"required":true,"prerequisite_keys":["human_biology_medicine.medical_vocabulary"],"fallback_key":null,"title_fr":"Ce qu'est un médicament","title_en":"What a medicine is","summary_fr":"Distinguer principe actif, excipients et forme galénique, et comprendre ce que chacun apporte.","summary_en":"Tell apart active ingredient, excipients and dosage form, and what each contributes.","learning_goals_fr":["Distinguer principe actif et excipients sur une notice.","Expliquer ce que la forme du médicament change à son action."],"learning_goals_en":["Tell active ingredient from excipients on a leaflet.","Explain what the dosage form changes about the action."],"tutor_focus_fr":"Fais lire la composition d'une notice et distinguer principe actif et excipients, puis demande ce que change une forme à libération prolongée.","tutor_focus_en":"Have the student read a leaflet's composition and separate active ingredient from excipients, then ask what an extended-release form changes.","example_contexts_fr":["une notice listant plusieurs composants","un comprimé à libération prolongée","un générique comparé à un médicament d'origine"],"example_contexts_en":["a leaflet listing several components","an extended-release tablet","a generic compared with an originator medicine"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.anatomical_orientation","domain_id":"human_biology_medicine","objective_ids":["medicine_body","medicine_disease","medicine_evidence"],"stage":2,"order":9,"required":true,"prerequisite_keys":["human_biology_medicine.medical_vocabulary"],"fallback_key":"human_biology_medicine.medical_vocabulary","title_fr":"Se repérer dans le corps : plans et positions","title_en":"Orienting yourself in the body: planes and positions","summary_fr":"Utiliser le vocabulaire de position pour décrire une localisation sans ambiguïté.","summary_en":"Use positional vocabulary to describe a location without ambiguity.","learning_goals_fr":["Utiliser correctement quatre termes de position.","Décrire une localisation sans ambiguïté."],"learning_goals_en":["Correctly use four positional terms.","Describe a location without ambiguity."],"tutor_focus_fr":"Fais décrire la position d'un organe par rapport à deux autres avec le vocabulaire adapté, puis corrige les ambiguïtés.","tutor_focus_en":"Have the student describe an organ's position relative to two others using the right vocabulary, then fix the ambiguities.","example_contexts_fr":["la description d'une douleur lors d'une consultation","une coupe d'imagerie médicale","un schéma d'anatomie vu de face et de profil"],"example_contexts_en":["describing a pain during a consultation","a medical imaging slice","an anatomy diagram seen from front and side"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.immune_defense_lines","domain_id":"human_biology_medicine","objective_ids":["medicine_body","medicine_disease","medicine_evidence"],"stage":2,"order":10,"required":true,"prerequisite_keys":["human_biology_medicine.anatomical_orientation"],"fallback_key":"human_biology_medicine.medical_vocabulary","title_fr":"Les deux lignes de défense de l'immunité","title_en":"The two lines of immune defence","summary_fr":"Distinguer la réponse immédiate non spécifique de la réponse ciblée et mémorisée.","summary_en":"Tell apart the immediate non-specific response and the targeted, remembered one.","learning_goals_fr":["Comparer immunité innée et immunité adaptative sur trois critères.","Expliquer ce que la mémoire immunitaire change lors d'un second contact."],"learning_goals_en":["Compare innate and adaptive immunity on three criteria.","Explain what immune memory changes on a second contact."],"tutor_focus_fr":"Fais comparer les deux réponses lors d'une coupure infectée, puis demande ce qui change lors d'un second contact avec le même agent.","tutor_focus_en":"Have the student compare both responses on an infected cut, then ask what changes on a second contact with the same agent.","example_contexts_fr":["une coupure qui rougit et gonfle","une seconde exposition au même virus","une fièvre déclenchée par une infection"],"example_contexts_en":["a cut turning red and swollen","a second exposure to the same virus","a fever triggered by an infection"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.metabolism_energy","domain_id":"human_biology_medicine","objective_ids":["medicine_body","medicine_disease","medicine_evidence"],"stage":2,"order":11,"required":true,"prerequisite_keys":["human_biology_medicine.immune_defense_lines"],"fallback_key":"human_biology_medicine.medical_vocabulary","title_fr":"D'où vient l'énergie des cellules","title_en":"Where cells get their energy","summary_fr":"Relier les nutriments consommés à la production d'énergie utilisable par les cellules.","summary_en":"Connect consumed nutrients to the production of energy cells can use.","learning_goals_fr":["Décrire le chemin d'un nutriment jusqu'à l'énergie cellulaire.","Comparer une dépense au repos et à l'effort."],"learning_goals_en":["Describe the path from a nutrient to cellular energy.","Compare energy expenditure at rest and during exercise."],"tutor_focus_fr":"Fais suivre le trajet d'un sucre depuis l'assiette jusqu'à la contraction d'un muscle, en nommant chaque étape.","tutor_focus_en":"Have the student follow a sugar from the plate to a muscle contraction, naming every step.","example_contexts_fr":["un sprint de trente secondes","un jeûne d'une nuit","une marche longue à allure régulière"],"example_contexts_en":["a thirty-second sprint","an overnight fast","a long walk at steady pace"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.medical_uncertainty","domain_id":"human_biology_medicine","objective_ids":["medicine_body","medicine_disease","medicine_evidence"],"stage":2,"order":12,"required":true,"prerequisite_keys":["human_biology_medicine.metabolism_energy"],"fallback_key":"human_biology_medicine.medical_vocabulary","title_fr":"Pourquoi la médecine raisonne en probabilités","title_en":"Why medicine reasons in probabilities","summary_fr":"Comprendre qu'un raisonnement médical pondère des hypothèses au lieu de certitudes.","summary_en":"Understand that medical reasoning weighs hypotheses rather than certainties.","learning_goals_fr":["Expliquer pourquoi un même symptôme admet plusieurs causes.","Dire ce qu'un examen complémentaire modifie dans le raisonnement."],"learning_goals_en":["Explain why one symptom admits several causes.","Say what an additional test changes in the reasoning."],"tutor_focus_fr":"Fais lister plusieurs causes possibles d'un symptôme courant, puis demande ce qu'un examen change dans la hiérarchie des hypothèses. Reste général et n'évoque aucun cas personnel.","tutor_focus_en":"Have the student list several possible causes of a common symptom, then ask what a test changes in the ranking. Stay general and avoid any personal case.","example_contexts_fr":["une fatigue persistante aux causes multiples","un examen qui écarte une hypothèse","deux patients aux mêmes symptômes et aux causes différentes"],"example_contexts_en":["persistent tiredness with multiple causes","a test ruling out one hypothesis","two patients with the same symptoms and different causes"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.heart_circulation","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":2,"order":13,"required":true,"prerequisite_keys":["human_biology_medicine.medical_uncertainty"],"fallback_key":"human_biology_medicine.skeleton_and_muscles","title_fr":"Le trajet du sang dans le cœur","title_en":"The path of blood through the heart","summary_fr":"Suivre les deux circulations et comprendre le rôle des valves dans le sens du flux.","summary_en":"Follow both circulations and understand the role of valves in flow direction.","learning_goals_fr":["Ordonner les cavités traversées par le sang.","Expliquer le rôle des valves cardiaques."],"learning_goals_en":["Order the chambers the blood passes through.","Explain the role of the heart valves."],"tutor_focus_fr":"Fais suivre une goutte de sang depuis une jambe jusqu'au retour dans cette même jambe, cavité par cavité.","tutor_focus_en":"Have the student follow a drop of blood from a leg back to that same leg, chamber by chamber.","example_contexts_fr":["une goutte de sang partie d'une jambe","un souffle entendu à l'auscultation","un rythme cardiaque accéléré par l'effort"],"example_contexts_en":["a drop of blood leaving a leg","a murmur heard on auscultation","a heart rate raised by exercise"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.respiration_gas_exchange","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":2,"order":14,"required":false,"prerequisite_keys":["human_biology_medicine.heart_circulation"],"fallback_key":"human_biology_medicine.skeleton_and_muscles","title_fr":"Les échanges gazeux dans les poumons","title_en":"Gas exchange in the lungs","summary_fr":"Relier la surface alvéolaire, la diffusion des gaz et le transport par le sang.","summary_en":"Connect alveolar surface, gas diffusion and transport by the blood.","learning_goals_fr":["Expliquer la diffusion de l'oxygène au niveau alvéolaire.","Dire ce qui déclenche l'augmentation du rythme respiratoire."],"learning_goals_en":["Explain oxygen diffusion at the alveolar level.","Say what triggers an increase in breathing rate."],"tutor_focus_fr":"Fais expliquer ce qui traverse la paroi alvéolaire dans chaque sens, puis demande quel gaz déclenche l'envie de respirer.","tutor_focus_en":"Have the student explain what crosses the alveolar wall in each direction, then ask which gas drives the urge to breathe.","example_contexts_fr":["un effort qui accélère la respiration","une altitude élevée en montagne","une apnée volontaire de trente secondes"],"example_contexts_en":["exercise speeding up breathing","high altitude in the mountains","a thirty-second voluntary breath hold"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.infection_transmission","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":2,"order":15,"required":true,"prerequisite_keys":["human_biology_medicine.medical_uncertainty"],"fallback_key":"human_biology_medicine.pathogen_types","title_fr":"Comment une infection se transmet","title_en":"How an infection spreads","summary_fr":"Relier le mode de transmission aux mesures de prévention réellement efficaces.","summary_en":"Connect the transmission route to the prevention measures that actually work.","learning_goals_fr":["Associer trois modes de transmission à leur prévention adaptée.","Expliquer pourquoi une mesure efficace ici est inutile ailleurs."],"learning_goals_en":["Match three transmission routes to their fitting prevention.","Explain why a measure effective here is useless elsewhere."],"tutor_focus_fr":"Fais associer trois modes de transmission aux mesures adaptées, puis demande pourquoi la même mesure ne convient pas partout.","tutor_focus_en":"Have the student match three transmission routes to fitting measures, then ask why the same measure does not suit all of them.","example_contexts_fr":["une transmission par gouttelettes dans une salle fermée","une contamination par les mains et les surfaces","une infection transmise par un insecte piqueur"],"example_contexts_en":["droplet transmission in a closed room","contamination through hands and surfaces","an infection carried by a biting insect"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.inflammation","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":2,"order":16,"required":false,"prerequisite_keys":["human_biology_medicine.infection_transmission"],"fallback_key":"human_biology_medicine.pathogen_types","title_fr":"L'inflammation : utile et dangereuse","title_en":"Inflammation: useful and dangerous","summary_fr":"Comprendre pourquoi une réaction protectrice devient nuisible lorsqu'elle se prolonge.","summary_en":"Understand why a protective reaction becomes harmful when it persists.","learning_goals_fr":["Citer les signes classiques d'une inflammation aiguë.","Opposer inflammation aiguë et inflammation chronique."],"learning_goals_en":["Name the classic signs of acute inflammation.","Contrast acute and chronic inflammation."],"tutor_focus_fr":"Fais citer les signes d'une inflammation aiguë, puis demande ce qui change quand elle persiste pendant des mois.","tutor_focus_en":"Have the student name the signs of acute inflammation, then ask what changes when it persists for months.","example_contexts_fr":["une entorse gonflée et douloureuse","une inflammation persistante d'une articulation","une rougeur autour d'une plaie infectée"],"example_contexts_en":["a swollen and painful sprain","persistent inflammation of a joint","redness around an infected wound"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.dose_response","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":2,"order":17,"required":true,"prerequisite_keys":["human_biology_medicine.medical_uncertainty"],"fallback_key":"human_biology_medicine.what_is_a_drug","title_fr":"La relation dose-effet","title_en":"The dose-response relationship","summary_fr":"Comprendre la courbe qui relie une dose à un effet et la marge entre efficacité et toxicité.","summary_en":"Understand the curve linking dose to effect and the margin between efficacy and toxicity.","learning_goals_fr":["Décrire l'allure d'une courbe dose-effet.","Expliquer ce qu'est une marge thérapeutique étroite."],"learning_goals_en":["Describe the shape of a dose-response curve.","Explain what a narrow therapeutic margin is."],"tutor_focus_fr":"Fais décrire l'allure d'une courbe dose-effet, puis demande ce qu'implique une marge thérapeutique étroite pour la surveillance.","tutor_focus_en":"Have the student describe the shape of a dose-response curve, then ask what a narrow margin implies for monitoring.","example_contexts_fr":["un effet qui n'augmente plus au-delà d'une dose","une substance efficace à faible dose et toxique au-delà","un ajustement de dose selon le poids"],"example_contexts_en":["an effect that stops rising beyond a dose","a substance effective at low dose and toxic above","a dose adjusted to body weight"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.drug_journey","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":2,"order":18,"required":false,"prerequisite_keys":["human_biology_medicine.dose_response"],"fallback_key":"human_biology_medicine.what_is_a_drug","title_fr":"Le trajet d'un médicament dans le corps","title_en":"The journey of a medicine through the body","summary_fr":"Suivre absorption, distribution, métabolisme et élimination pour comprendre la durée d'action.","summary_en":"Follow absorption, distribution, metabolism and elimination to understand duration of action.","learning_goals_fr":["Ordonner les quatre étapes du devenir d'un médicament.","Expliquer ce que la demi-vie détermine dans un schéma de prise."],"learning_goals_en":["Order the four steps of a medicine's fate.","Explain what half-life determines in a dosing schedule."],"tutor_focus_fr":"Fais ordonner les quatre étapes, puis demande pourquoi certains médicaments se prennent une fois par jour et d'autres trois fois.","tutor_focus_en":"Have the student order the four steps, then ask why some medicines are taken once a day and others three times.","example_contexts_fr":["un médicament pris trois fois par jour","une prise à jeun ou pendant le repas","une élimination ralentie chez une personne âgée"],"example_contexts_en":["a medicine taken three times a day","a dose taken fasting or with a meal","slowed elimination in an older person"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.neuron_signal","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":3,"order":19,"required":true,"prerequisite_keys":["human_biology_medicine.respiration_gas_exchange"],"fallback_key":"human_biology_medicine.respiration_gas_exchange","title_fr":"Comment un neurone transmet un signal","title_en":"How a neuron transmits a signal","summary_fr":"Distinguer la propagation électrique le long de l'axone de la transmission chimique à la synapse.","summary_en":"Tell apart electrical propagation along the axon and chemical transmission at the synapse.","learning_goals_fr":["Décrire les deux modes de transmission successifs.","Expliquer ce qui limite la vitesse d'un influx."],"learning_goals_en":["Describe the two successive transmission modes.","Explain what limits the speed of an impulse."],"tutor_focus_fr":"Fais suivre un signal depuis un récepteur cutané jusqu'au cerveau, en distinguant les deux modes de transmission.","tutor_focus_en":"Have the student follow a signal from a skin receptor to the brain, distinguishing the two transmission modes.","example_contexts_fr":["un réflexe de retrait au contact d'une surface brûlante","une main endormie après une compression","un message de douleur remontant depuis un pied"],"example_contexts_en":["a withdrawal reflex on touching a hot surface","a hand gone numb after compression","a pain message travelling up from a foot"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.digestion_absorption","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":3,"order":20,"required":false,"prerequisite_keys":["human_biology_medicine.neuron_signal"],"fallback_key":"human_biology_medicine.respiration_gas_exchange","title_fr":"La digestion et l'absorption","title_en":"Digestion and absorption","summary_fr":"Suivre la transformation mécanique et chimique des aliments jusqu'au passage dans le sang.","summary_en":"Follow the mechanical and chemical transformation of food until it enters the blood.","learning_goals_fr":["Associer chaque organe digestif à sa transformation principale.","Dire où et comment les nutriments passent dans le sang."],"learning_goals_en":["Match each digestive organ to its main transformation.","Say where and how nutrients pass into the blood."],"tutor_focus_fr":"Fais suivre un morceau de pain de la bouche jusqu'au sang, en nommant les transformations à chaque étape.","tutor_focus_en":"Have the student follow a piece of bread from mouth to blood, naming the transformation at each step.","example_contexts_fr":["un morceau de pain mâché puis avalé","un repas gras qui ralentit la vidange de l'estomac","une prise de médicament pendant le repas"],"example_contexts_en":["a piece of bread chewed then swallowed","a fatty meal slowing stomach emptying","a medicine taken during a meal"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.kidney_filtration","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":3,"order":21,"required":false,"prerequisite_keys":["human_biology_medicine.digestion_absorption"],"fallback_key":"human_biology_medicine.respiration_gas_exchange","title_fr":"La filtration rénale","title_en":"Kidney filtration","summary_fr":"Comprendre l'enchaînement filtration, réabsorption et sécrétion qui produit l'urine.","summary_en":"Understand the chain of filtration, reabsorption and secretion that produces urine.","learning_goals_fr":["Ordonner les trois étapes de formation de l'urine.","Expliquer pourquoi le volume filtré dépasse largement le volume émis."],"learning_goals_en":["Order the three steps of urine formation.","Explain why the filtered volume far exceeds the emitted volume."],"tutor_focus_fr":"Fais comparer le volume filtré chaque jour et le volume d'urine émis, puis demande ce qui explique l'écart.","tutor_focus_en":"Have the student compare the daily filtered volume and the emitted urine volume, then explain the gap.","example_contexts_fr":["une journée sans boire suffisamment","une urine plus foncée le matin","une consommation importante d'eau en une heure"],"example_contexts_en":["a day without drinking enough","darker urine in the morning","a large water intake within an hour"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.hormonal_regulation","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":3,"order":22,"required":false,"prerequisite_keys":["human_biology_medicine.kidney_filtration"],"fallback_key":"human_biology_medicine.respiration_gas_exchange","title_fr":"Les hormones et la régulation à distance","title_en":"Hormones and regulation at a distance","summary_fr":"Comprendre une communication lente et diffuse fondée sur des récepteurs spécifiques.","summary_en":"Understand a slow, diffuse communication based on specific receptors.","learning_goals_fr":["Comparer signal nerveux et signal hormonal sur trois critères.","Expliquer pourquoi seules certaines cellules répondent à une hormone."],"learning_goals_en":["Compare nerve and hormone signals on three criteria.","Explain why only some cells respond to a hormone."],"tutor_focus_fr":"Fais comparer la réponse nerveuse et la réponse hormonale à un même stress, puis demande pourquoi toutes les cellules ne réagissent pas.","tutor_focus_en":"Have the student compare the nervous and hormonal response to the same stress, then ask why not all cells react.","example_contexts_fr":["une montée d'adrénaline lors d'une frayeur","une régulation de la glycémie après un repas","une croissance étalée sur plusieurs années"],"example_contexts_en":["an adrenaline surge during a fright","blood sugar regulation after a meal","growth spread over several years"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.antibiotic_resistance","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":3,"order":23,"required":true,"prerequisite_keys":["human_biology_medicine.inflammation"],"fallback_key":"human_biology_medicine.inflammation","title_fr":"La résistance aux antibiotiques","title_en":"Antibiotic resistance","summary_fr":"Comprendre la sélection de bactéries résistantes et ses conséquences collectives.","summary_en":"Understand the selection of resistant bacteria and its collective consequences.","learning_goals_fr":["Expliquer le mécanisme de sélection des bactéries résistantes.","Dire pourquoi la résistance est un problème collectif."],"learning_goals_en":["Explain the selection mechanism of resistant bacteria.","Say why resistance is a collective problem."],"tutor_focus_fr":"Fais expliquer ce qui arrive aux bactéries survivantes après un traitement incomplet, puis demande l'effet à l'échelle d'une population.","tutor_focus_en":"Have the student explain what happens to surviving bacteria after an incomplete course, then ask the effect at population scale.","example_contexts_fr":["un traitement interrompu dès la disparition des symptômes","un usage massif d'antibiotiques en élevage","une infection hospitalière difficile à traiter"],"example_contexts_en":["a course stopped as soon as symptoms disappear","heavy antibiotic use in livestock farming","a hospital infection that is hard to treat"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.cancer_mechanisms","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":3,"order":24,"required":false,"prerequisite_keys":["human_biology_medicine.antibiotic_resistance"],"fallback_key":"human_biology_medicine.inflammation","title_fr":"Comment naît un cancer","title_en":"How a cancer arises","summary_fr":"Comprendre l'accumulation d'altérations qui libère une cellule des contrôles de division.","summary_en":"Understand the accumulation of alterations that frees a cell from division controls.","learning_goals_fr":["Expliquer pourquoi une seule mutation ne suffit généralement pas.","Distinguer une tumeur locale d'une dissémination."],"learning_goals_en":["Explain why a single mutation is usually not enough.","Tell a local tumour apart from a dissemination."],"tutor_focus_fr":"Fais expliquer pourquoi plusieurs altérations sont nécessaires, puis demande ce que change une dissémination à distance. Reste général et n'évoque aucun cas personnel.","tutor_focus_en":"Have the student explain why several alterations are needed, then ask what distant spread changes. Stay general and avoid any personal case.","example_contexts_fr":["une exposition prolongée à un agent cancérigène","des mécanismes de réparation de l'ADN défaillants","une tumeur détectée à un stade précoce"],"example_contexts_en":["prolonged exposure to a carcinogenic agent","failing DNA repair mechanisms","a tumour detected at an early stage"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.autoimmune_disease","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":3,"order":25,"required":false,"prerequisite_keys":["human_biology_medicine.cancer_mechanisms"],"fallback_key":"human_biology_medicine.inflammation","title_fr":"Les maladies auto-immunes","title_en":"Autoimmune diseases","summary_fr":"Comprendre une réponse immunitaire dirigée contre les propres tissus de l'organisme.","summary_en":"Understand an immune response directed against the body's own tissues.","learning_goals_fr":["Expliquer ce qu'est une perte de tolérance immunitaire.","Dire pourquoi ces maladies évoluent souvent par poussées."],"learning_goals_en":["Explain what a loss of immune tolerance is.","Say why these diseases often progress in flares."],"tutor_focus_fr":"Fais expliquer ce que signifie une perte de tolérance, puis demande pourquoi l'évolution se fait souvent par poussées. Reste général.","tutor_focus_en":"Have the student explain what loss of tolerance means, then ask why progression often happens in flares. Stay general.","example_contexts_fr":["une atteinte articulaire évoluant par poussées","une destruction progressive de cellules productrices d'hormone","un traitement qui module la réponse immunitaire"],"example_contexts_en":["joint involvement progressing in flares","progressive destruction of hormone-producing cells","a treatment that modulates the immune response"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.genetic_disease","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":3,"order":26,"required":false,"prerequisite_keys":["human_biology_medicine.autoimmune_disease"],"fallback_key":"human_biology_medicine.inflammation","title_fr":"Les maladies génétiques","title_en":"Genetic diseases","summary_fr":"Distinguer une maladie liée à un seul gène d'une prédisposition multifactorielle.","summary_en":"Tell apart a single-gene disease and a multifactorial predisposition.","learning_goals_fr":["Comparer maladie monogénique et prédisposition multifactorielle.","Expliquer ce qu'un facteur de risque génétique ne détermine pas."],"learning_goals_en":["Compare a monogenic disease and a multifactorial predisposition.","Explain what a genetic risk factor does not determine."],"tutor_focus_fr":"Fais comparer une maladie monogénique et une prédisposition, puis demande ce qu'un résultat génétique ne permet pas de conclure. Reste général.","tutor_focus_en":"Have the student compare a monogenic disease and a predisposition, then ask what a genetic result cannot conclude. Stay general.","example_contexts_fr":["une maladie transmise selon un schéma familial clair","une prédisposition combinée à un mode de vie","un test génétique proposé au grand public"],"example_contexts_en":["a disease transmitted along a clear family pattern","a predisposition combined with lifestyle","a genetic test marketed to the general public"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.clinical_trial_phases","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":3,"order":27,"required":true,"prerequisite_keys":["human_biology_medicine.drug_journey"],"fallback_key":"human_biology_medicine.drug_journey","title_fr":"Les phases d'un essai clinique","title_en":"The phases of a clinical trial","summary_fr":"Associer chaque phase à la question qu'elle cherche à trancher et à sa population.","summary_en":"Match each phase to the question it aims to settle and to its population.","learning_goals_fr":["Associer chaque phase à sa question principale.","Expliquer pourquoi un effet rare n'apparaît qu'après commercialisation."],"learning_goals_en":["Match each phase to its main question.","Explain why a rare effect only appears after marketing."],"tutor_focus_fr":"Fais associer chaque phase à sa question, puis demande pourquoi un effet indésirable rare échappe souvent aux essais.","tutor_focus_en":"Have the student match each phase to its question, then ask why a rare adverse effect often escapes trials.","example_contexts_fr":["un essai de tolérance sur quelques dizaines de volontaires","une comparaison à un traitement existant sur des milliers de patients","un effet indésirable détecté après plusieurs années d'usage"],"example_contexts_en":["a tolerance trial on a few dozen volunteers","a comparison to an existing treatment on thousands of patients","an adverse effect detected after years of use"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.placebo_control","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":3,"order":28,"required":false,"prerequisite_keys":["human_biology_medicine.clinical_trial_phases"],"fallback_key":"human_biology_medicine.drug_journey","title_fr":"Le placebo et le groupe témoin","title_en":"Placebo and the control group","summary_fr":"Comprendre pourquoi un groupe de comparaison est nécessaire pour attribuer un effet au traitement.","summary_en":"Understand why a comparison group is needed to attribute an effect to the treatment.","learning_goals_fr":["Expliquer ce qu'un groupe témoin permet d'isoler.","Citer deux phénomènes confondus avec un effet du traitement."],"learning_goals_en":["Explain what a control group isolates.","Name two phenomena confused with a treatment effect."],"tutor_focus_fr":"Fais expliquer pourquoi une amélioration observée sans groupe témoin ne prouve rien, puis demande deux explications alternatives.","tutor_focus_en":"Have the student explain why an improvement without a control group proves nothing, then give two alternative explanations.","example_contexts_fr":["une amélioration observée sans comparaison","une maladie qui guérit spontanément en une semaine","un essai où les deux groupes s'améliorent"],"example_contexts_en":["an improvement observed with no comparison","a condition that resolves on its own within a week","a trial where both groups improve"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.randomization_blinding","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":3,"order":29,"required":false,"prerequisite_keys":["human_biology_medicine.placebo_control"],"fallback_key":"human_biology_medicine.drug_journey","title_fr":"Randomisation et insu","title_en":"Randomisation and blinding","summary_fr":"Comprendre ce que le tirage au sort et l'aveugle éliminent comme biais.","summary_en":"Understand which biases random allocation and blinding eliminate.","learning_goals_fr":["Expliquer ce que la randomisation équilibre entre les groupes.","Dire ce que l'insu protège chez le patient et chez l'évaluateur."],"learning_goals_en":["Explain what randomisation balances between groups.","Say what blinding protects in the patient and in the assessor."],"tutor_focus_fr":"Fais expliquer ce que la randomisation équilibre, puis demande ce qui se passe si l'évaluateur connaît le groupe de chaque patient.","tutor_focus_en":"Have the student explain what randomisation balances, then ask what happens if the assessor knows each patient's group.","example_contexts_fr":["deux groupes constitués par tirage au sort","un évaluateur qui connaît le traitement reçu","un essai où les patients devinent leur groupe"],"example_contexts_en":["two groups formed by random allocation","an assessor who knows the treatment received","a trial where patients guess their group"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.pharmacovigilance","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":3,"order":30,"required":false,"prerequisite_keys":["human_biology_medicine.randomization_blinding"],"fallback_key":"human_biology_medicine.drug_journey","title_fr":"La pharmacovigilance","title_en":"Pharmacovigilance","summary_fr":"Comprendre la surveillance après commercialisation et ce qu'un signalement isolé prouve.","summary_en":"Understand post-marketing surveillance and what an isolated report proves.","learning_goals_fr":["Expliquer pourquoi la surveillance continue après l'autorisation.","Dire ce qu'un signalement isolé permet et ne permet pas de conclure."],"learning_goals_en":["Explain why surveillance continues after authorisation.","Say what an isolated report can and cannot establish."],"tutor_focus_fr":"Fais expliquer ce qu'un signalement isolé permet de conclure, puis demande ce qu'il faut pour établir un lien de causalité.","tutor_focus_en":"Have the student explain what an isolated report establishes, then ask what is needed to show causality.","example_contexts_fr":["un signalement isolé après une vaccination","un effet rare détecté sur un million de doses","un retrait de médicament décidé après plusieurs années"],"example_contexts_en":["an isolated report after a vaccination","a rare effect detected across a million doses","a medicine withdrawn after several years"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.brain_regions","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":4,"order":31,"required":true,"prerequisite_keys":["human_biology_medicine.hormonal_regulation"],"fallback_key":"human_biology_medicine.hormonal_regulation","title_fr":"Les grandes régions du cerveau","title_en":"The major brain regions","summary_fr":"Associer des fonctions à des régions tout en évitant la caricature des zones isolées.","summary_en":"Match functions to regions while avoiding the caricature of isolated areas.","learning_goals_fr":["Associer trois régions à leurs fonctions dominantes.","Expliquer pourquoi une fonction mobilise plusieurs régions."],"learning_goals_en":["Match three regions to their dominant functions.","Explain why one function recruits several regions."],"tutor_focus_fr":"Fais associer trois régions à leurs fonctions, puis demande pourquoi parler d'une zone unique du langage est réducteur.","tutor_focus_en":"Have the student match three regions to their functions, then ask why speaking of a single language area is reductive.","example_contexts_fr":["la production et la compréhension du langage","la coordination d'un geste précis","la mémorisation d'un itinéraire"],"example_contexts_en":["producing and understanding language","coordinating a precise gesture","memorising a route"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.liver_functions","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":4,"order":32,"required":false,"prerequisite_keys":["human_biology_medicine.brain_regions"],"fallback_key":"human_biology_medicine.hormonal_regulation","title_fr":"Les fonctions du foie","title_en":"The functions of the liver","summary_fr":"Comprendre pourquoi un même organe assure stockage, synthèse et transformation des substances.","summary_en":"Understand why one organ handles storage, synthesis and transformation of substances.","learning_goals_fr":["Citer trois fonctions distinctes du foie.","Expliquer le rôle du foie dans le devenir d'un médicament."],"learning_goals_en":["Name three distinct liver functions.","Explain the liver's role in the fate of a medicine."],"tutor_focus_fr":"Fais citer trois fonctions du foie, puis demande pourquoi un médicament avalé n'a pas le même effet qu'un médicament injecté.","tutor_focus_en":"Have the student name three liver functions, then ask why a swallowed medicine does not act like an injected one.","example_contexts_fr":["un médicament avalé qui passe d'abord par le foie","une réserve de sucre mobilisée pendant la nuit","des protéines du sang fabriquées en continu"],"example_contexts_en":["a swallowed medicine passing through the liver first","a sugar reserve mobilised overnight","blood proteins produced continuously"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.blood_composition","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":4,"order":33,"required":false,"prerequisite_keys":["human_biology_medicine.liver_functions"],"fallback_key":"human_biology_medicine.hormonal_regulation","title_fr":"La composition du sang","title_en":"The composition of blood","summary_fr":"Relier chaque composant du sang à sa fonction et lire un bilan sanguin de façon générale.","summary_en":"Connect each blood component to its function and read a blood panel in general terms.","learning_goals_fr":["Associer trois composants sanguins à leur fonction.","Expliquer ce qu'un taux anormal signale en général."],"learning_goals_en":["Match three blood components to their function.","Explain what an abnormal level signals in general."],"tutor_focus_fr":"Fais associer trois composants du sang à leur fonction, puis demande ce qu'un taux abaissé pourrait signaler de façon générale, sans interpréter de cas personnel.","tutor_focus_en":"Have the student match three blood components to their function, then ask what a low level could signal in general, without interpreting a personal case.","example_contexts_fr":["un don du sang et ses composants séparés","une plaie qui cesse de saigner","un transport d'oxygène vers les muscles"],"example_contexts_en":["a blood donation separated into components","a wound that stops bleeding","oxygen transported to the muscles"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.sleep_and_circadian","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":4,"order":34,"required":false,"prerequisite_keys":["human_biology_medicine.blood_composition"],"fallback_key":"human_biology_medicine.hormonal_regulation","title_fr":"Le sommeil et l'horloge biologique","title_en":"Sleep and the biological clock","summary_fr":"Comprendre l'alternance des cycles de sommeil et le rôle de la lumière comme synchroniseur.","summary_en":"Understand the alternation of sleep cycles and the role of light as a synchroniser.","learning_goals_fr":["Décrire la succession des stades au cours d'un cycle.","Expliquer le rôle de la lumière dans le réglage de l'horloge."],"learning_goals_en":["Describe the succession of stages within a cycle.","Explain the role of light in setting the clock."],"tutor_focus_fr":"Fais décrire l'enchaînement des stades d'un cycle, puis demande pourquoi la lumière du matin avance l'horloge interne.","tutor_focus_en":"Have the student describe the succession of stages in one cycle, then ask why morning light advances the internal clock.","example_contexts_fr":["un décalage horaire après un vol long","un travail de nuit répété plusieurs semaines","un réveil difficile en plein cycle profond"],"example_contexts_en":["jet lag after a long flight","night work repeated over several weeks","a hard awakening in the middle of deep sleep"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.cardiovascular_risk","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":4,"order":35,"required":true,"prerequisite_keys":["human_biology_medicine.genetic_disease"],"fallback_key":"human_biology_medicine.genetic_disease","title_fr":"Comment se construit un risque cardiovasculaire","title_en":"How cardiovascular risk builds up","summary_fr":"Comprendre l'accumulation lente de facteurs qui aboutit à un événement brutal.","summary_en":"Understand the slow accumulation of factors leading to a sudden event.","learning_goals_fr":["Distinguer un facteur de risque modifiable d'un facteur non modifiable.","Expliquer pourquoi le risque se calcule globalement et non facteur par facteur."],"learning_goals_en":["Tell a modifiable risk factor apart from a non-modifiable one.","Explain why risk is computed globally rather than factor by factor."],"tutor_focus_fr":"Fais distinguer facteurs modifiables et non modifiables, puis demande pourquoi un score global vaut mieux qu'un seul chiffre. Reste général.","tutor_focus_en":"Have the student separate modifiable and non-modifiable factors, then ask why a global score beats a single figure. Stay general.","example_contexts_fr":["un dépôt qui se constitue sur des décennies","un score de risque calculé en population","un événement aigu survenant sans signe préalable"],"example_contexts_en":["a deposit building over decades","a risk score computed at population level","an acute event occurring with no prior sign"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.diabetes_mechanism","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":4,"order":36,"required":false,"prerequisite_keys":["human_biology_medicine.cardiovascular_risk"],"fallback_key":"human_biology_medicine.genetic_disease","title_fr":"Le mécanisme du diabète","title_en":"The mechanism of diabetes","summary_fr":"Distinguer un défaut de production d'insuline d'une résistance des tissus à son action.","summary_en":"Tell apart a defect in insulin production and a tissue resistance to its action.","learning_goals_fr":["Comparer les deux principaux mécanismes.","Expliquer pourquoi une glycémie élevée abîme les vaisseaux à long terme."],"learning_goals_en":["Compare the two main mechanisms.","Explain why high blood sugar damages vessels over time."],"tutor_focus_fr":"Fais comparer les deux mécanismes principaux, puis demande pourquoi les complications touchent surtout les petits vaisseaux. Reste général.","tutor_focus_en":"Have the student compare the two main mechanisms, then ask why complications mostly affect small vessels. Stay general.","example_contexts_fr":["une insuline absente faute de cellules productrices","des tissus qui répondent mal à l'insuline présente","un suivi de glycémie sur plusieurs mois"],"example_contexts_en":["insulin absent for lack of producing cells","tissues responding poorly to available insulin","blood sugar monitored over several months"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.neurodegenerative_disease","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":4,"order":37,"required":false,"prerequisite_keys":["human_biology_medicine.diabetes_mechanism"],"fallback_key":"human_biology_medicine.genetic_disease","title_fr":"Les maladies neurodégénératives","title_en":"Neurodegenerative diseases","summary_fr":"Comprendre une perte progressive de neurones et le décalage entre lésions et symptômes.","summary_en":"Understand a progressive loss of neurons and the lag between lesions and symptoms.","learning_goals_fr":["Expliquer pourquoi les symptômes apparaissent tardivement.","Distinguer un déclin cognitif attendu d'un processus pathologique."],"learning_goals_en":["Explain why symptoms appear late.","Tell an expected cognitive decline apart from a pathological process."],"tutor_focus_fr":"Fais expliquer pourquoi les symptômes apparaissent longtemps après les premières lésions. Reste général et n'évoque aucun cas personnel.","tutor_focus_en":"Have the student explain why symptoms appear long after the first lesions. Stay general and avoid any personal case.","example_contexts_fr":["des lésions présentes des années avant les symptômes","une compensation par d'autres circuits neuronaux","un suivi de recherche sur plusieurs années"],"example_contexts_en":["lesions present years before symptoms","compensation by other neural circuits","a research follow-up over several years"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.mental_health_biology","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":4,"order":38,"required":false,"prerequisite_keys":["human_biology_medicine.neurodegenerative_disease"],"fallback_key":"human_biology_medicine.genetic_disease","title_fr":"Ce que la biologie explique des troubles psychiques","title_en":"What biology explains about mental health conditions","summary_fr":"Situer la part biologique parmi les facteurs psychologiques et sociaux, sans réduction abusive.","summary_en":"Place the biological share among psychological and social factors, without undue reduction.","learning_goals_fr":["Citer trois familles de facteurs impliqués dans un trouble.","Expliquer pourquoi une explication uniquement chimique est réductrice."],"learning_goals_en":["Name three families of factors involved in a condition.","Explain why a purely chemical account is reductive."],"tutor_focus_fr":"Fais citer trois familles de facteurs, puis demande pourquoi une explication uniquement chimique est insuffisante. Reste général.","tutor_focus_en":"Have the student name three families of factors, then ask why a purely chemical account is insufficient. Stay general.","example_contexts_fr":["une vulnérabilité familiale associée à un événement de vie","une explication publique réduite à un déséquilibre chimique","un accompagnement combinant plusieurs approches"],"example_contexts_en":["a family vulnerability combined with a life event","a public account reduced to a chemical imbalance","care combining several approaches"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.relative_absolute_risk","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":4,"order":39,"required":true,"prerequisite_keys":["human_biology_medicine.pharmacovigilance"],"fallback_key":"human_biology_medicine.pharmacovigilance","title_fr":"Risque relatif et risque absolu","title_en":"Relative and absolute risk","summary_fr":"Traduire une réduction annoncée en pourcentage en effet réellement attendu dans une population.","summary_en":"Translate an announced percentage reduction into the effect actually expected in a population.","learning_goals_fr":["Convertir une réduction relative en réduction absolue.","Expliquer pourquoi la présentation relative impressionne davantage."],"learning_goals_en":["Convert a relative reduction into an absolute one.","Explain why the relative presentation impresses more."],"tutor_focus_fr":"Fais convertir une réduction de 50 % appliquée à un risque de 2 pour 1000, puis demande laquelle des deux formulations informe le mieux.","tutor_focus_en":"Have the student convert a 50% reduction applied to a risk of 2 per 1000, then ask which framing informs better.","example_contexts_fr":["un titre annonçant un risque divisé par deux","un risque initial de deux cas pour mille","une communication publique sur un traitement préventif"],"example_contexts_en":["a headline announcing a risk halved","a baseline risk of two cases per thousand","public communication about a preventive treatment"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.number_needed_to_treat","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":4,"order":40,"required":false,"prerequisite_keys":["human_biology_medicine.relative_absolute_risk"],"fallback_key":"human_biology_medicine.pharmacovigilance","title_fr":"Le nombre de sujets à traiter","title_en":"The number needed to treat","summary_fr":"Traduire un bénéfice statistique en nombre de personnes à traiter pour éviter un événement.","summary_en":"Translate a statistical benefit into how many people must be treated to avoid one event.","learning_goals_fr":["Calculer un nombre de sujets à traiter à partir d'une réduction absolue.","Comparer bénéfice attendu et effets indésirables attendus."],"learning_goals_en":["Compute a number needed to treat from an absolute reduction.","Compare expected benefit with expected adverse effects."],"tutor_focus_fr":"Fais calculer un nombre de sujets à traiter à partir d'une réduction absolue, puis demande comment le comparer aux effets indésirables.","tutor_focus_en":"Have the student compute a number needed to treat from an absolute reduction, then compare it with adverse effects.","example_contexts_fr":["un traitement préventif à large échelle","un bénéfice obtenu chez une personne sur cent traitées","un effet indésirable survenant chez une personne sur cinquante"],"example_contexts_en":["a large-scale preventive treatment","a benefit obtained in one person out of a hundred treated","an adverse effect occurring in one person out of fifty"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.screening_tradeoffs","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":4,"order":41,"required":false,"prerequisite_keys":["human_biology_medicine.number_needed_to_treat"],"fallback_key":"human_biology_medicine.pharmacovigilance","title_fr":"Les compromis d'un dépistage","title_en":"The trade-offs of screening","summary_fr":"Peser bénéfice attendu, faux positifs et surdiagnostic avant d'élargir un dépistage.","summary_en":"Weigh expected benefit, false positives and overdiagnosis before broadening a screening programme.","learning_goals_fr":["Expliquer ce qu'est un surdiagnostic.","Dire pourquoi dépister plus largement n'est pas toujours bénéfique."],"learning_goals_en":["Explain what overdiagnosis is.","Say why screening more widely is not always beneficial."],"tutor_focus_fr":"Fais estimer le nombre de faux positifs d'un dépistage en population, puis demande ce que le surdiagnostic ajoute comme coût.","tutor_focus_en":"Have the student estimate the false positives of a population screening, then ask what overdiagnosis adds as a cost.","example_contexts_fr":["un dépistage proposé à toute une classe d'âge","des examens complémentaires déclenchés par un faux positif","une anomalie détectée qui n'aurait jamais causé de symptôme"],"example_contexts_en":["a screening offered to a whole age group","follow-up tests triggered by a false positive","a detected anomaly that would never have caused symptoms"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.vaccine_mechanism","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":4,"order":42,"required":false,"prerequisite_keys":["human_biology_medicine.screening_tradeoffs"],"fallback_key":"human_biology_medicine.pharmacovigilance","title_fr":"Comment fonctionne un vaccin","title_en":"How a vaccine works","summary_fr":"Relier la présentation d'un antigène à la mémoire immunitaire et à la protection collective.","summary_en":"Connect antigen presentation to immune memory and to population-level protection.","learning_goals_fr":["Décrire le mécanisme de la mémoire immunitaire induite.","Expliquer ce que la couverture vaccinale change pour une population."],"learning_goals_en":["Describe the mechanism of induced immune memory.","Explain what vaccine coverage changes for a population."],"tutor_focus_fr":"Fais décrire ce qui se passe lors de la première puis de la seconde rencontre avec l'agent, puis demande l'effet d'une couverture élevée.","tutor_focus_en":"Have the student describe the first then the second encounter with the agent, then ask the effect of high coverage.","example_contexts_fr":["une première exposition sous forme vaccinale","une couverture élevée protégeant des personnes non vaccinées","un rappel administré à distance de la première dose"],"example_contexts_en":["a first exposure in vaccine form","high coverage protecting unvaccinated people","a booster given long after the first dose"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.reproduction_development","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":5,"order":43,"required":true,"prerequisite_keys":["human_biology_medicine.sleep_and_circadian"],"fallback_key":"human_biology_medicine.sleep_and_circadian","title_fr":"Reproduction et développement embryonnaire","title_en":"Reproduction and embryonic development","summary_fr":"Suivre les grandes étapes qui mènent d'une cellule unique à un organisme différencié.","summary_en":"Follow the major steps from a single cell to a differentiated organism.","learning_goals_fr":["Ordonner les grandes étapes du développement précoce.","Expliquer ce que signifie la différenciation cellulaire."],"learning_goals_en":["Order the major steps of early development.","Explain what cell differentiation means."],"tutor_focus_fr":"Fais ordonner les grandes étapes du développement précoce, puis demande comment des cellules identiques deviennent différentes.","tutor_focus_en":"Have the student order the major steps of early development, then ask how identical cells become different.","example_contexts_fr":["une cellule unique devenue un organisme complet","des cellules identiques qui se spécialisent","un suivi de grossesse par imagerie"],"example_contexts_en":["a single cell becoming a full organism","identical cells that specialise","a pregnancy followed through imaging"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.skin_barrier","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":5,"order":44,"required":false,"prerequisite_keys":["human_biology_medicine.reproduction_development"],"fallback_key":"human_biology_medicine.sleep_and_circadian","title_fr":"La peau comme organe","title_en":"The skin as an organ","summary_fr":"Comprendre les fonctions de barrière, de régulation thermique et de perception de la peau.","summary_en":"Understand the barrier, thermal regulation and sensing functions of the skin.","learning_goals_fr":["Citer trois fonctions de la peau au-delà de la protection.","Décrire les étapes de la cicatrisation d'une plaie."],"learning_goals_en":["Name three skin functions beyond protection.","Describe the steps of wound healing."],"tutor_focus_fr":"Fais citer trois fonctions de la peau, puis demande de décrire les étapes de la cicatrisation d'une coupure superficielle.","tutor_focus_en":"Have the student name three skin functions, then describe the healing steps of a superficial cut.","example_contexts_fr":["une coupure superficielle qui cicatrise","une transpiration abondante par forte chaleur","une exposition solaire prolongée"],"example_contexts_en":["a superficial cut healing over","heavy sweating in hot weather","prolonged sun exposure"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.aging_physiology","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":5,"order":45,"required":false,"prerequisite_keys":["human_biology_medicine.skin_barrier"],"fallback_key":"human_biology_medicine.sleep_and_circadian","title_fr":"Ce que le vieillissement change dans l'organisme","title_en":"What ageing changes in the body","summary_fr":"Distinguer les modifications physiologiques attendues des processus pathologiques.","summary_en":"Tell expected physiological changes apart from pathological processes.","learning_goals_fr":["Citer trois changements physiologiques liés à l'âge.","Distinguer un changement attendu d'un signe pathologique."],"learning_goals_en":["Name three physiological changes linked to age.","Tell an expected change apart from a pathological sign."],"tutor_focus_fr":"Fais distinguer trois changements attendus avec l'âge et un processus pathologique, en restant général et sans évoquer de cas personnel.","tutor_focus_en":"Have the student separate three expected age-related changes from a pathological process, staying general and avoiding personal cases.","example_contexts_fr":["une masse musculaire qui diminue avec les décennies","une récupération plus lente après un effort","une audition moins fine dans les aigus"],"example_contexts_en":["muscle mass decreasing over decades","slower recovery after exercise","reduced hearing in high frequencies"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.exercise_adaptation","domain_id":"human_biology_medicine","objective_ids":["medicine_body"],"stage":5,"order":46,"required":false,"prerequisite_keys":["human_biology_medicine.aging_physiology"],"fallback_key":"human_biology_medicine.sleep_and_circadian","title_fr":"Comment le corps s'adapte à l'effort répété","title_en":"How the body adapts to repeated exercise","summary_fr":"Comprendre l'adaptation progressive du cœur, des muscles et du métabolisme à l'entraînement.","summary_en":"Understand the gradual adaptation of heart, muscles and metabolism to training.","learning_goals_fr":["Décrire deux adaptations physiologiques à l'entraînement.","Expliquer le rôle de la récupération dans l'adaptation."],"learning_goals_en":["Describe two physiological adaptations to training.","Explain the role of recovery in adaptation."],"tutor_focus_fr":"Fais décrire deux adaptations obtenues après plusieurs semaines d'entraînement, puis demande pourquoi la récupération en fait partie.","tutor_focus_en":"Have the student describe two adaptations obtained after several weeks of training, then ask why recovery is part of it.","example_contexts_fr":["un rythme cardiaque de repos qui baisse","une même distance parcourue plus facilement","une reprise après plusieurs mois d'arrêt"],"example_contexts_en":["a resting heart rate going down","the same distance covered more easily","resuming after several months off"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.epidemic_dynamics","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":5,"order":47,"required":true,"prerequisite_keys":["human_biology_medicine.mental_health_biology"],"fallback_key":"human_biology_medicine.mental_health_biology","title_fr":"La dynamique d'une épidémie","title_en":"The dynamics of an epidemic","summary_fr":"Relier le nombre de reproduction, le délai entre contaminations et l'effet des mesures.","summary_en":"Connect the reproduction number, the delay between infections and the effect of measures.","learning_goals_fr":["Interpréter un nombre de reproduction supérieur ou inférieur à un.","Expliquer le décalage entre une mesure et son effet visible."],"learning_goals_en":["Interpret a reproduction number above or below one.","Explain the lag between a measure and its visible effect."],"tutor_focus_fr":"Fais interpréter un nombre de reproduction de 1,3, puis demande pourquoi l'effet d'une mesure met deux semaines à se voir.","tutor_focus_en":"Have the student interpret a reproduction number of 1.3, then ask why a measure takes two weeks to show its effect.","example_contexts_fr":["un nombre de reproduction estimé à 1,3","une courbe de cas qui continue de monter après une mesure","une couverture vaccinale partielle dans une population"],"example_contexts_en":["a reproduction number estimated at 1.3","a case curve still rising after a measure","partial vaccine coverage in a population"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.chronic_disease_progression","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":5,"order":48,"required":false,"prerequisite_keys":["human_biology_medicine.epidemic_dynamics"],"fallback_key":"human_biology_medicine.mental_health_biology","title_fr":"L'évolution d'une maladie chronique","title_en":"The course of a chronic disease","summary_fr":"Comprendre une trajectoire longue faite de stabilité, de poussées et d'adaptations du suivi.","summary_en":"Understand a long trajectory of stability, flares and adjustments to follow-up.","learning_goals_fr":["Décrire les phases typiques d'une trajectoire chronique.","Expliquer le rôle du suivi régulier dans cette trajectoire."],"learning_goals_en":["Describe the typical phases of a chronic trajectory.","Explain the role of regular follow-up along that trajectory."],"tutor_focus_fr":"Fais décrire les phases d'une trajectoire chronique, puis demande à quoi sert un suivi régulier en période stable. Reste général.","tutor_focus_en":"Have the student describe the phases of a chronic trajectory, then ask what regular follow-up achieves in a stable period. Stay general.","example_contexts_fr":["une période stable de plusieurs années","une poussée déclenchée par une infection","un ajustement de suivi après un changement d'état"],"example_contexts_en":["a stable period lasting several years","a flare triggered by an infection","a follow-up adjusted after a change in condition"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.comorbidity","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":5,"order":49,"required":false,"prerequisite_keys":["human_biology_medicine.chronic_disease_progression"],"fallback_key":"human_biology_medicine.mental_health_biology","title_fr":"Les comorbidités","title_en":"Comorbidities","summary_fr":"Comprendre pourquoi plusieurs maladies simultanées compliquent le raisonnement médical.","summary_en":"Understand why several simultaneous diseases complicate medical reasoning.","learning_goals_fr":["Expliquer comment deux maladies peuvent aggraver leurs effets mutuels.","Dire pourquoi les recommandations isolées se contredisent parfois."],"learning_goals_en":["Explain how two diseases can worsen each other's effects.","Say why isolated guidelines sometimes contradict each other."],"tutor_focus_fr":"Fais expliquer pourquoi deux recommandations distinctes peuvent devenir contradictoires chez une même personne. Reste général.","tutor_focus_en":"Have the student explain why two separate guidelines can become contradictory for one person. Stay general.","example_contexts_fr":["deux recommandations qui s'opposent pour un même patient","des essais cliniques excluant les patients complexes","un suivi coordonné entre plusieurs spécialités"],"example_contexts_en":["two guidelines conflicting for one patient","clinical trials excluding complex patients","care coordinated across several specialties"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.rare_disease_diagnosis","domain_id":"human_biology_medicine","objective_ids":["medicine_disease"],"stage":5,"order":50,"required":false,"prerequisite_keys":["human_biology_medicine.comorbidity"],"fallback_key":"human_biology_medicine.mental_health_biology","title_fr":"Le parcours diagnostique d'une maladie rare","title_en":"The diagnostic journey of a rare disease","summary_fr":"Comprendre pourquoi une maladie rare met souvent des années à être identifiée.","summary_en":"Understand why a rare disease often takes years to be identified.","learning_goals_fr":["Expliquer pourquoi les hypothèses fréquentes sont explorées en premier.","Dire ce qu'un registre de maladies rares apporte."],"learning_goals_en":["Explain why frequent hypotheses are explored first.","Say what a rare disease registry brings."],"tutor_focus_fr":"Fais expliquer pourquoi les hypothèses les plus fréquentes sont explorées d'abord, puis demande ce qu'un registre change. Reste général.","tutor_focus_en":"Have the student explain why the most frequent hypotheses are explored first, then ask what a registry changes. Stay general.","example_contexts_fr":["un symptôme compatible avec vingt maladies courantes","un délai de plusieurs années avant identification","un registre national regroupant des cas dispersés"],"example_contexts_en":["a symptom compatible with twenty common diseases","a delay of several years before identification","a national registry gathering scattered cases"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.evidence_hierarchy","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":5,"order":51,"required":true,"prerequisite_keys":["human_biology_medicine.vaccine_mechanism"],"fallback_key":"human_biology_medicine.vaccine_mechanism","title_fr":"La hiérarchie des preuves","title_en":"The hierarchy of evidence","summary_fr":"Classer les sources selon leur capacité à établir un lien de cause à effet.","summary_en":"Rank sources by their ability to establish a cause-and-effect link.","learning_goals_fr":["Classer quatre types d'études par niveau de preuve.","Dire pourquoi une étude observationnelle ne conclut pas à la causalité."],"learning_goals_en":["Rank four study types by evidence level.","Say why an observational study does not conclude causality."],"tutor_focus_fr":"Fais classer quatre sources par niveau de preuve, puis demande pourquoi un témoignage individuel se situe en bas du classement.","tutor_focus_en":"Have the student rank four sources by evidence level, then ask why an individual testimony sits at the bottom.","example_contexts_fr":["un témoignage individuel relayé en ligne","une étude observationnelle sur dix mille personnes","un essai randomisé contre placebo"],"example_contexts_en":["an individual testimony shared online","an observational study on ten thousand people","a randomised placebo-controlled trial"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.meta_analysis","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":5,"order":52,"required":false,"prerequisite_keys":["human_biology_medicine.evidence_hierarchy"],"fallback_key":"human_biology_medicine.vaccine_mechanism","title_fr":"La méta-analyse","title_en":"Meta-analysis","summary_fr":"Comprendre l'agrégation de plusieurs études et ce que l'hétérogénéité entre elles signale.","summary_en":"Understand the aggregation of several studies and what heterogeneity between them signals.","learning_goals_fr":["Expliquer ce qu'une méta-analyse gagne par rapport à une étude isolée.","Dire ce qu'une forte hétérogénéité doit faire suspecter."],"learning_goals_en":["Explain what a meta-analysis gains over a single study.","Say what strong heterogeneity should raise as a suspicion."],"tutor_focus_fr":"Fais expliquer ce qu'une méta-analyse apporte, puis demande ce qu'il faut conclure quand les études incluses se contredisent.","tutor_focus_en":"Have the student explain what a meta-analysis adds, then ask what to conclude when included studies contradict each other.","example_contexts_fr":["douze études de tailles très différentes","des résultats contradictoires entre deux pays","une conclusion reposant surtout sur une seule grande étude"],"example_contexts_en":["twelve studies of very different sizes","contradictory results between two countries","a conclusion resting mostly on one large study"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.publication_bias","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":5,"order":53,"required":false,"prerequisite_keys":["human_biology_medicine.meta_analysis"],"fallback_key":"human_biology_medicine.vaccine_mechanism","title_fr":"Le biais de publication","title_en":"Publication bias","summary_fr":"Comprendre comment la non-publication des résultats négatifs déforme l'état des connaissances.","summary_en":"Understand how not publishing negative results distorts the state of knowledge.","learning_goals_fr":["Expliquer l'effet de la non-publication des essais négatifs.","Citer un dispositif qui limite ce biais."],"learning_goals_en":["Explain the effect of unpublished negative trials.","Name a mechanism that limits this bias."],"tutor_focus_fr":"Fais expliquer ce que change la non-publication de dix essais négatifs sur douze, puis demande quel dispositif corrige ce problème.","tutor_focus_en":"Have the student explain what ten unpublished negative trials out of twelve change, then ask which mechanism fixes it.","example_contexts_fr":["dix essais négatifs jamais publiés","un registre d'essais déclarés avant leur démarrage","une littérature qui semble unanimement favorable"],"example_contexts_en":["ten negative trials never published","a trial registry filled in before the study starts","a literature that looks unanimously favourable"],"safety_category":"medical_educational"},{"key":"human_biology_medicine.reading_guidelines","domain_id":"human_biology_medicine","objective_ids":["medicine_evidence"],"stage":5,"order":54,"required":false,"prerequisite_keys":["human_biology_medicine.publication_bias"],"fallback_key":"human_biology_medicine.vaccine_mechanism","title_fr":"Lire une recommandation médicale","title_en":"Reading a clinical guideline","summary_fr":"Comprendre le niveau de preuve, la force d'une recommandation et les conflits d'intérêts déclarés.","summary_en":"Understand evidence level, strength of recommendation and declared conflicts of interest.","learning_goals_fr":["Distinguer force de recommandation et niveau de preuve.","Repérer les éléments de transparence attendus dans un document."],"learning_goals_en":["Tell strength of recommendation apart from evidence level.","Spot the transparency elements expected in a document."],"tutor_focus_fr":"Fais distinguer force de recommandation et niveau de preuve dans un extrait, puis demande quels éléments de transparence vérifier.","tutor_focus_en":"Have the student separate strength of recommendation from evidence level in an extract, then ask which transparency elements to check.","example_contexts_fr":["une recommandation forte fondée sur un niveau de preuve faible","une mise à jour publiée cinq ans après la précédente","une déclaration de liens d'intérêts en fin de document"],"example_contexts_en":["a strong recommendation based on weak evidence","an update published five years after the previous one","a conflict-of-interest statement at the end of the document"],"safety_category":"medical_educational"}]}$catalog$::jsonb)
ON CONFLICT (domain_id) DO UPDATE
SET version = EXCLUDED.version, payload = EXCLUDED.payload, updated_at = now();

INSERT INTO public.learning_catalog_domains (domain_id, version, payload)
VALUES ($catalog$mathematics$catalog$, $catalog$v1$catalog$, $catalog${"version":"v1","steps":[{"key":"mathematics.number_sets","domain_id":"mathematics","objective_ids":["math_foundations","math_probability","math_technology"],"stage":1,"order":1,"required":true,"prerequisite_keys":[],"fallback_key":null,"title_fr":"Les ensembles de nombres et pourquoi ils s'étendent","title_en":"Number sets and why they keep extending","summary_fr":"Comprendre chaque extension des nombres comme la réponse à une opération jusque-là impossible.","summary_en":"Understand each extension of numbers as the answer to a previously impossible operation.","learning_goals_fr":["Associer chaque ensemble à l'opération qui a exigé sa création.","Dire à quel ensemble appartient un nombre donné."],"learning_goals_en":["Match each set to the operation that required its creation.","Say which set a given number belongs to."],"tutor_focus_fr":"Fais dire quelle opération devient possible en passant des entiers aux rationnels puis aux réels, avec un exemple à chaque étape.","tutor_focus_en":"Have the student say which operation becomes possible moving from integers to rationals then to reals, with an example each time.","example_contexts_fr":["un partage de trois gâteaux entre quatre personnes","une température descendue sous zéro","la diagonale d'un carré de côté un"],"example_contexts_en":["sharing three cakes among four people","a temperature below zero","the diagonal of a unit square"],"safety_category":"standard"},{"key":"mathematics.proportions_percentages","domain_id":"mathematics","objective_ids":["math_foundations","math_probability","math_technology"],"stage":1,"order":2,"required":true,"prerequisite_keys":["mathematics.number_sets"],"fallback_key":null,"title_fr":"Proportions, pourcentages et variations relatives","title_en":"Proportions, percentages and relative changes","summary_fr":"Manipuler les pourcentages successifs et distinguer un écart en points d'un écart en pourcentage.","summary_en":"Handle successive percentages and separate a change in points from a relative change.","learning_goals_fr":["Calculer l'effet d'une hausse suivie d'une baisse du même pourcentage.","Distinguer une variation en points d'une variation relative."],"learning_goals_en":["Compute the effect of a rise followed by an equal-percentage fall.","Tell apart a change in points and a relative change."],"tutor_focus_fr":"Fais calculer le prix final après une hausse de 20 % puis une baisse de 20 %, puis demande pourquoi on ne revient pas au prix initial.","tutor_focus_en":"Have the student compute the final price after a 20% rise then a 20% discount, then ask why it does not return to the start.","example_contexts_fr":["un prix augmenté de 20 % puis soldé de 20 %","un taux passé de 4 % à 6 %","une part de marché annoncée en hausse de moitié"],"example_contexts_en":["a price raised 20% then discounted 20%","a rate moving from 4% to 6%","a market share announced as up by half"],"safety_category":"standard"},{"key":"mathematics.equation_meaning","domain_id":"mathematics","objective_ids":["math_foundations","math_probability","math_technology"],"stage":1,"order":3,"required":true,"prerequisite_keys":["mathematics.proportions_percentages"],"fallback_key":null,"title_fr":"Ce qu'une équation affirme vraiment","title_en":"What an equation actually states","summary_fr":"Lire une équation comme une contrainte sur une inconnue plutôt que comme un calcul à effectuer.","summary_en":"Read an equation as a constraint on an unknown rather than a calculation to perform.","learning_goals_fr":["Traduire un énoncé en équation et nommer l'inconnue.","Vérifier qu'une valeur proposée satisfait l'équation."],"learning_goals_en":["Translate a statement into an equation and name the unknown.","Check whether a proposed value satisfies the equation."],"tutor_focus_fr":"Fais traduire un énoncé simple en équation, puis demande de vérifier deux valeurs candidates et d'expliquer ce que « résoudre » signifie.","tutor_focus_en":"Have the student translate a simple statement into an equation, then check two candidate values and explain what “solving” means.","example_contexts_fr":["un budget partagé entre trois postes de dépense","une distance parcourue à vitesse constante","un ingrédient dont on cherche la quantité dans une recette"],"example_contexts_en":["a budget split across three spending lines","a distance covered at constant speed","an ingredient quantity to find in a recipe"],"safety_category":"standard"},{"key":"mathematics.reading_a_graph","domain_id":"mathematics","objective_ids":["math_foundations","math_probability","math_technology"],"stage":1,"order":4,"required":true,"prerequisite_keys":["mathematics.equation_meaning"],"fallback_key":null,"title_fr":"Lire un graphique sans se faire tromper","title_en":"Reading a chart without being fooled","summary_fr":"Vérifier les axes, l'échelle et l'origine avant d'interpréter une courbe ou un histogramme.","summary_en":"Check axes, scale and origin before interpreting a curve or a histogram.","learning_goals_fr":["Repérer un axe tronqué et son effet sur l'impression visuelle.","Reformuler ce qu'un graphique montre réellement."],"learning_goals_en":["Spot a truncated axis and its effect on the visual impression.","Restate what a chart actually shows."],"tutor_focus_fr":"Fais critiquer un graphique dont l'axe vertical commence à 90, puis demande de reformuler l'évolution réelle en une phrase.","tutor_focus_en":"Have the student critique a chart whose vertical axis starts at 90, then restate the real change in one sentence.","example_contexts_fr":["un graphique de ventes dont l'axe commence à 90","une échelle logarithmique dans un article scientifique","un histogramme aux classes de largeurs inégales"],"example_contexts_en":["a sales chart whose axis starts at 90","a logarithmic scale in a scientific article","a histogram with unequal class widths"],"safety_category":"standard"},{"key":"mathematics.units_and_magnitudes","domain_id":"mathematics","objective_ids":["math_foundations","math_probability","math_technology"],"stage":1,"order":5,"required":true,"prerequisite_keys":["mathematics.reading_a_graph"],"fallback_key":null,"title_fr":"Unités, conversions et ordres de grandeur","title_en":"Units, conversions and orders of magnitude","summary_fr":"Contrôler un résultat par ses unités et par une estimation avant de le croire.","summary_en":"Check a result through its units and through an estimate before believing it.","learning_goals_fr":["Vérifier la cohérence des unités d'un calcul.","Estimer un ordre de grandeur avant de calculer précisément."],"learning_goals_en":["Check the unit consistency of a computation.","Estimate an order of magnitude before computing precisely."],"tutor_focus_fr":"Fais estimer un ordre de grandeur avant tout calcul, puis demande d'utiliser les unités pour détecter une erreur de formule.","tutor_focus_en":"Have the student estimate an order of magnitude before any computation, then use units to catch a formula error.","example_contexts_fr":["une consommation annoncée en kilowattheures","une vitesse convertie de kilomètres par heure en mètres par seconde","un devis dont le total est cent fois trop grand"],"example_contexts_en":["a consumption announced in kilowatt-hours","a speed converted from kilometres per hour to metres per second","a quote whose total is a hundred times too large"],"safety_category":"standard"},{"key":"mathematics.inequalities_intervals","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":1,"order":6,"required":true,"prerequisite_keys":["mathematics.units_and_magnitudes"],"fallback_key":null,"title_fr":"Inégalités et intervalles","title_en":"Inequalities and intervals","summary_fr":"Résoudre une inégalité en surveillant le sens du signe et exprimer la solution en intervalle.","summary_en":"Solve an inequality while watching the direction of the sign and express the solution as an interval.","learning_goals_fr":["Résoudre une inégalité comportant une multiplication par un négatif.","Écrire un ensemble de solutions sous forme d'intervalle."],"learning_goals_en":["Solve an inequality involving multiplication by a negative.","Write a solution set as an interval."],"tutor_focus_fr":"Fais résoudre une inégalité où l'on multiplie par un nombre négatif, puis demande d'expliquer le changement de sens.","tutor_focus_en":"Have the student solve an inequality multiplied by a negative number, then explain the reversal of direction.","example_contexts_fr":["une condition de remise à partir d'un certain montant","une température maintenue dans une plage précise","une inégalité multipliée par un nombre négatif"],"example_contexts_en":["a discount condition above a given amount","a temperature kept inside a precise range","an inequality multiplied by a negative number"],"safety_category":"standard"},{"key":"mathematics.random_experiment","domain_id":"mathematics","objective_ids":["math_probability"],"stage":1,"order":7,"required":true,"prerequisite_keys":["mathematics.units_and_magnitudes"],"fallback_key":null,"title_fr":"Expérience aléatoire, issues et événements","title_en":"Random experiment, outcomes and events","summary_fr":"Décrire précisément l'univers des issues avant tout calcul de probabilité.","summary_en":"Describe the outcome space precisely before computing any probability.","learning_goals_fr":["Lister l'univers des issues d'une expérience simple.","Calculer une probabilité en situation d'équiprobabilité."],"learning_goals_en":["List the outcome space of a simple experiment.","Compute a probability under equal likelihood."],"tutor_focus_fr":"Fais lister les issues du lancer de deux dés, puis demande pourquoi la somme 7 est plus probable que la somme 2.","tutor_focus_en":"Have the student list the outcomes of rolling two dice, then ask why a sum of 7 is more likely than a sum of 2.","example_contexts_fr":["le lancer de deux dés et la somme obtenue","un tirage au sort parmi trente élèves","une carte tirée dans un jeu de 52"],"example_contexts_en":["rolling two dice and reading the sum","a draw among thirty students","a card drawn from a 52-card deck"],"safety_category":"standard"},{"key":"mathematics.coordinates_and_vectors","domain_id":"mathematics","objective_ids":["math_technology"],"stage":1,"order":8,"required":true,"prerequisite_keys":["mathematics.units_and_magnitudes"],"fallback_key":null,"title_fr":"Coordonnées et vecteurs","title_en":"Coordinates and vectors","summary_fr":"Représenter un déplacement par un couple de nombres et additionner deux déplacements.","summary_en":"Represent a displacement by a pair of numbers and add two displacements.","learning_goals_fr":["Additionner deux vecteurs et interpréter le résultat.","Distinguer un point d'un vecteur."],"learning_goals_en":["Add two vectors and interpret the result.","Tell a point apart from a vector."],"tutor_focus_fr":"Fais additionner deux déplacements successifs, puis demande pourquoi l'ordre de l'addition ne change pas l'arrivée.","tutor_focus_en":"Have the student add two successive displacements, then ask why the order of addition does not change the arrival.","example_contexts_fr":["deux déplacements successifs sur une carte","une position d'objet dans une image en pixels","une force appliquée dans deux directions"],"example_contexts_en":["two successive moves on a map","an object position in an image in pixels","a force applied in two directions"],"safety_category":"standard"},{"key":"mathematics.function_concept","domain_id":"mathematics","objective_ids":["math_foundations","math_probability","math_technology"],"stage":2,"order":9,"required":true,"prerequisite_keys":["mathematics.units_and_magnitudes"],"fallback_key":"mathematics.units_and_magnitudes","title_fr":"La notion de fonction : entrée, sortie, unicité","title_en":"The idea of a function: input, output, uniqueness","summary_fr":"Distinguer une fonction d'une simple relation grâce à l'unicité de l'image.","summary_en":"Tell a function apart from a mere relation through the uniqueness of the image.","learning_goals_fr":["Décider si une correspondance donnée est une fonction.","Nommer domaine et image sur un exemple concret."],"learning_goals_en":["Decide whether a given correspondence is a function.","Name domain and range on a concrete example."],"tutor_focus_fr":"Fais décider si trois correspondances sont des fonctions, puis demande de justifier le cas qui échoue.","tutor_focus_en":"Have the student decide whether three correspondences are functions, then justify the one that fails.","example_contexts_fr":["un tarif postal en fonction du poids","une correspondance entre élèves et notes de plusieurs matières","une machine qui rend toujours la même monnaie pour la même pièce"],"example_contexts_en":["a postage price as a function of weight","a correspondence between students and grades in several subjects","a machine always returning the same change for the same coin"],"safety_category":"standard"},{"key":"mathematics.algebraic_manipulation","domain_id":"mathematics","objective_ids":["math_foundations","math_probability","math_technology"],"stage":2,"order":10,"required":true,"prerequisite_keys":["mathematics.function_concept"],"fallback_key":"mathematics.units_and_magnitudes","title_fr":"Manipuler une expression sans changer sa valeur","title_en":"Transforming an expression without changing its value","summary_fr":"Appliquer les transformations autorisées et repérer celles qui font perdre des solutions.","summary_en":"Apply the allowed transformations and spot the ones that lose solutions.","learning_goals_fr":["Justifier chaque étape d'une transformation d'expression.","Repérer une division par une quantité pouvant être nulle."],"learning_goals_en":["Justify each step of an expression transformation.","Spot a division by a quantity that may be zero."],"tutor_focus_fr":"Fais justifier chaque étape d'une simplification, puis demande où une division cache une perte de solution.","tutor_focus_en":"Have the student justify each step of a simplification, then ask where a division hides a lost solution.","example_contexts_fr":["une simplification qui fait disparaître une solution","une formule de physique isolée pour une variable","une identité remarquable utilisée pour factoriser"],"example_contexts_en":["a simplification that makes a solution disappear","a physics formula rearranged for one variable","a standard identity used to factorise"],"safety_category":"standard"},{"key":"mathematics.counterexample_power","domain_id":"mathematics","objective_ids":["math_foundations","math_probability","math_technology"],"stage":2,"order":11,"required":true,"prerequisite_keys":["mathematics.algebraic_manipulation"],"fallback_key":"mathematics.units_and_magnitudes","title_fr":"La force d'un contre-exemple","title_en":"The power of a counterexample","summary_fr":"Comprendre qu'un seul cas suffit à réfuter un énoncé général alors que mille cas ne le prouvent pas.","summary_en":"Understand that one case refutes a general claim while a thousand cases never prove it.","learning_goals_fr":["Réfuter un énoncé général par un contre-exemple.","Expliquer pourquoi des exemples favorables ne suffisent jamais."],"learning_goals_en":["Refute a general statement with a counterexample.","Explain why favourable examples are never enough."],"tutor_focus_fr":"Fais trouver un contre-exemple à un énoncé faux mais crédible, puis demande combien d'exemples suffiraient à le prouver.","tutor_focus_en":"Have the student find a counterexample to a false but credible claim, then ask how many examples would prove it.","example_contexts_fr":["l'affirmation que tout nombre impair est premier","une règle vérifiée sur les dix premiers cas","une formule qui échoue seulement pour zéro"],"example_contexts_en":["the claim that every odd number is prime","a rule verified on the first ten cases","a formula failing only at zero"],"safety_category":"standard"},{"key":"mathematics.exact_and_approximate","domain_id":"mathematics","objective_ids":["math_foundations","math_probability","math_technology"],"stage":2,"order":12,"required":true,"prerequisite_keys":["mathematics.counterexample_power"],"fallback_key":"mathematics.units_and_magnitudes","title_fr":"Valeur exacte et valeur approchée","title_en":"Exact value and approximate value","summary_fr":"Choisir entre forme exacte et arrondi, et suivre la propagation d'une erreur dans un calcul.","summary_en":"Choose between exact form and rounding, and follow how an error propagates in a computation.","learning_goals_fr":["Dire quand une forme exacte est préférable à un arrondi.","Estimer l'effet d'arrondis successifs sur un résultat final."],"learning_goals_en":["Say when an exact form beats a rounded one.","Estimate the effect of successive roundings on a final result."],"tutor_focus_fr":"Fais comparer un calcul mené en valeurs exactes puis avec des arrondis intermédiaires, et demande l'écart final obtenu.","tutor_focus_en":"Have the student compare a computation in exact values and with intermediate roundings, and ask for the final gap.","example_contexts_fr":["un devis calculé avec des arrondis à chaque ligne","une racine carrée laissée sous forme exacte","un taux d'intérêt arrondi au centième"],"example_contexts_en":["a quote computed with rounding on each line","a square root left in exact form","an interest rate rounded to the hundredth"],"safety_category":"standard"},{"key":"mathematics.linear_systems","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":2,"order":13,"required":true,"prerequisite_keys":["mathematics.exact_and_approximate"],"fallback_key":"mathematics.inequalities_intervals","title_fr":"Résoudre un système de deux équations","title_en":"Solving a system of two equations","summary_fr":"Interpréter un système comme l'intersection de deux droites et reconnaître les cas sans solution.","summary_en":"Read a system as the intersection of two lines and recognise the cases with no solution.","learning_goals_fr":["Résoudre un système par substitution et par combinaison.","Reconnaître un système sans solution ou à une infinité de solutions."],"learning_goals_en":["Solve a system by substitution and by combination.","Recognise a system with no solution or infinitely many."],"tutor_focus_fr":"Fais résoudre un système par deux méthodes, puis demande à quoi ressemble géométriquement un système sans solution.","tutor_focus_en":"Have the student solve a system by two methods, then ask what a system with no solution looks like geometrically.","example_contexts_fr":["deux tarifs d'abonnement égalisés à un certain usage","un mélange de deux produits à concentration donnée","deux droites parallèles tracées dans un repère"],"example_contexts_en":["two subscription plans equal at a certain usage","a mixture of two products at a given concentration","two parallel lines drawn in a coordinate frame"],"safety_category":"standard"},{"key":"mathematics.quadratic_roots","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":2,"order":14,"required":false,"prerequisite_keys":["mathematics.linear_systems"],"fallback_key":"mathematics.inequalities_intervals","title_fr":"Le discriminant et les racines d'un trinôme","title_en":"The discriminant and the roots of a quadratic","summary_fr":"Relier le signe du discriminant au nombre de racines et à la position de la parabole.","summary_en":"Connect the sign of the discriminant to the number of roots and to the parabola's position.","learning_goals_fr":["Calculer un discriminant et en déduire le nombre de racines.","Relier ce résultat à l'allure de la courbe."],"learning_goals_en":["Compute a discriminant and deduce the number of roots.","Relate that result to the shape of the curve."],"tutor_focus_fr":"Fais calculer trois discriminants de signes différents, puis demande de dessiner l'allure de chaque parabole correspondante.","tutor_focus_en":"Have the student compute three discriminants of different signs, then sketch the matching parabolas.","example_contexts_fr":["la trajectoire d'un ballon lancé en l'air","une aire maximale pour un périmètre donné","une équation sans solution réelle"],"example_contexts_en":["the path of a ball thrown into the air","a maximum area for a given perimeter","an equation with no real solution"],"safety_category":"standard"},{"key":"mathematics.counting_combinations","domain_id":"mathematics","objective_ids":["math_probability"],"stage":2,"order":15,"required":true,"prerequisite_keys":["mathematics.exact_and_approximate"],"fallback_key":"mathematics.random_experiment","title_fr":"Dénombrer : arrangements et combinaisons","title_en":"Counting: arrangements and combinations","summary_fr":"Choisir la bonne formule de comptage selon que l'ordre compte ou non.","summary_en":"Pick the right counting formula depending on whether order matters.","learning_goals_fr":["Décider si l'ordre intervient dans un problème donné.","Calculer un nombre de combinaisons sans énumérer."],"learning_goals_en":["Decide whether order matters in a given problem.","Compute a number of combinations without enumerating."],"tutor_focus_fr":"Fais comparer le nombre de podiums possibles et le nombre d'équipes de trois, puis demande d'où vient la division.","tutor_focus_en":"Have the student compare the number of podiums and the number of three-person teams, then ask where the division comes from.","example_contexts_fr":["un podium à trois places parmi dix concurrents","une équipe de trois personnes choisie parmi dix","un code à quatre chiffres avec répétition autorisée"],"example_contexts_en":["a three-place podium among ten competitors","a three-person team chosen among ten","a four-digit code with repetition allowed"],"safety_category":"standard"},{"key":"mathematics.independence","domain_id":"mathematics","objective_ids":["math_probability"],"stage":2,"order":16,"required":false,"prerequisite_keys":["mathematics.counting_combinations"],"fallback_key":"mathematics.random_experiment","title_fr":"Événements indépendants","title_en":"Independent events","summary_fr":"Tester l'indépendance de deux événements plutôt que la supposer par intuition.","summary_en":"Test the independence of two events rather than assume it by intuition.","learning_goals_fr":["Vérifier l'indépendance par le produit des probabilités.","Citer un cas d'indépendance supposée à tort."],"learning_goals_en":["Check independence through the product of probabilities.","Give a case where independence is wrongly assumed."],"tutor_focus_fr":"Fais vérifier l'indépendance de deux événements par le calcul, puis demande pourquoi une intuition de série est trompeuse.","tutor_focus_en":"Have the student check independence by computation, then ask why a streak intuition misleads.","example_contexts_fr":["une pièce lancée dix fois de suite","deux pannes de serveurs alimentés par la même source","un joueur convaincu qu'une couleur est « due »"],"example_contexts_en":["a coin tossed ten times in a row","two server failures sharing one power supply","a gambler convinced a colour is “due”"],"safety_category":"standard"},{"key":"mathematics.matrix_as_transformation","domain_id":"mathematics","objective_ids":["math_technology"],"stage":2,"order":17,"required":true,"prerequisite_keys":["mathematics.exact_and_approximate"],"fallback_key":"mathematics.coordinates_and_vectors","title_fr":"Une matrice comme transformation","title_en":"A matrix as a transformation","summary_fr":"Lire une matrice comme une opération géométrique appliquée à tout l'espace.","summary_en":"Read a matrix as a geometric operation applied to the whole space.","learning_goals_fr":["Décrire l'effet géométrique d'une matrice simple.","Identifier une matrice qui ne change rien."],"learning_goals_en":["Describe the geometric effect of a simple matrix.","Identify a matrix that changes nothing."],"tutor_focus_fr":"Fais appliquer une matrice à trois points d'un carré, puis demande de nommer la transformation obtenue.","tutor_focus_en":"Have the student apply a matrix to three corners of a square, then name the resulting transformation.","example_contexts_fr":["une image redimensionnée dans un éditeur","une rotation appliquée à un objet à l'écran","un aplatissement qui écrase une figure sur une droite"],"example_contexts_en":["an image resized in an editor","a rotation applied to an on-screen object","a flattening that collapses a figure onto a line"],"safety_category":"standard"},{"key":"mathematics.slope_rate_of_change","domain_id":"mathematics","objective_ids":["math_technology"],"stage":2,"order":18,"required":false,"prerequisite_keys":["mathematics.matrix_as_transformation"],"fallback_key":"mathematics.coordinates_and_vectors","title_fr":"La pente comme taux de variation","title_en":"Slope as a rate of change","summary_fr":"Interpréter une pente dans les unités du problème plutôt que comme un nombre abstrait.","summary_en":"Interpret a slope in the units of the problem rather than as an abstract number.","learning_goals_fr":["Calculer une pente entre deux points et l'exprimer en unités métier.","Distinguer une pente moyenne d'une pente instantanée."],"learning_goals_en":["Compute a slope between two points and express it in business units.","Tell an average slope apart from an instantaneous one."],"tutor_focus_fr":"Fais calculer une pente entre deux relevés et l'exprimer en euros par unité, puis demande ce qu'elle cache entre les deux points.","tutor_focus_en":"Have the student compute a slope between two readings and express it in euros per unit, then ask what it hides in between.","example_contexts_fr":["un coût qui augmente avec la quantité produite","une distance parcourue relevée toutes les heures","une consommation mesurée en début et fin de mois"],"example_contexts_en":["a cost rising with produced quantity","a distance recorded every hour","a consumption measured at the start and end of a month"],"safety_category":"standard"},{"key":"mathematics.logic_connectives","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":3,"order":19,"required":true,"prerequisite_keys":["mathematics.quadratic_roots"],"fallback_key":"mathematics.quadratic_roots","title_fr":"Connecteurs logiques et tables de vérité","title_en":"Logical connectives and truth tables","summary_fr":"Formaliser un énoncé composé et déterminer sa valeur de vérité de façon mécanique.","summary_en":"Formalise a compound statement and determine its truth value mechanically.","learning_goals_fr":["Construire la table de vérité d'un énoncé à deux propositions.","Traduire une condition du langage courant en formule logique."],"learning_goals_en":["Build the truth table of a statement with two propositions.","Translate an everyday condition into a logical formula."],"tutor_focus_fr":"Fais construire la table de vérité d'une condition d'accès à deux critères, puis demande la formulation exacte de son contraire.","tutor_focus_en":"Have the student build the truth table of a two-criterion access condition, then state its exact negation.","example_contexts_fr":["une condition d'accès combinant âge et abonnement","un filtre de recherche avec deux critères","une consigne ambiguë contenant « ou »"],"example_contexts_en":["an access condition combining age and subscription","a search filter with two criteria","an ambiguous instruction containing “or”"],"safety_category":"standard"},{"key":"mathematics.implication_contrapositive","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":3,"order":20,"required":false,"prerequisite_keys":["mathematics.logic_connectives"],"fallback_key":"mathematics.quadratic_roots","title_fr":"Implication, réciproque et contraposée","title_en":"Implication, converse and contrapositive","summary_fr":"Distinguer un énoncé de sa réciproque et utiliser la contraposée comme outil de preuve.","summary_en":"Tell a statement apart from its converse and use the contrapositive as a proof tool.","learning_goals_fr":["Écrire la réciproque et la contraposée d'une implication.","Dire laquelle est toujours équivalente à l'énoncé initial."],"learning_goals_en":["Write the converse and the contrapositive of an implication.","Say which one is always equivalent to the original statement."],"tutor_focus_fr":"Fais écrire réciproque et contraposée d'un énoncé donné, puis demande laquelle peut être fausse alors que l'énoncé est vrai.","tutor_focus_en":"Have the student write the converse and contrapositive of a given statement, then ask which can be false while the statement is true.","example_contexts_fr":["« s'il pleut, le sol est mouillé » et ses variantes","une condition suffisante confondue avec une condition nécessaire","un test médical dont on inverse la lecture"],"example_contexts_en":["“if it rains, the ground is wet” and its variants","a sufficient condition mistaken for a necessary one","a medical test whose reading is reversed"],"safety_category":"standard"},{"key":"mathematics.proof_by_induction","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":3,"order":21,"required":false,"prerequisite_keys":["mathematics.implication_contrapositive"],"fallback_key":"mathematics.quadratic_roots","title_fr":"La démonstration par récurrence","title_en":"Proof by induction","summary_fr":"Établir une propriété pour tous les entiers à partir d'une initialisation et d'une hérédité.","summary_en":"Establish a property for all integers from a base case and an inductive step.","learning_goals_fr":["Rédiger les deux étapes d'une preuve par récurrence.","Repérer une récurrence dont l'initialisation est fausse."],"learning_goals_en":["Write the two steps of an induction proof.","Spot an induction whose base case is false."],"tutor_focus_fr":"Fais rédiger les deux étapes pour la somme des n premiers entiers, puis demande ce qui casse si l'initialisation est omise.","tutor_focus_en":"Have the student write both steps for the sum of the first n integers, then ask what breaks if the base case is skipped.","example_contexts_fr":["la somme des n premiers entiers","une rangée de dominos dont l'un est mal placé","une formule vérifiée à partir de n égal 3 seulement"],"example_contexts_en":["the sum of the first n integers","a row of dominoes with one badly placed","a formula true only from n equal to 3"],"safety_category":"standard"},{"key":"mathematics.set_operations","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":3,"order":22,"required":false,"prerequisite_keys":["mathematics.proof_by_induction"],"fallback_key":"mathematics.quadratic_roots","title_fr":"Opérations sur les ensembles et dénombrement","title_en":"Set operations and counting","summary_fr":"Utiliser union, intersection et complémentaire pour compter sans double comptage.","summary_en":"Use union, intersection and complement to count without double counting.","learning_goals_fr":["Appliquer la formule du cardinal d'une union.","Représenter une situation par un diagramme d'ensembles."],"learning_goals_en":["Apply the formula for the size of a union.","Represent a situation with a set diagram."],"tutor_focus_fr":"Fais compter les personnes parlant au moins une de deux langues à partir de trois chiffres, puis demande d'où vient la soustraction.","tutor_focus_en":"Have the student count people speaking at least one of two languages from three figures, then ask where the subtraction comes from.","example_contexts_fr":["des clients abonnés à une offre, à l'autre ou aux deux","un sondage sur deux pratiques déclarées","un fichier fusionné contenant des doublons"],"example_contexts_en":["customers subscribed to one offer, the other or both","a survey about two declared practices","a merged file containing duplicates"],"safety_category":"standard"},{"key":"mathematics.conditional_probability","domain_id":"mathematics","objective_ids":["math_probability"],"stage":3,"order":23,"required":true,"prerequisite_keys":["mathematics.independence"],"fallback_key":"mathematics.independence","title_fr":"Probabilité conditionnelle","title_en":"Conditional probability","summary_fr":"Recalculer une probabilité en restreignant l'univers à l'information effectivement connue.","summary_en":"Recompute a probability by restricting the universe to the information actually known.","learning_goals_fr":["Calculer une probabilité conditionnelle sur un tableau croisé.","Expliquer pourquoi l'information disponible change le résultat."],"learning_goals_en":["Compute a conditional probability from a cross table.","Explain why available information changes the result."],"tutor_focus_fr":"Fais calculer une probabilité avant puis après une information supplémentaire, et demande d'expliquer l'écart.","tutor_focus_en":"Have the student compute a probability before and after extra information, and explain the gap.","example_contexts_fr":["un tableau croisant sexe et pratique sportive","un test positif chez une personne à faible risque","un client déjà connu comme mauvais payeur"],"example_contexts_en":["a table crossing gender and sport practice","a positive test in a low-risk person","a customer already known as a late payer"],"safety_category":"standard"},{"key":"mathematics.bayes_theorem","domain_id":"mathematics","objective_ids":["math_probability"],"stage":3,"order":24,"required":false,"prerequisite_keys":["mathematics.conditional_probability"],"fallback_key":"mathematics.independence","title_fr":"Le théorème de Bayes","title_en":"Bayes' theorem","summary_fr":"Renverser une probabilité conditionnelle en tenant compte de la fréquence de base.","summary_en":"Reverse a conditional probability while accounting for the base rate.","learning_goals_fr":["Calculer une probabilité a posteriori sur un cas de dépistage.","Expliquer l'effet d'une maladie rare sur le résultat."],"learning_goals_en":["Compute a posterior probability on a screening case.","Explain the effect of a rare disease on the result."],"tutor_focus_fr":"Fais calculer la probabilité d'être malade après un test positif pour une maladie rare, puis demande pourquoi le résultat surprend.","tutor_focus_en":"Have the student compute the probability of being ill after a positive test for a rare disease, then ask why the result surprises.","example_contexts_fr":["un dépistage d'une maladie touchant une personne sur mille","une alarme de sécurité qui se déclenche souvent à tort","un filtre anti-spam appliqué à un message rare"],"example_contexts_en":["screening for a disease affecting one person in a thousand","a security alarm often triggering wrongly","a spam filter applied to a rare message"],"safety_category":"standard"},{"key":"mathematics.expected_value","domain_id":"mathematics","objective_ids":["math_probability"],"stage":3,"order":25,"required":false,"prerequisite_keys":["mathematics.bayes_theorem"],"fallback_key":"mathematics.independence","title_fr":"L'espérance d'un gain aléatoire","title_en":"Expected value of a random gain","summary_fr":"Calculer la valeur moyenne d'un gain aléatoire et l'utiliser pour comparer deux décisions.","summary_en":"Compute the average value of a random gain and use it to compare two decisions.","learning_goals_fr":["Calculer l'espérance d'un jeu à trois issues.","Dire pourquoi une espérance positive ne garantit rien à court terme."],"learning_goals_en":["Compute the expected value of a three-outcome game.","Say why a positive expectation guarantees nothing short term."],"tutor_focus_fr":"Fais calculer l'espérance de deux offres concurrentes, puis demande pourquoi la meilleure espérance peut décevoir sur dix essais.","tutor_focus_en":"Have the student compute the expectation of two competing offers, then ask why the better one can disappoint over ten trials.","example_contexts_fr":["une extension de garantie proposée à l'achat","un jeu de loterie à trois lots","un investissement à trois scénarios chiffrés"],"example_contexts_en":["an extended warranty offered at purchase","a lottery with three prizes","an investment with three quantified scenarios"],"safety_category":"standard"},{"key":"mathematics.variance_spread","domain_id":"mathematics","objective_ids":["math_probability"],"stage":3,"order":26,"required":false,"prerequisite_keys":["mathematics.expected_value"],"fallback_key":"mathematics.independence","title_fr":"Variance et écart-type","title_en":"Variance and standard deviation","summary_fr":"Mesurer la dispersion et comprendre pourquoi deux séries de même moyenne ne se valent pas.","summary_en":"Measure spread and see why two series with the same mean are not equivalent.","learning_goals_fr":["Comparer deux séries de même moyenne par leur dispersion.","Interpréter un écart-type dans l'unité des données."],"learning_goals_en":["Compare two series with the same mean by their spread.","Interpret a standard deviation in the unit of the data."],"tutor_focus_fr":"Fais comparer deux séries de même moyenne mais de dispersions différentes, puis demande laquelle est préférable et pourquoi.","tutor_focus_en":"Have the student compare two series with equal means but different spread, then ask which is preferable and why.","example_contexts_fr":["deux fournisseurs au même délai moyen de livraison","deux classes à la même moyenne générale","un temps de réponse serveur très irrégulier"],"example_contexts_en":["two suppliers with the same average delivery time","two classes with the same overall average","a very irregular server response time"],"safety_category":"standard"},{"key":"mathematics.dot_product","domain_id":"mathematics","objective_ids":["math_technology"],"stage":3,"order":27,"required":true,"prerequisite_keys":["mathematics.slope_rate_of_change"],"fallback_key":"mathematics.slope_rate_of_change","title_fr":"Le produit scalaire et l'angle","title_en":"The dot product and angle","summary_fr":"Utiliser le produit scalaire pour mesurer l'alignement de deux vecteurs.","summary_en":"Use the dot product to measure how aligned two vectors are.","learning_goals_fr":["Calculer un produit scalaire et en déduire une orientation relative.","Reconnaître deux vecteurs orthogonaux."],"learning_goals_en":["Compute a dot product and deduce a relative orientation.","Recognise two orthogonal vectors."],"tutor_focus_fr":"Fais calculer le produit scalaire de deux vecteurs, puis demande ce que signale un résultat nul puis un résultat négatif.","tutor_focus_en":"Have the student compute the dot product of two vectors, then ask what a zero and then a negative result signals.","example_contexts_fr":["deux textes comparés par leurs vecteurs de mots","un éclairage dont l'intensité dépend de l'angle","deux directions perpendiculaires dans un plan"],"example_contexts_en":["two texts compared through their word vectors","lighting whose intensity depends on the angle","two perpendicular directions in a plane"],"safety_category":"standard"},{"key":"mathematics.matrix_multiplication","domain_id":"mathematics","objective_ids":["math_technology"],"stage":3,"order":28,"required":false,"prerequisite_keys":["mathematics.dot_product"],"fallback_key":"mathematics.slope_rate_of_change","title_fr":"Le produit matriciel","title_en":"Matrix multiplication","summary_fr":"Comprendre la composition de deux transformations et pourquoi l'ordre compte.","summary_en":"Understand the composition of two transformations and why order matters.","learning_goals_fr":["Effectuer un produit de deux matrices deux par deux.","Montrer sur un exemple que le produit n'est pas commutatif."],"learning_goals_en":["Multiply two two-by-two matrices.","Show on an example that the product is not commutative."],"tutor_focus_fr":"Fais composer une rotation et une mise à l'échelle dans les deux ordres, puis demande de comparer les résultats.","tutor_focus_en":"Have the student compose a rotation and a scaling in both orders, then compare the results.","example_contexts_fr":["une rotation suivie d'un agrandissement","deux transformations enchaînées sur une image","une couche de réseau de neurones appliquée à un lot"],"example_contexts_en":["a rotation followed by an enlargement","two transformations chained on an image","a neural network layer applied to a batch"],"safety_category":"standard"},{"key":"mathematics.derivative_meaning","domain_id":"mathematics","objective_ids":["math_technology"],"stage":3,"order":29,"required":false,"prerequisite_keys":["mathematics.matrix_multiplication"],"fallback_key":"mathematics.slope_rate_of_change","title_fr":"La dérivée et la variation instantanée","title_en":"The derivative and instantaneous change","summary_fr":"Interpréter la dérivée comme vitesse instantanée et comme outil de recherche d'extremum.","summary_en":"Read the derivative as an instantaneous rate and as a tool for finding extrema.","learning_goals_fr":["Interpréter le signe de la dérivée sur un intervalle.","Localiser un maximum à partir de la dérivée."],"learning_goals_en":["Interpret the sign of the derivative on an interval.","Locate a maximum from the derivative."],"tutor_focus_fr":"Fais localiser le maximum d'une fonction de profit par sa dérivée, puis demande ce que signale une dérivée négative ensuite.","tutor_focus_en":"Have the student locate the maximum of a profit function through its derivative, then ask what a negative derivative signals after it.","example_contexts_fr":["un profit maximal pour une quantité produite","une vitesse lue sur un compteur à un instant précis","une courbe de température qui atteint son sommet"],"example_contexts_en":["a maximum profit for a produced quantity","a speed read on a dial at a precise instant","a temperature curve reaching its peak"],"safety_category":"standard"},{"key":"mathematics.integral_meaning","domain_id":"mathematics","objective_ids":["math_technology"],"stage":3,"order":30,"required":false,"prerequisite_keys":["mathematics.derivative_meaning"],"fallback_key":"mathematics.slope_rate_of_change","title_fr":"L'intégrale comme accumulation","title_en":"The integral as accumulation","summary_fr":"Lire une intégrale comme la somme d'un débit sur une durée, avec ses unités.","summary_en":"Read an integral as the sum of a rate over a duration, units included.","learning_goals_fr":["Interpréter l'aire sous une courbe dans les unités du problème.","Relier une intégrale à la dérivée correspondante."],"learning_goals_en":["Interpret the area under a curve in the problem's units.","Relate an integral to the matching derivative."],"tutor_focus_fr":"Fais interpréter l'aire sous une courbe de puissance en fonction du temps, puis demande l'unité du résultat.","tutor_focus_en":"Have the student interpret the area under a power-versus-time curve, then ask the unit of the result.","example_contexts_fr":["une consommation électrique cumulée sur une journée","une distance obtenue à partir d'une courbe de vitesse","un volume d'eau accumulé dans un réservoir"],"example_contexts_en":["electricity consumption accumulated over a day","a distance obtained from a speed curve","a water volume accumulated in a tank"],"safety_category":"standard"},{"key":"mathematics.proof_by_contradiction","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":4,"order":31,"required":true,"prerequisite_keys":["mathematics.set_operations"],"fallback_key":"mathematics.set_operations","title_fr":"Le raisonnement par l'absurde","title_en":"Proof by contradiction","summary_fr":"Supposer le contraire d'un énoncé et en tirer une contradiction pour établir sa vérité.","summary_en":"Assume the opposite of a statement and derive a contradiction to establish its truth.","learning_goals_fr":["Structurer une preuve par l'absurde en trois étapes.","Formuler correctement la négation de l'énoncé de départ."],"learning_goals_en":["Structure a proof by contradiction in three steps.","Correctly formulate the negation of the initial statement."],"tutor_focus_fr":"Fais rédiger la preuve de l'irrationalité de la racine de deux, puis demande où se situe exactement la contradiction.","tutor_focus_en":"Have the student write the proof that the square root of two is irrational, then locate the exact contradiction.","example_contexts_fr":["l'irrationalité de la racine carrée de deux","l'infinité des nombres premiers","une hypothèse d'unicité qui mène à deux objets distincts"],"example_contexts_en":["the irrationality of the square root of two","the infinitude of prime numbers","a uniqueness assumption leading to two distinct objects"],"safety_category":"standard"},{"key":"mathematics.sequences_convergence","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":4,"order":32,"required":false,"prerequisite_keys":["mathematics.proof_by_contradiction"],"fallback_key":"mathematics.set_operations","title_fr":"Suites et convergence","title_en":"Sequences and convergence","summary_fr":"Distinguer une suite qui s'approche d'une limite d'une suite qui croît sans borne.","summary_en":"Tell apart a sequence approaching a limit and a sequence growing without bound.","learning_goals_fr":["Décider si une suite simple converge ou diverge.","Expliquer ce que signifie s'approcher d'une limite."],"learning_goals_en":["Decide whether a simple sequence converges or diverges.","Explain what approaching a limit means."],"tutor_focus_fr":"Fais calculer les cinq premiers termes de deux suites, puis demande laquelle converge et comment le justifier.","tutor_focus_en":"Have the student compute the first five terms of two sequences, then say which converges and justify it.","example_contexts_fr":["un capital placé à intérêts composés","une distance divisée par deux à chaque étape","une somme infinie qui reste finie"],"example_contexts_en":["capital invested with compound interest","a distance halved at every step","an infinite sum that stays finite"],"safety_category":"standard"},{"key":"mathematics.exponential_logarithm","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":4,"order":33,"required":false,"prerequisite_keys":["mathematics.sequences_convergence"],"fallback_key":"mathematics.set_operations","title_fr":"Exponentielle et logarithme","title_en":"Exponential and logarithm","summary_fr":"Reconnaître une croissance multiplicative et utiliser le logarithme pour la ramener à une droite.","summary_en":"Recognise multiplicative growth and use the logarithm to turn it into a straight line.","learning_goals_fr":["Distinguer une croissance linéaire d'une croissance exponentielle.","Utiliser le logarithme pour retrouver un temps de doublement."],"learning_goals_en":["Tell apart linear growth and exponential growth.","Use the logarithm to recover a doubling time."],"tutor_focus_fr":"Fais calculer un temps de doublement à partir d'un taux de croissance, puis demande pourquoi une échelle logarithmique linéarise la courbe.","tutor_focus_en":"Have the student compute a doubling time from a growth rate, then ask why a logarithmic scale straightens the curve.","example_contexts_fr":["une épidémie dont les cas doublent chaque semaine","un capital placé à taux composé sur vingt ans","une courbe tracée en échelle logarithmique"],"example_contexts_en":["an epidemic whose cases double each week","capital compounded over twenty years","a curve plotted on a logarithmic scale"],"safety_category":"standard"},{"key":"mathematics.euclidean_algorithm","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":4,"order":34,"required":false,"prerequisite_keys":["mathematics.exponential_logarithm"],"fallback_key":"mathematics.set_operations","title_fr":"L'algorithme d'Euclide et le PGCD","title_en":"The Euclidean algorithm and the GCD","summary_fr":"Calculer un plus grand diviseur commun par divisions successives et comprendre pourquoi cela termine.","summary_en":"Compute a greatest common divisor by successive divisions and see why it terminates.","learning_goals_fr":["Dérouler l'algorithme sur deux nombres à trois chiffres.","Expliquer pourquoi la suite des restes finit par s'annuler."],"learning_goals_en":["Run the algorithm on two three-digit numbers.","Explain why the sequence of remainders eventually hits zero."],"tutor_focus_fr":"Fais dérouler l'algorithme sur deux nombres à trois chiffres, puis demande pourquoi il se termine toujours.","tutor_focus_en":"Have the student run the algorithm on two three-digit numbers, then ask why it always terminates.","example_contexts_fr":["une fraction à réduire à sa forme irréductible","deux engrenages dont on cherche la période commune","un pavage régulier d'une pièce rectangulaire"],"example_contexts_en":["a fraction to reduce to lowest terms","two gears whose common period is sought","a regular tiling of a rectangular room"],"safety_category":"standard"},{"key":"mathematics.normal_distribution","domain_id":"mathematics","objective_ids":["math_probability"],"stage":4,"order":35,"required":true,"prerequisite_keys":["mathematics.variance_spread"],"fallback_key":"mathematics.variance_spread","title_fr":"La loi normale","title_en":"The normal distribution","summary_fr":"Reconnaître les situations où la courbe en cloche s'applique et celles où elle induit en erreur.","summary_en":"Recognise where the bell curve applies and where it misleads.","learning_goals_fr":["Utiliser les repères à un et deux écarts-types.","Citer une grandeur qui ne suit pas une loi normale."],"learning_goals_en":["Use the one and two standard deviation landmarks.","Name a quantity that does not follow a normal law."],"tutor_focus_fr":"Fais estimer la proportion à moins de deux écarts-types de la moyenne, puis demande une grandeur pour laquelle ce modèle échoue.","tutor_focus_en":"Have the student estimate the share within two standard deviations of the mean, then name a quantity where the model fails.","example_contexts_fr":["les tailles adultes dans une population","les revenus dans un pays","une note d'examen centrée sur la moyenne"],"example_contexts_en":["adult heights in a population","incomes in a country","an exam grade centred on the average"],"safety_category":"standard"},{"key":"mathematics.law_of_large_numbers","domain_id":"mathematics","objective_ids":["math_probability"],"stage":4,"order":36,"required":false,"prerequisite_keys":["mathematics.normal_distribution"],"fallback_key":"mathematics.variance_spread","title_fr":"La loi des grands nombres","title_en":"The law of large numbers","summary_fr":"Comprendre pourquoi une fréquence observée se rapproche d'une probabilité sans jamais « rattraper » le passé.","summary_en":"Understand why an observed frequency approaches a probability without ever “making up” for the past.","learning_goals_fr":["Expliquer ce que la loi garantit et sur quelle échelle.","Réfuter l'idée qu'un écart passé doit être compensé."],"learning_goals_en":["Explain what the law guarantees and at which scale.","Refute the idea that a past deviation must be compensated."],"tutor_focus_fr":"Fais expliquer ce qui se passe après une série de sept faces, puis demande ce que la loi garantit vraiment sur dix mille lancers.","tutor_focus_en":"Have the student explain what happens after seven heads in a row, then ask what the law really guarantees over ten thousand tosses.","example_contexts_fr":["sept faces consécutives au jeu de pile ou face","un taux de conversion mesuré sur cent visiteurs","un sondage réalisé sur mille personnes"],"example_contexts_en":["seven consecutive heads in a coin game","a conversion rate measured on a hundred visitors","a survey run on a thousand people"],"safety_category":"standard"},{"key":"mathematics.sampling_bias","domain_id":"mathematics","objective_ids":["math_probability"],"stage":4,"order":37,"required":false,"prerequisite_keys":["mathematics.law_of_large_numbers"],"fallback_key":"mathematics.variance_spread","title_fr":"Échantillonnage et biais de sélection","title_en":"Sampling and selection bias","summary_fr":"Repérer comment le mode de recueil détermine la population réellement décrite.","summary_en":"Spot how the collection method decides which population is actually described.","learning_goals_fr":["Identifier la population effectivement représentée par un échantillon.","Expliquer pourquoi augmenter la taille ne corrige pas un biais."],"learning_goals_en":["Identify the population a sample really represents.","Explain why increasing the size does not fix a bias."],"tutor_focus_fr":"Fais identifier qui est réellement représenté par un sondage en ligne, puis demande si dix fois plus de réponses corrigeraient le problème.","tutor_focus_en":"Have the student identify who an online poll really represents, then ask whether ten times more answers would fix it.","example_contexts_fr":["un sondage diffusé sur un réseau social","des avis clients laissés spontanément","une étude menée uniquement en semaine"],"example_contexts_en":["a poll shared on a social network","customer reviews left spontaneously","a study run only on weekdays"],"safety_category":"standard"},{"key":"mathematics.confidence_interval","domain_id":"mathematics","objective_ids":["math_probability"],"stage":4,"order":38,"required":false,"prerequisite_keys":["mathematics.sampling_bias"],"fallback_key":"mathematics.variance_spread","title_fr":"L'intervalle de confiance","title_en":"The confidence interval","summary_fr":"Interpréter correctement une marge d'erreur et ce qu'elle dit d'une estimation.","summary_en":"Correctly interpret a margin of error and what it says about an estimate.","learning_goals_fr":["Lire une marge d'erreur et en déduire une fourchette.","Réfuter une interprétation fausse d'un intervalle."],"learning_goals_en":["Read a margin of error and derive a range.","Refute a wrong interpretation of an interval."],"tutor_focus_fr":"Fais interpréter un sondage à 52 % avec trois points de marge, puis demande si l'écart entre deux candidats est significatif.","tutor_focus_en":"Have the student interpret a poll at 52% with three points of margin, then ask whether a gap between two candidates is meaningful.","example_contexts_fr":["un sondage à 52 % avec trois points de marge","deux candidats séparés par un point","un taux de panne estimé sur cinquante machines"],"example_contexts_en":["a poll at 52% with three points of margin","two candidates one point apart","a failure rate estimated on fifty machines"],"safety_category":"standard"},{"key":"mathematics.eigenvectors","domain_id":"mathematics","objective_ids":["math_technology"],"stage":4,"order":39,"required":true,"prerequisite_keys":["mathematics.integral_meaning"],"fallback_key":"mathematics.integral_meaning","title_fr":"Vecteurs propres et directions stables","title_en":"Eigenvectors and stable directions","summary_fr":"Identifier les directions qu'une transformation conserve et ce qu'elles révèlent du système.","summary_en":"Identify the directions a transformation preserves and what they reveal about the system.","learning_goals_fr":["Vérifier qu'un vecteur donné est vecteur propre d'une matrice.","Interpréter une valeur propre supérieure ou inférieure à un."],"learning_goals_en":["Check that a given vector is an eigenvector of a matrix.","Interpret an eigenvalue above or below one."],"tutor_focus_fr":"Fais vérifier qu'un vecteur est propre pour une matrice donnée, puis demande ce qu'implique une valeur propre supérieure à un après vingt itérations.","tutor_focus_en":"Have the student check a vector is an eigenvector, then ask what an eigenvalue above one implies after twenty iterations.","example_contexts_fr":["une population répartie entre deux villes après plusieurs années","un axe principal dans un nuage de points","une direction inchangée par une rotation d'axe"],"example_contexts_en":["a population split between two cities after several years","a principal axis in a point cloud","a direction left unchanged by an axial rotation"],"safety_category":"standard"},{"key":"mathematics.gradient_multivariable","domain_id":"mathematics","objective_ids":["math_technology"],"stage":4,"order":40,"required":false,"prerequisite_keys":["mathematics.eigenvectors"],"fallback_key":"mathematics.integral_meaning","title_fr":"Le gradient d'une fonction à plusieurs variables","title_en":"The gradient of a multivariable function","summary_fr":"Utiliser le gradient comme direction de plus forte pente pour se déplacer dans un paysage.","summary_en":"Use the gradient as the steepest ascent direction to move through a landscape.","learning_goals_fr":["Interpréter le gradient comme direction de montée la plus rapide.","Dire ce qu'un gradient nul signale."],"learning_goals_en":["Interpret the gradient as the direction of fastest increase.","Say what a zero gradient signals."],"tutor_focus_fr":"Fais interpréter le gradient sur une carte de relief, puis demande ce que signale un gradient nul en un point.","tutor_focus_en":"Have the student interpret the gradient on a relief map, then ask what a zero gradient at a point signals.","example_contexts_fr":["une carte de relief parcourue dans le brouillard","un coût dépendant de deux réglages","un point où la pente s'annule dans toutes les directions"],"example_contexts_en":["a relief map walked in fog","a cost depending on two settings","a point where the slope vanishes in every direction"],"safety_category":"standard"},{"key":"mathematics.convexity_optimization","domain_id":"mathematics","objective_ids":["math_technology"],"stage":4,"order":41,"required":false,"prerequisite_keys":["mathematics.gradient_multivariable"],"fallback_key":"mathematics.integral_meaning","title_fr":"Convexité et minimum global","title_en":"Convexity and the global minimum","summary_fr":"Comprendre pourquoi la convexité garantit qu'un minimum local est le minimum global.","summary_en":"Understand why convexity guarantees that a local minimum is the global one.","learning_goals_fr":["Reconnaître une fonction convexe sur un graphique.","Expliquer le risque d'un minimum local dans un cas non convexe."],"learning_goals_en":["Recognise a convex function on a chart.","Explain the risk of a local minimum in a non-convex case."],"tutor_focus_fr":"Fais comparer deux paysages d'optimisation, puis demande dans lequel un algorithme de descente peut rester coincé.","tutor_focus_en":"Have the student compare two optimisation landscapes, then ask in which a descent algorithm can get stuck.","example_contexts_fr":["un paysage à une seule cuvette","un paysage à plusieurs creux de profondeurs inégales","un algorithme relancé depuis plusieurs points de départ"],"example_contexts_en":["a landscape with a single basin","a landscape with several dips of unequal depth","an algorithm restarted from several starting points"],"safety_category":"standard"},{"key":"mathematics.graph_theory_basics","domain_id":"mathematics","objective_ids":["math_technology"],"stage":4,"order":42,"required":false,"prerequisite_keys":["mathematics.convexity_optimization"],"fallback_key":"mathematics.integral_meaning","title_fr":"Graphes : sommets, arêtes et degrés","title_en":"Graphs: vertices, edges and degrees","summary_fr":"Modéliser un réseau par un graphe et lire ses propriétés élémentaires.","summary_en":"Model a network as a graph and read its elementary properties.","learning_goals_fr":["Modéliser une situation concrète par un graphe.","Relier la somme des degrés au nombre d'arêtes."],"learning_goals_en":["Model a concrete situation as a graph.","Relate the sum of degrees to the number of edges."],"tutor_focus_fr":"Fais modéliser un réseau de correspondances par un graphe, puis demande de vérifier la relation entre degrés et arêtes.","tutor_focus_en":"Have the student model a connection network as a graph, then check the relation between degrees and edges.","example_contexts_fr":["un réseau de lignes de bus avec correspondances","des relations d'amitié dans un groupe de dix personnes","des dépendances entre tâches d'un projet"],"example_contexts_en":["a bus line network with interchanges","friendship links in a group of ten people","dependencies between the tasks of a project"],"safety_category":"standard"},{"key":"mathematics.quantifiers_negation","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":5,"order":43,"required":true,"prerequisite_keys":["mathematics.euclidean_algorithm"],"fallback_key":"mathematics.euclidean_algorithm","title_fr":"Quantificateurs et négation d'un énoncé","title_en":"Quantifiers and negating a statement","summary_fr":"Manipuler « pour tout » et « il existe » et écrire correctement la négation d'un énoncé quantifié.","summary_en":"Handle “for all” and “there exists” and correctly write the negation of a quantified statement.","learning_goals_fr":["Écrire la négation d'un énoncé à deux quantificateurs.","Expliquer pourquoi l'ordre des quantificateurs change le sens."],"learning_goals_en":["Write the negation of a statement with two quantifiers.","Explain why quantifier order changes the meaning."],"tutor_focus_fr":"Fais écrire la négation d'un énoncé à deux quantificateurs, puis demande ce que change l'inversion de leur ordre.","tutor_focus_en":"Have the student write the negation of a two-quantifier statement, then ask what swapping their order changes.","example_contexts_fr":["« tout étudiant a un tuteur » et « un tuteur pour tous »","une garantie de service formulée avec « pour tout »","la négation d'une promesse commerciale"],"example_contexts_en":["“every student has a tutor” versus “one tutor for all”","a service guarantee phrased with “for all”","the negation of a commercial promise"],"safety_category":"standard"},{"key":"mathematics.modular_arithmetic","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":5,"order":44,"required":false,"prerequisite_keys":["mathematics.quantifiers_negation"],"fallback_key":"mathematics.euclidean_algorithm","title_fr":"L'arithmétique modulaire","title_en":"Modular arithmetic","summary_fr":"Calculer avec des restes et utiliser la congruence pour raisonner sur des cycles.","summary_en":"Compute with remainders and use congruence to reason about cycles.","learning_goals_fr":["Calculer un reste sans effectuer la division complète.","Résoudre un problème de cycle par congruence."],"learning_goals_en":["Compute a remainder without performing the full division.","Solve a cycle problem using congruence."],"tutor_focus_fr":"Fais calculer le jour de la semaine dans mille jours, puis demande quelle opération modulaire a été utilisée.","tutor_focus_en":"Have the student compute the weekday in a thousand days, then ask which modular operation was used.","example_contexts_fr":["le jour de la semaine dans mille jours","une clé de contrôle sur un numéro de compte","une aiguille d'horloge après cent heures"],"example_contexts_en":["the weekday in a thousand days","a check digit on an account number","a clock hand after a hundred hours"],"safety_category":"standard"},{"key":"mathematics.group_structure","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":5,"order":45,"required":false,"prerequisite_keys":["mathematics.modular_arithmetic"],"fallback_key":"mathematics.euclidean_algorithm","title_fr":"La notion de groupe","title_en":"The idea of a group","summary_fr":"Reconnaître une structure algébrique commune derrière des objets très différents.","summary_en":"Recognise one algebraic structure shared by very different objects.","learning_goals_fr":["Vérifier les axiomes d'un groupe sur un exemple fini.","Citer deux exemples de groupes issus de contextes différents."],"learning_goals_en":["Check the group axioms on a finite example.","Give two group examples from different contexts."],"tutor_focus_fr":"Fais vérifier les axiomes sur les rotations d'un carré, puis demande quel autre exemple partage exactement la même structure.","tutor_focus_en":"Have the student check the axioms on the rotations of a square, then ask which other example shares exactly that structure.","example_contexts_fr":["les rotations qui laissent un carré inchangé","les entiers munis de l'addition","les permutations d'un jeu de trois cartes"],"example_contexts_en":["the rotations leaving a square unchanged","the integers under addition","the permutations of a three-card deck"],"safety_category":"standard"},{"key":"mathematics.comparing_infinities","domain_id":"mathematics","objective_ids":["math_foundations"],"stage":5,"order":46,"required":false,"prerequisite_keys":["mathematics.group_structure"],"fallback_key":"mathematics.euclidean_algorithm","title_fr":"Comparer deux infinis","title_en":"Comparing two infinities","summary_fr":"Utiliser la mise en correspondance pour comparer des ensembles infinis sans les compter.","summary_en":"Use pairing to compare infinite sets without counting them.","learning_goals_fr":["Construire une bijection entre deux ensembles infinis.","Expliquer pourquoi les réels ne se mettent pas en liste."],"learning_goals_en":["Build a bijection between two infinite sets.","Explain why the reals cannot be put in a list."],"tutor_focus_fr":"Fais construire une correspondance entre entiers et entiers pairs, puis demande pourquoi la même méthode échoue pour les réels.","tutor_focus_en":"Have the student build a pairing between integers and even integers, then ask why the same method fails for the reals.","example_contexts_fr":["les entiers pairs mis en face des entiers","un hôtel infini qui accueille un client de plus","une liste censée contenir tous les nombres réels"],"example_contexts_en":["even integers paired with all integers","an infinite hotel welcoming one more guest","a list claiming to hold every real number"],"safety_category":"standard"},{"key":"mathematics.hypothesis_testing","domain_id":"mathematics","objective_ids":["math_probability"],"stage":5,"order":47,"required":true,"prerequisite_keys":["mathematics.confidence_interval"],"fallback_key":"mathematics.confidence_interval","title_fr":"Le test d'hypothèse et la p-valeur","title_en":"Hypothesis testing and the p-value","summary_fr":"Comprendre ce qu'une p-valeur mesure et ce qu'elle ne dit pas de l'hypothèse testée.","summary_en":"Understand what a p-value measures and what it does not say about the tested hypothesis.","learning_goals_fr":["Énoncer correctement ce que mesure une p-valeur.","Expliquer pourquoi multiplier les tests fabrique des découvertes."],"learning_goals_en":["State correctly what a p-value measures.","Explain why running many tests manufactures discoveries."],"tutor_focus_fr":"Fais reformuler ce que signifie une p-valeur de 0,03, puis demande ce qui arrive après vingt tests sur les mêmes données.","tutor_focus_en":"Have the student restate what a p-value of 0.03 means, then ask what happens after twenty tests on the same data.","example_contexts_fr":["un test A/B déclaré gagnant à 0,03","vingt hypothèses testées sur le même jeu de données","un résultat non reproduit par une seconde étude"],"example_contexts_en":["an A/B test declared a winner at 0.03","twenty hypotheses tested on the same dataset","a result not reproduced by a second study"],"safety_category":"standard"},{"key":"mathematics.correlation_causation","domain_id":"mathematics","objective_ids":["math_probability"],"stage":5,"order":48,"required":false,"prerequisite_keys":["mathematics.hypothesis_testing"],"fallback_key":"mathematics.confidence_interval","title_fr":"Corrélation et causalité","title_en":"Correlation and causation","summary_fr":"Distinguer une association statistique d'un lien de cause à effet et repérer une variable cachée.","summary_en":"Tell a statistical association apart from a causal link and spot a hidden variable.","learning_goals_fr":["Proposer une variable de confusion pour une corrélation donnée.","Dire ce qu'une expérience randomisée apporte de plus."],"learning_goals_en":["Propose a confounding variable for a given correlation.","Say what a randomised experiment adds."],"tutor_focus_fr":"Fais proposer une variable cachée expliquant une corrélation surprenante, puis demande quelle expérience trancherait.","tutor_focus_en":"Have the student propose a hidden variable explaining a surprising correlation, then ask which experiment would settle it.","example_contexts_fr":["ventes de glaces et noyades corrélées en été","des utilisateurs d'une fonctionnalité plus fidèles que les autres","un médicament testé sans groupe témoin"],"example_contexts_en":["ice cream sales and drownings correlated in summer","users of a feature more loyal than others","a drug tested without a control group"],"safety_category":"standard"},{"key":"mathematics.regression_to_the_mean","domain_id":"mathematics","objective_ids":["math_probability"],"stage":5,"order":49,"required":false,"prerequisite_keys":["mathematics.correlation_causation"],"fallback_key":"mathematics.confidence_interval","title_fr":"La régression vers la moyenne","title_en":"Regression to the mean","summary_fr":"Expliquer pourquoi une performance extrême est naturellement suivie d'une performance plus ordinaire.","summary_en":"Explain why an extreme performance is naturally followed by a more ordinary one.","learning_goals_fr":["Reconnaître une régression vers la moyenne dans une évaluation.","Expliquer pourquoi elle fait surestimer l'effet d'une intervention."],"learning_goals_en":["Recognise regression to the mean in an evaluation.","Explain why it inflates the apparent effect of an intervention."],"tutor_focus_fr":"Fais analyser une formation suivie par les moins performants, puis demande quelle part du progrès aurait eu lieu sans elle.","tutor_focus_en":"Have the student analyse a training given to the weakest performers, then ask how much progress would have happened anyway.","example_contexts_fr":["une formation réservée aux plus faibles d'une promotion","un traitement commencé au pire moment d'une douleur","une équipe brillante une saison puis moyenne la suivante"],"example_contexts_en":["a training reserved for the weakest of a cohort","a treatment started at the worst moment of a pain","a team brilliant one season and average the next"],"safety_category":"standard"},{"key":"mathematics.markov_chains","domain_id":"mathematics","objective_ids":["math_probability"],"stage":5,"order":50,"required":false,"prerequisite_keys":["mathematics.regression_to_the_mean"],"fallback_key":"mathematics.confidence_interval","title_fr":"Les chaînes de Markov","title_en":"Markov chains","summary_fr":"Modéliser un système par des états et des probabilités de transition sans mémoire du passé.","summary_en":"Model a system with states and transition probabilities that ignore the past.","learning_goals_fr":["Écrire une matrice de transition à trois états.","Expliquer ce que l'absence de mémoire simplifie et ce qu'elle perd."],"learning_goals_en":["Write a three-state transition matrix.","Explain what memorylessness simplifies and what it loses."],"tutor_focus_fr":"Fais écrire une matrice de transition à trois états, puis demande ce que le modèle ignore volontairement du passé.","tutor_focus_en":"Have the student write a three-state transition matrix, then ask what the model deliberately ignores about the past.","example_contexts_fr":["un client qui passe d'actif à inactif puis revient","la météo modélisée par trois états quotidiens","un utilisateur naviguant entre trois pages d'un site"],"example_contexts_en":["a customer moving from active to inactive and back","weather modelled by three daily states","a user navigating between three pages of a site"],"safety_category":"standard"},{"key":"mathematics.linear_independence_rank","domain_id":"mathematics","objective_ids":["math_technology"],"stage":5,"order":51,"required":true,"prerequisite_keys":["mathematics.graph_theory_basics"],"fallback_key":"mathematics.graph_theory_basics","title_fr":"Indépendance linéaire et rang","title_en":"Linear independence and rank","summary_fr":"Détecter l'information redondante dans un ensemble de vecteurs ou de colonnes de données.","summary_en":"Detect redundant information in a set of vectors or data columns.","learning_goals_fr":["Décider si trois vecteurs sont linéairement indépendants.","Relier un rang déficient à une colonne redondante."],"learning_goals_en":["Decide whether three vectors are linearly independent.","Link a deficient rank to a redundant column."],"tutor_focus_fr":"Fais repérer la colonne redondante d'un petit tableau de données, puis demande ce que cela implique pour un modèle linéaire.","tutor_focus_en":"Have the student spot the redundant column of a small data table, then ask what it implies for a linear model.","example_contexts_fr":["un tableau contenant à la fois un prix hors taxe et un prix TTC","trois capteurs dont l'un mesure la somme des deux autres","un système d'équations sans solution unique"],"example_contexts_en":["a table holding both a pre-tax and an all-tax price","three sensors where one measures the sum of the other two","a system of equations without a unique solution"],"safety_category":"standard"},{"key":"mathematics.combinatorial_explosion","domain_id":"mathematics","objective_ids":["math_technology"],"stage":5,"order":52,"required":false,"prerequisite_keys":["mathematics.linear_independence_rank"],"fallback_key":"mathematics.graph_theory_basics","title_fr":"L'explosion combinatoire","title_en":"Combinatorial explosion","summary_fr":"Estimer le nombre de possibilités d'un problème pour savoir si l'énumération est envisageable.","summary_en":"Estimate the number of possibilities of a problem to know whether enumeration is feasible.","learning_goals_fr":["Estimer le nombre de configurations d'un problème donné.","Décider si une recherche exhaustive est réaliste."],"learning_goals_en":["Estimate the number of configurations of a given problem.","Decide whether exhaustive search is realistic."],"tutor_focus_fr":"Fais estimer le nombre de tournées possibles pour quinze villes, puis demande si une machine rapide y changerait quelque chose.","tutor_focus_en":"Have the student estimate the number of routes for fifteen cities, then ask whether a faster machine would change anything.","example_contexts_fr":["une tournée de livraison passant par quinze villes","un emploi du temps à contraintes multiples","un mot de passe testé par force brute"],"example_contexts_en":["a delivery route through fifteen cities","a timetable with multiple constraints","a password tested by brute force"],"safety_category":"standard"},{"key":"mathematics.frequency_decomposition","domain_id":"mathematics","objective_ids":["math_technology"],"stage":5,"order":53,"required":false,"prerequisite_keys":["mathematics.combinatorial_explosion"],"fallback_key":"mathematics.graph_theory_basics","title_fr":"La décomposition en fréquences","title_en":"Frequency decomposition","summary_fr":"Comprendre qu'un signal se décompose en composantes simples et ce que cela permet de faire.","summary_en":"Understand that a signal decomposes into simple components and what that enables.","learning_goals_fr":["Expliquer ce qu'une décomposition en fréquences révèle d'un signal.","Citer un traitement rendu possible par ce changement de point de vue."],"learning_goals_en":["Explain what a frequency decomposition reveals about a signal.","Name a processing step made possible by that change of viewpoint."],"tutor_focus_fr":"Fais expliquer comment isoler un bourdonnement dans un enregistrement, puis demande ce que la décomposition permet ensuite.","tutor_focus_en":"Have the student explain how to isolate a hum in a recording, then ask what the decomposition then allows.","example_contexts_fr":["un bourdonnement de 50 hertz dans un enregistrement","une image compressée en supprimant des détails fins","un accord de musique décomposé en notes"],"example_contexts_en":["a 50 hertz hum in a recording","an image compressed by dropping fine detail","a musical chord decomposed into notes"],"safety_category":"standard"},{"key":"mathematics.numerical_precision","domain_id":"mathematics","objective_ids":["math_technology"],"stage":5,"order":54,"required":false,"prerequisite_keys":["mathematics.frequency_decomposition"],"fallback_key":"mathematics.graph_theory_basics","title_fr":"Erreurs d'arrondi en calcul numérique","title_en":"Rounding errors in numerical computation","summary_fr":"Comprendre pourquoi un calcul mathématiquement correct peut donner un résultat faux sur machine.","summary_en":"Understand why a mathematically correct computation can give a wrong result on a machine.","learning_goals_fr":["Expliquer pourquoi 0,1 additionné trois fois ne donne pas exactement 0,3.","Citer une opération à éviter pour limiter la perte de précision."],"learning_goals_en":["Explain why adding 0.1 three times does not give exactly 0.3.","Name an operation to avoid in order to limit precision loss."],"tutor_focus_fr":"Fais expliquer le résultat surprenant d'une somme de décimaux, puis demande quelle réécriture limiterait l'erreur.","tutor_focus_en":"Have the student explain the surprising result of a decimal sum, then ask which rewriting would limit the error.","example_contexts_fr":["un total de facture faux d'un centime","une soustraction de deux nombres très proches","une somme de millions de petites valeurs"],"example_contexts_en":["an invoice total wrong by one cent","a subtraction of two very close numbers","a sum of millions of small values"],"safety_category":"standard"}]}$catalog$::jsonb)
ON CONFLICT (domain_id) DO UPDATE
SET version = EXCLUDED.version, payload = EXCLUDED.payload, updated_at = now();

INSERT INTO public.learning_catalog_domains (domain_id, version, payload)
VALUES ($catalog$quantum_physics$catalog$, $catalog$v1$catalog$, $catalog${"version":"v1","steps":[{"key":"quantum_physics.quantum_scale","domain_id":"quantum_physics","objective_ids":["quantum_intuition","quantum_mathematics","quantum_computing"],"stage":1,"order":1,"required":true,"prerequisite_keys":[],"fallback_key":null,"title_fr":"À quelle échelle les effets quantiques apparaissent","title_en":"At which scale quantum effects appear","summary_fr":"Situer les tailles et les énergies où la description classique cesse de suffire.","summary_en":"Place the sizes and energies where the classical description stops being enough.","learning_goals_fr":["Comparer la taille d'un atome et celle d'un grain de poussière.","Dire pourquoi un ballon ne montre pas d'effets quantiques."],"learning_goals_en":["Compare the size of an atom with that of a dust grain.","Say why a ball shows no quantum effects."],"tutor_focus_fr":"Fais comparer trois échelles de taille, puis demande pourquoi une balle de tennis ne traverse jamais un mur alors qu'un électron peut le faire.","tutor_focus_en":"Have the student compare three size scales, then ask why a tennis ball never crosses a wall while an electron can.","example_contexts_fr":["un électron dans un atome de silicium","une balle de tennis lancée contre un mur","une molécule d'eau dans un verre"],"example_contexts_en":["an electron inside a silicon atom","a tennis ball thrown at a wall","a water molecule in a glass"],"safety_category":"standard"},{"key":"quantum_physics.wave_particle_duality","domain_id":"quantum_physics","objective_ids":["quantum_intuition","quantum_mathematics","quantum_computing"],"stage":1,"order":2,"required":true,"prerequisite_keys":["quantum_physics.quantum_scale"],"fallback_key":null,"title_fr":"La dualité onde-corpuscule dans l'expérience des fentes","title_en":"Wave-particle duality in the double-slit experiment","summary_fr":"Comprendre pourquoi des particules envoyées une par une dessinent quand même des franges.","summary_en":"Understand why particles sent one at a time still build an interference pattern.","learning_goals_fr":["Décrire la figure obtenue avec une fente puis avec deux fentes.","Dire ce que devient la figure quand on détecte le passage."],"learning_goals_en":["Describe the pattern obtained with one slit then with two.","Say what the pattern becomes when the passage is detected."],"tutor_focus_fr":"Fais décrire la figure obtenue en envoyant les électrons un par un, puis demande ce qui change dès qu'un détecteur observe les fentes.","tutor_focus_en":"Have the student describe the pattern built by electrons sent one by one, then ask what changes as soon as a detector watches the slits.","example_contexts_fr":["des électrons envoyés un par un vers deux fentes","un faisceau lumineux traversant une fine ouverture","un détecteur placé devant l'une des deux fentes"],"example_contexts_en":["electrons sent one at a time toward two slits","a light beam crossing a narrow opening","a detector placed in front of one of the two slits"],"safety_category":"standard"},{"key":"quantum_physics.energy_quantization","domain_id":"quantum_physics","objective_ids":["quantum_intuition","quantum_mathematics","quantum_computing"],"stage":1,"order":3,"required":true,"prerequisite_keys":["quantum_physics.wave_particle_duality"],"fallback_key":null,"title_fr":"Pourquoi l'énergie vient par paquets","title_en":"Why energy comes in packets","summary_fr":"Comprendre que certains systèmes n'acceptent que des valeurs d'énergie discrètes.","summary_en":"Understand that some systems only accept discrete energy values.","learning_goals_fr":["Citer un système dont les niveaux d'énergie sont discrets.","Expliquer pourquoi une lampe à sodium émet une couleur précise."],"learning_goals_en":["Name a system whose energy levels are discrete.","Explain why a sodium lamp emits one precise colour."],"tutor_focus_fr":"Fais expliquer pourquoi un atome n'absorbe que certaines couleurs, puis demande ce que cela implique pour la lumière transmise.","tutor_focus_en":"Have the student explain why an atom only absorbs certain colours, then ask what that implies for the transmitted light.","example_contexts_fr":["la lumière orange d'un lampadaire au sodium","un atome qui absorbe une couleur précise","une corde de guitare et ses harmoniques"],"example_contexts_en":["the orange light of a sodium street lamp","an atom absorbing one precise colour","a guitar string and its harmonics"],"safety_category":"standard"},{"key":"quantum_physics.measurement_disturbance","domain_id":"quantum_physics","objective_ids":["quantum_intuition","quantum_mathematics","quantum_computing"],"stage":1,"order":4,"required":true,"prerequisite_keys":["quantum_physics.energy_quantization"],"fallback_key":null,"title_fr":"Pourquoi mesurer change le système","title_en":"Why measuring changes the system","summary_fr":"Distinguer la perturbation ordinaire d'une mesure du rôle particulier de la mesure quantique.","summary_en":"Separate the ordinary disturbance of a measurement from the specific role of quantum measurement.","learning_goals_fr":["Distinguer une mesure classique perturbante d'une mesure quantique.","Dire ce qui reste vrai d'un système juste après sa mesure."],"learning_goals_en":["Tell apart a disturbing classical measurement and a quantum one.","Say what remains true of a system right after measurement."],"tutor_focus_fr":"Fais comparer la mesure d'une pression de pneu et la mesure d'une polarisation de photon, puis demande ce qui diffère fondamentalement.","tutor_focus_en":"Have the student compare measuring a tyre pressure and measuring a photon polarisation, then ask what differs fundamentally.","example_contexts_fr":["un manomètre qui laisse échapper un peu d'air","un photon dont on mesure la polarisation","deux mesures successives sur le même système"],"example_contexts_en":["a pressure gauge letting a little air escape","a photon whose polarisation is measured","two successive measurements on the same system"],"safety_category":"standard"},{"key":"quantum_physics.quantum_probability","domain_id":"quantum_physics","objective_ids":["quantum_intuition","quantum_mathematics","quantum_computing"],"stage":1,"order":5,"required":true,"prerequisite_keys":["quantum_physics.measurement_disturbance"],"fallback_key":null,"title_fr":"Une probabilité qui n'est pas de l'ignorance","title_en":"A probability that is not ignorance","summary_fr":"Comparer le hasard d'un dé caché et le hasard quantique qui ne cache aucune valeur préexistante.","summary_en":"Compare the randomness of a hidden die with quantum randomness, which hides no pre-existing value.","learning_goals_fr":["Distinguer une probabilité d'ignorance d'une probabilité fondamentale.","Expliquer ce qu'une variable cachée devrait garantir."],"learning_goals_en":["Tell apart a probability of ignorance and a fundamental probability.","Explain what a hidden variable would have to guarantee."],"tutor_focus_fr":"Fais comparer un dé sous un gobelet et un photon avant mesure, puis demande ce qu'il faudrait pour que les deux situations soient identiques.","tutor_focus_en":"Have the student compare a die under a cup and a photon before measurement, then ask what would make the two situations identical.","example_contexts_fr":["un dé lancé sous un gobelet","un photon avant la mesure de sa polarisation","une pièce en train de tourner sur une table"],"example_contexts_en":["a die rolled under a cup","a photon before its polarisation is measured","a coin still spinning on a table"],"safety_category":"standard"},{"key":"quantum_physics.photoelectric_effect","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":1,"order":6,"required":true,"prerequisite_keys":["quantum_physics.quantum_probability"],"fallback_key":null,"title_fr":"Le photon et l'effet photoélectrique","title_en":"The photon and the photoelectric effect","summary_fr":"Comprendre pourquoi l'énergie arrachée dépend de la couleur et non de l'intensité lumineuse.","summary_en":"Understand why the extracted energy depends on colour rather than on light intensity.","learning_goals_fr":["Expliquer le rôle du seuil de fréquence.","Dire ce que change une lumière plus intense au-dessus du seuil."],"learning_goals_en":["Explain the role of the frequency threshold.","Say what stronger light changes above the threshold."],"tutor_focus_fr":"Fais prédire l'effet d'une lampe rouge très puissante puis d'une lampe bleue faible sur une plaque métallique, et demande d'expliquer l'écart.","tutor_focus_en":"Have the student predict the effect of a very strong red lamp then a weak blue lamp on a metal plate, and explain the gap.","example_contexts_fr":["une plaque métallique éclairée en rouge puis en bleu","une cellule photovoltaïque au soleil","un capteur d'appareil photo en faible lumière"],"example_contexts_en":["a metal plate lit in red then in blue","a photovoltaic cell in sunlight","a camera sensor in low light"],"safety_category":"standard"},{"key":"quantum_physics.state_as_vector","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":1,"order":7,"required":true,"prerequisite_keys":["quantum_physics.quantum_probability"],"fallback_key":null,"title_fr":"Un état représenté par un vecteur","title_en":"A state represented by a vector","summary_fr":"Représenter un système à deux issues par un vecteur de norme un dans un plan.","summary_en":"Represent a two-outcome system by a unit-norm vector in a plane.","learning_goals_fr":["Écrire un état à deux composantes et vérifier sa normalisation.","Dire ce que représente chaque composante."],"learning_goals_en":["Write a two-component state and check its normalisation.","Say what each component represents."],"tutor_focus_fr":"Fais écrire l'état d'un système à deux issues avec des composantes égales, puis demande pourquoi la somme des carrés doit valoir un.","tutor_focus_en":"Have the student write a two-outcome state with equal components, then ask why the squares must sum to one.","example_contexts_fr":["un système à deux issues équiprobables","un vecteur de norme un dessiné dans un plan","un état déséquilibré à 80 % et 20 %"],"example_contexts_en":["a two-outcome system with equal chances","a unit vector drawn in a plane","an unbalanced state at 80% and 20%"],"safety_category":"standard"},{"key":"quantum_physics.qubit_vs_bit","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":1,"order":8,"required":true,"prerequisite_keys":["quantum_physics.quantum_probability"],"fallback_key":null,"title_fr":"Ce qu'un qubit ajoute à un bit","title_en":"What a qubit adds to a bit","summary_fr":"Comparer un bit classique et un qubit sur ce qu'on peut préparer et sur ce qu'on peut lire.","summary_en":"Compare a classical bit and a qubit on what can be prepared and on what can be read.","learning_goals_fr":["Dire combien d'information une mesure de qubit fournit.","Expliquer pourquoi « un qubit vaut deux valeurs » est trompeur."],"learning_goals_en":["Say how much information a qubit measurement yields.","Explain why “a qubit holds two values” is misleading."],"tutor_focus_fr":"Fais comparer ce qu'un bit et un qubit permettent de préparer puis de lire, et demande pourquoi la lecture ne donne qu'un seul résultat.","tutor_focus_en":"Have the student compare what a bit and a qubit allow preparing then reading, and ask why the readout gives a single result.","example_contexts_fr":["un bit classique valant zéro ou un","une mesure de qubit qui renvoie un seul bit","un registre de dix qubits préparé en superposition"],"example_contexts_en":["a classical bit holding zero or one","a qubit measurement returning a single bit","a ten-qubit register prepared in superposition"],"safety_category":"standard"},{"key":"quantum_physics.superposition_meaning","domain_id":"quantum_physics","objective_ids":["quantum_intuition","quantum_mathematics","quantum_computing"],"stage":2,"order":9,"required":true,"prerequisite_keys":["quantum_physics.quantum_probability"],"fallback_key":"quantum_physics.quantum_probability","title_fr":"Ce que signifie une superposition","title_en":"What a superposition means","summary_fr":"Comprendre qu'une superposition n'est pas une hésitation mais un état à part entière.","summary_en":"Understand that a superposition is not hesitation but a state in its own right.","learning_goals_fr":["Expliquer pourquoi « à la fois ici et là » est une formulation trompeuse.","Dire ce qu'une superposition permet d'observer d'inaccessible autrement."],"learning_goals_en":["Explain why “both here and there” is a misleading phrasing.","Say what a superposition lets you observe that is otherwise inaccessible."],"tutor_focus_fr":"Fais critiquer la formule « la particule est aux deux endroits », puis demande quelle observation distingue une superposition d'un mélange.","tutor_focus_en":"Have the student critique the phrase “the particle is in both places”, then ask which observation separates a superposition from a mixture.","example_contexts_fr":["un photon polarisé à 45 degrés","un atome soumis à une impulsion laser calibrée","un mélange statistique de deux états bien définis"],"example_contexts_en":["a photon polarised at 45 degrees","an atom driven by a calibrated laser pulse","a statistical mixture of two well-defined states"],"safety_category":"standard"},{"key":"quantum_physics.uncertainty_principle","domain_id":"quantum_physics","objective_ids":["quantum_intuition","quantum_mathematics","quantum_computing"],"stage":2,"order":10,"required":true,"prerequisite_keys":["quantum_physics.superposition_meaning"],"fallback_key":"quantum_physics.quantum_probability","title_fr":"Le principe d'indétermination","title_en":"The uncertainty principle","summary_fr":"Comprendre que certaines grandeurs ne peuvent pas être définies simultanément avec précision.","summary_en":"Understand that some quantities cannot be simultaneously defined with precision.","learning_goals_fr":["Citer une paire de grandeurs incompatibles.","Expliquer pourquoi ce n'est pas un défaut d'instrument."],"learning_goals_en":["Name a pair of incompatible quantities.","Explain why this is not an instrument defect."],"tutor_focus_fr":"Fais expliquer pourquoi resserrer la position élargit l'impulsion, puis demande pourquoi un meilleur appareil ne résoudrait pas le problème.","tutor_focus_en":"Have the student explain why narrowing position widens momentum, then ask why a better device would not solve it.","example_contexts_fr":["un électron confiné dans une région très étroite","une impulsion laser très brève et sa couleur","un microscope de résolution parfaite imaginé en pensée"],"example_contexts_en":["an electron confined in a very narrow region","a very short laser pulse and its colour","a perfectly resolving microscope imagined in thought"],"safety_category":"standard"},{"key":"quantum_physics.decoherence","domain_id":"quantum_physics","objective_ids":["quantum_intuition","quantum_mathematics","quantum_computing"],"stage":2,"order":11,"required":true,"prerequisite_keys":["quantum_physics.uncertainty_principle"],"fallback_key":"quantum_physics.quantum_probability","title_fr":"La décohérence : pourquoi le monde paraît classique","title_en":"Decoherence: why the world looks classical","summary_fr":"Relier l'interaction avec l'environnement à la disparition rapide des effets d'interférence.","summary_en":"Connect interaction with the environment to the fast disappearance of interference effects.","learning_goals_fr":["Expliquer le rôle de l'environnement dans la perte de cohérence.","Dire pourquoi les objets macroscopiques décohèrent quasi instantanément."],"learning_goals_en":["Explain the role of the environment in the loss of coherence.","Say why macroscopic objects decohere almost instantly."],"tutor_focus_fr":"Fais estimer ce qui perturbe un état fragile dans une pièce ordinaire, puis demande pourquoi un objet visible ne montre jamais d'interférences.","tutor_focus_en":"Have the student estimate what disturbs a fragile state in an ordinary room, then ask why a visible object never shows interference.","example_contexts_fr":["un qubit perturbé par une vibration thermique","un objet visible bombardé de photons ambiants","une expérience refroidie près du zéro absolu"],"example_contexts_en":["a qubit disturbed by thermal vibration","a visible object bombarded by ambient photons","an experiment cooled near absolute zero"],"safety_category":"standard"},{"key":"quantum_physics.quantum_technology_today","domain_id":"quantum_physics","objective_ids":["quantum_intuition","quantum_mathematics","quantum_computing"],"stage":2,"order":12,"required":true,"prerequisite_keys":["quantum_physics.decoherence"],"fallback_key":"quantum_physics.quantum_probability","title_fr":"Ce que la physique quantique fait déjà fonctionner","title_en":"What quantum physics already makes work","summary_fr":"Repérer les technologies courantes qui reposent déjà sur des effets quantiques établis.","summary_en":"Identify everyday technologies that already rely on established quantum effects.","learning_goals_fr":["Citer trois technologies existantes fondées sur la mécanique quantique.","Distinguer ces technologies d'un ordinateur quantique."],"learning_goals_en":["Name three existing technologies grounded in quantum mechanics.","Tell these technologies apart from a quantum computer."],"tutor_focus_fr":"Fais expliquer quel effet quantique rend un transistor possible, puis demande en quoi cela diffère d'un ordinateur quantique.","tutor_focus_en":"Have the student explain which quantum effect makes a transistor possible, then ask how that differs from a quantum computer.","example_contexts_fr":["un transistor dans un processeur de téléphone","une imagerie par résonance magnétique à l'hôpital","un lecteur optique équipé d'une diode laser"],"example_contexts_en":["a transistor inside a phone processor","magnetic resonance imaging in a hospital","an optical reader fitted with a laser diode"],"safety_category":"standard"},{"key":"quantum_physics.atomic_orbitals","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":2,"order":13,"required":true,"prerequisite_keys":["quantum_physics.quantum_technology_today"],"fallback_key":"quantum_physics.photoelectric_effect","title_fr":"Les orbitales : pourquoi l'électron n'est pas une bille en orbite","title_en":"Orbitals: why the electron is not a ball in orbit","summary_fr":"Remplacer l'image planétaire par une distribution de probabilité de présence.","summary_en":"Replace the planetary picture with a probability distribution of presence.","learning_goals_fr":["Décrire ce que représente le nuage d'une orbitale.","Expliquer pourquoi l'électron ne s'écrase pas sur le noyau."],"learning_goals_en":["Describe what an orbital cloud represents.","Explain why the electron does not fall onto the nucleus."],"tutor_focus_fr":"Fais critiquer le schéma planétaire de l'atome, puis demande ce que représente exactement la zone dessinée autour du noyau.","tutor_focus_en":"Have the student critique the planetary picture of the atom, then ask what the drawn region around the nucleus actually represents.","example_contexts_fr":["le schéma planétaire d'un manuel scolaire","la forme allongée d'une orbitale p","une liaison chimique entre deux atomes"],"example_contexts_en":["the planetary diagram in a school textbook","the elongated shape of a p orbital","a chemical bond between two atoms"],"safety_category":"standard"},{"key":"quantum_physics.spectral_lines","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":2,"order":14,"required":false,"prerequisite_keys":["quantum_physics.atomic_orbitals"],"fallback_key":"quantum_physics.photoelectric_effect","title_fr":"Les raies spectrales","title_en":"Spectral lines","summary_fr":"Relier les couleurs émises par un gaz aux écarts entre ses niveaux d'énergie.","summary_en":"Connect the colours emitted by a gas to the gaps between its energy levels.","learning_goals_fr":["Expliquer l'origine d'une raie d'émission.","Dire ce qu'un spectre permet d'identifier à distance."],"learning_goals_en":["Explain where an emission line comes from.","Say what a spectrum lets you identify from far away."],"tutor_focus_fr":"Fais expliquer pourquoi chaque élément produit une signature de raies, puis demande comment on identifie un gaz dans une étoile.","tutor_focus_en":"Have the student explain why each element produces a line signature, then ask how a gas is identified inside a star.","example_contexts_fr":["la lumière d'une étoile analysée par un télescope","un tube à néon dans une enseigne","une flamme colorée par un sel métallique"],"example_contexts_en":["starlight analysed through a telescope","a neon tube in a shop sign","a flame coloured by a metallic salt"],"safety_category":"standard"},{"key":"quantum_physics.complex_amplitudes","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":2,"order":15,"required":true,"prerequisite_keys":["quantum_physics.quantum_technology_today"],"fallback_key":"quantum_physics.state_as_vector","title_fr":"Amplitudes complexes et probabilités","title_en":"Complex amplitudes and probabilities","summary_fr":"Comprendre pourquoi la phase d'une amplitude ne se voit pas sur une probabilité mais gouverne les interférences.","summary_en":"Understand why the phase of an amplitude is invisible in a probability yet governs interference.","learning_goals_fr":["Calculer une probabilité à partir d'une amplitude complexe.","Montrer que deux amplitudes peuvent s'annuler."],"learning_goals_en":["Compute a probability from a complex amplitude.","Show that two amplitudes can cancel out."],"tutor_focus_fr":"Fais additionner deux amplitudes de phases opposées, puis demande pourquoi la probabilité obtenue n'est pas la somme des probabilités.","tutor_focus_en":"Have the student add two amplitudes with opposite phases, then ask why the resulting probability is not the sum of probabilities.","example_contexts_fr":["deux chemins possibles menant au même détecteur","deux amplitudes de signes opposés","une figure d'interférence avec des zones sombres"],"example_contexts_en":["two possible paths reaching the same detector","two amplitudes with opposite signs","an interference pattern with dark regions"],"safety_category":"standard"},{"key":"quantum_physics.dirac_notation","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":2,"order":16,"required":false,"prerequisite_keys":["quantum_physics.complex_amplitudes"],"fallback_key":"quantum_physics.state_as_vector","title_fr":"La notation de Dirac","title_en":"Dirac notation","summary_fr":"Lire les notations de vecteurs et de produits scalaires utilisées dans toute la littérature quantique.","summary_en":"Read the vector and inner-product notation used throughout the quantum literature.","learning_goals_fr":["Traduire une expression en notation de Dirac en langage vectoriel.","Interpréter un produit scalaire entre deux états."],"learning_goals_en":["Translate a Dirac expression into vector language.","Interpret an inner product between two states."],"tutor_focus_fr":"Fais traduire deux expressions en notation de Dirac vers des vecteurs et un produit scalaire, puis demande ce que vaut ce produit pour deux états orthogonaux.","tutor_focus_en":"Have the student translate two Dirac expressions into vectors and an inner product, then ask its value for two orthogonal states.","example_contexts_fr":["une formule lue dans un article de recherche","un produit scalaire entre deux états orthogonaux","un état écrit comme somme de deux états de base"],"example_contexts_en":["a formula read in a research paper","an inner product between two orthogonal states","a state written as a sum of two basis states"],"safety_category":"standard"},{"key":"quantum_physics.bloch_sphere","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":2,"order":17,"required":true,"prerequisite_keys":["quantum_physics.quantum_technology_today"],"fallback_key":"quantum_physics.qubit_vs_bit","title_fr":"La sphère de Bloch","title_en":"The Bloch sphere","summary_fr":"Représenter l'état d'un qubit comme un point sur une sphère et lire l'effet d'une opération.","summary_en":"Represent a qubit state as a point on a sphere and read the effect of an operation.","learning_goals_fr":["Placer trois états de base sur la sphère.","Décrire l'effet d'une porte comme une rotation."],"learning_goals_en":["Place three basis states on the sphere.","Describe a gate's effect as a rotation."],"tutor_focus_fr":"Fais placer trois états sur la sphère, puis demande quelle rotation transforme le premier en le deuxième.","tutor_focus_en":"Have the student place three states on the sphere, then ask which rotation turns the first into the second.","example_contexts_fr":["un état placé au pôle nord de la sphère","une rotation d'un quart de tour autour d'un axe","deux états diamétralement opposés"],"example_contexts_en":["a state at the north pole of the sphere","a quarter-turn rotation about one axis","two diametrically opposite states"],"safety_category":"standard"},{"key":"quantum_physics.quantum_gates","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":2,"order":18,"required":false,"prerequisite_keys":["quantum_physics.bloch_sphere"],"fallback_key":"quantum_physics.qubit_vs_bit","title_fr":"Les portes quantiques élémentaires","title_en":"Elementary quantum gates","summary_fr":"Appliquer les portes de base et vérifier qu'une opération quantique est réversible.","summary_en":"Apply the basic gates and check that a quantum operation is reversible.","learning_goals_fr":["Décrire l'effet des portes X et H sur un état de base.","Expliquer pourquoi une porte quantique est toujours réversible."],"learning_goals_en":["Describe the effect of the X and H gates on a basis state.","Explain why a quantum gate is always reversible."],"tutor_focus_fr":"Fais appliquer deux portes successives à un état de base, puis demande quelle porte annule la transformation obtenue.","tutor_focus_en":"Have the student apply two gates in a row to a basis state, then ask which gate undoes the resulting transformation.","example_contexts_fr":["une porte qui échange zéro et un","une porte qui crée une superposition égale","deux portes identiques appliquées à la suite"],"example_contexts_en":["a gate swapping zero and one","a gate creating an equal superposition","two identical gates applied in a row"],"safety_category":"standard"},{"key":"quantum_physics.entanglement_intuition","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":3,"order":19,"required":true,"prerequisite_keys":["quantum_physics.spectral_lines"],"fallback_key":"quantum_physics.spectral_lines","title_fr":"L'intrication expliquée sans formalisme","title_en":"Entanglement explained without formalism","summary_fr":"Comprendre une corrélation parfaite entre deux systèmes qui ne transmet pourtant aucun message.","summary_en":"Understand a perfect correlation between two systems that still carries no message.","learning_goals_fr":["Décrire la corrélation observée entre deux mesures distantes.","Expliquer pourquoi cela ne permet pas de communiquer plus vite que la lumière."],"learning_goals_en":["Describe the correlation observed between two distant measurements.","Explain why it does not allow faster-than-light communication."],"tutor_focus_fr":"Fais décrire les résultats de deux mesures distantes sur une paire intriquée, puis demande pourquoi aucun message n'est transmis.","tutor_focus_en":"Have the student describe the outcomes of two distant measurements on an entangled pair, then ask why no message is transmitted.","example_contexts_fr":["deux photons produits ensemble puis séparés","deux expérimentateurs séparés par un continent","une paire de gants séparés dans deux valises"],"example_contexts_en":["two photons produced together then separated","two experimenters a continent apart","a pair of gloves split into two suitcases"],"safety_category":"standard"},{"key":"quantum_physics.bell_experiment","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":3,"order":20,"required":false,"prerequisite_keys":["quantum_physics.entanglement_intuition"],"fallback_key":"quantum_physics.spectral_lines","title_fr":"Ce que montre l'expérience de Bell","title_en":"What Bell's experiment shows","summary_fr":"Comprendre pourquoi les corrélations mesurées excluent une explication par variables cachées locales.","summary_en":"Understand why the measured correlations rule out a local hidden-variable explanation.","learning_goals_fr":["Expliquer ce qu'une inégalité de Bell teste réellement.","Dire ce que la violation observée élimine comme explication."],"learning_goals_en":["Explain what a Bell inequality actually tests.","Say which explanation the observed violation eliminates."],"tutor_focus_fr":"Fais expliquer ce qu'une explication classique prédit et ce que l'expérience mesure, puis demande quelle hypothèse doit être abandonnée.","tutor_focus_en":"Have the student state what a classical explanation predicts and what the experiment measures, then ask which assumption must be dropped.","example_contexts_fr":["deux détecteurs orientés indépendamment","une explication par instructions cachées à la création","des mesures répétées des milliers de fois"],"example_contexts_en":["two detectors oriented independently","an explanation by hidden instructions set at creation","measurements repeated thousands of times"],"safety_category":"standard"},{"key":"quantum_physics.quantum_tunneling","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":3,"order":21,"required":false,"prerequisite_keys":["quantum_physics.bell_experiment"],"fallback_key":"quantum_physics.spectral_lines","title_fr":"L'effet tunnel","title_en":"Quantum tunnelling","summary_fr":"Comprendre le franchissement d'une barrière d'énergie interdite à un objet classique.","summary_en":"Understand the crossing of an energy barrier forbidden to a classical object.","learning_goals_fr":["Expliquer comment la probabilité de passage dépend de l'épaisseur de la barrière.","Citer une technologie qui exploite directement cet effet."],"learning_goals_en":["Explain how the crossing probability depends on barrier thickness.","Name a technology that directly exploits this effect."],"tutor_focus_fr":"Fais estimer l'effet d'une barrière deux fois plus épaisse sur la probabilité de passage, puis demande où cet effet est utilisé en pratique.","tutor_focus_en":"Have the student estimate the effect of doubling barrier thickness on the crossing probability, then ask where the effect is used in practice.","example_contexts_fr":["un microscope à effet tunnel qui image des atomes","la fusion nucléaire au cœur du Soleil","une mémoire flash dont la charge finit par fuir"],"example_contexts_en":["a scanning tunnelling microscope imaging atoms","nuclear fusion in the core of the Sun","a flash memory whose charge eventually leaks"],"safety_category":"standard"},{"key":"quantum_physics.quantum_spin","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":3,"order":22,"required":false,"prerequisite_keys":["quantum_physics.quantum_tunneling"],"fallback_key":"quantum_physics.spectral_lines","title_fr":"Le spin, une grandeur sans équivalent classique","title_en":"Spin, a quantity with no classical counterpart","summary_fr":"Comprendre une grandeur sans équivalent classique qui ne prend que deux valeurs à la mesure.","summary_en":"Understand a quantity with no classical counterpart that only takes two values on measurement.","learning_goals_fr":["Dire pourquoi l'image d'une toupie est trompeuse.","Décrire le résultat d'une mesure de spin selon un axe."],"learning_goals_en":["Say why the spinning-top picture misleads.","Describe the result of a spin measurement along one axis."],"tutor_focus_fr":"Fais décrire le résultat d'une mesure de spin selon un axe puis selon un axe perpendiculaire, et demande ce que la seconde mesure détruit.","tutor_focus_en":"Have the student describe a spin measurement along one axis then along a perpendicular one, and ask what the second destroys.","example_contexts_fr":["un faisceau d'atomes séparé en deux par un aimant","un électron dans un champ magnétique d'IRM","deux mesures successives selon des axes perpendiculaires"],"example_contexts_en":["a beam of atoms split in two by a magnet","an electron in an MRI magnetic field","two successive measurements along perpendicular axes"],"safety_category":"standard"},{"key":"quantum_physics.basis_change","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":3,"order":23,"required":true,"prerequisite_keys":["quantum_physics.dirac_notation"],"fallback_key":"quantum_physics.dirac_notation","title_fr":"Bases et changement de base","title_en":"Bases and change of basis","summary_fr":"Comprendre qu'un même état s'écrit différemment selon la base de mesure choisie.","summary_en":"Understand that one state is written differently depending on the chosen measurement basis.","learning_goals_fr":["Réécrire un état dans une seconde base orthonormée.","Expliquer pourquoi un état certain dans une base est incertain dans une autre."],"learning_goals_en":["Rewrite a state in a second orthonormal basis.","Explain why a state certain in one basis is uncertain in another."],"tutor_focus_fr":"Fais réécrire un état bien défini dans une base tournée de 45 degrés, puis demande ce que donnerait la mesure dans cette nouvelle base.","tutor_focus_en":"Have the student rewrite a well-defined state in a basis rotated by 45 degrees, then ask what a measurement in that basis would give.","example_contexts_fr":["un photon polarisé mesuré selon deux orientations de filtre","un état certain dans une base et équiprobable dans l'autre","un même vecteur exprimé dans deux repères"],"example_contexts_en":["a polarised photon measured through two filter orientations","a state certain in one basis and even in the other","the same vector expressed in two frames"],"safety_category":"standard"},{"key":"quantum_physics.born_rule","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":3,"order":24,"required":false,"prerequisite_keys":["quantum_physics.basis_change"],"fallback_key":"quantum_physics.dirac_notation","title_fr":"La règle de Born","title_en":"The Born rule","summary_fr":"Calculer la probabilité d'un résultat comme le carré du module de l'amplitude correspondante.","summary_en":"Compute the probability of an outcome as the squared modulus of the matching amplitude.","learning_goals_fr":["Appliquer la règle sur un état à trois composantes.","Vérifier que les probabilités obtenues somment à un."],"learning_goals_en":["Apply the rule to a three-component state.","Check that the resulting probabilities sum to one."],"tutor_focus_fr":"Fais calculer les trois probabilités d'un état donné, puis demande de vérifier leur somme et d'expliquer ce que garantit la normalisation.","tutor_focus_en":"Have the student compute the three probabilities of a given state, then check their sum and explain what normalisation guarantees.","example_contexts_fr":["un état à trois issues possibles","un état mal normalisé qui donne des probabilités absurdes","un histogramme de résultats mesurés mille fois"],"example_contexts_en":["a state with three possible outcomes","a badly normalised state giving absurd probabilities","a histogram of a thousand measured results"],"safety_category":"standard"},{"key":"quantum_physics.operators_observables","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":3,"order":25,"required":false,"prerequisite_keys":["quantum_physics.born_rule"],"fallback_key":"quantum_physics.dirac_notation","title_fr":"Opérateurs et observables","title_en":"Operators and observables","summary_fr":"Associer une grandeur mesurable à un opérateur agissant sur les états.","summary_en":"Associate a measurable quantity with an operator acting on states.","learning_goals_fr":["Dire quelle propriété un opérateur doit avoir pour représenter une mesure.","Appliquer un opérateur simple à un état."],"learning_goals_en":["Say which property an operator must have to represent a measurement.","Apply a simple operator to a state."],"tutor_focus_fr":"Fais appliquer un opérateur donné à deux états de base, puis demande pourquoi les résultats de mesure doivent être réels.","tutor_focus_en":"Have the student apply a given operator to two basis states, then ask why measurement results must be real.","example_contexts_fr":["une matrice deux par deux appliquée à un état","une énergie mesurée en laboratoire","un opérateur qui laisse un état inchangé"],"example_contexts_en":["a two-by-two matrix applied to a state","an energy measured in the laboratory","an operator leaving a state unchanged"],"safety_category":"standard"},{"key":"quantum_physics.eigenvalues_measurement","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":3,"order":26,"required":false,"prerequisite_keys":["quantum_physics.operators_observables"],"fallback_key":"quantum_physics.dirac_notation","title_fr":"Valeurs propres et résultats de mesure","title_en":"Eigenvalues and measurement outcomes","summary_fr":"Identifier les résultats possibles d'une mesure aux valeurs propres de l'opérateur associé.","summary_en":"Identify the possible outcomes of a measurement with the eigenvalues of its operator.","learning_goals_fr":["Calculer les valeurs propres d'un opérateur deux par deux.","Dire dans quel état se trouve le système juste après la mesure."],"learning_goals_en":["Compute the eigenvalues of a two-by-two operator.","Say which state the system is in right after measurement."],"tutor_focus_fr":"Fais calculer les valeurs propres d'un opérateur simple, puis demande dans quel état se trouve le système juste après le résultat obtenu.","tutor_focus_en":"Have the student compute the eigenvalues of a simple operator, then ask which state the system is in right after the obtained result.","example_contexts_fr":["une mesure qui ne peut donner que deux valeurs","un état propre qui reste inchangé après mesure","une seconde mesure identique à la première"],"example_contexts_en":["a measurement that can only yield two values","an eigenstate left unchanged by measurement","a second measurement identical to the first"],"safety_category":"standard"},{"key":"quantum_physics.quantum_circuit_reading","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":3,"order":27,"required":true,"prerequisite_keys":["quantum_physics.quantum_gates"],"fallback_key":"quantum_physics.quantum_gates","title_fr":"Lire un circuit quantique","title_en":"Reading a quantum circuit","summary_fr":"Suivre un circuit de gauche à droite et prédire la distribution des résultats de mesure.","summary_en":"Follow a circuit left to right and predict the distribution of measurement results.","learning_goals_fr":["Suivre l'état à travers trois portes successives.","Prédire la distribution des résultats à la mesure finale."],"learning_goals_en":["Follow the state through three successive gates.","Predict the outcome distribution at the final measurement."],"tutor_focus_fr":"Fais suivre l'état à travers un circuit à trois portes, puis demande la distribution attendue sur mille exécutions.","tutor_focus_en":"Have the student follow the state through a three-gate circuit, then ask the expected distribution over a thousand runs.","example_contexts_fr":["un circuit à deux qubits et trois portes","une mesure répétée mille fois","un circuit dont la dernière porte est retirée"],"example_contexts_en":["a two-qubit circuit with three gates","a measurement repeated a thousand times","a circuit with its last gate removed"],"safety_category":"standard"},{"key":"quantum_physics.entangling_gate","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":3,"order":28,"required":false,"prerequisite_keys":["quantum_physics.quantum_circuit_reading"],"fallback_key":"quantum_physics.quantum_gates","title_fr":"La porte contrôlée et la création d'intrication","title_en":"The controlled gate and creating entanglement","summary_fr":"Construire une paire intriquée avec deux portes et vérifier la corrélation obtenue.","summary_en":"Build an entangled pair with two gates and check the resulting correlation.","learning_goals_fr":["Décrire l'effet d'une porte contrôlée sur un état superposé.","Prédire les résultats corrélés des deux mesures."],"learning_goals_en":["Describe the effect of a controlled gate on a superposed state.","Predict the correlated outcomes of both measurements."],"tutor_focus_fr":"Fais construire une paire intriquée avec deux portes, puis demande quels résultats de mesure sont possibles et lesquels ne le sont jamais.","tutor_focus_en":"Have the student build an entangled pair with two gates, then ask which measurement results are possible and which never occur.","example_contexts_fr":["deux qubits mesurés toujours identiques","un circuit à une porte H suivie d'une porte contrôlée","une combinaison de résultats jamais observée"],"example_contexts_en":["two qubits always measured identical","a circuit with an H gate followed by a controlled gate","a result combination never observed"],"safety_category":"standard"},{"key":"quantum_physics.interference_as_engine","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":3,"order":29,"required":false,"prerequisite_keys":["quantum_physics.entangling_gate"],"fallback_key":"quantum_physics.quantum_gates","title_fr":"L'interférence comme moteur des algorithmes","title_en":"Interference as the engine of algorithms","summary_fr":"Comprendre qu'un algorithme quantique organise l'annulation des mauvaises réponses.","summary_en":"Understand that a quantum algorithm organises the cancellation of wrong answers.","learning_goals_fr":["Expliquer pourquoi tester toutes les possibilités ne suffit pas.","Dire ce qu'un algorithme doit organiser pour être utile."],"learning_goals_en":["Explain why testing all possibilities is not enough.","Say what an algorithm must organise to be useful."],"tutor_focus_fr":"Fais expliquer pourquoi une superposition de toutes les réponses ne donne rien à la mesure, puis demande ce que l'algorithme doit ajouter.","tutor_focus_en":"Have the student explain why a superposition of every answer yields nothing at measurement, then ask what the algorithm must add.","example_contexts_fr":["une superposition de toutes les réponses possibles","une mesure qui renvoie une réponse au hasard","des amplitudes concentrées sur la bonne réponse"],"example_contexts_en":["a superposition of every possible answer","a measurement returning a random answer","amplitudes concentrated on the right answer"],"safety_category":"standard"},{"key":"quantum_physics.measurement_readout","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":3,"order":30,"required":false,"prerequisite_keys":["quantum_physics.interference_as_engine"],"fallback_key":"quantum_physics.quantum_gates","title_fr":"Lire le résultat d'un calcul quantique","title_en":"Reading the result of a quantum computation","summary_fr":"Comprendre qu'un résultat s'obtient par répétitions et statistiques plutôt qu'en une lecture.","summary_en":"Understand that a result comes from repetitions and statistics rather than a single readout.","learning_goals_fr":["Expliquer pourquoi une exécution unique ne suffit pas.","Estimer le nombre de répétitions nécessaires à une précision donnée."],"learning_goals_en":["Explain why one run is not enough.","Estimate how many repetitions a given precision needs."],"tutor_focus_fr":"Fais estimer combien d'exécutions sont nécessaires pour distinguer deux distributions proches, puis demande ce que coûte cette répétition.","tutor_focus_en":"Have the student estimate how many runs separate two close distributions, then ask what that repetition costs.","example_contexts_fr":["un algorithme exécuté dix mille fois","deux distributions de résultats très proches","un résultat vérifiable classiquement en une seconde"],"example_contexts_en":["an algorithm executed ten thousand times","two very close result distributions","a result verifiable classically in one second"],"safety_category":"standard"},{"key":"quantum_physics.pauli_exclusion","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":4,"order":31,"required":true,"prerequisite_keys":["quantum_physics.quantum_spin"],"fallback_key":"quantum_physics.quantum_spin","title_fr":"Le principe d'exclusion et la structure de la matière","title_en":"The exclusion principle and the structure of matter","summary_fr":"Relier l'interdiction pour deux électrons d'occuper le même état à la stabilité de la matière.","summary_en":"Connect the ban on two electrons sharing a state to the stability of matter.","learning_goals_fr":["Expliquer comment le remplissage des couches construit le tableau périodique.","Dire pourquoi la matière ordinaire ne s'effondre pas."],"learning_goals_en":["Explain how shell filling builds the periodic table.","Say why ordinary matter does not collapse."],"tutor_focus_fr":"Fais remplir les couches d'un atome léger électron par électron, puis demande ce qui se passerait sans cette interdiction.","tutor_focus_en":"Have the student fill the shells of a light atom electron by electron, then ask what would happen without that ban.","example_contexts_fr":["le remplissage des couches d'un atome de carbone","la rigidité d'un morceau de métal","une étoile qui résiste à sa propre gravité"],"example_contexts_en":["filling the shells of a carbon atom","the stiffness of a piece of metal","a star resisting its own gravity"],"safety_category":"standard"},{"key":"quantum_physics.quantum_interpretations","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":4,"order":32,"required":false,"prerequisite_keys":["quantum_physics.pauli_exclusion"],"fallback_key":"quantum_physics.quantum_spin","title_fr":"Ce que les interprétations changent et ne changent pas","title_en":"What interpretations change and do not change","summary_fr":"Distinguer le formalisme prédictif, identique pour tous, des récits qui l'accompagnent.","summary_en":"Separate the predictive formalism, shared by all, from the stories told around it.","learning_goals_fr":["Dire ce que toutes les interprétations partagent obligatoirement.","Expliquer pourquoi le choix d'interprétation ne change aucune prédiction."],"learning_goals_en":["Say what every interpretation necessarily shares.","Explain why the choice of interpretation changes no prediction."],"tutor_focus_fr":"Fais comparer deux interprétations sur une même expérience, puis demande quelle prédiction chiffrée diffère entre elles.","tutor_focus_en":"Have the student compare two interpretations on the same experiment, then ask which numeric prediction differs between them.","example_contexts_fr":["une même expérience racontée de deux façons","un débat entre deux physiciens sur le rôle de la mesure","un calcul de probabilité identique dans les deux récits"],"example_contexts_en":["the same experiment told in two ways","a debate between two physicists on the role of measurement","a probability computation identical in both accounts"],"safety_category":"standard"},{"key":"quantum_physics.vacuum_energy","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":4,"order":33,"required":false,"prerequisite_keys":["quantum_physics.quantum_interpretations"],"fallback_key":"quantum_physics.quantum_spin","title_fr":"L'énergie du vide","title_en":"Vacuum energy","summary_fr":"Comprendre que le vide quantique n'est pas rien et produit des effets mesurables.","summary_en":"Understand that the quantum vacuum is not nothing and produces measurable effects.","learning_goals_fr":["Expliquer pourquoi un champ ne peut pas être exactement nul partout.","Citer un effet mesuré attribué aux fluctuations du vide."],"learning_goals_en":["Explain why a field cannot be exactly zero everywhere.","Name a measured effect attributed to vacuum fluctuations."],"tutor_focus_fr":"Fais expliquer pourquoi le vide garde une énergie minimale, puis demande quelle mesure de laboratoire le met en évidence.","tutor_focus_en":"Have the student explain why the vacuum keeps a minimum energy, then ask which laboratory measurement reveals it.","example_contexts_fr":["deux plaques très proches qui s'attirent dans le vide","une chambre pompée jusqu'à la pression la plus basse possible","un atome excité qui finit par retomber tout seul"],"example_contexts_en":["two very close plates attracting each other in vacuum","a chamber pumped to the lowest achievable pressure","an excited atom that eventually decays on its own"],"safety_category":"standard"},{"key":"quantum_physics.laser_stimulated_emission","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":4,"order":34,"required":false,"prerequisite_keys":["quantum_physics.vacuum_energy"],"fallback_key":"quantum_physics.quantum_spin","title_fr":"Comment un laser amplifie la lumière","title_en":"How a laser amplifies light","summary_fr":"Relier émission stimulée, inversion de population et cavité optique à un faisceau cohérent.","summary_en":"Connect stimulated emission, population inversion and an optical cavity to a coherent beam.","learning_goals_fr":["Expliquer ce qu'apporte l'émission stimulée par rapport à l'émission spontanée.","Dire pourquoi une inversion de population est nécessaire."],"learning_goals_en":["Explain what stimulated emission adds over spontaneous emission.","Say why a population inversion is required."],"tutor_focus_fr":"Fais expliquer pourquoi un photon en produit un identique, puis demande pourquoi une lampe ordinaire ne produit jamais un faisceau laser.","tutor_focus_en":"Have the student explain why one photon produces an identical one, then ask why an ordinary lamp never yields a laser beam.","example_contexts_fr":["un pointeur laser de conférence","une lampe à incandescence qui éclaire dans toutes les directions","un laser de découpe industrielle"],"example_contexts_en":["a conference laser pointer","an incandescent lamp shining in all directions","an industrial cutting laser"],"safety_category":"standard"},{"key":"quantum_physics.commutators","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":4,"order":35,"required":true,"prerequisite_keys":["quantum_physics.eigenvalues_measurement"],"fallback_key":"quantum_physics.eigenvalues_measurement","title_fr":"Commutateurs et grandeurs incompatibles","title_en":"Commutators and incompatible quantities","summary_fr":"Utiliser le commutateur pour savoir si deux mesures peuvent être précises en même temps.","summary_en":"Use the commutator to know whether two measurements can both be precise.","learning_goals_fr":["Calculer un commutateur de deux opérateurs simples.","Relier un commutateur non nul à une relation d'indétermination."],"learning_goals_en":["Compute the commutator of two simple operators.","Link a non-zero commutator to an uncertainty relation."],"tutor_focus_fr":"Fais calculer le commutateur de deux opérateurs donnés, puis demande ce que le résultat implique sur l'ordre des mesures.","tutor_focus_en":"Have the student compute the commutator of two given operators, then ask what the result implies about measurement order.","example_contexts_fr":["deux mesures effectuées dans un ordre puis dans l'autre","deux opérateurs qui commutent","position et impulsion d'une particule"],"example_contexts_en":["two measurements performed in one order then the other","two operators that commute","position and momentum of a particle"],"safety_category":"standard"},{"key":"quantum_physics.schrodinger_equation","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":4,"order":36,"required":false,"prerequisite_keys":["quantum_physics.commutators"],"fallback_key":"quantum_physics.eigenvalues_measurement","title_fr":"L'équation d'évolution des états","title_en":"The state evolution equation","summary_fr":"Comprendre l'évolution déterministe d'un état entre deux mesures et le rôle de l'énergie.","summary_en":"Understand the deterministic evolution of a state between measurements and the role of energy.","learning_goals_fr":["Dire ce que l'équation prédit exactement.","Opposer l'évolution continue au saut produit par la mesure."],"learning_goals_en":["Say exactly what the equation predicts.","Contrast continuous evolution with the jump caused by measurement."],"tutor_focus_fr":"Fais opposer l'évolution entre deux mesures et le changement au moment de la mesure, puis demande laquelle est déterministe.","tutor_focus_en":"Have the student contrast evolution between measurements and the change at measurement, then ask which one is deterministic.","example_contexts_fr":["un état qui oscille entre deux niveaux","un système isolé laissé à lui-même une seconde","une mesure qui interrompt l'évolution"],"example_contexts_en":["a state oscillating between two levels","an isolated system left alone for a second","a measurement interrupting the evolution"],"safety_category":"standard"},{"key":"quantum_physics.hilbert_space","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":4,"order":37,"required":false,"prerequisite_keys":["quantum_physics.schrodinger_equation"],"fallback_key":"quantum_physics.eigenvalues_measurement","title_fr":"L'espace des états","title_en":"The space of states","summary_fr":"Situer les états dans un espace vectoriel muni d'un produit scalaire et d'une dimension propre au système.","summary_en":"Place states inside a vector space with an inner product and a dimension set by the system.","learning_goals_fr":["Donner la dimension de l'espace pour un système à deux niveaux.","Expliquer ce que la structure d'espace vectoriel autorise."],"learning_goals_en":["Give the space dimension for a two-level system.","Explain what the vector space structure allows."],"tutor_focus_fr":"Fais donner la dimension de l'espace pour un puis pour trois systèmes à deux niveaux, et demande d'où vient la croissance.","tutor_focus_en":"Have the student give the dimension for one then three two-level systems, and ask where the growth comes from.","example_contexts_fr":["un système à deux niveaux isolé","trois systèmes à deux niveaux considérés ensemble","un espace de dimension infinie pour une position continue"],"example_contexts_en":["an isolated two-level system","three two-level systems considered together","an infinite-dimensional space for a continuous position"],"safety_category":"standard"},{"key":"quantum_physics.tensor_product","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":4,"order":38,"required":false,"prerequisite_keys":["quantum_physics.hilbert_space"],"fallback_key":"quantum_physics.eigenvalues_measurement","title_fr":"Le produit tensoriel et les systèmes composés","title_en":"The tensor product and composite systems","summary_fr":"Construire l'état de deux systèmes réunis et reconnaître un état qui ne se factorise pas.","summary_en":"Build the state of two joined systems and recognise a state that does not factorise.","learning_goals_fr":["Écrire l'état de deux systèmes indépendants.","Montrer qu'un état intriqué ne se factorise pas."],"learning_goals_en":["Write the state of two independent systems.","Show that an entangled state does not factorise."],"tutor_focus_fr":"Fais écrire l'état de deux systèmes indépendants, puis demande de prouver qu'un état donné ne peut pas s'écrire ainsi.","tutor_focus_en":"Have the student write the state of two independent systems, then prove a given state cannot be written that way.","example_contexts_fr":["deux particules préparées séparément","un état qui ne s'écrit pas comme un produit","un espace dont la dimension double à chaque ajout"],"example_contexts_en":["two particles prepared separately","a state that cannot be written as a product","a space whose dimension doubles with each addition"],"safety_category":"standard"},{"key":"quantum_physics.grover_search","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":4,"order":39,"required":true,"prerequisite_keys":["quantum_physics.measurement_readout"],"fallback_key":"quantum_physics.measurement_readout","title_fr":"L'algorithme de recherche de Grover","title_en":"Grover's search algorithm","summary_fr":"Comprendre le gain quadratique d'une recherche non structurée et ses conditions d'application.","summary_en":"Understand the quadratic gain of unstructured search and its conditions of use.","learning_goals_fr":["Comparer le nombre d'essais classique et quantique.","Dire ce que l'algorithme exige pour être applicable."],"learning_goals_en":["Compare the classical and quantum number of trials.","Say what the algorithm requires to be applicable."],"tutor_focus_fr":"Fais comparer le nombre d'essais pour un million d'éléments, puis demande ce qu'il faut pouvoir écrire pour appliquer l'algorithme.","tutor_focus_en":"Have the student compare the number of trials for a million items, then ask what must be writable to apply the algorithm.","example_contexts_fr":["une recherche parmi un million d'éléments non triés","une fonction qui reconnaît la bonne réponse","une base de données classique déjà indexée"],"example_contexts_en":["a search among a million unsorted items","a function recognising the right answer","a classical database that is already indexed"],"safety_category":"standard"},{"key":"quantum_physics.shor_factoring","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":4,"order":40,"required":false,"prerequisite_keys":["quantum_physics.grover_search"],"fallback_key":"quantum_physics.measurement_readout","title_fr":"L'algorithme de factorisation de Shor","title_en":"Shor's factoring algorithm","summary_fr":"Comprendre pourquoi la factorisation devient traitable et ce que cela menace en cryptographie.","summary_en":"Understand why factoring becomes tractable and what that threatens in cryptography.","learning_goals_fr":["Dire quelle structure mathématique l'algorithme exploite.","Expliquer quelles cryptographies sont concernées."],"learning_goals_en":["Say which mathematical structure the algorithm exploits.","Explain which cryptographic systems are affected."],"tutor_focus_fr":"Fais expliquer quelle propriété périodique l'algorithme exploite, puis demande quels systèmes cryptographiques sont réellement menacés.","tutor_focus_en":"Have the student explain which periodic property the algorithm exploits, then ask which cryptographic systems are really threatened.","example_contexts_fr":["une clé publique fondée sur un produit de deux grands nombres","un message chiffré aujourd'hui et stocké pour plus tard","un algorithme de signature fondé sur les courbes elliptiques"],"example_contexts_en":["a public key based on a product of two large numbers","a message encrypted today and stored for later","a signature algorithm based on elliptic curves"],"safety_category":"standard"},{"key":"quantum_physics.quantum_noise","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":4,"order":41,"required":false,"prerequisite_keys":["quantum_physics.shor_factoring"],"fallback_key":"quantum_physics.measurement_readout","title_fr":"Le bruit et la fidélité des portes","title_en":"Noise and gate fidelity","summary_fr":"Comprendre l'accumulation des erreurs le long d'un circuit et la profondeur utile qui en résulte.","summary_en":"Understand how errors accumulate along a circuit and the usable depth that results.","learning_goals_fr":["Estimer la fidélité d'un circuit à partir de celle de ses portes.","Dire ce qui limite la profondeur d'un circuit exécutable."],"learning_goals_en":["Estimate a circuit's fidelity from its gate fidelity.","Say what limits the depth of an executable circuit."],"tutor_focus_fr":"Fais estimer la fidélité d'un circuit de cent portes à 99,9 % chacune, puis demande ce que cela impose sur la taille des algorithmes.","tutor_focus_en":"Have the student estimate the fidelity of a hundred-gate circuit at 99.9% each, then ask what that imposes on algorithm size.","example_contexts_fr":["un circuit de cent portes successives","une porte fidèle à 99,9 %","un temps de cohérence de cent microsecondes"],"example_contexts_en":["a circuit of a hundred successive gates","a gate with 99.9% fidelity","a coherence time of a hundred microseconds"],"safety_category":"standard"},{"key":"quantum_physics.quantum_error_correction","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":4,"order":42,"required":false,"prerequisite_keys":["quantum_physics.quantum_noise"],"fallback_key":"quantum_physics.measurement_readout","title_fr":"La correction d'erreur quantique","title_en":"Quantum error correction","summary_fr":"Comprendre l'encodage d'un qubit logique sur de nombreux qubits physiques et son coût.","summary_en":"Understand encoding a logical qubit across many physical qubits and its cost.","learning_goals_fr":["Expliquer pourquoi on ne peut pas simplement copier un qubit.","Estimer le coût en qubits physiques d'un qubit logique."],"learning_goals_en":["Explain why a qubit cannot simply be copied.","Estimate the physical qubit cost of one logical qubit."],"tutor_focus_fr":"Fais expliquer pourquoi la copie d'un qubit est impossible, puis demande comment on détecte une erreur sans lire l'information.","tutor_focus_en":"Have the student explain why copying a qubit is impossible, then ask how an error is detected without reading the information.","example_contexts_fr":["un qubit logique porté par mille qubits physiques","une erreur détectée sans lire la valeur encodée","une machine annoncée avec un million de qubits physiques"],"example_contexts_en":["a logical qubit carried by a thousand physical qubits","an error detected without reading the encoded value","a machine announced with a million physical qubits"],"safety_category":"standard"},{"key":"quantum_physics.superconductivity","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":5,"order":43,"required":true,"prerequisite_keys":["quantum_physics.laser_stimulated_emission"],"fallback_key":"quantum_physics.laser_stimulated_emission","title_fr":"La supraconductivité","title_en":"Superconductivity","summary_fr":"Comprendre la disparition de la résistance électrique par appariement des électrons sous une température critique.","summary_en":"Understand the vanishing of electrical resistance through electron pairing below a critical temperature.","learning_goals_fr":["Expliquer ce que devient la résistance sous la température critique.","Citer un usage industriel qui justifie le refroidissement."],"learning_goals_en":["Explain what resistance becomes below the critical temperature.","Name an industrial use that justifies the cooling."],"tutor_focus_fr":"Fais expliquer pourquoi un courant peut circuler sans perte, puis demande ce qui justifie le coût du refroidissement en pratique.","tutor_focus_en":"Have the student explain why a current can flow without loss, then ask what justifies the cooling cost in practice.","example_contexts_fr":["un aimant d'IRM refroidi à l'hélium liquide","un anneau de courant qui circule sans s'atténuer","une ligne électrique expérimentale sans pertes"],"example_contexts_en":["an MRI magnet cooled with liquid helium","a current loop circulating without decaying","an experimental lossless power line"],"safety_category":"standard"},{"key":"quantum_physics.bose_einstein_condensate","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":5,"order":44,"required":false,"prerequisite_keys":["quantum_physics.superconductivity"],"fallback_key":"quantum_physics.laser_stimulated_emission","title_fr":"Le condensat de Bose-Einstein","title_en":"The Bose-Einstein condensate","summary_fr":"Comprendre l'état où des milliers d'atomes occupent le même état quantique et se comportent comme un seul.","summary_en":"Understand the state where thousands of atoms share one quantum state and act as one.","learning_goals_fr":["Expliquer ce que le refroidissement extrême rend possible.","Dire ce qu'on observe qui serait impossible à température ambiante."],"learning_goals_en":["Explain what extreme cooling makes possible.","Say what is observed that would be impossible at room temperature."],"tutor_focus_fr":"Fais expliquer pourquoi il faut descendre près du zéro absolu, puis demande ce que l'on observe alors et qui serait impossible autrement.","tutor_focus_en":"Have the student explain why one must go near absolute zero, then ask what is observed there that is otherwise impossible.","example_contexts_fr":["un nuage d'atomes refroidi au nanokelvin","des atomes qui interfèrent comme une onde unique","une expérience de laboratoire filmée image par image"],"example_contexts_en":["an atom cloud cooled to the nanokelvin range","atoms interfering as a single wave","a laboratory experiment filmed frame by frame"],"safety_category":"standard"},{"key":"quantum_physics.single_photon_experiments","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":5,"order":45,"required":false,"prerequisite_keys":["quantum_physics.bose_einstein_condensate"],"fallback_key":"quantum_physics.laser_stimulated_emission","title_fr":"Les expériences à photon unique","title_en":"Single-photon experiments","summary_fr":"Comprendre ce que garantit une source de photons uniques et pourquoi elle change l'interprétation d'un résultat.","summary_en":"Understand what a single-photon source guarantees and why it changes how a result is read.","learning_goals_fr":["Expliquer ce qu'une source atténuée ne garantit pas.","Dire ce que prouve une expérience réalisée photon par photon."],"learning_goals_en":["Explain what an attenuated source does not guarantee.","Say what an experiment run photon by photon proves."],"tutor_focus_fr":"Fais comparer une source atténuée et une vraie source de photons uniques, puis demande ce que la seconde permet de conclure.","tutor_focus_en":"Have the student compare an attenuated source with a true single-photon source, then ask what the second allows concluding.","example_contexts_fr":["un laser fortement atténué","un détecteur qui compte les clics un par un","une distribution de clé quantique en laboratoire"],"example_contexts_en":["a heavily attenuated laser","a detector counting clicks one by one","a laboratory quantum key distribution setup"],"safety_category":"standard"},{"key":"quantum_physics.quantum_thermodynamics","domain_id":"quantum_physics","objective_ids":["quantum_intuition"],"stage":5,"order":46,"required":false,"prerequisite_keys":["quantum_physics.single_photon_experiments"],"fallback_key":"quantum_physics.laser_stimulated_emission","title_fr":"Chaleur et information à l'échelle quantique","title_en":"Heat and information at the quantum scale","summary_fr":"Relier l'effacement d'une information à une dissipation minimale de chaleur.","summary_en":"Connect erasing information to a minimal dissipation of heat.","learning_goals_fr":["Expliquer pourquoi effacer un bit coûte de l'énergie.","Dire ce qu'un calcul réversible change à cette dépense."],"learning_goals_en":["Explain why erasing a bit costs energy.","Say what reversible computation changes about that cost."],"tutor_focus_fr":"Fais expliquer pourquoi l'effacement d'un bit dissipe de la chaleur, puis demande ce que change un calcul réversible.","tutor_focus_en":"Have the student explain why erasing a bit dissipates heat, then ask what a reversible computation changes.","example_contexts_fr":["un processeur qui chauffe en effaçant des données","une mémoire réinitialisée avant chaque calcul","une porte logique réversible imaginée en pensée"],"example_contexts_en":["a processor heating as it erases data","a memory reset before each computation","a reversible logic gate imagined in thought"],"safety_category":"standard"},{"key":"quantum_physics.density_matrix","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":5,"order":47,"required":true,"prerequisite_keys":["quantum_physics.tensor_product"],"fallback_key":"quantum_physics.tensor_product","title_fr":"La matrice densité","title_en":"The density matrix","summary_fr":"Décrire un système partiellement connu et distinguer une superposition d'un mélange statistique.","summary_en":"Describe a partially known system and tell a superposition apart from a statistical mixture.","learning_goals_fr":["Écrire la matrice d'un état pur et celle d'un mélange.","Repérer sur la matrice ce qui distingue les deux cas."],"learning_goals_en":["Write the matrix of a pure state and of a mixture.","Spot in the matrix what separates the two cases."],"tutor_focus_fr":"Fais écrire les deux matrices pour une superposition et pour un mélange équiprobable, puis demande quel terme les distingue.","tutor_focus_en":"Have the student write both matrices for a superposition and for an even mixture, then ask which term distinguishes them.","example_contexts_fr":["un mélange équiprobable de deux états","une superposition à composantes égales","un système couplé à un environnement bruyant"],"example_contexts_en":["an even mixture of two states","a superposition with equal components","a system coupled to a noisy environment"],"safety_category":"standard"},{"key":"quantum_physics.entanglement_entropy","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":5,"order":48,"required":false,"prerequisite_keys":["quantum_physics.density_matrix"],"fallback_key":"quantum_physics.tensor_product","title_fr":"L'entropie d'intrication","title_en":"Entanglement entropy","summary_fr":"Quantifier l'intrication par l'incertitude qui subsiste sur une partie du système.","summary_en":"Quantify entanglement by the uncertainty remaining about one part of the system.","learning_goals_fr":["Calculer l'entropie d'une partie d'un état maximalement intriqué.","Expliquer pourquoi le tout peut être mieux connu que ses parties."],"learning_goals_en":["Compute the entropy of one half of a maximally entangled state.","Explain why the whole can be better known than its parts."],"tutor_focus_fr":"Fais calculer l'entropie d'une moitié d'une paire maximalement intriquée, puis demande pourquoi elle dépasse celle du système entier.","tutor_focus_en":"Have the student compute the entropy of one half of a maximally entangled pair, then ask why it exceeds that of the whole system.","example_contexts_fr":["une paire maximalement intriquée séparée en deux","un état produit dont chaque partie est bien définie","une mesure limitée à une seule des deux particules"],"example_contexts_en":["a maximally entangled pair split in two","a product state whose parts are well defined","a measurement limited to one of the two particles"],"safety_category":"standard"},{"key":"quantum_physics.perturbation_theory","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":5,"order":49,"required":false,"prerequisite_keys":["quantum_physics.entanglement_entropy"],"fallback_key":"quantum_physics.tensor_product","title_fr":"La théorie des perturbations","title_en":"Perturbation theory","summary_fr":"Approcher un système compliqué comme un système simple légèrement modifié.","summary_en":"Approach a complicated system as a simple one that has been slightly modified.","learning_goals_fr":["Expliquer la démarche d'un développement au premier ordre.","Dire quand l'approximation cesse d'être valable."],"learning_goals_en":["Explain the approach of a first-order expansion.","Say when the approximation stops being valid."],"tutor_focus_fr":"Fais estimer le décalage d'un niveau d'énergie sous une petite perturbation, puis demande à partir de quand l'approche échoue.","tutor_focus_en":"Have the student estimate the shift of an energy level under a small perturbation, then ask when the approach fails.","example_contexts_fr":["un atome placé dans un champ électrique faible","un niveau d'énergie légèrement décalé","une perturbation devenue comparable au terme principal"],"example_contexts_en":["an atom placed in a weak electric field","an energy level slightly shifted","a perturbation grown comparable to the main term"],"safety_category":"standard"},{"key":"quantum_physics.path_integral","domain_id":"quantum_physics","objective_ids":["quantum_mathematics"],"stage":5,"order":50,"required":false,"prerequisite_keys":["quantum_physics.perturbation_theory"],"fallback_key":"quantum_physics.tensor_product","title_fr":"La somme sur les chemins","title_en":"The sum over paths","summary_fr":"Comprendre une amplitude comme la somme des contributions de tous les trajets possibles.","summary_en":"Understand an amplitude as the sum of contributions from every possible trajectory.","learning_goals_fr":["Expliquer comment les chemins éloignés du trajet classique s'annulent.","Relier cette vision au trajet unique de la mécanique classique."],"learning_goals_en":["Explain how paths far from the classical one cancel out.","Relate this picture to the single path of classical mechanics."],"tutor_focus_fr":"Fais expliquer comment la somme sur tous les trajets redonne la trajectoire classique, puis demande ce que deviennent les autres contributions.","tutor_focus_en":"Have the student explain how the sum over all paths recovers the classical trajectory, then ask what happens to the other contributions.","example_contexts_fr":["tous les trajets possibles entre deux points","une trajectoire classique retrouvée à grande échelle","deux chemins dont les contributions s'annulent"],"example_contexts_en":["every possible path between two points","a classical trajectory recovered at large scale","two paths whose contributions cancel"],"safety_category":"standard"},{"key":"quantum_physics.hardware_platforms","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":5,"order":51,"required":true,"prerequisite_keys":["quantum_physics.quantum_error_correction"],"fallback_key":"quantum_physics.quantum_error_correction","title_fr":"Les plateformes matérielles comparées","title_en":"Hardware platforms compared","summary_fr":"Comparer supraconducteurs, ions piégés et photons sur la vitesse, la fidélité et la connectivité.","summary_en":"Compare superconductors, trapped ions and photons on speed, fidelity and connectivity.","learning_goals_fr":["Comparer deux plateformes sur trois critères techniques.","Dire pourquoi aucune ne domine sur tous les critères."],"learning_goals_en":["Compare two platforms on three technical criteria.","Say why none dominates on every criterion."],"tutor_focus_fr":"Fais comparer deux plateformes sur vitesse, fidélité et connectivité, puis demande laquelle conviendrait à un algorithme profond.","tutor_focus_en":"Have the student compare two platforms on speed, fidelity and connectivity, then ask which suits a deep algorithm.","example_contexts_fr":["des qubits supraconducteurs refroidis au millikelvin","des ions piégés manipulés par laser","un processeur photonique fonctionnant à température ambiante"],"example_contexts_en":["superconducting qubits cooled to millikelvin","trapped ions manipulated by laser","a photonic processor working at room temperature"],"safety_category":"standard"},{"key":"quantum_physics.quantum_advantage","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":5,"order":52,"required":false,"prerequisite_keys":["quantum_physics.hardware_platforms"],"fallback_key":"quantum_physics.quantum_error_correction","title_fr":"Ce que signifie un avantage quantique","title_en":"What quantum advantage means","summary_fr":"Distinguer une démonstration sur une tâche artificielle d'un gain sur un problème utile.","summary_en":"Tell apart a demonstration on an artificial task and a gain on a useful problem.","learning_goals_fr":["Dire ce qu'une démonstration d'avantage établit exactement.","Citer ce qu'il faudrait pour parler d'utilité industrielle."],"learning_goals_en":["Say what an advantage demonstration actually establishes.","Name what would be needed to claim industrial usefulness."],"tutor_focus_fr":"Fais critiquer une annonce d'avantage quantique, puis demande quelles conditions manquent pour parler d'utilité réelle.","tutor_focus_en":"Have the student critique a quantum advantage announcement, then ask which conditions are missing to claim real usefulness.","example_contexts_fr":["un échantillonnage sans application connue","un algorithme classique amélioré après l'annonce","un problème industriel de planification"],"example_contexts_en":["a sampling task with no known application","a classical algorithm improved after the announcement","an industrial scheduling problem"],"safety_category":"standard"},{"key":"quantum_physics.variational_algorithms","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":5,"order":53,"required":false,"prerequisite_keys":["quantum_physics.quantum_advantage"],"fallback_key":"quantum_physics.quantum_error_correction","title_fr":"Les algorithmes hybrides variationnels","title_en":"Hybrid variational algorithms","summary_fr":"Comprendre la boucle entre un circuit court paramétré et un optimiseur classique.","summary_en":"Understand the loop between a short parameterised circuit and a classical optimiser.","learning_goals_fr":["Décrire un tour complet de la boucle hybride.","Dire pourquoi cette approche convient aux machines bruitées."],"learning_goals_en":["Describe one full turn of the hybrid loop.","Say why this approach suits noisy machines."],"tutor_focus_fr":"Fais décrire un tour complet de la boucle hybride, puis demande pourquoi des circuits courts sont préférés sur les machines actuelles.","tutor_focus_en":"Have the student describe one full turn of the hybrid loop, then ask why short circuits are preferred on today's machines.","example_contexts_fr":["un calcul d'énergie d'une petite molécule","un optimiseur classique qui ajuste des paramètres","un circuit volontairement court pour limiter le bruit"],"example_contexts_en":["an energy computation for a small molecule","a classical optimiser adjusting parameters","a deliberately short circuit to limit noise"],"safety_category":"standard"},{"key":"quantum_physics.post_quantum_migration","domain_id":"quantum_physics","objective_ids":["quantum_computing"],"stage":5,"order":54,"required":false,"prerequisite_keys":["quantum_physics.variational_algorithms"],"fallback_key":"quantum_physics.quantum_error_correction","title_fr":"Ce que la cryptographie doit changer","title_en":"What cryptography must change","summary_fr":"Planifier une migration cryptographique en tenant compte des données déjà interceptées.","summary_en":"Plan a cryptographic migration accounting for data already intercepted.","learning_goals_fr":["Expliquer la menace « récolter maintenant, déchiffrer plus tard ».","Ordonner les systèmes à migrer par urgence."],"learning_goals_en":["Explain the “harvest now, decrypt later” threat.","Rank systems to migrate by urgency."],"tutor_focus_fr":"Fais classer trois systèmes par urgence de migration, puis demande pourquoi la durée de confidentialité des données est le critère décisif.","tutor_focus_en":"Have the student rank three systems by migration urgency, then ask why the data's confidentiality lifetime is the decisive criterion.","example_contexts_fr":["un dossier médical à protéger trente ans","un jeton de session valable dix minutes","un trafic chiffré enregistré aujourd'hui pour plus tard"],"example_contexts_en":["a medical record to protect for thirty years","a session token valid for ten minutes","encrypted traffic recorded today for later"],"safety_category":"standard"}]}$catalog$::jsonb)
